INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('06dd831b-801d-4ea3-bd40-74df0c8d9a24', 'Strawberry Mascarpone Swiss Roll', 'A feather-light genoise sponge tightly spiraled around a luxuriously smooth mascarpone Chantilly cream and fresh strawberry jewels. This dessert balances the airy texture of the cake with the richness of the filling and the tart brightness of seasonal berries.', 'Dessert', 'French', 'Intermediate', '[{"group_name": "Sponge Cake", "items": [{"name": "large eggs", "quantity": 4, "unit": null, "preparation": "room temperature", "notes": "approx 220g total weight", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "cake flour", "quantity": 100, "unit": "g", "preparation": null, "notes": "low protein flour ensures tenderness", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "warm water", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "small pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Mascarpone Filling", "items": [{"name": "mascarpone cheese", "quantity": 250, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "fc428935-3bcd-4cef-8495-7ed35e7dae22", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 150, "unit": "ml", "preparation": "chilled", "notes": "min 35% fat", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 60, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla bean paste", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fa27169b-bdb5-4f0c-abab-0b67a3e924e6", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Assembly", "items": [{"name": "fresh strawberries", "quantity": 200, "unit": "g", "preparation": "diced small", "notes": "dry thoroughly after washing", "substitutions": [], "ingredient_id": "b2199214-7c2d-4083-92ae-b0a8a044e25b", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": "for dusting", "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 190\u00b0C/375\u00b0F. Grease the Swiss roll tin and line it with parchment paper, ensuring the paper extends slightly over the edges.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Sift the cake flour and salt together three times to aerate it. This is crucial for a light sponge.", "structured": {"action": "SIFT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a stand mixer, whisk eggs and granulated sugar on high speed for 5-7 minutes until the mixture triples in volume and reaches the ''ribbon stage'' (pale and thick enough to hold a trail).", "structured": {"action": "WHISK", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Pale, tripled in volume, holds a ribbon trail", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Gently fold in the vanilla and warm water. Then, sift the flour mixture over the egg foam in three batches, folding very gently with a spatula to retain air.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour the batter into the prepared tin. Gently tilt to spread evenly into corners. Bake for 10-12 minutes until the top is springy to the touch and pale golden.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT12M", "doneness_cues": {"visual": "Pale golden brown", "tactile": "Springs back when touched"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "While the cake bakes, lay a clean kitchen towel on the counter and dust it liberally with powdered sugar. Immediately upon removing the cake from the oven, invert it onto the towel. Peel off the parchment paper carefully.", "structured": {"action": "PREPARE_VEG", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "prep", "text": "Starting from a short end, roll the warm cake up tightly with the towel inside the spiral. Let it cool completely in this rolled shape on a wire rack.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Cool to the touch"}}, "tips": ["Rolling while hot trains the sponge''s memory, preventing cracks later."]}, {"step_number": 8, "phase": "prep", "text": "To make the filling, whisk the mascarpone, heavy cream, powdered sugar, and vanilla bean paste until stiff peaks form. Do not overbeat or the mascarpone may curdle.", "structured": {"action": "WHIP", "temperature": null, "duration": null, "doneness_cues": {"visual": "Stiff peaks", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Once the cake is cool, gently unroll it. Spread the mascarpone cream evenly over the surface, leaving a 2cm border at the far end. Scatter the diced strawberries over the cream.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "assemble", "text": "Roll the cake back up (without the towel this time), using the towel to help lift and guide the sponge. Place seam-side down on a serving platter.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 11, "phase": "finish", "text": "Refrigerate for at least 2 hours to set the filling. Dust with powdered sugar and slice with a warm knife before serving.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT2H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT2H30M", "total_time": "PT3H15M", "overnight_required": false, "yields": "10 slices", "yield_count": 10, "serving_size_g": 95}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Vegans", "Lactose intolerance"]}', '{"per_serving": {"calories": 296.07, "protein_g": 5.61, "carbohydrates_g": 34.19, "fat_g": 18.17, "saturated_fat_g": 10.41, "trans_fat_g": 0.2, "monounsaturated_fat_g": 2.19, "polyunsaturated_fat_g": 0.73, "fiber_g": 0.87, "sugar_g": 20.69, "sodium_mg": 84.86, "cholesterol_mg": 98.79, "potassium_mg": 87.01, "calcium_mg": 80.7, "iron_mg": 0.61, "magnesium_mg": 8.57, "phosphorus_mg": 67.89, "zinc_mg": 0.42, "vitamin_a_mcg": 231.05, "vitamin_c_mg": 11.85, "vitamin_d_mcg": 0.68, "vitamin_e_mg": 0.43, "vitamin_k_mcg": 1.02, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.22, "thiamin_mg": 0.03, "riboflavin_mg": 0.14, "niacin_mg": 0.23, "folate_mcg": 18.34, "water_g": 46.59, "alcohol_g": 0.17, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep covered to prevent the sponge from drying out. Best consumed within 24 hours.", "duration": "P3D"}, "freezer": {"notes": "Freeze without fresh strawberry garnish. Wrap tightly in plastic wrap then foil.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Stand mixer or electric hand mixer", "required": true, "alternative": null}, {"name": "Swiss roll tin (approx 23x33cm / 9x13 inch)", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Clean kitchen towel", "required": true, "alternative": "Additional sheet of parchment paper dusted with sugar"}, {"name": "Fine mesh sieve", "required": true, "alternative": null}, {"name": "Offset spatula", "required": true, "alternative": null}, {"name": "Rubber spatula", "required": true, "alternative": null}]', '[{"symptom": "Sponge cracked when rolling", "likely_cause": "The cake was overbaked (too dry) or cooled down too much before the initial roll", "prevention": "Bake only until just set; roll immediately while piping hot", "fix": "Cover the cracks with extra whipped cream or a ganache coating to hide them"}, {"symptom": "Filling squirts out when slicing", "likely_cause": "Cake was not chilled long enough or filling was too soft", "prevention": "Chill for full 2 hours; ensure cream is whipped to stiff peaks", "fix": "Chill for an additional hour before attempting to slice again"}]', '["Room temperature eggs are non-negotiable for this recipe; they whip to a much greater volume than cold eggs, providing the sponge''s structure without baking powder.", "When folding flour, use a ''cut and fold'' motion. Cut down the center, scrape along the bottom, and fold over. Stop exactly when the flour streaks disappear to avoid deflating the batter.", "To get clean slices, dip your knife in hot water and wipe it dry between every single cut.", "The warm water added to the eggs helps emulsify the mixture and keeps the sponge pliable for rolling."]', '"Despite the name, the Swiss Roll likely originated in Central Europe or the UK in the 19th century, not Switzerland. It evolved from ''jelly cakes'' and became a staple of British tea time. This variation elevates the humble jam roll with Italian mascarpone for a richer, creamier finish."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('06ff1c50-c861-4585-a575-4ad9b9dd9707', 'Tamarind & Soy Marinated Bavette Steak', 'A robust, flavor-forward steak dish where the tart complexity of tamarind concentrate meets the deep umami of soy sauce. The bavette''s loose, coarse grain absorbs the marinade exceptionally well, resulting in a caramelized crust and tender interior.', 'Dinner', 'Southeast Asian', 'Intermediate', '[{"group_name": "Marinade", "items": [{"name": "tamarind concentrate", "quantity": 40, "unit": "g", "preparation": "paste", "notes": "ensure it is the smooth concentrate, not the block with seeds", "substitutions": [], "ingredient_id": "c9dd70fa-d98b-459d-bd61-21b5778f1d4a", "nutrition_source": "USDA FoodData Central"}, {"name": "soy sauce", "quantity": 60, "unit": "ml", "preparation": null, "notes": "use light or all-purpose soy sauce", "substitutions": [], "ingredient_id": "1a157828-0624-4e67-815d-8e6bdf8b23c2", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": "or palm sugar for authenticity", "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 10, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "vegetable or canola oil", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Steak", "items": [{"name": "bavette steak", "quantity": 800, "unit": "g", "preparation": "whole", "notes": "also known as flap steak; skirt steak is a viable alternative", "substitutions": [], "ingredient_id": "9eefd433-4f88-4921-a43c-fd1a1181ef62", "nutrition_source": "USDA FoodData Central"}, {"name": "flaky sea salt", "quantity": null, "unit": null, "preparation": "to taste", "notes": "for finishing", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a mixing bowl, combine the tamarind concentrate, soy sauce, brown sugar, minced garlic, grated ginger, neutral oil, and black pepper. Whisk vigorously until the sugar has completely dissolved.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Place the bavette steak in a shallow dish or resealable bag. Pour the marinade over the meat, ensuring it is thoroughly coated. Refrigerate for at least 2 hours, up to 8 hours. Flip halfway through if using a dish.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT2H", "doneness_cues": null}, "tips": ["Do not marinate longer than 12 hours, or the acid in the tamarind will make the meat texture mushy."]}, {"step_number": 3, "phase": "cook", "text": "Remove the steak from the refrigerator 30 minutes before cooking to take the chill off. Preheat your grill or grill pan to high heat (approx. 230\u00b0C/450\u00b0F).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 230, "fahrenheit": 446}, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Remove the steak from the marinade and shake off excess liquid to prevent steaming. Grill the steak for 4-5 minutes per side, or until a deep char develops and the internal temperature reaches 52\u00b0C/125\u00b0F for medium-rare.", "structured": {"action": "GRILL", "temperature": {"celsius": 52, "fahrenheit": 126}, "duration": "PT10M", "doneness_cues": {"visual": "Deep brown char marks, no grey spots", "tactile": "Meat should feel soft with slight resistance (like the heel of your hand)"}}, "tips": ["The sugar in the marinade can burn quickly. If it flares up, move the steak to a cooler part of the grill."]}, {"step_number": 5, "phase": "finish", "text": "Transfer the steak to a cutting board and let it rest for 10 minutes. This allows the juices to redistribute throughout the muscle fibers.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Slice the steak thinly against the grain (perpendicular to the muscle fibers). This is critical for bavette to ensure tenderness. Finish with a sprinkle of flaky sea salt.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT2H10M", "total_time": "PT2H35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Dairy-Free", "Nut-Free", "Egg-Free"], "not_suitable_for": ["Gluten-Free (unless Tamari is substituted for Soy Sauce)"]}', '{"per_serving": {"calories": 418.54, "protein_g": 44.88, "carbohydrates_g": 16.79, "fat_g": 18.64, "saturated_fat_g": 5.25, "trans_fat_g": null, "monounsaturated_fat_g": 3.94, "polyunsaturated_fat_g": 0.43, "fiber_g": 0.84, "sugar_g": 11.43, "sodium_mg": 1332.96, "cholesterol_mg": 124, "potassium_mg": 851.93, "calcium_mg": 73.77, "iron_mg": 3.66, "magnesium_mg": 63.1, "phosphorus_mg": 437.08, "zinc_mg": 7.98, "vitamin_a_mcg": 0.34, "vitamin_c_mg": 1.65, "vitamin_d_mcg": null, "vitamin_e_mg": 0.63, "vitamin_k_mcg": 3.57, "vitamin_b6_mg": 1.29, "vitamin_b12_mcg": 2.12, "thiamin_mg": 0.2, "riboflavin_mg": 0.26, "niacin_mg": 14.04, "folate_mcg": 29.9, "water_g": 161.87, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store cooked steak in an airtight container.", "duration": "P3D"}, "freezer": {"notes": "Best frozen in marinade before cooking, rather than after cooking.", "duration": "P2M"}, "reheating": "Reheat gently in a skillet over low heat just until warm to prevent overcooking.", "does_not_keep": false}', '[{"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Outdoor grill or cast-iron grill pan", "required": true, "alternative": "Heavy skillet"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Instant-read thermometer", "required": true, "alternative": null}, {"name": "Sharp carving knife", "required": true, "alternative": null}]', '[{"symptom": "Steak is chewy or tough", "likely_cause": "The meat was sliced with the grain rather than against it", "prevention": "Identify the direction of the muscle fibers before cutting and position your knife at a 90-degree angle to them.", "fix": "Cut the existing slices into very small bite-sized pieces to minimize chewing effort."}]', '["Bavette has a very coarse, loose grain structure which makes it excellent for holding marinades but unforgiving if overcooked past medium.", "If you cannot find tamarind concentrate, you can substitute with a mix of lime juice and a dash of molasses, though the flavor profile will lack the specific earthy sourness of tamarind.", "Always pat the steak slightly dry before grilling; wet steak steams instead of searing, and you want that Maillard reaction for flavor.", "The marinade can be boiled down in a small saucepan for 5 minutes to create a safe, sticky glaze to brush on the sliced meat."]', '"This dish draws inspiration from the Thai dish ''Crying Tiger'' (Suea Rong Hai), which typically pairs grilled brisket or flank steak with a spicy, tart tamarind dipping sauce (Nam Jim Jaew). Here, the flavor profile is integrated directly into the marinade for a fusion approach that suits the grill."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('081efa84-48ac-4577-8fbb-9a267867d215', 'Classic Soft-Shell Crabs Meunière', 'Crisp, golden-fried soft-shell crabs served with a nutty, foaming brown butter and lemon sauce. The delicate sweetness of the crab is amplified by the toasted milk solids of the butter and brightened by fresh parsley and capers.', 'Dinner', 'French', 'Intermediate', '[{"group_name": "Crabs", "items": [{"name": "soft-shell crabs", "quantity": 8, "unit": null, "preparation": "fresh or thawed", "notes": "cleaned, approx. 500g total", "substitutions": [], "ingredient_id": "2ce537a0-fad3-40b0-a1aa-1eac21539b1f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dredge", "items": [{"name": "all-purpose flour", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Frying", "items": [{"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "grapeseed or canola", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Brown Butter Sauce", "items": [{"name": "unsalted butter", "quantity": 80, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "capers", "quantity": 15, "unit": "g", "preparation": "drained", "notes": null, "substitutions": [], "ingredient_id": "e7301d2c-b906-4ef8-917e-787be0b25880", "nutrition_source": "USDA FoodData Central"}, {"name": "flat-leaf parsley", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Clean the crabs if not pre-cleaned: Using shears, cut off the front of the face (behind the eyes). Lift the side points of the top shell and pull out the fibrous gills. Flip over and pull off the apron flap. Rinse briefly.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Ask your fishmonger to clean them for you to save time."]}, {"step_number": 2, "phase": "prep", "text": "Pat the crabs extremely dry with paper towels. Press gently to expel excess water from the legs and body cavities.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Moisture is the enemy of crispiness and causes dangerous oil splatter."]}, {"step_number": 3, "phase": "prep", "text": "In a shallow dish, combine the flour, salt, and black pepper. Dredge each crab lightly, shaking off all excess flour.", "structured": {"action": "DREDGE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat the neutral oil and frying butter (30g) in a large skillet over medium-high heat until the butter foams and subsides.", "structured": {"action": "HEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Place crabs in the pan, shell-side down (do not crowd; cook in batches if necessary). Sear until golden brown and crisp, about 3 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown crust", "tactile": null}}, "tips": ["Use a splatter screen as soft-shell crabs tend to pop and spit hot fat."]}, {"step_number": 6, "phase": "cook", "text": "Flip the crabs and cook the other side until crisp and cooked through, about 2 minutes. Transfer to a warm plate.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Wipe out the skillet carefully. Add the sauce butter (80g) and melt over medium heat. Swirl constantly until the milk solids turn a hazelnut brown and smell nutty.", "structured": {"action": "CARAMELIZE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Golden-brown specks", "tactile": "Nutty aroma"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Immediately remove from heat. Stir in lemon juice, capers, and parsley (caution: it will sputter). Spoon the foaming sauce over the crabs and serve.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 200}', '{"flags": ["Pescatarian", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Shellfish allergy", "Dairy allergy", "Gluten intolerance"]}', '{"per_serving": {"calories": 425.67, "protein_g": 26.26, "carbohydrates_g": 12.78, "fat_g": 31.41, "saturated_fat_g": 15.01, "trans_fat_g": null, "monounsaturated_fat_g": 6.46, "polyunsaturated_fat_g": 0.91, "fiber_g": 1.12, "sugar_g": 0.32, "sodium_mg": 1100.49, "cholesterol_mg": 59.13, "potassium_mg": 325.54, "calcium_mg": 122.39, "iron_mg": 2, "magnesium_mg": 7.43, "phosphorus_mg": 25.72, "zinc_mg": 0.18, "vitamin_a_mcg": 202.77, "vitamin_c_mg": 7.44, "vitamin_d_mcg": null, "vitamin_e_mg": 0.71, "vitamin_k_mcg": 44.71, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": 0.05, "thiamin_mg": 0.02, "riboflavin_mg": 0.02, "niacin_mg": 0.26, "folate_mcg": 10.22, "water_g": 15.1, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture degrades rapidly; best eaten immediately.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze cooked soft-shell crabs.", "duration": null}, "reheating": "Reheat in a dry pan over medium heat to recrisp, but fresh is significantly better.", "does_not_keep": true}', '[{"name": "Kitchen shears", "required": true, "alternative": null}, {"name": "Large skillet", "required": true, "alternative": "Saut\u00e9 pan"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Shallow dish", "required": true, "alternative": null}, {"name": "Paper towels", "required": true, "alternative": null}, {"name": "Splatter screen", "required": false, "alternative": "Lid (slightly ajar)"}]', '[{"symptom": "Breading is soggy or falling off", "likely_cause": "Crabs were too wet or pan was overcrowded", "prevention": "Pat crabs very dry before dredging and leave space between them in the pan", "fix": "Place on a wire rack in a 200\u00b0C/400\u00b0F oven for 2-3 minutes to dry out"}, {"symptom": "Butter sauce tastes bitter", "likely_cause": "Butter solids were burned rather than browned", "prevention": "Remove pan from heat the moment the butter smells nutty and turns golden", "fix": "Cannot be fixed; discard and start sauce over"}]', '["Soft-shell crabs are blue crabs caught immediately after molting. Their season typically runs from late spring to early autumn.", "Beurre Noisette (brown butter) relies on residual heat; removing the pan from the burner before it looks fully done prevents burning.", "If the crabs are very large, you can prick the legs and claws with a pin before frying to release steam and reduce popping.", "Serve with crusty baguette to mop up the excess brown butter."]', '"This preparation is a variation of ''\u00e0 la Meuni\u00e8re'' (in the style of the miller''s wife), a classic French technique traditionally applied to sole. The dusting of flour protects the delicate protein while creating a crisp crust that absorbs the rich butter sauce."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('09ad606c-794a-42ce-a5f5-f4ed60d53e2a', 'Duck Confit and Wild Mushroom Pappardelle', 'Silky ribbons of egg pasta tossed in a luxurious ragu of tender shredded duck leg and earthy wild mushrooms. The sauce is emulsified with duck fat, white wine, and a touch of cream for a decadent finish.', 'Dinner', 'Italian', 'Intermediate', '[{"group_name": "Duck and Mushrooms", "items": [{"name": "duck confit legs", "quantity": 2, "unit": null, "preparation": "cooked", "notes": "approximately 450-500g total weight before cleaning", "substitutions": [], "ingredient_id": "5525ed3e-a663-4b6c-beee-5c2a1c7b0558", "nutrition_source": "Aggregated Public Data"}, {"name": "mixed wild mushrooms", "quantity": 300, "unit": "g", "preparation": "cleaned and sliced", "notes": "chanterelle, porcini, oyster, or shiitake", "substitutions": [], "ingredient_id": "59d83971-a3c1-4b9c-b949-625005657048", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics and Sauce", "items": [{"name": "shallots", "quantity": 2, "unit": null, "preparation": "finely diced", "notes": "approx. 60g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": "whole sprigs", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "dry white wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": "Pinot Grigio or Sauvignon Blanc", "substitutions": [], "ingredient_id": "5e1efe68-ff2d-432c-9239-ff83f37c5e07", "nutrition_source": "Aggregated Public Data"}, {"name": "chicken stock", "quantity": 250, "unit": "ml", "preparation": null, "notes": "preferably low-sodium", "substitutions": [], "ingredient_id": "ba5595e6-e708-4989-9687-6837b15f9b83", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0568a393-d5cb-461f-97b5-66e29fdcbc79", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Pasta and Finish", "items": [{"name": "dried pappardelle pasta", "quantity": 350, "unit": "g", "preparation": null, "notes": null, "substitutions": ["fresh tagliatelle", "fettuccine"], "ingredient_id": "52cdfe63-4362-4d80-9ed0-9fc7041f2721", "nutrition_source": "USDA FoodData Central"}, {"name": "parmigiano reggiano", "quantity": 40, "unit": "g", "preparation": "freshly grated", "notes": null, "substitutions": [], "ingredient_id": "75aede38-b00a-4383-9000-06b67134eb61", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the duck: Remove the skin and bones from the confit legs. Shred the meat into bite-sized pieces. Reserve 1 tablespoon (approx 15ml) of the rendered duck fat surrounding the legs for cooking. Crisping the skin separately for garnish is optional but recommended.", "structured": {"action": "SHRED", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Bring a large pot of salted water to a boil for the pasta.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat the reserved duck fat in a large saut\u00e9 pan over medium-high heat. Add the sliced mushrooms and saut\u00e9 until golden brown and their moisture has evaporated, about 5-7 minutes. Do not crowd the pan.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Tender but not mushy"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to medium. Add the butter, shallots, garlic, and thyme sprigs to the mushrooms. Saut\u00e9 for 2-3 minutes until the shallots are translucent and aromatic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Deglaze the pan with white wine, scraping up any fond (browned bits) from the bottom. Let the wine reduce by half, approximately 2 minutes.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add the chicken stock and shredded duck meat. Bring to a simmer and let cook for 5 minutes to meld flavors. If using heavy cream, stir it in now and simmer for 1 additional minute.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT6M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Cook the pappardelle in the boiling water until just shy of al dente (usually 1-2 minutes less than package instructions). Reserve 120ml (1/2 cup) of starchy pasta water.", "structured": {"action": "BOIL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Transfer the pasta directly into the saut\u00e9 pan with the sauce using tongs. Add half the reserved pasta water. Increase heat to high and toss vigorously for 1-2 minutes until the sauce emulsifies and coats the noodles efficiently. Add more pasta water if the sauce looks dry.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Glossy sauce clinging to pasta", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove from heat. Discard thyme stems. Stir in the grated parmesan and parsley. Season with black pepper. Taste before adding salt, as the duck and cheese are already salty.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT10M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 380}', '{"flags": ["Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 641.33, "protein_g": 46.27, "carbohydrates_g": 35.61, "fat_g": 32.97, "saturated_fat_g": 4.53, "trans_fat_g": null, "monounsaturated_fat_g": 2.4, "polyunsaturated_fat_g": 1.05, "fiber_g": 2.96, "sugar_g": 3.99, "sodium_mg": 743.55, "cholesterol_mg": 54, "potassium_mg": 600.28, "calcium_mg": 182.5, "iron_mg": 13.97, "magnesium_mg": 43.83, "phosphorus_mg": 301.53, "zinc_mg": 2.46, "vitamin_a_mcg": 221.18, "vitamin_c_mg": 10.95, "vitamin_d_mcg": 3.83, "vitamin_e_mg": 0.22, "vitamin_k_mcg": 62.64, "vitamin_b6_mg": 0.24, "vitamin_b12_mcg": 0.21, "thiamin_mg": 0.23, "riboflavin_mg": 0.32, "niacin_mg": 2.93, "folate_mcg": 58.47, "water_g": 146.79, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. The sauce may separate upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended as the cream sauce may split and pasta texture will degrade.", "duration": null}, "reheating": "Gently reheat in a pan with a splash of water or stock to re-emulsify the sauce.", "does_not_keep": false}', '[{"name": "Large stockpot", "required": true, "alternative": null}, {"name": "Large saut\u00e9 pan or skillet", "required": true, "alternative": "Dutch oven"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Sauce is oily or separated", "likely_cause": "Broken emulsion from too much fat or insufficient agitation", "prevention": "Ensure you add starchy pasta water and toss vigorously at high heat", "fix": "Add a splash of hot water and toss the pasta rapidly to re-emulsify the fat and liquid"}, {"symptom": "Dish is too salty", "likely_cause": "Duck confit is inherently salty and additional salt was added too early", "prevention": "Taste the duck before cooking; do not salt the sauce until the very end", "fix": "Add a splash of unsalted cream or a squeeze of lemon juice to cut the saltiness"}]', '["Duck confit is very salty. Be extremely conservative with added salt until the final tasting step.", "For extra texture, fry the reserved duck skin in a separate small pan until crisp, chop it, and sprinkle over the finished dish as ''duck cracklings''.", "If you cannot find fresh wild mushrooms, rehydrate 30g of dried porcini mushrooms in hot water, chop them, and add them (along with their strained soaking liquid) to the sauce.", "The ''mantecatura'' step (tossing pasta with sauce, cheese, and water) is vital. It turns separate oily ingredients into a creamy, cohesive glaze."]', '"This dish draws inspiration from the rustic cooking of Northern Italy, specifically Veneto and Tuscany, where game birds and forest mushrooms are staples. While traditional rag\u00f9 often uses minced meat and tomato, this ''rag\u00f9 bianco'' (white ragu) highlights the delicate flavor of the duck and the earthiness of the mushrooms without masking them."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('09cf69a0-4ed3-4d85-bbe6-2a384b5ac6b0', 'Pan-Seared Brussels Sprouts with Bacon and Pine Nuts', 'Crisp-tender Brussels sprouts deeply caramelized in rendered bacon fat, finished with smoky bacon lardons and buttery toasted pine nuts. A textural masterpiece balancing savory richness with nutty warmth.', 'Side Dish', 'American', 'Easy', '[{"group_name": "Main", "items": [{"name": "brussels sprouts", "quantity": 500, "unit": "g", "preparation": "trimmed and halved", "notes": "Use similar sizes for even cooking", "substitutions": [], "ingredient_id": "2ee7388c-3256-477d-8d05-4ce09df9d8f1", "nutrition_source": "USDA FoodData Central"}, {"name": "thick-cut bacon", "quantity": 150, "unit": "g", "preparation": "diced", "notes": "approx 4-6 slices", "substitutions": [], "ingredient_id": "339a356e-8f77-48fe-9293-b8e35fed3e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "pine nuts", "quantity": 40, "unit": "g", "preparation": "raw", "notes": null, "substitutions": [], "ingredient_id": "971298ad-a9d7-49f7-811b-46afedad18d4", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Seasoning", "items": [{"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "Only if bacon renders insufficient fat", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, be sparing as bacon is salty", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": "freshly squeezed, to finish", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the pine nuts in a dry, cold skillet. Turn heat to medium and toast, shaking the pan frequently, until golden brown and fragrant (about 2-3 minutes). Immediately transfer to a small bowl to stop cooking.", "structured": {"action": "TOAST", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown color", "tactile": "Fragrant aroma"}}, "tips": ["Pine nuts burn in seconds; do not walk away."]}, {"step_number": 2, "phase": "cook", "text": "Return the skillet to medium heat and add the diced bacon. Cook until the fat has rendered and the bacon is crispy. Use a slotted spoon to transfer bacon to a paper towel-lined plate, leaving the rendered fat in the pan.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT6M", "doneness_cues": {"visual": "Bacon is crispy", "tactile": "Fat is liquid and clear"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Increase heat to medium-high. Ensure there is enough fat to coat the pan bottom (add olive oil if needed). Place Brussels sprouts cut-side down in a single layer. Sear undisturbed for 3-4 minutes until deeply browned.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT4M", "doneness_cues": {"visual": "Deep golden-brown sear on cut side", "tactile": null}}, "tips": ["Crowding the pan causes steaming rather than searing. Cook in batches if necessary."]}, {"step_number": 4, "phase": "cook", "text": "Stir the sprouts, reduce heat to medium-low, and cover the pan (if you don''t have a lid, use a baking sheet). Cook for another 3-5 minutes until the sprouts are tender when pierced with a knife.", "structured": {"action": "STEAM", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT4M", "doneness_cues": {"visual": null, "tactile": "Tender throughout"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove the lid. Add the crispy bacon and toasted pine nuts back to the pan. Toss to combine and warm through. Season with black pepper and a small squeeze of lemon juice. Taste before adding salt, as the bacon provides significant salinity.", "structured": {"action": "SEASON", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Transfer to a serving dish immediately while hot.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 150}', '{"flags": ["Gluten-Free", "Dairy-Free", "Paleo", "Whole30", "Keto", "Low-Carb"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 359.5, "protein_g": 19.67, "carbohydrates_g": 13.1, "fat_g": 26.4, "saturated_fat_g": 6.67, "trans_fat_g": null, "monounsaturated_fat_g": 9.93, "polyunsaturated_fat_g": 2.41, "fiber_g": 5.25, "sugar_g": 2.97, "sodium_mg": 1046.94, "cholesterol_mg": 40.13, "potassium_mg": 755.67, "calcium_mg": 59.39, "iron_mg": 2.84, "magnesium_mg": 63.36, "phosphorus_mg": 330.25, "zinc_mg": 2.38, "vitamin_a_mcg": 51.69, "vitamin_c_mg": 106.74, "vitamin_d_mcg": null, "vitamin_e_mg": 1.77, "vitamin_k_mcg": 223.96, "vitamin_b6_mg": 0.39, "vitamin_b12_mcg": 0.44, "thiamin_mg": 0.31, "riboflavin_mg": 0.21, "niacin_mg": 4.9, "folate_mcg": 77.29, "water_g": 113.38, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Texture will soften slightly upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; sprouts will become mushy.", "duration": null}, "reheating": "Reheat in a hot skillet for 2-3 minutes to restore crispiness.", "does_not_keep": false}', '[{"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": "Cast iron skillet"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Slotted spoon", "required": true, "alternative": null}]', '[{"symptom": "Sprouts are burnt on the outside but hard inside", "likely_cause": "Heat was too high during the searing phase", "prevention": "Sear at medium-high, then significantly lower the heat and cover to finish cooking the interior", "fix": "Add 30ml of water to the pan and cover immediately to steam them quickly without further burning"}]', '["Size matters: Try to buy sprouts of uniform size so they cook at the same rate. If you have some very large ones, quarter them instead of halving.", "Pine nut freshness: Pine nuts have a high oil content and go rancid quickly. Always taste one raw before toasting; if it tastes metallic or bitter, discard the batch.", "The cut side rule: Placing the sprouts cut-side down first creates a delicious Maillard reaction surface that defines the flavor profile of this dish."]', '"While Brussels sprouts originate from cultivation near Brussels, Belgium, in the 13th century, the combination with cured pork and nuts is a modern staple in American and British cuisine. This method transforms the vegetable from the boiled, sulfurous side dish of the past into a caramelized, savory delight."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('112aa2d8-4938-4163-95c7-d414f2bcbfc2', 'Classic Creamy Hummus', 'Velvety smooth and airy chickpea spread with rich nutty undertones from tahini and a bright kick of fresh lemon. This technique uses ice water to create a perfectly emulsified, cloud-like texture.', 'Appetizer', 'Middle Eastern', 'Easy', '[{"group_name": "Base", "items": [{"name": "canned chickpeas", "quantity": 425, "unit": "g", "preparation": "drained and rinsed", "notes": "1 standard can; save 30ml liquid (aquafaba) if desired, otherwise discard", "substitutions": [], "ingredient_id": "bc61d002-fe4c-464e-97fc-4323b3f26855", "nutrition_source": "Aggregated Public Data"}, {"name": "baking soda", "quantity": 3, "unit": "g", "preparation": null, "notes": "1/2 tsp; aids in softening skins for smoother texture", "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Emulsion", "items": [{"name": "tahini paste", "quantity": 120, "unit": "g", "preparation": "well-stirred", "notes": "Sesame paste; quality significantly affects flavor", "substitutions": [], "ingredient_id": "87ae6455-8e22-4c1b-bad7-89fa69c4dc57", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh lemon juice", "quantity": 60, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "peeled", "notes": "approx 5g; use 2 cloves for stronger flavor", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "ice water", "quantity": 45, "unit": "ml", "preparation": "very cold", "notes": "plus more if needed for consistency", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Garnish (Optional)", "items": [{"name": "extra virgin olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "paprika", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place drained chickpeas and baking soda in a small pot. Cover with water by 5cm and boil for 20 minutes until chickpeas are very soft and skins are falling off. Drain well.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT20M", "doneness_cues": {"visual": "Skins separating", "tactile": "Mushy when pressed"}}, "tips": ["Overcooking the chickpeas breaks down the pectin, ensuring a silky smooth dip without needing to peel them individually."]}, {"step_number": 2, "phase": "prep", "text": "While chickpeas boil, mince the garlic in the food processor. Add lemon juice and let sit for 5-10 minutes.", "structured": {"action": "MINCE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": ["Letting garlic sit in lemon juice neutralizes the sharp sulfur compounds, leaving the garlic flavor without the harsh bite."]}, {"step_number": 3, "phase": "cook", "text": "Add the tahini and salt to the lemon-garlic mixture in the food processor. Process until the mixture thickens and seizes up.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Thick, paste-like consistency", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "With the processor running, slowly drizzle in the ice water. Blend until the mixture turns pale, creamy, and aerated.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Color lightens significantly", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Add the warm chickpeas (and cumin if using) to the tahini base. Process for 3-5 minutes, scraping down sides occasionally, until ultra-smooth.", "structured": {"action": "PUREE", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "No visible graininess", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Taste and adjust salt or lemon if needed. Transfer to a serving bowl, create a swirl with a spoon, and drizzle with olive oil and paprika.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "500g", "yield_count": 8, "serving_size_g": 60}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 191.08, "protein_g": 8.14, "carbohydrates_g": 16.94, "fat_g": 11.79, "saturated_fat_g": 1.57, "trans_fat_g": null, "monounsaturated_fat_g": 1.41, "polyunsaturated_fat_g": 0.22, "fiber_g": 8.93, "sugar_g": 4.43, "sodium_mg": 701.96, "cholesterol_mg": null, "potassium_mg": 460.81, "calcium_mg": 194.73, "iron_mg": 5.61, "magnesium_mg": 54.31, "phosphorus_mg": 87.2, "zinc_mg": 0.78, "vitamin_a_mcg": 3.24, "vitamin_c_mg": 3.12, "vitamin_d_mcg": null, "vitamin_e_mg": 0.33, "vitamin_k_mcg": 1.25, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": null, "thiamin_mg": null, "riboflavin_mg": 0.01, "niacin_mg": 0.03, "folate_mcg": 1.61, "water_g": 12.95, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container; drizzle with olive oil to prevent a skin from forming.", "duration": "P5D"}, "freezer": {"notes": "Texture may change slightly; thaw in fridge and re-whip before serving.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Food processor", "required": true, "alternative": "High-speed blender"}, {"name": "Small pot", "required": false, "alternative": "Microwave-safe bowl"}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Citrus juicer", "required": false, "alternative": null}]', '[{"symptom": "Texture is grainy or gritty", "likely_cause": "Chickpea skins were tough or processing time was too short", "prevention": "Boil canned chickpeas with baking soda as instructed", "fix": "Add 1 tablespoon of warm water and process for another 2-3 minutes"}, {"symptom": "Taste is too bitter", "likely_cause": "Low quality tahini or old garlic", "prevention": "Use premium Ethiopian or Levantine tahini", "fix": "Balance with a pinch more salt and a small drizzle of maple syrup or honey"}]', '["The Ice Water Secret: Adding ice-cold water to the fatty tahini creates a stable emulsion and whips air into the mixture, resulting in a lighter, creamier hummus similar to gelato.", "Order Matters: Processing the tahini, lemon, and garlic first creates a ''tahini sauce'' base that coats the starch of the chickpeas, preventing a gluey texture.", "Chickpea Quality: While this recipe uses canned for speed, over-boiling them with baking soda mimics the texture of home-cooked dried chickpeas.", "Flavor Balance: If your lemons are not very acidic, you may need to increase the quantity to cut through the rich fat of the tahini."]', '"Hummus bi tahini (chickpeas with tahini) is a staple Levantine dish with ancient roots, consumed across the Middle East for breakfast, mezze, or dinner. While its exact origins are debated among regional cultures, it represents a unifying culinary tradition centered on hospitality, sharing, and the maximization of humble, nutritious ingredients."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('17e72793-f0b2-443d-85c5-8c27b63607ab', 'Vibrant Citrus Napa Slaw', 'A crisp and refreshing salad combining the delicate crunch of Napa cabbage with sweet red bell peppers and savory scallions. The bright citrus dressing, emulsified with high-quality olive oil, brings a zesty finish that cleanses the palate.', 'Salad', 'Modern American', 'Easy', '[{"group_name": "Vegetables", "items": [{"name": "napa cabbage", "quantity": 400, "unit": "g", "preparation": "shredded", "notes": "approximately half a medium head", "substitutions": [], "ingredient_id": "771c0eca-db4a-4c97-b01d-ee14efc0d3aa", "nutrition_source": "Aggregated Public Data"}, {"name": "red bell pepper", "quantity": 150, "unit": "g", "preparation": "julienned", "notes": "1 large pepper", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 30, "unit": "g", "preparation": "thinly sliced", "notes": "green and white parts", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Citrus Dressing", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "orange juice", "quantity": 30, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "a15da11d-f8dd-46e3-9ac5-725a7912f1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Remove any wilted outer leaves from the Napa cabbage. Cut the head in half lengthwise, remove the core, and shred the leaves into thin strips.", "structured": {"action": "SHRED", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Slice the red bell pepper into thin julienne strips and thinly slice the scallions on a bias.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Combine the shredded cabbage, julienned peppers, and sliced scallions in a large mixing bowl.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a small bowl, whisk together the lemon juice, orange juice, salt, and pepper. Slowly drizzle in the olive oil while whisking continuously to emulsify.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Ensure ingredients are at room temperature for better emulsification."]}, {"step_number": 5, "phase": "assemble", "text": "Pour the dressing over the vegetables and toss thoroughly to coat. Taste and adjust salt if necessary before serving immediately.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 160}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Low-Carb", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 130.43, "protein_g": 1.8, "carbohydrates_g": 7.01, "fat_g": 11.51, "saturated_fat_g": 1.63, "trans_fat_g": null, "monounsaturated_fat_g": 8.23, "polyunsaturated_fat_g": 1.25, "fiber_g": 1.67, "sugar_g": 3.9, "sodium_mg": 309.09, "cholesterol_mg": null, "potassium_mg": 375.19, "calcium_mg": 53.48, "iron_mg": 0.68, "magnesium_mg": 21.49, "phosphorus_mg": 54.5, "zinc_mg": 0.34, "vitamin_a_mcg": 253.44, "vitamin_c_mg": 79.61, "vitamin_d_mcg": null, "vitamin_e_mg": 2.27, "vitamin_k_mcg": 24.55, "vitamin_b6_mg": 0.12, "vitamin_b12_mcg": null, "thiamin_mg": 0.03, "riboflavin_mg": 0.04, "niacin_mg": 0.44, "folate_mcg": 25.09, "water_g": 146.43, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten fresh; cabbage will soften significantly over time.", "duration": "P1D"}, "freezer": {"notes": "Raw lettuce and cabbage do not freeze well.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": "Fork or jar with lid"}]', '[{"symptom": "Slaw is watery and soggy", "likely_cause": "The slaw sat for too long after dressing; salt drew moisture out of the cabbage", "prevention": "Wait to dress the salad until right before serving", "fix": "Drain the excess liquid from the bottom of the bowl and re-season slightly"}]', '["Napa cabbage is much more delicate than standard green cabbage; slice it slightly thicker (about 0.5cm) to maintain crunch.", "For the red bell pepper, cut on the flesh side rather than the skin side to prevent the knife from slipping.", "This dressing is a basic vinaigrette ratio (3 parts oil to 1 part acid). Since we are using orange juice which is less acidic than lemon, we slightly adjust the ratio to maintain brightness.", "To turn this into a main course, top with grilled tofu or chickpeas for added protein.", "Using freshly squeezed citrus makes a noticeable difference in aroma compared to bottled juice."]', '"While coleslaw is traditionally associated with heavy mayonnaise dressings in American cuisine, this iteration reflects modern Californian influences which prioritize fresh produce and lighter, vinaigrette-based dressings that highlight rather than mask the vegetables."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('1d3b7ef1-c12d-491d-ae3e-f26441b5348d', 'Roast Fillet of Beef with Dried Cherry Reduction and Horseradish Crème', 'A centerpiece British roast featuring center-cut beef tenderloin, seared for a caramelized crust and roasted to tender perfection. It is served with two contrasting sauces: a rich, tart red wine reduction studded with dried cherries, and a sharp, cooling horseradish cream.', 'Dinner', 'British', 'Advanced', '[{"group_name": "Beef Fillet", "items": [{"name": "beef tenderloin", "quantity": 1200, "unit": "g", "preparation": "center cut, trimmed and tied", "notes": "Bring to room temperature 1 hour before cooking", "substitutions": [], "ingredient_id": "a821f612-21c1-4514-969d-c3a2101cd8d5", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 6, "unit": null, "preparation": "whole sprigs", "notes": "approx 5g", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt flakes", "quantity": 10, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 5, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dried Cherry Reduction", "items": [{"name": "dry red wine", "quantity": 250, "unit": "ml", "preparation": null, "notes": "Cabernet Sauvignon or Merlot", "substitutions": [], "ingredient_id": "0fc93141-8ba8-42e0-ac8b-b5af3851554c", "nutrition_source": "USDA FoodData Central"}, {"name": "beef stock", "quantity": 300, "unit": "ml", "preparation": null, "notes": "high quality, low sodium", "substitutions": [], "ingredient_id": "390b2a8f-1613-4b2d-ae97-8403bbc9f505", "nutrition_source": "Aggregated Public Data"}, {"name": "dried cherries", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fc2b3924-abc5-498f-b917-8bb60e75b983", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx 25g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Horseradish Cr\u00e8me", "items": [{"name": "cr\u00e8me fra\u00eeche", "quantity": 150, "unit": "ml", "preparation": null, "notes": "or heavy cream", "substitutions": [], "ingredient_id": "d171100e-1088-4266-8d50-06cdedda7193", "nutrition_source": "USDA FoodData Central"}, {"name": "prepared horseradish", "quantity": 45, "unit": "g", "preparation": "drained", "notes": null, "substitutions": [], "ingredient_id": "72f7fb8a-7b34-41ea-9e5f-8fec2553cae8", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2f2247dc-52b3-4782-a330-b355c8c10e4f", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh chives", "quantity": 5, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Remove the beef from the refrigerator at least 45-60 minutes before cooking to allow it to come to room temperature. This ensures even roasting.", "structured": {"action": "REST", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Pat the beef thoroughly dry with paper towels. Rub all over with olive oil, sea salt, and freshly cracked black pepper. Tie the roast with butcher''s twine at 3cm intervals to maintain a uniform cylindrical shape.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Dry meat sears better. Moisture creates steam which inhibits browning."]}, {"step_number": 3, "phase": "cook", "text": "Preheat oven to 200\u00b0C/390\u00b0F. Heat a large cast-iron skillet over high heat until smoking. Add the beef and sear aggressively on all sides until deep brown, about 2-3 minutes per side. Add thyme sprigs to the pan during the last minute of searing.", "structured": {"action": "SEAR", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Transfer the beef (and thyme) to a roasting rack set over a tray. Roast in the oven until an instant-read thermometer inserted into the thickest part reads 52\u00b0C/125\u00b0F for medium-rare.", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT25M", "doneness_cues": {"visual": "Browned crust", "tactile": "Internal temp 52\u00b0C"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove beef from the oven. Transfer to a carving board and cover loosely with foil. Allow to rest for at least 15-20 minutes. This is critical for retaining juices.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "While beef rests, prepare the cherry sauce. In the saucepan, combine red wine, minced shallot, and dried cherries. Bring to a boil and reduce liquid by half.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Add beef stock to the wine mixture. Simmer until reduced to a sauce consistency that coats the back of a spoon (nappe). Remove from heat and whisk in the cold cubed butter to emulsify and add gloss. Season with salt to taste.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "prep", "text": "For the horseradish cr\u00e8me, whisk together cr\u00e8me fra\u00eeche, prepared horseradish, Dijon mustard, lemon juice, and chives in a small bowl. Season with a pinch of salt and pepper. Refrigerate until serving.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove twine from the beef. Slice into thick medallions (approx. 2-3cm). Serve with the warm dried cherry reduction poured over the meat and the cool horseradish cr\u00e8me on the side.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT1H15M", "total_time": "PT2H", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 250}', '{"flags": ["Gluten-Free", "Low-Carb", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 529.93, "protein_g": 48.41, "carbohydrates_g": 11.26, "fat_g": 29.94, "saturated_fat_g": 11.27, "trans_fat_g": 0.66, "monounsaturated_fat_g": 11.44, "polyunsaturated_fat_g": 2.04, "fiber_g": 1.51, "sugar_g": 3.67, "sodium_mg": 856.16, "cholesterol_mg": 142.6, "potassium_mg": 744.08, "calcium_mg": 83.48, "iron_mg": 5.9, "magnesium_mg": 45.48, "phosphorus_mg": 511.83, "zinc_mg": 7.39, "vitamin_a_mcg": 73.36, "vitamin_c_mg": 4.64, "vitamin_d_mcg": 0.25, "vitamin_e_mg": 1.34, "vitamin_k_mcg": 8.01, "vitamin_b6_mg": 1.27, "vitamin_b12_mcg": 7.07, "thiamin_mg": 0.15, "riboflavin_mg": 0.69, "niacin_mg": 9.66, "folate_mcg": 17.47, "water_g": 212.65, "alcohol_g": 3.88, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store beef and sauces in separate airtight containers.", "duration": "P3D"}, "freezer": {"notes": "Beef can be frozen but texture may suffer upon reheating. Sauces freeze well.", "duration": "P1M"}, "reheating": "Gently reheat beef slices in the cherry sauce over low heat just until warm. Do not overheat or the meat will toughen.", "does_not_keep": false}', '[{"name": "Large cast-iron skillet or heavy-bottomed frying pan", "required": true, "alternative": null}, {"name": "Roasting tray with rack", "required": true, "alternative": "Baking sheet with a wire cooling rack"}, {"name": "Digital probe thermometer", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Butchers twine", "required": true, "alternative": null}]', '[{"symptom": "Beef is tough or dry", "likely_cause": "Overcooking beyond medium-rare or not resting the meat", "prevention": "Use a probe thermometer to pull meat exactly at 52\u00b0C/125\u00b0F and rest for the full 20 minutes.", "fix": "Slice very thinly against the grain and serve with extra sauce to provide moisture."}]', '["Uniformity is key: Tying the beef with butcher''s twine ensures the roast is the same thickness throughout, preventing the ends from overcooking while the center is raw.", "The ''monter au beurre'' technique (whisking cold butter into the hot sauce off the heat) is essential for a glossy, professional finish on the cherry reduction.", "If your dried cherries are very hard or old, rehydrate them in the red wine for 15 minutes before starting the sauce.", "For the horseradish sauce, use fresh horseradish root grated on a microplane if available for a more potent, aromatic kick compared to jarred."]', '"Roast beef is the quintessence of British culinary identity, historically celebrated in ballads and patriotic songs. This recipe elevates the traditional Sunday lunch by pairing the earthy, iron-rich beef with a classic ''agrodolce'' style fruit sauce and the traditional sharp bite of horseradish."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('20ed0258-63a0-46bf-bb7d-524c253b2264', 'Stir-Fried Chinese Broccoli with Anchovies and Garlic', 'Vibrant emerald greens meet a savory, deep umami punch from melted anchovies and golden garlic. The crisp stems and tender leaves absorb the complex salty-savory sauce, creating a quick vegetable dish that rivals restaurant quality.', 'Side Dish', 'Chinese', 'Easy', '[{"group_name": "Vegetables", "items": [{"name": "chinese broccoli (gai lan)", "quantity": 500, "unit": "g", "preparation": "washed and trimmed", "notes": "Trim tough ends; separate leaves from thick stems if stems are very thick", "substitutions": [], "ingredient_id": "d76b34d6-ab24-47c9-95a6-fe49dc10c82f", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 5, "unit": null, "preparation": "minced", "notes": "approximately 20g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics & Seasoning", "items": [{"name": "anchovy fillets in oil", "quantity": 6, "unit": null, "preparation": "chopped", "notes": "approximately 18g; use high quality fillets", "substitutions": [], "ingredient_id": "cfdad407-c486-4fcc-9e47-7dd4cb32277c", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "vegetable, canola, or grapeseed oil", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "shaoxing rice wine", "quantity": 15, "unit": "ml", "preparation": null, "notes": "optional; replace with water or dry sherry for gluten-free if needed", "substitutions": [], "ingredient_id": "bb7adcb8-7e07-46ec-a3ac-e02f9ffb6f9f", "nutrition_source": "Aggregated Public Data"}, {"name": "sugar", "quantity": 2, "unit": "g", "preparation": null, "notes": "just a pinch to balance the saltiness", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 30, "unit": "ml", "preparation": null, "notes": "for steam-frying", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the Chinese broccoli by washing thoroughly. Cut off and discard the bottom 1-2 cm of the tough stems. Slice the remaining stems diagonally into bite-sized pieces and keep the leaves whole or halved. Keep stems and leaves separate.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the wok or large skillet over medium heat. Add the oil and the chopped anchovies. Cook, stirring constantly, until the anchovies break down and dissolve into the oil, about 1-2 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT2M", "doneness_cues": {"visual": "Anchovies have dissolved into a paste", "tactile": "Oil is fragrant"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the minced garlic to the anchovy oil. Stir-fry for 30 seconds until fragrant and pale golden. Be careful not to burn the garlic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT30S", "doneness_cues": {"visual": "Garlic is pale golden", "tactile": "Aromatic"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Increase heat to high. Add the broccoli stems first. Stir-fry for 1-2 minutes until they turn bright green and start to soften.", "structured": {"action": "STIR", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the broccoli leaves, the splash of Shaoxing wine (if using), sugar, and water. Immediately cover the pan with a lid or baking sheet to trap the steam. Cook for 1-2 minutes.", "structured": {"action": "STEAM", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Leaves are wilted and dark green", "tactile": "Stems are tender-crisp"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Uncover and toss everything together for a final 30 seconds to evaporate excess liquid. Serve immediately.", "structured": {"action": "SERVE", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 130}', '{"flags": ["Pescatarian", "Dairy-Free", "Nut-Free", "Peanut-Free", "Low-Carb", "Keto"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 118.45, "protein_g": 2.67, "carbohydrates_g": 8.18, "fat_g": 8.64, "saturated_fat_g": 1.28, "trans_fat_g": null, "monounsaturated_fat_g": 0.06, "polyunsaturated_fat_g": 0.45, "fiber_g": 3.36, "sugar_g": 1.65, "sodium_mg": 14.65, "cholesterol_mg": null, "potassium_mg": 377.75, "calcium_mg": 145.74, "iron_mg": 1.02, "magnesium_mg": 26.88, "phosphorus_mg": 71.89, "zinc_mg": 0.63, "vitamin_a_mcg": 107.5, "vitamin_c_mg": 38.56, "vitamin_d_mcg": null, "vitamin_e_mg": 0.63, "vitamin_k_mcg": 111.46, "vitamin_b6_mg": 0.15, "vitamin_b12_mcg": null, "thiamin_mg": 0.14, "riboflavin_mg": 0.19, "niacin_mg": 0.61, "folate_mcg": 130.15, "water_g": 126.18, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Texture may soften slightly upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; freezing destroys the crisp texture of the greens.", "duration": null}, "reheating": "Briefly stir-fry over high heat or microwave for 30-45 seconds.", "does_not_keep": false}', '[{"name": "Wok or large skillet", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Stems are tough but leaves are mushy", "likely_cause": "The stems and leaves were cooked for the same amount of time", "prevention": "Always add the thick stems to the wok 1-2 minutes before the delicate leaves", "fix": "Pick out the stems and microwave them for 30 seconds, then return to the mix"}, {"symptom": "Dish tastes burnt or bitter", "likely_cause": "Garlic was burned during the initial saut\u00e9", "prevention": "Add garlic only after anchovies have melted and keep heat medium until vegetables are added", "fix": "Cannot be fixed; burnt garlic flavor permeates the oil. Start over."}]', '["Anchovies are a cheat code for instant depth. They don''t make the dish taste ''fishy'', but rather provide a rich savory backbone similar to shrimp paste or fish sauce.", "If your Chinese broccoli has very thick stems (over 1.5 cm), slice them in half lengthwise before cutting diagonally to ensure even cooking.", "High heat is crucial for the final toss to achieve ''wok hei'' (breath of the wok) and prevent the vegetables from stewing in their own juices.", "This technique works brilliantly with other greens like broccolini, kale, or choy sum."]', '"In Cantonese cuisine, stir-frying leafy greens with salted fish is a classic preparation used to add intense umami to simple vegetables. This recipe substitutes hard-to-find traditional salted fish with accessible anchovy fillets, replicating that signature savory depth found in homestyle Hong Kong cooking."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('2388d8a1-e508-40be-93a0-a8e852901321', 'Velvet Celeriac Puree', 'A sophisticated alternative to mashed potatoes, this puree offers a silky texture with the subtle, nutty flavor of celery root. Enriched with creaminess from a milk poach and finished with cold butter for a glossy sheen, it pairs exceptionally well with roasted meats or rich winter stews.', 'Side Dish', 'French', 'Intermediate', '[{"group_name": "Main", "items": [{"name": "celeriac", "quantity": 800, "unit": "g", "preparation": "peeled and diced into 2cm cubes", "notes": "approx. 1 large root; weigh after peeling", "substitutions": [], "ingredient_id": "2fcb3469-785d-4383-ac0d-773795c790f8", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 500, "unit": "ml", "preparation": null, "notes": "enough to just cover the vegetables", "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Using a sharp knife, cut away the thick, knobby skin of the celeriac until only the creamy white flesh remains. Dice into uniform 2cm cubes.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Be aggressive when peeling celeriac; the root end can trap dirt deep inside.", "Rub cut surfaces with lemon to prevent browning if not cooking immediately."]}, {"step_number": 2, "phase": "cook", "text": "Place the celeriac cubes, milk, and half the salt in a large saucepan. Ensure the milk just covers the vegetables (add a splash of water if necessary). Bring to a boil, then reduce heat immediately to a gentle simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Simmer uncovered for 15-20 minutes until the celeriac is completely tender and offers no resistance when pierced with a knife.", "structured": {"action": "SIMMER", "temperature": null, "duration": null, "doneness_cues": {"visual": "Milk has reduced and thickened slightly", "tactile": "Mushy when pressed with a fork"}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Drain the celeriac through a colander, reserving the hot cooking milk in a separate bowl. Do not discard the liquid.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Transfer the hot celeriac to a blender. Add the lemon juice and a small splash (about 30ml) of the reserved cooking milk. Puree on high speed.", "structured": {"action": "PUREE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "With the blender running, gradually add the cold butter cubes one by one to emulsify. Adjust consistency with more reserved milk if needed until it reaches a thick, velvety texture.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Adding cold butter creates a tighter, glossier emulsion than melted butter."]}, {"step_number": 7, "phase": "finish", "text": "For a Michelin-level texture, pass the puree through a fine-mesh sieve (chinois) into a warm serving bowl. Season with remaining salt to taste.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT20M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 150}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Egg-Free", "Low-Carb"], "not_suitable_for": ["Vegans (contains dairy)", "Lactose intolerant"]}', '{"per_serving": {"calories": 268.35, "protein_g": 7.07, "carbohydrates_g": 24.58, "fat_g": 16.83, "saturated_fat_g": 10.06, "trans_fat_g": null, "monounsaturated_fat_g": 4.64, "polyunsaturated_fat_g": 1, "fiber_g": 3.61, "sugar_g": 9.59, "sodium_mg": 740.43, "cholesterol_mg": 44.75, "potassium_mg": 771.28, "calcium_mg": 231.3, "iron_mg": 1.45, "magnesium_mg": 52.96, "phosphorus_mg": 338.8, "zinc_mg": 1.14, "vitamin_a_mcg": 160.1, "vitamin_c_mg": 16.97, "vitamin_d_mcg": 1.63, "vitamin_e_mg": 1.16, "vitamin_k_mcg": 83.43, "vitamin_b6_mg": 0.39, "vitamin_b12_mcg": 0.59, "thiamin_mg": 0.17, "riboflavin_mg": 0.34, "niacin_mg": 1.52, "folate_mcg": 23.2, "water_g": 290.87, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Press plastic wrap directly onto the surface to prevent skin formation.", "duration": "P3D"}, "freezer": {"notes": "Texture may degrade slightly; reheat gently while whisking.", "duration": "P1M"}, "reheating": "Reheat gently in a saucepan over low heat, adding a splash of milk or water to loosen consistency.", "does_not_keep": false}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Vegetable peeler", "required": true, "alternative": null}, {"name": "Large saucepan", "required": true, "alternative": null}, {"name": "High-speed blender", "required": true, "alternative": "Food processor or immersion blender"}, {"name": "Fine-mesh sieve (Chinois)", "required": false, "alternative": "Standard strainer"}]', '[{"symptom": "Texture is grainy or lumpy", "likely_cause": "Celeriac was undercooked or blender speed was too low", "prevention": "Cook until the vegetable falls apart when touched; use a high-speed blender", "fix": "Pass through a fine-mesh sieve twice to remove lumps"}, {"symptom": "Milk scorched on bottom of pan", "likely_cause": "Heat was too high during simmering", "prevention": "Simmer gently; milk boils over and burns easily at high temps", "fix": "Do not scrape the bottom of the pan when pouring out; taste the milk. If burnt, rinse celeriac and blend with fresh cream/milk"}]', '["To keep the puree snowy white, ensure you peel away all green parts of the root and cook entirely in milk rather than water.", "Celeriac absorbs liquid differently than potatoes. Add the reserved liquid slowly; you can always add more, but you cannot take it out.", "The lemon juice is critical not just for flavor balance, but to prevent the puree from oxidizing and turning grey as it sits.", "This dish is an excellent low-carb substitute for mashed potatoes on a holiday table."]', '"Known in France as Pur\u00e9e de C\u00e9leri-Rave, this dish highlights the often-overlooked celery root. It became a staple in French bistros as a winter accompaniment that offers the comfort of a starch with a more complex, herbaceous flavor profile suitable for cutting through rich sauces."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('2857721c-7d4a-49b8-a916-faa28e2039b9', 'Buttery Heritage Corn Muffins', 'A nostalgic homage to the early West Village bakery days, these muffins feature a rich, golden crumb studded with sweet corn kernels. They strike the perfect balance between savory and sweet, with a distinct buttery richness that pairs equally well with breakfast jam or a bowl of chili.', 'Baked Good', 'American', 'Easy', '[{"group_name": "Dry Ingredients", "items": [{"name": "all-purpose flour", "quantity": 190, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow cornmeal", "quantity": 120, "unit": "g", "preparation": "medium grind", "notes": "provides texture and color", "substitutions": [], "ingredient_id": "7fb6be00-5ba2-483a-af74-961f21de4055", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 12, "unit": "g", "preparation": null, "notes": "approx 1 tablespoon", "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1/2 teaspoon", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Ingredients & Add-ins", "items": [{"name": "unsalted butter", "quantity": 170, "unit": "g", "preparation": "melted and slightly cooled", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 240, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "large, room temperature", "notes": "approx 100g total without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "corn kernels", "quantity": 150, "unit": "g", "preparation": "fresh, frozen (thawed), or canned (drained)", "notes": "adds texture and moisture", "substitutions": [], "ingredient_id": "46ca2aab-cb23-4397-9711-528c234b2cf8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 200\u00b0C (400\u00b0F). Generously grease the muffin tin cups with butter or insert paper liners.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, whisk together the flour, cornmeal, sugar, baking powder, and salt until uniformly combined.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a medium bowl, whisk the eggs and milk together. Slowly stream in the melted butter while whisking constantly to emulsify slightly.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": ["Ensure the butter is not hot, or it will cook the eggs."]}, {"step_number": 4, "phase": "assemble", "text": "Pour the wet ingredients into the dry ingredients. Using a silicone spatula, mix until just barely combined and streaks of flour remain.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Add the corn kernels and fold them gently into the batter. Stop mixing the moment no dry flour is visible.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Overmixing develops gluten, resulting in tough muffins. Lumps in the batter are fine."]}, {"step_number": 6, "phase": "cook", "text": "Divide the batter evenly among the 12 muffin cups. Bake in the center of the oven for 20-25 minutes, or until the tops are golden and a toothpick inserted into the center comes out clean.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT25M", "doneness_cues": {"visual": "Golden domed tops", "tactile": "Toothpick comes out clean"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from the oven and let the muffins cool in the pan for 10 minutes before transferring them to a wire rack to cool completely.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT30M", "total_time": "PT45M", "overnight_required": false, "yields": "12 muffins", "yield_count": 12, "serving_size_g": 95}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Vegans (contains dairy, eggs)", "Celiacs (contains gluten)"]}', '{"per_serving": {"calories": 290.13, "protein_g": 4.79, "carbohydrates_g": 38.32, "fat_g": 13.61, "saturated_fat_g": 7.9, "trans_fat_g": null, "monounsaturated_fat_g": 3.85, "polyunsaturated_fat_g": 0.75, "fiber_g": 1.43, "sugar_g": 14.51, "sodium_mg": 233.11, "cholesterol_mg": 63.46, "potassium_mg": 121.11, "calcium_mg": 93.41, "iron_mg": 1.2, "magnesium_mg": 37.06, "phosphorus_mg": 135.03, "zinc_mg": 0.73, "vitamin_a_mcg": 122.76, "vitamin_c_mg": 0.85, "vitamin_d_mcg": 0.43, "vitamin_e_mg": 0.45, "vitamin_k_mcg": 1.16, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": 0.19, "thiamin_mg": 0.05, "riboflavin_mg": 0.09, "niacin_mg": 0.45, "folate_mcg": 14.71, "water_g": 37.7, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to prevent drying out.", "duration": "P3D"}, "freezer": {"notes": "Wrap individually in plastic wrap, then place in a zip-top bag.", "duration": "P2M"}, "reheating": "Microwave for 15 seconds or warm in a 150\u00b0C oven for 5 minutes.", "does_not_keep": false}', '[{"name": "Standard 12-cup muffin tin", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Medium mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Silicone spatula", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}]', '[{"symptom": "Muffins are tough and dense", "likely_cause": "The batter was overmixed after adding the wet ingredients", "prevention": "Use a spatula instead of a whisk for the final mix; stop as soon as the flour disappears", "fix": "Cannot be fixed once baked; serve warm with extra butter to mask density"}, {"symptom": "Muffins have soggy bottoms", "likely_cause": "Left in the hot tin too long after baking", "prevention": "Remove from tin after exactly 10 minutes", "fix": "Place on a wire rack in a warm oven for 3-5 minutes to dry out the base"}]', '["For a true bakery-style ''muffin top'', fill the cups nearly to the brim. If you do this, place a baking sheet on the rack below to catch any potential drips.", "If using frozen corn, ensure it is completely thawed and patted dry to avoid adding excess water to the batter.", "These muffins are best served warm. If serving the next day, a quick toast revives the buttery edges.", "Yellow cornmeal is preferred over white for that classic golden hue and slightly nuttier flavor."]', '"Inspired by the early repertoire of NYC''s Magnolia Bakery in the 1990s, these muffins represent a shift in American baking where ''morning pastries'' moved away from purely sugary confections toward richer, savory-sweet comforts. The inclusion of whole kernels and a high butter content mimics the Southern-style spoonbread tradition adapted for an urban grab-and-go format."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('29d83991-c2d6-4ae4-b7ea-7c5a9451595b', 'Salabat-Inspired Honey Ginger Loaf', 'A tender, aromatic loaf cake channeling the soothing warmth of Salabat (traditional Filipino ginger tea). The crumb is enriched with sour cream and brightened with lemon zest, while a double dose of fresh and ground ginger provides a gentle, spicy heat balanced by floral honey.', 'Baked Good', 'Filipino', 'Intermediate', '[{"group_name": "Dry Ingredients", "items": [{"name": "all-purpose flour", "quantity": 240, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "ground ginger", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 2g (1 tsp), increase for more heat", "substitutions": [], "ingredient_id": "401ddd0b-3597-4b46-bb54-f3bc755048bb", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 85, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "large, room temperature", "notes": "approx 100g total without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "sour cream", "quantity": 120, "unit": "g", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "d171100e-1088-4266-8d50-06cdedda7193", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 15, "unit": "g", "preparation": "peeled and finely grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "zest of 1 lemon, approx 3-5g", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Honey Lemon Glaze (Optional)", "items": [{"name": "powdered sugar", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": "add more to reach desired consistency", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 175\u00b0C (350\u00b0F). Grease a 23x13 cm (9x5 inch) loaf pan with butter or oil and line the bottom with parchment paper for easy removal.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a medium bowl, whisk together the flour, ground ginger, baking powder, baking soda, and salt until well combined.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a large mixing bowl or stand mixer fitted with the paddle attachment, beat the room temperature butter and granulated sugar on medium-high speed until pale and fluffy, about 3-4 minutes.", "structured": {"action": "CREAM", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Pale yellow color", "tactile": "Fluffy and aerated texture"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce mixer speed to medium. Add the honey, grated fresh ginger, and lemon zest. Beat until incorporated.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the eggs one at a time, beating well after each addition and scraping down the sides of the bowl to ensure even mixing.", "structured": {"action": "BEAT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Reduce speed to low. Add half of the dry ingredients, followed by the sour cream and lemon juice, then the remaining dry ingredients. Mix only until the flour streaks disappear. Do not overmix.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": {"visual": "No dry flour streaks remaining", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Pour the batter into the prepared loaf pan and smooth the top with a spatula. Bake in the center of the oven for 50-60 minutes, or until a toothpick inserted into the center comes out clean or with just a few moist crumbs.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT55M", "doneness_cues": {"visual": "Golden brown top with a center crack", "tactile": "Toothpick comes out clean"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Let the cake cool in the pan for 10 minutes, then transfer it to a wire rack to cool completely. If using the glaze, whisk the glaze ingredients together and drizzle over the completely cooled cake.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT1H", "total_time": "PT1H20M", "overnight_required": false, "yields": "1 standard loaf (10 slices)", "yield_count": 10, "serving_size_g": 85}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Infants under 12 months (honey)", "Vegans (eggs, dairy)", "Celiacs (gluten)"]}', '{"per_serving": {"calories": 314.85, "protein_g": 4.27, "carbohydrates_g": 48.86, "fat_g": 11.98, "saturated_fat_g": 7.06, "trans_fat_g": null, "monounsaturated_fat_g": 3.5, "polyunsaturated_fat_g": 0.69, "fiber_g": 0.75, "sugar_g": 29.28, "sodium_mg": 268.58, "cholesterol_mg": 66.6, "potassium_mg": 75.44, "calcium_mg": 49.56, "iron_mg": 0.62, "magnesium_mg": 9.48, "phosphorus_mg": 70.15, "zinc_mg": 0.41, "vitamin_a_mcg": 106.91, "vitamin_c_mg": 1.42, "vitamin_d_mcg": 0.22, "vitamin_e_mg": 0.44, "vitamin_k_mcg": 0.98, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": 0.14, "thiamin_mg": 0.04, "riboflavin_mg": 0.09, "niacin_mg": 0.36, "folate_mcg": 13.54, "water_g": 27.57, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to maintain moisture.", "duration": "P1W"}, "freezer": {"notes": "Wrap individual slices tightly in plastic wrap and foil.", "duration": "P3M"}, "reheating": "Warm slices in a toaster oven or microwave for 10-15 seconds to revive the texture.", "does_not_keep": false}', '[{"name": "Loaf pan (23x13 cm / 9x5 inch)", "required": true, "alternative": null}, {"name": "Stand mixer or hand mixer", "required": true, "alternative": "Whisk and strong arm"}, {"name": "Microplane or fine grater", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}]', '[{"symptom": "Cake sinks in the middle", "likely_cause": "The oven door was opened too early or the cake was underbaked", "prevention": "Do not open the oven door during the first 45 minutes of baking; verify doneness with a skewer before removing", "fix": "If caught early, cover with foil and return to oven immediately; otherwise, fill the divot with extra glaze or fruit compote"}, {"symptom": "Texture is tough or rubbery", "likely_cause": "Overmixing the batter after adding the flour", "prevention": "Stop mixing as soon as the last streak of flour disappears", "fix": "Cannot be fixed"}]', '["Rub the lemon zest into the sugar with your fingertips before creaming it with the butter. This releases the lemon oils for a more potent citrus aroma.", "Ensure all dairy and eggs are at room temperature. Cold ingredients will cause the butter batter to seize and curdle, leading to a denser cake.", "If the top of the loaf is browning too quickly before the center is set (check around the 40-minute mark), tent it loosely with aluminum foil.", "For a stronger ginger kick evocative of authentic Salabat, double the fresh ginger quantity."]', '"This recipe draws inspiration from ''Salabat'', a traditional Filipino ginger tea served as a restorative tonic and breakfast staple. By incorporating the tea''s core elements\u2014warm ginger, soothing honey, and bright citrus\u2014this loaf translates a beloved beverage into a comforting baked good suitable for ''Merienda'' (afternoon snack)."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('2aa2f206-8cc8-4564-ae26-9350c755da71', 'Mediterranean Lamb Burgers with Sautéed Peppers', 'Juicy, herb-infused lean lamb patties nestled in warm pita pockets, topped with sweet sautéed peppers and onions. A vibrant, protein-rich dinner that balances savory richness with fresh, zesty aromatics.', 'Dinner', 'Greek', 'Easy', '[{"group_name": "Lamb Patties", "items": [{"name": "lean ground lamb", "quantity": 500, "unit": "g", "preparation": "chilled", "notes": "at least 90% lean recommended for lower fat", "substitutions": [], "ingredient_id": "283a36a7-2de3-480f-a632-76e0445799dd", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "minced", "notes": "about 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Saut\u00e9ed Vegetables", "items": [{"name": "red bell pepper", "quantity": 1, "unit": null, "preparation": "sliced into strips", "notes": "about 150g", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}, {"name": "green bell pepper", "quantity": 1, "unit": null, "preparation": "sliced into strips", "notes": "about 150g", "substitutions": [], "ingredient_id": "627afa21-0392-4082-ab38-0f20446e190e", "nutrition_source": "Aggregated Public Data"}, {"name": "red onion", "quantity": 1, "unit": null, "preparation": "sliced into half-moons", "notes": "medium size, approx 150g", "substitutions": [], "ingredient_id": "1c270c6e-0acc-4c5c-9935-7eff3240fc4a", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Assembly & Garnish", "items": [{"name": "pita breads", "quantity": 4, "unit": null, "preparation": "warmed", "notes": "whole wheat preferred", "substitutions": [], "ingredient_id": "6bc4d0e9-228a-453e-8349-8169e84e7a7f", "nutrition_source": "Aggregated Public Data"}, {"name": "tzatziki sauce", "quantity": 120, "unit": "ml", "preparation": null, "notes": "store-bought or homemade", "substitutions": [], "ingredient_id": "d9a2dea7-8ccd-425e-87f5-d156b0d55925", "nutrition_source": "Aggregated Public Data"}, {"name": "tomato", "quantity": 1, "unit": null, "preparation": "sliced", "notes": "optional for freshness", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a large mixing bowl, gently combine the lean ground lamb, minced garlic, oregano, cumin, salt, and pepper. Use your hands to mix just until combined to ensure tenderness.", "structured": {"action": "MIX", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": ["Do not overmix the meat, or the burgers will become tough."]}, {"step_number": 2, "phase": "prep", "text": "Divide the lamb mixture into 4 equal portions. Shape each portion into an oval patty roughly the same shape as your pita pockets, about 1.5 cm (0.6 inches) thick.", "structured": {"action": "SHAPE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat half of the olive oil (7-8 ml) in a large skillet over medium-high heat. Add the lamb patties and cook for 3-4 minutes per side, or until browned and cooked through to an internal temperature of 71\u00b0C/160\u00b0F.", "structured": {"action": "SEAR", "temperature": {"celsius": 71, "fahrenheit": 160}, "duration": "PT8M", "doneness_cues": {"visual": "Deep brown crust", "tactile": "Firm to the touch"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Remove patties from the pan and set aside on a plate to rest. Drain excess fat from the pan if necessary, leaving a thin coating for flavor.", "structured": {"action": "REST", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the remaining olive oil to the same skillet. Add the sliced peppers and onions. Saut\u00e9 over medium-high heat until the vegetables are tender and slightly charred at the edges.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Softened with charred edges", "tactile": "Tender-crisp"}}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "While vegetables cook, warm the pita breads in a toaster or low oven. Slice open the tops to create pockets.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Spread a generous tablespoon of tzatziki inside each pita. Insert a lamb patty and top with the hot saut\u00e9ed pepper and onion mixture.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT10M", "total_time": "PT35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegans", "Vegetarians"]}', '{"per_serving": {"calories": 646.35, "protein_g": 29.78, "carbohydrates_g": 48.98, "fat_g": 36.6, "saturated_fat_g": 13.44, "trans_fat_g": null, "monounsaturated_fat_g": 14.88, "polyunsaturated_fat_g": 3.15, "fiber_g": 4.57, "sugar_g": 6.8, "sodium_mg": 1026.04, "cholesterol_mg": 91.25, "potassium_mg": 704.39, "calcium_mg": 130.05, "iron_mg": 4.99, "magnesium_mg": 64.57, "phosphorus_mg": 304.83, "zinc_mg": 5.14, "vitamin_a_mcg": 76.81, "vitamin_c_mg": 125.46, "vitamin_d_mcg": 0.13, "vitamin_e_mg": 1.69, "vitamin_k_mcg": 12.32, "vitamin_b6_mg": 0.33, "vitamin_b12_mcg": 2.89, "thiamin_mg": 0.56, "riboflavin_mg": 0.52, "niacin_mg": 10.89, "folate_mcg": 110.65, "water_g": 164.78, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store patties and peppers separately from pitas to prevent sogginess.", "duration": "P3D"}, "freezer": {"notes": "Cooked or raw patties freeze well; wrap individually.", "duration": "P2M"}, "reheating": "Reheat patties in a pan over medium heat or microwave gently; toast pitas fresh.", "does_not_keep": false}', '[{"name": "Large skillet or cast iron pan", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Burgers are tough or dry", "likely_cause": "Meat was overmixed or overcooked", "prevention": "Mix gently only until ingredients are incorporated and use a thermometer to pull exactly at 71\u00b0C/160\u00b0F", "fix": "Add extra tzatziki sauce to the pita to add moisture"}, {"symptom": "Burgers fall apart in the pan", "likely_cause": "Fat content too low or handled too roughly while flipping", "prevention": "Pack patties firmly (without overworking) and let a crust form before the first flip", "fix": " crumble the meat and serve as a \"loose meat\" pita filling"}]', '["Indent the center of each raw patty slightly with your thumb; this prevents them from puffing up into a ball while cooking.", "For a true low-fat version, drain the pan completely after cooking the lamb and use a quick spray of oil for the peppers instead of adding more liquid oil.", "If you have time, let the formed patties chill in the fridge for 20 minutes before cooking to help them hold their shape better."]', '"While the concept of a ground meat patty in bread is universal, this recipe draws heavily on the Greek ''bifteki'' tradition. The use of oregano, cumin, and garlic pairs classically with the cooling properties of yogurt-based tzatziki, reflecting the balance of heat and cool found in Eastern Mediterranean cuisine."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('2ca343ed-c9a6-45b9-8045-0e89974fbf48', 'Mediterranean Crispy Calamari Panzanella', 'A vibrant textural masterpiece combining golden, flash-fried calamari rings with rustic garlic-infused sourdough croutons. Sweet ripe tomatoes and biting red onion cut through the richness, all tied together with a zesty lemon-oregano vinaigrette.', 'Salad', 'Mediterranean', 'Intermediate', '[{"group_name": "Vegetables", "items": [{"name": "mixed heirloom tomatoes", "quantity": 400, "unit": "g", "preparation": "cut into wedges", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "red onion", "quantity": 1, "unit": null, "preparation": "thinly sliced", "notes": "approx 100g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "cucumber", "quantity": 150, "unit": "g", "preparation": "sliced into half-moons", "notes": null, "substitutions": [], "ingredient_id": "457adec2-3e06-4efe-a26e-9e6ea9f84924", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garlic Bread Croutons", "items": [{"name": "country sourdough bread", "quantity": 200, "unit": "g", "preparation": "torn into 3cm chunks", "notes": "preferably day-old", "substitutions": [], "ingredient_id": "90f297c6-9ec3-45a6-850d-9aa9c65b45e7", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "for frying bread", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "crushed", "notes": "approx 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Calamari", "items": [{"name": "squid tubes", "quantity": 500, "unit": "g", "preparation": "cleaned, sliced into 1cm rings", "notes": null, "substitutions": [], "ingredient_id": "e126ab3d-72fc-463a-a50c-461c65ccdf4d", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "semolina flour", "quantity": 60, "unit": "g", "preparation": null, "notes": "for crunch", "substitutions": [], "ingredient_id": "276312e9-6353-4fa7-8538-bf43246ba74e", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 100, "unit": "ml", "preparation": null, "notes": "for shallow frying", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}]}, {"group_name": "Lemon Dressing", "items": [{"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh lemon juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the sliced red onion in a small bowl and cover with cold water. Let sit for 10 minutes to remove the harsh raw bite, then drain and pat dry.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Whisk together extra virgin olive oil, lemon juice, minced garlic, oregano, and a pinch of salt and pepper in a small bowl to create the dressing. Set aside.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat 45ml olive oil in a large skillet over medium heat. Add the crushed garlic cloves to infuse the oil for 1 minute, then remove them. Add the torn bread chunks. Fry, tossing frequently, until golden brown and very crisp. Remove bread to a plate lined with paper towels.", "structured": {"action": "FRY", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT5M", "doneness_cues": {"visual": "Golden brown", "tactile": "Crisp and rigid"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a shallow bowl, mix the all-purpose flour, semolina, and salt. Pat the squid rings very dry with paper towels to ensure the coating sticks.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Wipe the skillet clean and add the vegetable oil over medium-high heat. Toss the squid rings in the flour mixture, shaking off excess. Fry in batches (do not crowd the pan) for 2-3 minutes until golden and crisp. Transfer to fresh paper towels.", "structured": {"action": "FRY", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT3M", "doneness_cues": {"visual": "Golden coating, opaque meat", "tactile": null}}, "tips": ["Crowding the pan steams the squid instead of frying it, resulting in rubbery texture."]}, {"step_number": 6, "phase": "assemble", "text": "In a large bowl, combine the tomatoes, drained onions, cucumber, parsley, and garlic croutons. Add half the dressing and toss. Top with the hot crispy calamari, drizzle with the remaining dressing, and serve immediately.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT10M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Pescatarian", "Dairy-Free", "Nut-Free"], "not_suitable_for": ["Gluten intolerance (unless GF bread/flour used)"]}', '{"per_serving": {"calories": 628.94, "protein_g": 29, "carbohydrates_g": 59.95, "fat_g": 29.16, "saturated_fat_g": 4.17, "trans_fat_g": null, "monounsaturated_fat_g": 8.38, "polyunsaturated_fat_g": 1.94, "fiber_g": 5.09, "sugar_g": 6.61, "sodium_mg": 1097.86, "cholesterol_mg": 291.25, "potassium_mg": 730.13, "calcium_mg": 84.83, "iron_mg": 2.19, "magnesium_mg": 74.6, "phosphorus_mg": 362.35, "zinc_mg": 2.57, "vitamin_a_mcg": 30.59, "vitamin_c_mg": 31.55, "vitamin_d_mcg": null, "vitamin_e_mg": 3.28, "vitamin_k_mcg": 77.74, "vitamin_b6_mg": 0.18, "vitamin_b12_mcg": 1.63, "thiamin_mg": 0.08, "riboflavin_mg": 0.55, "niacin_mg": 3.09, "folate_mcg": 26.02, "water_g": 170.47, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store components separately if possible; bread and calamari will lose crunch.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Large heavy-bottomed skillet or frying pan", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Slotted spoon or spider", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}]', '[{"symptom": "Calamari coating is soggy or falling off", "likely_cause": "Squid was too wet before dredging or oil wasn''t hot enough", "prevention": "Pat squid extremely dry; ensure oil shimmers before adding", "fix": "Cannot fix current batch; increase heat for next batch"}, {"symptom": "Calamari is rubbery and tough", "likely_cause": "Overcooked", "prevention": "Cook for no more than 2-3 minutes; remove as soon as coating is gold", "fix": "Cannot be fixed"}]', '["The semolina is crucial here; it provides a ''sandy'' crunch that stays crispier longer than plain flour when in contact with the dressing.", "Using torn bread rather than cut cubes creates craggy edges that catch more of the dressing and garlic oil.", "This dish is best assembled \u00e0 la minute. If preparing ahead, keep the fried components, salad vegetables, and dressing in three separate containers.", "If your tomatoes are very juicy, salt them in a colander for 10 minutes first to concentrate their flavor and prevent a watery salad bottom."]', '"This dish is a coastal spin on the Tuscan ''Panzanella,'' a salad originally designed to use up stale bread and ripe summer produce. By adding fried calamari (a staple of Mediterranean coastal frying or ''fritto misto''), it bridges the gap between a light peasant lunch and a substantial seafood dinner."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('2f11a20d-95ab-437b-a87c-643824a1c571', 'Lamb Tagine with Seckel Pears and Saffron', 'Tender chunks of lamb shoulder slow-braised in a fragrant sauce of turmeric, ginger, and saffron. Whole Seckel pears are poached directly in the stew, adding a honeyed sweetness that balances the savory, warming spices.', 'Main Course', 'Moroccan', 'Intermediate', '[{"group_name": "Lamb and Aromatics", "items": [{"name": "boneless lamb shoulder", "quantity": 1000, "unit": "g", "preparation": "cut into 4cm cubes", "notes": "Leg can be used but shoulder yields better texture", "substitutions": [], "ingredient_id": "27672021-dc31-45a5-9ce8-f08dbbae93b4", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onions", "quantity": 2, "unit": null, "preparation": "finely diced", "notes": "approx 300g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx 20g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 15, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Spice Blend", "items": [{"name": "ground turmeric", "quantity": 1, "unit": null, "preparation": "teaspoon", "notes": "approx 3g", "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 1, "unit": null, "preparation": "teaspoon", "notes": "approx 3g", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "ground coriander", "quantity": 1, "unit": null, "preparation": "teaspoon", "notes": "approx 2g", "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "sweet paprika", "quantity": 1, "unit": null, "preparation": "teaspoon", "notes": "approx 3g", "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 5g", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "saffron threads", "quantity": 1, "unit": null, "preparation": null, "notes": "generous pinch, soaked in 15ml warm water", "substitutions": [], "ingredient_id": "7f9ec0c8-2db1-48ac-a2c9-9b1efce12cf3", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 10, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Liquids and Fruit", "items": [{"name": "lamb or chicken stock", "quantity": 500, "unit": "ml", "preparation": null, "notes": "low sodium preferred", "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "seckel pears", "quantity": 6, "unit": null, "preparation": null, "notes": "firm, approx 450g total", "substitutions": [], "ingredient_id": "ed5dd928-efa8-4c10-aeb3-3c08c94c62f8", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "blanched almonds", "quantity": 30, "unit": "g", "preparation": "toasted", "notes": null, "substitutions": [], "ingredient_id": "859f0247-6cc6-47f4-b38e-d2696789442f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 10, "unit": "g", "preparation": "roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the lamb cubes dry with paper towels and season generously with the salt and black pepper.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the olive oil in the tagine base or Dutch oven over medium-high heat. Sear the lamb in batches until browned on all sides, then remove to a plate.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": {"visual": "Deep golden brown crust", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to medium. Add the onions to the pot and saut\u00e9 until softened and translucent, about 5-8 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Translucent and soft", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stir in the garlic, grated ginger, turmeric, cumin, coriander, and paprika. Toast the spices for 1 minute until fragrant, being careful not to burn them.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Spices darken slightly", "tactile": "Very aromatic"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Return the lamb and its juices to the pot. Add the cinnamon stick, saffron (with its soaking water), and stock. Bring to a boil, then reduce heat to low, cover, and simmer for 1.5 hours.", "structured": {"action": "BRAISE", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT1H30M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "While the lamb simmers, peel the Seckel pears, leaving the stems intact for presentation. You may core them from the bottom if desired, but leaving them whole helps them hold their shape.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "After the lamb has cooked for 1.5 hours, uncover the pot. Stir in the honey, then nestle the peeled pears into the liquid. Cover and continue to simmer for another 20-30 minutes until pears are tender.", "structured": {"action": "STEW", "temperature": null, "duration": "PT30M", "doneness_cues": {"visual": null, "tactile": "Pears easily pierced with knife, lamb fork-tender"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Check the sauce consistency. If too thin, remove the pears and meat carefully and boil the liquid to reduce until it coats the back of a spoon. Discard the cinnamon stick.", "structured": {"action": "REDUCE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Sauce is glossy and thickened", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Return meat and pears to the sauce if separated. Garnish with toasted almonds and fresh cilantro. Serve hot.", "structured": {"action": "SERVE", "temperature": {"celsius": 70, "fahrenheit": 158}, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT2H", "total_time": "PT2H35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Dairy-Free", "Gluten-Free", "Egg-Free", "Soy-Free", "Paleo"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 659.49, "protein_g": 54.51, "carbohydrates_g": 38.28, "fat_g": 33.73, "saturated_fat_g": 6.21, "trans_fat_g": null, "monounsaturated_fat_g": 8.28, "polyunsaturated_fat_g": 1.96, "fiber_g": 7.29, "sugar_g": 20.94, "sodium_mg": 6031.05, "cholesterol_mg": null, "potassium_mg": 608.9, "calcium_mg": 84.21, "iron_mg": 3.36, "magnesium_mg": 60.24, "phosphorus_mg": 217.84, "zinc_mg": 4.21, "vitamin_a_mcg": 71.01, "vitamin_c_mg": 12.5, "vitamin_d_mcg": null, "vitamin_e_mg": 3.34, "vitamin_k_mcg": 11.81, "vitamin_b6_mg": 0.23, "vitamin_b12_mcg": null, "thiamin_mg": 0.08, "riboflavin_mg": 0.13, "niacin_mg": 0.76, "folate_mcg": 27.38, "water_g": 169.34, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors improve significantly after 24 hours.", "duration": "P3D"}, "freezer": {"notes": "Freeze without the pears if possible, as their texture may degrade upon thawing.", "duration": "P3M"}, "reheating": "Reheat gently on the stove over low heat, adding a splash of water if the sauce has thickened too much.", "does_not_keep": false}', '[{"name": "Tagine or Dutch Oven", "required": true, "alternative": "Heavy-bottomed pot with tight lid"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Vegetable peeler", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}]', '[{"symptom": "Sauce is too watery", "likely_cause": "Modern Dutch ovens trap moisture more efficiently than clay tagines, preventing reduction", "prevention": "Use slightly less stock initially", "fix": "Remove solids and boil sauce vigorously for 5-10 minutes to reduce"}, {"symptom": "Pears are falling apart", "likely_cause": "Added too early or heat was too high", "prevention": "Add pears only in the last 20-30 minutes of cooking", "fix": "Remove immediately and serve as a compote on the side"}]', '["Seckel pears are ideal because of their small size and firm texture. If unavailable, use firm Bosc pears, peeled, cored, and quartered.", "Browning the lamb thoroughly in step 2 is critical for developing the rich base flavor of the sauce (Maillard reaction).", "If using a traditional clay tagine, a heat diffuser is necessary on electric or gas stovetops to prevent the clay from cracking.", "This dish is best served with couscous or warm crusty bread to soak up the sauce."]', '"Tagine refers to both the conical earthenware pot and the stew cooked within it. This recipe balances ''hlu'' (sweet) and ''maleh'' (savory), a signature profile of Moroccan cuisine often reserved for celebrations and guests."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('2f856299-721c-4807-b197-c8405158a60e', 'Baked Eggs with Tuna Pomodoro and Whipped Garlic Ricotta', 'A rustic, protein-rich Italian dish featuring eggs gently baked in a savory sauce of tomatoes, olive-oil-packed tuna, and aromatics. Finished with cool dollops of garlicky whipped ricotta for a striking contrast of temperatures and textures.', 'Main Course', 'Italian', 'Easy', '[{"group_name": "Garlic Ricotta", "items": [{"name": "whole milk ricotta", "quantity": 120, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "7a68dbea-ec03-42ae-b0eb-983bf3d4c7b6", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "grated or pressed", "notes": "approx 3g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": null, "unit": null, "preparation": "freshly grated", "notes": "from half a lemon", "substitutions": [], "ingredient_id": "a5fb6a2a-dcda-4ab2-8fe6-472d7fcc39d1", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Tomato Tuna Base", "items": [{"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "red chili flakes", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "canned tuna in olive oil", "quantity": 160, "unit": "g", "preparation": "drained", "notes": "solid pack preferred", "substitutions": [], "ingredient_id": "cf38e1f7-29ee-435e-b96b-f63164087af6", "nutrition_source": "USDA FoodData Central"}, {"name": "crushed tomatoes", "quantity": 400, "unit": "g", "preparation": "canned", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "dried oregano", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "To Finish", "items": [{"name": "large eggs", "quantity": 4, "unit": null, "preparation": null, "notes": "approx 200g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh parsley", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 200\u00b0C/400\u00b0F. Ensure the rack is in the center position.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small bowl, whisk the ricotta, grated garlic, lemon zest (if using), 5ml olive oil, and sea salt until smooth and creamy. Refrigerate until serving.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Smooth, aerated texture", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat 15ml olive oil in an oven-safe skillet over medium heat. Saut\u00e9 the diced onion until softened and translucent.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT5M", "doneness_cues": {"visual": "Onions are translucent but not browned", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the sliced garlic and red chili flakes. Cook for 1 minute until fragrant, being careful not to burn the garlic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Stir in the drained tuna, breaking up large chunks gently. Add the crushed tomatoes and dried oregano. Bring to a simmer and let cook for 5 minutes to thicken slightly.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT5M", "doneness_cues": {"visual": "Sauce has thickened enough to hold a depression", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Remove skillet from heat. Use the back of a spoon to make four indentations in the sauce. Crack one egg into each indentation.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Transfer the skillet to the preheated oven. Bake until the egg whites are set but the yolks are still runny. Monitor closely.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT8M", "doneness_cues": {"visual": "Whites opaque, yolks jiggle slightly when pan is shaken", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from oven. Immediately dollop the cold garlic ricotta over the hot sauce (avoiding the yolks). Garnish with fresh parsley and black pepper. Serve immediately.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT15M", "total_time": "PT30M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 380}', '{"flags": ["Pescatarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Low-Carb"], "not_suitable_for": ["Fish allergy", "Egg allergy", "Dairy allergy"]}', '{"per_serving": {"calories": 560.6, "protein_g": 43.64, "carbohydrates_g": 23.18, "fat_g": 32.93, "saturated_fat_g": 9.73, "trans_fat_g": 0.24, "monounsaturated_fat_g": 14.97, "polyunsaturated_fat_g": 5.68, "fiber_g": 6.06, "sugar_g": 11.73, "sodium_mg": 779.28, "cholesterol_mg": 415.8, "potassium_mg": 1090.89, "calcium_mg": 261.92, "iron_mg": 4.53, "magnesium_mg": 85.88, "phosphorus_mg": 622.67, "zinc_mg": 2.96, "vitamin_a_mcg": 276.74, "vitamin_c_mg": 39, "vitamin_d_mcg": 7.48, "vitamin_e_mg": 3.86, "vitamin_k_mcg": 91.66, "vitamin_b6_mg": 0.5, "vitamin_b12_mcg": 3.16, "thiamin_mg": 0.13, "riboflavin_mg": 0.79, "niacin_mg": 10.4, "folate_mcg": 74.45, "water_g": 241.01, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten fresh; yolks will harden upon reheating.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze.", "duration": null}, "reheating": "Reheat gently in a covered skillet on low heat, though texture will change.", "does_not_keep": false}', '[{"name": "Oven-safe skillet (25cm)", "required": true, "alternative": "Standard skillet plus baking dish"}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": "Fork"}, {"name": "Knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Egg yolks are hard/chalky", "likely_cause": "Overcooked due to residual heat in the cast iron skillet", "prevention": "Remove the skillet from the oven when the whites are just barely set; they will continue to cook on the counter.", "fix": "Cannot be fixed, but sauce will still be delicious."}, {"symptom": "Sauce is too watery", "likely_cause": "Tomatoes were not reduced enough before adding eggs", "prevention": "Simmer sauce longer before cracking eggs; ensure tuna is well-drained.", "fix": "Serve with extra bread to soak up liquid."}]', '["Use tuna packed in olive oil (Tonno all''olio di oliva) rather than water; the fat carries the flavor and prevents the fish from becoming dry during baking.", "The contrast between the piping hot, acidic tomato sauce and the cold, creamy ricotta is essential to this dish. Do not add the ricotta before baking.", "Serve with toasted ciabatta or sourdough to ''fare la scarpetta'' (make the little shoe)\u2014the Italian act of mopping up sauce with bread.", "If you do not have an oven-safe skillet, you can transfer the sauce to a ceramic baking dish before cracking the eggs.", "For perfectly even cooking, ensure your eggs are at room temperature before cracking them into the hot sauce."]', '"This dish is a pescatarian riff on ''Uova al Purgatorio'' (Eggs in Purgatory), a Neapolitan classic. The addition of tuna transforms it into a robust main course, reflecting the ''cucina povera'' tradition of using pantry staples like canned fish and tomatoes to create nutritious, satisfying meals."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('2feae634-6a29-437c-8045-56e781e0ea5b', 'Lemon & Pine Nut Cornmeal Cookies', 'Golden, tender cookies with a delicate crumb somewhere between a buttery shortbread and a soft madeleine. The fine cornmeal adds a pleasing sunny hue and subtle texture, while lemon zest and toasted pine nuts provide a sophisticated, aromatic finish perfect for tea time.', 'Dessert', 'Italian', 'Intermediate', '[{"group_name": "Wet Ingredients", "items": [{"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "room temperature", "notes": "softened", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": "finely grated", "notes": "approx 6g", "substitutions": [], "ingredient_id": "03fb65be-9b62-44e7-a121-694de64cdec0", "nutrition_source": "Aggregated Public Data"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "room temperature", "notes": "large, approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dry Ingredients & Mix-ins", "items": [{"name": "all-purpose flour", "quantity": 140, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "fine yellow cornmeal", "quantity": 65, "unit": "g", "preparation": null, "notes": "must be fine grind, not coarse polenta", "substitutions": [], "ingredient_id": "7fb6be00-5ba2-483a-af74-961f21de4055", "nutrition_source": "Aggregated Public Data"}, {"name": "baking powder", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "pine nuts", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "971298ad-a9d7-49f7-811b-46afedad18d4", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the pine nuts in a small dry skillet over medium-low heat. Toast, shaking the pan frequently, until fragrant and lightly golden (approx 3-4 minutes). Remove immediately to a cool plate to stop cooking.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Lightly golden brown", "tactile": "Fragrant"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a medium bowl, whisk together the flour, fine cornmeal, baking powder, and salt. Stir in the cooled pine nuts.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In the bowl of a stand mixer fitted with the paddle attachment, combine the softened butter, sugar, and lemon zest. Beat on medium-high speed until pale and fluffy, about 3-4 minutes. This aeration creates the madeleine-like texture.", "structured": {"action": "CREAM", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Pale yellow and increased volume", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Add the egg and vanilla extract to the butter mixture. Beat on medium speed until fully incorporated and smooth, scraping down the sides of the bowl as needed.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Reduce mixer speed to low. Add the dry ingredient mixture in two batches, mixing only until just combined and no streaks of flour remain. Do not overmix.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Uniform dough with no dry flour", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Cover the bowl with plastic wrap and refrigerate the dough for at least 1 hour. This hydrates the cornmeal and ensures the cookies hold their shape.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Preheat the oven to 175\u00b0C (350\u00b0F). Line two baking sheets with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Scoop the chilled dough into tablespoon-sized mounds (approx 20g each) and roll into balls. Place on prepared baking sheets spaced 5cm (2 inches) apart. Flatten slightly with the palm of your hand.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Bake for 10-12 minutes, or until the edges are golden brown and the centers are set but soft. Rotate pans halfway through baking.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT12M", "doneness_cues": {"visual": "Golden edges, matte tops", "tactile": null}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Allow cookies to cool on the baking sheet for 5 minutes before transferring to a wire rack to cool completely. They will firm up as they cool.", "structured": {"action": "COOL", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT1H15M", "total_time": "PT1H40M", "overnight_required": false, "yields": "24 cookies", "yield_count": 24, "serving_size_g": 22}', '{"flags": ["Vegetarian", "Soy-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 99.44, "protein_g": 1.5, "carbohydrates_g": 11.67, "fat_g": 5.24, "saturated_fat_g": 2.63, "trans_fat_g": null, "monounsaturated_fat_g": 1.2, "polyunsaturated_fat_g": 0.21, "fiber_g": 0.46, "sugar_g": 4.3, "sodium_mg": 55.3, "cholesterol_mg": 18.05, "potassium_mg": 29.29, "calcium_mg": 13.68, "iron_mg": 0.39, "magnesium_mg": 12.43, "phosphorus_mg": 37.25, "zinc_mg": 0.27, "vitamin_a_mcg": 36.7, "vitamin_c_mg": null, "vitamin_d_mcg": 0.04, "vitamin_e_mg": 0.14, "vitamin_k_mcg": 0.36, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.08, "folate_mcg": 2.64, "water_g": 3.18, "alcohol_g": 0.07, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in airtight container; texture is best at room temperature.", "duration": "P1W"}, "freezer": {"notes": "Freeze raw dough balls or baked cookies.", "duration": "P3M"}, "reheating": "None required, but can be warmed briefly in a low oven if desired.", "does_not_keep": false}', '[{"name": "Stand mixer or electric hand mixer", "required": true, "alternative": null}, {"name": "Baking sheets", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Microplane or zester", "required": true, "alternative": null}, {"name": "Small skillet", "required": true, "alternative": "Oven tray for toasting nuts"}]', '[{"symptom": "Cookies spread flat and look greasy", "likely_cause": "Butter was too warm or dough wasn''t chilled long enough", "prevention": "Ensure butter is room temp (not melted) and chill dough for full hour", "fix": "Chill the remaining dough on the baking sheet for 15 minutes before baking"}, {"symptom": "Texture is gritty or crunchy rather than tender", "likely_cause": "Cornmeal grind was too coarse", "prevention": "Use ''fine'' cornmeal or corn flour, not coarse polenta grits", "fix": "Cannot be fixed after baking"}]', '["The grind of the cornmeal dictates the texture. For the requested ladyfinger/madeleine tenderness, look for ''fine'' stone-ground cornmeal or corn flour. Coarse grits will result in a hard crunch.", "Rubbing the lemon zest into the sugar with your fingers before creaming with the butter will release more essential oils and result in a more fragrant cookie.", "Pine nuts burn easily. Watch them closely while toasting in the skillet; they can go from golden to burnt in seconds.", "These cookies improve after 24 hours as the moisture from the butter softens the cornmeal further."]', '"These cookies draw inspiration from the Italian ''Paste di Meliga'', traditional Piedmontese cornmeal biscuits born from necessity when wheat prices rose. While traditional versions are often piped and crunchy, this variation incorporates the loftier, sponge-like texture found in French madeleines."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('30fbabfa-3766-4873-9d73-a3ce75a93d3b', 'Quick Miso-Glazed Black Cod', 'A streamlined version of the iconic Japanese dish. Buttery, flakey black cod fillets are coated in a sweet and savory umami-packed glaze that caramelizes under the broiler, delivering restaurant-quality flavor in under an hour.', 'Dinner', 'Japanese', 'Easy', '[{"group_name": "Fish", "items": [{"name": "black cod fillets", "quantity": 4, "unit": null, "preparation": "skin-on or off", "notes": "approx. 150g each (600g total), also known as Sablefish", "substitutions": ["Chilean Sea Bass", "Salmon fillets"], "ingredient_id": "229ccaef-c763-440b-b44f-6e22222d3fd1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Miso Glaze", "items": [{"name": "white miso paste", "quantity": 80, "unit": "g", "preparation": "smooth", "notes": "Shiro miso", "substitutions": [], "ingredient_id": "46697260-96ba-4751-83c0-b40aebb81229", "nutrition_source": "USDA FoodData Central"}, {"name": "mirin", "quantity": 30, "unit": "ml", "preparation": null, "notes": "sweet rice wine", "substitutions": [], "ingredient_id": "2a72c18d-8a1d-4259-8790-25d62f6fb5ba", "nutrition_source": "Aggregated Public Data"}, {"name": "sake", "quantity": 30, "unit": "ml", "preparation": null, "notes": "dry japanese rice wine", "substitutions": ["water", "dry sherry"], "ingredient_id": "1cfffbd2-7ea5-4cbc-bc35-c57e12233152", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 25, "unit": "g", "preparation": null, "notes": "dissolves easier than coarse sugar", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the black cod fillets completely dry with paper towels. Excess moisture will prevent the glaze from adhering and diluting the flavor.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small bowl, whisk together the white miso, mirin, sake, and sugar until the sugar is fully dissolved and the texture is smooth.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Brush or spoon the glaze generously over the top and sides of each fillet. Let them sit at room temperature for 30 minutes. This allows the salt in the miso to cure the fish slightly and flavors to penetrate.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While the fish marinates, preheat your oven to 200\u00b0C (400\u00b0F). Line a baking sheet with aluminum foil and lightly grease it to prevent sticking.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Place the fillets on the prepared baking sheet, skin-side down (if applicable). Bake for 10-12 minutes, or until the fish is opaque and begins to flake.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT12M", "doneness_cues": {"visual": "Fish is opaque", "tactile": "Flakes gently with pressure"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Switch the oven to ''Broil'' (High). Move the baking sheet to the upper rack and broil for 2-3 minutes. Watch closely\u2014the sugars in the miso can burn in seconds. You want a deep golden brown spotty caramelization (bubbling glaze).", "structured": {"action": "BROIL", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Deep golden brown spots, bubbling glaze", "tactile": null}}, "tips": ["Do not walk away during this step; miso goes from caramelized to charcoal very quickly."]}, {"step_number": 7, "phase": "finish", "text": "Remove from oven and let rest for 2 minutes before serving. The internal temperature should reach at least 63\u00b0C (145\u00b0F).", "structured": {"action": "REST", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": "PT2M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT30M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 170}', '{"flags": ["Pescatarian", "Dairy-Free", "Egg-Free", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 213.75, "protein_g": 29.32, "carbohydrates_g": 15.4, "fat_g": 2.21, "saturated_fat_g": 0.4, "trans_fat_g": null, "monounsaturated_fat_g": 0.36, "polyunsaturated_fat_g": 0.92, "fiber_g": 1.08, "sugar_g": 11, "sodium_mg": 849.98, "cholesterol_mg": 64.5, "potassium_mg": 663.5, "calcium_mg": 35.84, "iron_mg": 1.08, "magnesium_mg": 58.05, "phosphorus_mg": 336.75, "zinc_mg": 1.19, "vitamin_a_mcg": 18.8, "vitamin_c_mg": 1.5, "vitamin_d_mcg": 1.35, "vitamin_e_mg": 0.96, "vitamin_k_mcg": 6.01, "vitamin_b6_mg": 0.4, "vitamin_b12_mcg": 1.38, "thiamin_mg": 0.14, "riboflavin_mg": 0.15, "niacin_mg": 3.27, "folate_mcg": 14.3, "water_g": 136.28, "alcohol_g": 1.21, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best enjoyed immediately; reheat gently to avoid drying out.", "duration": "P2D"}, "freezer": {"notes": "Cooked fish does not freeze well; texture will degrade.", "duration": null}, "reheating": "Warm in a 150\u00b0C/300\u00b0F oven for 5-8 minutes.", "does_not_keep": false}', '[{"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Aluminum foil", "required": true, "alternative": "Parchment paper (caution under broiler)"}, {"name": "Whisk or fork", "required": true, "alternative": null}, {"name": "Pastry brush", "required": false, "alternative": "Spoon"}]', '[{"symptom": "Glaze is burnt/blackened", "likely_cause": "Broiled too close to the heating element or for too long", "prevention": "Watch constantly during the broiling step; keep rack 6 inches from heat", "fix": "Scrape off the burnt layer; the fish underneath is likely still moist"}, {"symptom": "Fish is rubbery or tough", "likely_cause": "Overcooked", "prevention": "Check for flakiness early; black cod is fatty and forgiving but can still dry out", "fix": "Cannot be fixed; flake into a salad or soup to mask texture"}]', '["While this ''quick'' version rests for 30 minutes, the traditional Nobu-style preparation involves marinating the fish for 2-3 days in the fridge. If you have time, extend the marinating step for deeper flavor.", "Black cod (Sablefish) is extremely rich in omega-3 fats, giving it a luxurious, buttery texture that is forgiving to cook. If unavailable, Chilean Sea Bass is the closest substitute.", "Make sure to use ''White Miso'' (Shiro Miso) rather than Red Miso. Red miso is too salty and robust for this delicate preparation."]', '"Gindara no Saikyo Yaki (Miso Marinated Black Cod) is a traditional Japanese dish originating from Kyoto, popularized globally by Chef Nobu Matsuhisa. The technique uses the preservation properties of miso and sake lees to cure the fatty fish."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('33d1b55f-b202-4122-a58f-835f147ffb66', 'Mediterranean Roasted Cauliflower with Feta and Olives', 'Golden, caramelized cauliflower florets meet the salty tang of feta and brine-cured olives, finished with the crunch of toasted almonds. A vibrant, textural side dish that balances savory depth with bright Mediterranean flavors.', 'Side Dish', 'Mediterranean', 'Easy', '[{"group_name": "Roasted Cauliflower", "items": [{"name": "cauliflower", "quantity": 1, "unit": null, "preparation": "cut into florets", "notes": "1 large head, approx. 800g-1kg", "substitutions": [], "ingredient_id": "2d9d5068-77e7-4dfc-b24b-8e6a6275cb33", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx. 1/2 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Toppings & Assembly", "items": [{"name": "feta cheese", "quantity": 100, "unit": "g", "preparation": "crumbled", "notes": null, "substitutions": ["goat cheese", "vegan feta"], "ingredient_id": "a9a8605c-3bf2-4ca3-8c58-80e87aff7cd8", "nutrition_source": "USDA FoodData Central"}, {"name": "kalamata olives", "quantity": 60, "unit": "g", "preparation": "pitted and sliced", "notes": null, "substitutions": [], "ingredient_id": "a0555be5-08e9-4d8e-9c05-5f5063ebd6bc", "nutrition_source": "USDA FoodData Central"}, {"name": "sliced almonds", "quantity": 40, "unit": "g", "preparation": "raw", "notes": null, "substitutions": ["pine nuts", "walnuts"], "ingredient_id": "cc530a54-fc67-4fb1-8ece-569ae4388041", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh parsley", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "freshly squeezed, about 1/2 lemon", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 220\u00b0C/425\u00b0F. High heat is essential for caramelization.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large bowl, toss the cauliflower florets with olive oil, kosher salt, black pepper, and dried oregano until evenly coated.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Spread the cauliflower in a single layer on a rimmed baking sheet. Ensure there is space between florets to avoid steaming.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT20M", "doneness_cues": {"visual": "Deep golden brown edges and tender stems", "tactile": null}}, "tips": ["Use two baking sheets if necessary to prevent overcrowding."]}, {"step_number": 4, "phase": "cook", "text": "While the cauliflower roasts, heat a small dry skillet over medium heat. Add the sliced almonds and toast, stirring constantly, until golden and fragrant (about 3-4 minutes). Remove from heat immediately.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Light golden brown color", "tactile": "Fragrant nutty aroma"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Roast the cauliflower for 20-25 minutes total, tossing halfway through, until tender and charred at the edges.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT25M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Transfer the hot roasted cauliflower to a serving dish. Immediately toss with the crumbled feta, sliced olives, toasted almonds, fresh parsley, and lemon juice.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Adding the feta while the cauliflower is hot helps it soften and meld with the other flavors."]}]', '{"active_time": "PT15M", "passive_time": "PT25M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Vegetarian", "Gluten-Free", "Low-Carb", "Keto", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 298.62, "protein_g": 10.24, "carbohydrates_g": 15.81, "fat_g": 23.93, "saturated_fat_g": 5.89, "trans_fat_g": null, "monounsaturated_fat_g": 10.59, "polyunsaturated_fat_g": 1.5, "fiber_g": 6.23, "sugar_g": 4.81, "sodium_mg": 754.83, "cholesterol_mg": 22.25, "potassium_mg": 706.89, "calcium_mg": 220.3, "iron_mg": 2.79, "magnesium_mg": 67.86, "phosphorus_mg": 185.49, "zinc_mg": 1.39, "vitamin_a_mcg": 39.34, "vitamin_c_mg": 111.71, "vitamin_d_mcg": 0.1, "vitamin_e_mg": 2.15, "vitamin_k_mcg": 64.77, "vitamin_b6_mg": 0.52, "vitamin_b12_mcg": 0.42, "thiamin_mg": 0.15, "riboflavin_mg": 0.35, "niacin_mg": 1.44, "folate_mcg": 139.54, "water_g": 237.65, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Texture will soften upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; cauliflower becomes mushy and feta texture degrades.", "duration": null}, "reheating": "Reheat in a 180\u00b0C/350\u00b0F oven for 5-10 minutes to restore crispness, or microwave briefly if texture is less important.", "does_not_keep": false}', '[{"name": "Large rimmed baking sheet", "required": true, "alternative": "Two smaller baking sheets"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Small skillet", "required": false, "alternative": "Baking sheet (for toasting almonds)"}]', '[{"symptom": "Cauliflower is mushy and pale instead of crispy", "likely_cause": "Overcrowding the baking sheet caused the vegetables to steam instead of roast", "prevention": "Ensure florets are in a single layer with air gaps between them; use two trays if needed", "fix": "Spread onto a second tray and return to oven on convection/fan mode for 5 minutes"}, {"symptom": "Almonds are burnt", "likely_cause": "Left unattended in the hot pan or oven", "prevention": "Watch nuts constantly while toasting; they go from raw to burnt in seconds", "fix": "Discard and re-toast a new batch; burnt nuts are unfixably bitter"}]', '["Cut the cauliflower florets into similar sizes (about 3-4cm) to ensure even cooking.", "For an extra depth of flavor, add a pinch of red chili flakes or lemon zest during the final toss.", "If you prefer a warm salad texture, allow the cauliflower to cool for 5 minutes before tossing with the feta to keep the cheese more distinct."]', '"This dish draws heavily from Eastern Mediterranean and Levantine cuisine, where the combination of salty cheese (feta/halloumi), rich olive oil, and bright citrus is a staple. Roasting vegetables to bring out their natural sweetness before pairing them with briny elements is a classic technique found in Greek and Turkish tables."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('3cdbc11f-164e-464c-9e21-62bba5339963', 'Warm Citrus Salmon Salad', 'Succulent pan-seared salmon fillets served atop tender roasted baby potatoes and crisp asparagus, tossed with fresh greens and a zesty orange-lemon vinaigrette.', 'Salad', 'Mediterranean', 'Easy', '[{"group_name": "Roasted Vegetables", "items": [{"name": "baby potatoes", "quantity": 250, "unit": "g", "preparation": "halved", "notes": null, "substitutions": [], "ingredient_id": "41f30ad1-82e5-4826-9de0-cd33ecd578c1", "nutrition_source": "USDA FoodData Central"}, {"name": "asparagus spears", "quantity": 150, "unit": "g", "preparation": "woody ends trimmed", "notes": "approx 10-12 spears", "substitutions": [], "ingredient_id": "8a2a9426-3755-4553-953a-fd9cf42cef90", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for roasting", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 2g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Salmon", "items": [{"name": "salmon fillets", "quantity": 300, "unit": "g", "preparation": "skin-on or skinless", "notes": "2 fillets, approx 150g each", "substitutions": [], "ingredient_id": "671c418a-0b74-45a8-a8b9-e4fd2f40e8ff", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 10, "unit": "ml", "preparation": null, "notes": "for searing", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "generous pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Citrus Dressing", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh orange juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a15da11d-f8dd-46e3-9ac5-725a7912f1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": ["maple syrup"], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Assembly", "items": [{"name": "mixed salad greens", "quantity": 80, "unit": "g", "preparation": "washed and dried", "notes": "spinach, arugula, or mesclun", "substitutions": [], "ingredient_id": "f84cf2f5-c8cc-4095-8c77-aedf16352c61", "nutrition_source": "Aggregated Public Data"}, {"name": "avocado", "quantity": 1, "unit": null, "preparation": "sliced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "2f40a31e-80a0-4265-b6f3-99ed88ee4c24", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 200\u00b0C (400\u00b0F). Toss the halved baby potatoes with 15ml olive oil, salt, and pepper on a large baking sheet.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Roast the potatoes for 15 minutes initially. While they roast, prepare the asparagus by trimming the woody ends.", "structured": {"action": "ROAST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Remove the baking sheet from the oven, push potatoes to one side, and add the asparagus. Return to the oven for another 10-12 minutes until vegetables are tender and slightly browned.", "structured": {"action": "ROAST", "temperature": null, "duration": "PT12M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "While vegetables finish roasting, whisk together extra virgin olive oil, orange juice, lemon juice, honey, and Dijon mustard in a small bowl or jar until emulsified. Season with salt and pepper to taste.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pat salmon fillets dry and season generously with salt. Heat 10ml olive oil in a skillet over medium-high heat. Sear salmon (skin-side down first if applicable) for 3-4 minutes per side until golden and cooked to your preference (aim for 52\u00b0C/125\u00b0F internal for medium).", "structured": {"action": "SEAR", "temperature": {"celsius": 52, "fahrenheit": 126}, "duration": "PT8M", "doneness_cues": {"visual": "Opaque and flakes easily with a fork", "tactile": "Firm but yielding to touch"}}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Arrange a bed of mixed greens on plates. Top with the warm roasted potatoes, asparagus, and avocado slices.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Place the warm salmon fillet on top of the salad. Drizzle generously with the citrus dressing and serve immediately.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT25M", "total_time": "PT45M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 450}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 1237.56, "protein_g": 43.07, "carbohydrates_g": 121.04, "fat_g": 66.87, "saturated_fat_g": 11.16, "trans_fat_g": null, "monounsaturated_fat_g": 22.16, "polyunsaturated_fat_g": 8.76, "fiber_g": 14.65, "sugar_g": 12.33, "sodium_mg": 791.55, "cholesterol_mg": 82.5, "potassium_mg": 2486.82, "calcium_mg": 145.2, "iron_mg": 4.71, "magnesium_mg": 167.87, "phosphorus_mg": 662.54, "zinc_mg": 2.25, "vitamin_a_mcg": 241.59, "vitamin_c_mg": 37.53, "vitamin_d_mcg": 16.5, "vitamin_e_mg": 9.86, "vitamin_k_mcg": 56.06, "vitamin_b6_mg": 2.2, "vitamin_b12_mcg": 4.85, "thiamin_mg": 0.78, "riboflavin_mg": 0.5, "niacin_mg": 19.51, "folate_mcg": 176.19, "water_g": 251.39, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store dressing separately from greens to prevent wilting. Salmon and roasted vegetables keep well.", "duration": "P2D"}, "freezer": {"notes": "Not recommended for salad components.", "duration": null}, "reheating": "Gently reheat salmon and roasted vegetables in a pan or microwave before assembling with cold greens.", "does_not_keep": false}', '[{"name": "Large baking sheet", "required": true, "alternative": null}, {"name": "Non-stick skillet", "required": true, "alternative": "Cast iron pan"}, {"name": "Small jar or whisking bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Salmon is dry or tough", "likely_cause": "Overcooking; salmon continues to cook after being removed from heat", "prevention": "Remove salmon from the pan when it is slightly underdone in the center (translucent pink)", "fix": "Flake the fish into smaller pieces and toss thoroughly with extra dressing to add moisture"}, {"symptom": "Dressing tastes too acidic", "likely_cause": "Imbalanced ratio of vinegar/citrus to oil", "prevention": "Measure liquids carefully", "fix": "Add a small amount of extra honey or olive oil to balance the acidity"}]', '["Pat the salmon very dry with paper towels before searing to ensure a crispy crust rather than steaming the fish.", "If using skin-on salmon, sear about 80% of the time on the skin side to get it crispy, then flip just to finish.", "The contrast between the warm fish/vegetables and the cool, crisp greens is key to this dish; do not assemble until just before eating.", "For extra crunch, garnish with toasted sliced almonds or pine nuts."]', '"Warm salads are a staple of modern bistro dining, bridging the gap between light fare and comforting meals. This recipe highlights the Mediterranean tradition of pairing oily fish with bright citrus acids to cut through the richness."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('41fcee31-e9fc-4ce1-a550-6e50414abedc', 'Strawberry Red Wine Matzo Layer Bars', 'A sweet, custardy Passover dessert reminiscent of a fruity lasagna or kugel. Layers of matzo softened in a spiced red wine egg batter alternate with sticky strawberry preserves, finished with a rich honey-butter glaze that caramelizes the edges.', 'Dessert', 'Jewish', 'Intermediate', '[{"group_name": "Red Wine Egg Batter", "items": [{"name": "large eggs", "quantity": 4, "unit": null, "preparation": "beaten", "notes": "approx. 200g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "sweet red wine", "quantity": 80, "unit": "ml", "preparation": null, "notes": "Kosher sweet wine (e.g., Manischewitz) or Ruby Port", "substitutions": [], "ingredient_id": "0fc93141-8ba8-42e0-ac8b-b5af3851554c", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx. 1 tsp", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Layers", "items": [{"name": "matzo sheets", "quantity": 6, "unit": null, "preparation": null, "notes": "plain, unsalted", "substitutions": [], "ingredient_id": "bce3d6d8-f342-4519-b3b7-5f3461243243", "nutrition_source": "USDA FoodData Central"}, {"name": "strawberry preserves", "quantity": 250, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "635edf1d-bc9a-412f-8753-b3a2370297ae", "nutrition_source": "Aggregated Public Data"}, {"name": "ground cinnamon", "quantity": 1, "unit": "g", "preparation": null, "notes": "for dusting layers", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Honey-Butter Glaze", "items": [{"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 60, "unit": "ml", "preparation": null, "notes": "approx. 85g", "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "sweet red wine", "quantity": 15, "unit": "ml", "preparation": null, "notes": "optional splash for color", "substitutions": [], "ingredient_id": "0fc93141-8ba8-42e0-ac8b-b5af3851554c", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 175\u00b0C (350\u00b0F). Grease a 20cm (8-inch) square baking dish with butter or neutral oil.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a wide shallow bowl, whisk together eggs, 80ml sweet red wine, vanilla extract, 3g cinnamon, and salt until completely thoroughly combined.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "Dip a sheet of matzo into the egg mixture, letting it soak for about 30 seconds per side until slightly pliable but not falling apart. Break pieces if necessary to fit a single layer into the bottom of the baking dish.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Spread a thin layer of strawberry preserves (about 2 tablespoons) over the soaked matzo base. Repeat the dipping and layering process until all matzo is used, ending with a soaked matzo layer on top. Do not top the final layer with jam.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour any remaining egg batter over the assembled layers. Bake for 30-35 minutes, or until the custard is set and the top is beginning to brown.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT35M", "doneness_cues": {"visual": "Top is golden brown and puffed", "tactile": "Center is firm to the touch"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "While the bars bake, combine butter, honey, and the optional splash of wine in a small saucepan over medium heat. Simmer for 2-3 minutes until the mixture foams and slightly thickens.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Immediately upon removing the dish from the oven, pour the hot honey-butter glaze evenly over the surface. Let the bars cool completely in the pan to allow the layers to set before slicing.", "structured": {"action": "GLAZE", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT45M", "total_time": "PT1H10M", "overnight_required": false, "yields": "9 bars", "yield_count": 9, "serving_size_g": 110}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 256.98, "protein_g": 5.14, "carbohydrates_g": 42.6, "fat_g": 6.42, "saturated_fat_g": 3.33, "trans_fat_g": 0.01, "monounsaturated_fat_g": 1.98, "polyunsaturated_fat_g": 0.57, "fiber_g": 1.06, "sugar_g": 22.2, "sodium_mg": 80.44, "cholesterol_mg": 93.42, "potassium_mg": 74.97, "calcium_mg": 26.65, "iron_mg": 1.77, "magnesium_mg": 14.25, "phosphorus_mg": 86.66, "zinc_mg": 0.6, "vitamin_a_mcg": 69.82, "vitamin_c_mg": 1.44, "vitamin_d_mcg": 0.44, "vitamin_e_mg": 0.36, "vitamin_k_mcg": 0.56, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": 0.21, "thiamin_mg": 0.01, "riboflavin_mg": 0.11, "niacin_mg": 0.03, "folate_mcg": 10.75, "water_g": 28.5, "alcohol_g": 1.17, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container; texture becomes denser when chilled.", "duration": "P4D"}, "freezer": {"notes": "Freeze individually wrapped; thaw in refrigerator.", "duration": "P2M"}, "reheating": "Warm gently in a 150\u00b0C oven for 5-10 minutes to crisp the top.", "does_not_keep": false}', '[{"name": "Square baking dish (20cm / 8-inch)", "required": true, "alternative": null}, {"name": "Wide shallow bowl", "required": true, "alternative": "Pie dish"}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Pastry brush", "required": false, "alternative": null}]', '[{"symptom": "Bars are soggy or falling apart", "likely_cause": "Matzo was soaked too long in the batter before baking", "prevention": "Dip matzo only until it begins to soften (30-45 seconds max); do not let it turn into mush before layering.", "fix": "Bake for an additional 10-15 minutes at a lower temperature (150\u00b0C/300\u00b0F) to dry out excess moisture."}]', '["Using sweet red wine (like Manischewitz or a Ruby Port) in the batter mimics the flavor profile of Charoset and adds a beautiful purple hue to the interior.", "If your strawberry preserves are very chunky, pulse them briefly in a blender or mash them with a fork for easier spreading between delicate matzo layers.", "These bars cut most cleanly after being chilled in the refrigerator for at least 2 hours, though they are delicious served warm.", "For a crunchy texture variation, sprinkle crushed walnuts or pecans on top of the glaze immediately after pouring (if nuts are permitted)."]', '"This recipe riffs on the concept of ''Matzo Mina'' (a Sephardic layered pie) and sweet Matzo Brei. It incorporates the symbolic use of wine and unleavened bread central to Passover, transforming humble pantry staples into a rich, sticky confection."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('47be2dba-bd88-4315-b27c-1bf308391902', 'Umami Mushroom and Miso Sausage Rolls', 'Deeply savory vegetarian rolls featuring a texturally complex blend of shiitake, oyster, and cremini mushrooms. Enriched with fermented miso paste and sharp cheddar for a moist, meat-like interior that contrasts perfectly with shatteringly crisp, golden puff pastry.', 'Appetizer', 'Modern British', 'Intermediate', '[{"group_name": "Mushroom Filling", "items": [{"name": "cremini mushrooms", "quantity": 200, "unit": "g", "preparation": "cleaned and roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "fdd23eb2-a71c-46d1-932b-295adf7d5ae5", "nutrition_source": "Aggregated Public Data"}, {"name": "oyster mushrooms", "quantity": 150, "unit": "g", "preparation": "tough stems removed", "notes": null, "substitutions": [], "ingredient_id": "4fb0a923-94d7-4be9-9f04-c4fa16aa1b64", "nutrition_source": "USDA FoodData Central"}, {"name": "shiitake mushrooms", "quantity": 150, "unit": "g", "preparation": "stems removed", "notes": null, "substitutions": [], "ingredient_id": "127ce8a8-238d-40e6-a4b0-c58c42a7c745", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "brown onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme leaves", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}, {"name": "white miso paste", "quantity": 30, "unit": "g", "preparation": null, "notes": "Shiro miso preferred for balance", "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "92441189-214a-4a8a-9cfc-dd578fe0d179", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Binding & Assembly", "items": [{"name": "panko breadcrumbs", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "6cc08e49-8e1b-4065-be23-f57782560a8b", "nutrition_source": "Aggregated Public Data"}, {"name": "sharp cheddar cheese", "quantity": 100, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "USDA FoodData Central"}, {"name": "large egg", "quantity": 1, "unit": null, "preparation": "beaten", "notes": "for binding filling", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "puff pastry sheets", "quantity": 2, "unit": null, "preparation": "thawed if frozen", "notes": "approx 500g total weight", "substitutions": [], "ingredient_id": "49bd8974-0750-40ca-80a7-7f195cdc662b", "nutrition_source": "USDA FoodData Central"}, {"name": "egg wash", "quantity": 1, "unit": null, "preparation": null, "notes": "1 egg beaten with 15ml milk", "substitutions": [], "ingredient_id": "36a7664a-f96c-44b9-9b6d-cdd5e9e54f55", "nutrition_source": "Aggregated Public Data"}, {"name": "sesame seeds", "quantity": 10, "unit": "g", "preparation": null, "notes": "white or black, for garnish", "substitutions": [], "ingredient_id": "0edc9256-6bac-4718-9f80-12351b1bc941", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the cremini, oyster, and shiitake mushrooms in a food processor. Pulse in short bursts until the mushrooms resemble ground meat or coarse gravel. Do not over-process into a paste.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Process mushrooms in two batches if your machine is small to ensure even size."]}, {"step_number": 2, "phase": "cook", "text": "Heat butter in a large skillet over medium-high heat. Add the diced onion and saut\u00e9 until softened and translucent, about 5 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the processed mushrooms and garlic to the pan. Cook, stirring frequently, until the mushrooms have released their liquid and the pan is nearly dry. This step is critical for texture.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Volume reduced by half, no pooling liquid", "tactile": "Mixture begins to brown and sizzle"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stir in the miso paste, soy sauce, and fresh thyme. Cook for 1 more minute to activate the aromatics, then transfer the mixture to a large mixing bowl to cool slightly (about 10 minutes).", "structured": {"action": "MIX", "temperature": null, "duration": "PT11M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Once the mushroom mixture is warm (not hot), fold in the breadcrumbs, grated cheddar, and the beaten binding egg. Mix until a cohesive, moldable dough forms. If too wet, add 10g more breadcrumbs.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Preheat oven to 200\u00b0C/400\u00b0F. Lay out puff pastry sheets on a clean surface. Cut each square sheet in half to form two long rectangles.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Divide the filling into 4 equal parts. Shape each part into a long sausage log along the length of each pastry strip. Brush one long edge of the pastry with egg wash.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Roll the pastry over the filling, sealing it on the egg-washed edge. Place seam-side down. Cut each log into 6 smaller rolls. Score the tops diagonally with a sharp knife.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Place rolls on a parchment-lined baking sheet. Brush tops with egg wash and sprinkle with sesame seeds. Bake for 20-25 minutes until the pastry is puffed and deep golden brown.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT25M", "doneness_cues": {"visual": "Deep golden brown pastry", "tactile": "Pastry feels firm and crisp"}}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT35M", "total_time": "PT1H20M", "overnight_required": false, "yields": "24 mini rolls", "yield_count": 24, "serving_size_g": 45}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegans (contains egg and dairy)", "Gluten sensitivity"]}', '{"per_serving": {"calories": 168.55, "protein_g": 4.08, "carbohydrates_g": 12.67, "fat_g": 11.59, "saturated_fat_g": 3.37, "trans_fat_g": null, "monounsaturated_fat_g": 5.09, "polyunsaturated_fat_g": 1.27, "fiber_g": 1.1, "sugar_g": 1.07, "sodium_mg": 277.62, "cholesterol_mg": 25.94, "potassium_mg": 119.56, "calcium_mg": 51.5, "iron_mg": 1.2, "magnesium_mg": 16.31, "phosphorus_mg": 57.81, "zinc_mg": 0.45, "vitamin_a_mcg": 25.8, "vitamin_c_mg": 0.99, "vitamin_d_mcg": 0.19, "vitamin_e_mg": 0.21, "vitamin_k_mcg": 3.54, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.06, "thiamin_mg": 0.11, "riboflavin_mg": 0.13, "niacin_mg": 1.5, "folate_mcg": 24.68, "water_g": 24.04, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to prevent pastry from softening.", "duration": "P3D"}, "freezer": {"notes": "Freeze unbaked rolls on a tray, then bag. Bake from frozen adding 5-10 minutes to cook time.", "duration": "P3M"}, "reheating": "Reheat in a 180\u00b0C/350\u00b0F oven for 10 minutes to re-crisp pastry. Microwave not recommended.", "does_not_keep": false}', '[{"name": "Food processor", "required": true, "alternative": "Sharp knife and patience"}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}]', '[{"symptom": "Soggy pastry bottom", "likely_cause": "Mushrooms were not cooked down enough, releasing water during baking", "prevention": "Ensure the mushroom pan is completely dry and sizzling before removing from heat", "fix": "Bake on a wire rack over a tray for the last 5 minutes to circulate air underneath"}, {"symptom": "Filling spilling out", "likely_cause": "Pastry was not sealed tightly or filled too loosely", "prevention": "Press the seam firmly and chill the rolls for 15 minutes before baking", "fix": "Push filling back in with a spoon immediately after baking while soft"}]', '["The secret to a ''meaty'' vegetarian roll is the differing textures of mushrooms. Using a mix of Shiitake (chewy), Oyster (fibrous), and Cremini (soft) creates a complex mouthfeel.", "Allow the filling to cool completely before rolling. Hot filling will melt the butter layers in the puff pastry before it hits the oven, resulting in a greasy, flat crust.", "Miso is the key salinity driver here. If you substitute the miso, you must increase the salt content, but you will lose the deep umami background note.", "For cleaner cuts when portioning the rolls, wipe your knife with a damp cloth between slices."]', '"Sausage rolls are a quintessential British and Australian party food, traditionally filled with pork meat. This modern adaptation utilizes the Japanese culinary concept of ''kokumi'' (mouthfulness) via the interaction of aged cheese and fermented miso to replicate the satisfaction of the original meat version."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('4ec1271e-8df7-476e-bac9-6c3beaf61a3b', 'Braised Veal Shoulder with Cardamom Spinach Velvet', 'A luxurious roast-style braise where the veal shoulder transforms into meltingly tender meat with a rich, gelatinous glaze. It pairs with a striking emerald-green spinach puree, where the floral, citrusy warmth of green cardamom cuts through the richness of the meat.', 'Main Course', 'French', 'Advanced', '[{"group_name": "Veal Roast", "items": [{"name": "boneless veal shoulder", "quantity": 1000, "unit": "g", "preparation": "rolled and tied", "notes": "Ask butcher to roll for roasting", "substitutions": [], "ingredient_id": "154b7714-319a-47a1-802a-416797db0752", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 8, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "grapeseed oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Braising Aromatics", "items": [{"name": "onion", "quantity": 1, "unit": null, "preparation": "roughly chopped", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrot", "quantity": 1, "unit": null, "preparation": "roughly chopped", "notes": "approx 100g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "celery stalk", "quantity": 1, "unit": null, "preparation": "roughly chopped", "notes": "approx 50g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "smashed", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 200, "unit": "ml", "preparation": null, "notes": "Sauvignon Blanc or Pinot Grigio", "substitutions": [], "ingredient_id": "0c041362-befe-4c15-88d2-ba97c8f46428", "nutrition_source": "USDA FoodData Central"}, {"name": "veal stock", "quantity": 500, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["chicken stock"], "ingredient_id": "75bb51d6-9275-4c11-9fff-65bd7ed4b5b2", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": "sprigs", "notes": "approx 2g", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "bay leaf", "quantity": 1, "unit": null, "preparation": null, "notes": "dried", "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Cardamom Spinach Puree", "items": [{"name": "heavy cream", "quantity": 150, "unit": "ml", "preparation": null, "notes": "35% fat or higher", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "green cardamom pods", "quantity": 8, "unit": null, "preparation": "crushed", "notes": "approx 2g", "substitutions": [], "ingredient_id": "c56f6cd8-882c-487c-956f-3a91ee1fec07", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh spinach", "quantity": 600, "unit": "g", "preparation": "washed and stemmed", "notes": null, "substitutions": [], "ingredient_id": "4734440a-226d-4d26-a110-3ed5c3bde93f", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 40, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 2g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the veal shoulder dry with paper towels and season generously on all sides with salt and cracked black pepper. Preheat the oven to 150\u00b0C (300\u00b0F).", "structured": {"action": "SEASON", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small saucepan over low heat, combine heavy cream and crushed cardamom pods. Bring to a bare simmer, then remove from heat and let infuse for at least 20 minutes.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat grapeseed oil in the Dutch oven over medium-high heat. Sear the veal shoulder on all sides until deeply golden brown, about 3-4 minutes per side.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": "Deep golden brown crust", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Remove meat and set aside. Reduce heat to medium, add the 30g butter, onion, carrot, celery, and smashed garlic. Saut\u00e9 until softened and lightly browned.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Deglaze the pan with white wine, scraping up the fond (browned bits) from the bottom. Reduce the wine by half.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Return the veal to the pot. Add stock, thyme, and bay leaf. The liquid should come about halfway up the meat. Bring to a simmer, cover tightly, and transfer to the oven for 2.5 to 3 hours, or until the meat is fork-tender.", "structured": {"action": "BRAISE", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT3H", "doneness_cues": {"visual": null, "tactile": "Fork slides in with no resistance"}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "While the meat rests, bring a large pot of salted water to a rolling boil. Prepare an ice water bath. Blanch the spinach for 30 seconds only, then immediately transfer to the ice bath to shock it.", "structured": {"action": "BLANCH", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT30S", "doneness_cues": null}, "tips": ["Shocking locks in the chlorophyll for a bright green color."]}, {"step_number": 8, "phase": "finish", "text": "Squeeze as much water as possible out of the spinach using a clean kitchen towel. Strain the infused cream to remove cardamom pods.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Place spinach and infused cream into a high-speed blender. Blend until perfectly smooth. Add the cold cubed butter (40g) while blending to emulsify. Season with salt.", "structured": {"action": "BLEND", "temperature": null, "duration": null, "doneness_cues": {"visual": "Glossy, vibrant green puree", "tactile": null}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Remove veal from pot and rest loosely covered. Strain the braising liquid into a saucepan and reduce over high heat until it coats the back of a spoon (napp\u00e9 consistency).", "structured": {"action": "REDUCE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Glaze consistency", "tactile": null}}, "tips": []}, {"step_number": 11, "phase": "assemble", "text": "Slice the veal into thick rounds. Plate atop a swoosh of cardamom spinach puree and spoon the reduced braising glaze over the meat.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT3H", "total_time": "PT3H45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Keto", "Low-Carb", "Nut-Free", "Peanut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 987.95, "protein_g": 98.61, "carbohydrates_g": 20.36, "fat_g": 52.86, "saturated_fat_g": 23.49, "trans_fat_g": 0.47, "monounsaturated_fat_g": 13.36, "polyunsaturated_fat_g": 3.01, "fiber_g": 5.26, "sugar_g": 4.71, "sodium_mg": 1450.05, "cholesterol_mg": 443.75, "potassium_mg": 2291.01, "calcium_mg": 307.63, "iron_mg": 8.54, "magnesium_mg": 232.08, "phosphorus_mg": 962.77, "zinc_mg": 14.6, "vitamin_a_mcg": 1190.54, "vitamin_c_mg": 48.91, "vitamin_d_mcg": 0.6, "vitamin_e_mg": 5.21, "vitamin_k_mcg": 743.66, "vitamin_b6_mg": 1.95, "vitamin_b12_mcg": 5.29, "thiamin_mg": 0.44, "riboflavin_mg": 1.53, "niacin_mg": 33.76, "folate_mcg": 368.55, "water_g": 533.63, "alcohol_g": 4.45, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store meat in its braising liquid to prevent drying out. Spinach puree loses vibrant color after 24 hours.", "duration": "P3D"}, "freezer": {"notes": "Meat freezes well in sauce; spinach puree texture may degrade upon thawing.", "duration": "P2M"}, "reheating": "Reheat meat gently in sauce on stove. Reheat spinach in a double boiler to prevent scorching.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed braiser with lid", "required": true, "alternative": null}, {"name": "High-speed blender", "required": true, "alternative": null}, {"name": "Fine-mesh sieve", "required": true, "alternative": "Regular strainer"}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Large pot", "required": true, "alternative": "For blanching spinach"}, {"name": "Ice bath bowl", "required": true, "alternative": null}, {"name": "Kitchen twine", "required": true, "alternative": null}]', '[{"symptom": "Spinach puree is brown/olive instead of bright green", "likely_cause": "Overcooked during blanching or acid exposure (lemon/vinegar) in puree", "prevention": "Blanch quickly (30s) and shock in ice immediately; do not add acid to the green puree", "fix": "Cannot be fixed color-wise; serve as is, the flavor remains"}, {"symptom": "Veal is tough after 3 hours", "likely_cause": "The cut contains dense connective tissue that hasn''t fully gelatinized", "prevention": "Ensure oven temp is consistent; ensure lid is tight", "fix": "Return to oven for another 30-45 minutes; add a splash more liquid if needed"}]', '["Squeezing the spinach dry is crucial. If the spinach is too wet, the puree will be watery and separate on the plate.", "For the ultimate smooth texture, pass the finished spinach puree through a fine-mesh sieve (tamis) using a ladle.", "Resting the meat for at least 20 minutes before slicing allows the juices to redistribute, preventing them from leaking out onto the plate.", "The cardamom should be a subtle background note, not a dominant spice. Taste the infused cream before adding it to the spinach."]', '"This dish applies classic French braising techniques to veal, a protein prized in European gastronomy for its delicate flavor. The addition of cardamom introduces a subtle Scandinavian or Middle Eastern aromatic profile, modernizing the traditional roast dinner."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('517fc62b-bb95-4e47-bb5e-7afed06303cf', 'Lemon-Fire Cornmeal Fried Chicken', 'Golden, shatteringly crisp chicken thighs encasing succulent meat, marinated in a vibrant, high-acid blend of fresh lemon juice and aged hot sauce. The coarse cornmeal crust provides a distinct textural crunch that stands up to the zesty, spicy heat.', 'Main Course', 'American', 'Intermediate', '[{"group_name": "Chicken & Marinade", "items": [{"name": "chicken thighs", "quantity": 1000, "unit": "g", "preparation": "bone-in, skin-on", "notes": "approx. 6-8 pieces", "substitutions": [], "ingredient_id": "d7fc1bf9-fc05-429b-bfa6-2ad857cb0bb6", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 80, "unit": "ml", "preparation": "freshly squeezed", "notes": "about 2 lemons", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "cayenne pepper hot sauce", "quantity": 80, "unit": "ml", "preparation": null, "notes": "Frank''s RedHot or Crystal style", "substitutions": [], "ingredient_id": "f41f3bc3-3ea8-4cba-9158-e69cef32219f", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 60, "unit": "ml", "preparation": null, "notes": "to dilute acidity slightly", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Cornmeal Crust", "items": [{"name": "yellow cornmeal", "quantity": 150, "unit": "g", "preparation": "medium grind", "notes": null, "substitutions": [], "ingredient_id": "7fb6be00-5ba2-483a-af74-961f21de4055", "nutrition_source": "Aggregated Public Data"}, {"name": "all-purpose flour", "quantity": 150, "unit": "g", "preparation": null, "notes": "essential for binding the cornmeal", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic powder", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "177a312f-ef99-4398-9108-98f7a608a245", "nutrition_source": "USDA FoodData Central"}, {"name": "onion powder", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4f8e972-beb6-438b-aa1b-4129031597a3", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 3, "unit": "g", "preparation": "ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Frying", "items": [{"name": "neutral oil", "quantity": 1500, "unit": "ml", "preparation": null, "notes": "peanut, canola, or vegetable; enough for 5cm depth", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "beaten", "notes": "approx 100g, binder for coating", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Whisk together lemon juice, hot sauce, water, and the first measure of salt (10g) in a large bowl. Add the chicken thighs, tossing to coat thoroughly. Cover and refrigerate.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT4H", "doneness_cues": null}, "tips": ["Do not marinate longer than 6 hours or the high acidity will degrade the meat texture."]}, {"step_number": 2, "phase": "prep", "text": "In a shallow dish, combine cornmeal, flour, garlic powder, onion powder, smoked paprika, black pepper, and the remaining salt (5g). In a separate bowl, whisk the eggs.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "Remove chicken from marinade, letting excess liquid drip off. Dip each piece into the beaten eggs, then press firmly into the cornmeal mixture to coat all sides. Place on a wire rack set over a baking sheet.", "structured": {"action": "DREDGE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Pressing the chicken into the flour ensures the cornmeal adheres properly."]}, {"step_number": 4, "phase": "prep", "text": "Let the coated chicken rest on the rack at room temperature for 15-20 minutes. This hydration period ''glues'' the crust to the skin.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Fill a Dutch oven with 5cm of neutral oil. Heat over medium-high heat until the oil reaches 175\u00b0C (350\u00b0F).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Carefully lower chicken into the oil (fry in batches of 2-3 to avoid overcrowding). Maintain oil temperature between 160\u00b0C-170\u00b0C (320\u00b0F-340\u00b0F) during cooking.", "structured": {"action": "FRY", "temperature": {"celsius": 165, "fahrenheit": 329}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Fry for 12-15 minutes, turning occasionally, until the crust is deep golden brown and the internal temperature at the thickest part reaches 74\u00b0C (165\u00b0F).", "structured": {"action": "FRY", "temperature": null, "duration": "PT14M", "doneness_cues": {"visual": "Deep golden brown crust", "tactile": "Internal temp 74\u00b0C"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Transfer fried chicken to a clean wire rack to drain. Sprinkle immediately with a pinch of salt while hot.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT4H", "total_time": "PT4H45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 672.95, "protein_g": 60.78, "carbohydrates_g": 71.36, "fat_g": 14.62, "saturated_fat_g": 3.81, "trans_fat_g": 0.06, "monounsaturated_fat_g": 4.73, "polyunsaturated_fat_g": 3.08, "fiber_g": 4.81, "sugar_g": 1.56, "sodium_mg": 1880.1, "cholesterol_mg": 328, "potassium_mg": 898.44, "calcium_mg": 58.74, "iron_mg": 6.13, "magnesium_mg": 171.3, "phosphorus_mg": 750.22, "zinc_mg": 6.08, "vitamin_a_mcg": 106.95, "vitamin_c_mg": 8.99, "vitamin_d_mcg": 0.5, "vitamin_e_mg": 1.08, "vitamin_k_mcg": 9.54, "vitamin_b6_mg": 1.25, "vitamin_b12_mcg": 1.75, "thiamin_mg": 0.3, "riboflavin_mg": 0.65, "niacin_mg": 14.53, "folate_mcg": 37.78, "water_g": 247.87, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Crust will lose crispness; reheat in oven/air fryer.", "duration": "P3D"}, "freezer": {"notes": "Freeze on a tray first, then bag. Reheat from frozen.", "duration": "P2M"}, "reheating": "Reheat in an oven at 190\u00b0C (375\u00b0F) on a wire rack for 15-20 minutes until crisp.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed pot", "required": true, "alternative": "Deep fryer"}, {"name": "Kitchen thermometer", "required": true, "alternative": "Candy thermometer"}, {"name": "Wire cooling rack", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}]', '[{"symptom": "Coating falls off during frying", "likely_cause": "Chicken was too wet or didn''t rest after dredging", "prevention": "Ensure you rest the breaded chicken for 15 minutes before frying to let the gluten hydrate", "fix": "Handle very gently; cannot be re-adhered"}, {"symptom": "Crust burns before meat is cooked", "likely_cause": "Oil temperature is too high", "prevention": "Use a thermometer to monitor oil; reduce heat once chicken is added", "fix": "Remove from oil, place on rack, and finish cooking in a 175\u00b0C (350\u00b0F) oven"}]', '["The acidity in the lemon and hot sauce acts as a tenderizer similar to buttermilk, but faster. Do not exceed the marinating time.", "Medium-grind cornmeal offers the best texture; fine cornmeal can become pasty, while coarse grind may not adhere well.", "Always fry bone-in chicken thighs for this recipe; breast meat dries out too quickly with the longer fry times required for a thick cornmeal crust."]', '"This recipe marries the Southern US tradition of cornmeal-crusted catfish with classic fried chicken techniques. The lemon-heavy marinade nods to ''lemon pepper'' flavor profiles popular in Atlanta, while the cornmeal provides a heritage grain crunch distinct from standard flour batters."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('57d34285-fc29-43b3-9df5-2c86b1a3b0b2', 'Tropical Gingersnap & Caramelized Pineapple Cheesecake Bars', 'A vibrant no-bake dessert featuring a spicy, crunchy gingersnap base topped with ultra-creamy coconut-lime cheesecake. Swirls of jammy, golden-caramelized pineapple cut through the richness, finishing with a tropical aromatic lift.', 'Dessert', 'Tropical Fusion', 'Intermediate', '[{"group_name": "Caramelized Pineapple Jam", "items": [{"name": "fresh pineapple", "quantity": 300, "unit": "g", "preparation": "finely diced", "notes": "canned works if drained very well", "substitutions": [], "ingredient_id": "37da68de-6b6e-4619-9f28-52da1f26f4ce", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 45, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Gingersnap Crust", "items": [{"name": "gingersnap cookies", "quantity": 250, "unit": "g", "preparation": null, "notes": "crispy variety, not soft", "substitutions": [], "ingredient_id": "0070830f-d44d-4937-ba83-bc785ef4887a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 90, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "ground ginger", "quantity": 2, "unit": "g", "preparation": null, "notes": "optional for extra kick", "substitutions": [], "ingredient_id": "401ddd0b-3597-4b46-bb54-f3bc755048bb", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Coconut Lime Filling", "items": [{"name": "full-fat cream cheese", "quantity": 450, "unit": "g", "preparation": "room temperature", "notes": "brick style, not tub", "substitutions": [], "ingredient_id": "262c67de-76a4-4444-8c02-30ad4a179459", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 110, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "coconut cream", "quantity": 120, "unit": "ml", "preparation": "chilled", "notes": "thick solid part from top of can only", "substitutions": [], "ingredient_id": "af6f629b-fa13-4f67-8338-e06af8c943cc", "nutrition_source": "USDA FoodData Central"}, {"name": "lime zest", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 2 limes", "substitutions": [], "ingredient_id": "295e8d21-9ba3-4ab8-a118-b09b77defacc", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "toasted coconut flakes", "quantity": 30, "unit": "g", "preparation": null, "notes": "for garnish", "substitutions": [], "ingredient_id": "22ca2249-2951-4843-8ed0-fed51cf8338c", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the pineapple jam: Combine diced pineapple, brown sugar, lime juice (15ml), and salt in a small saucepan over medium heat. Cook, stirring occasionally, until the liquid evaporates and the pineapple turns golden and sticky. Remove from heat and cool completely.", "structured": {"action": "REDUCE", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT15M", "doneness_cues": {"visual": "Golden brown, no liquid pooling at bottom of pan", "tactile": "Sticky and jam-like"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Line a 20cm (8-inch) square pan with parchment paper, leaving an overhang on two sides for easy removal later.", "structured": {"action": "MEASURE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Make the crust: Pulse gingersnaps and ground ginger in a food processor until fine crumbs form. Add melted butter and pulse until the mixture resembles wet sand. Press firmly and evenly into the bottom of the prepared pan. Freeze for 10 minutes to set.", "structured": {"action": "CRUSH", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In a stand mixer fitted with the paddle attachment, beat the room temperature cream cheese and powdered sugar on medium speed until completely smooth and free of lumps. Scrape down the bowl.", "structured": {"action": "BEAT", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the thick coconut cream (solids only), lime zest, and vanilla. Beat on medium-high until the mixture is thickened and airy. Do not overbeat to the point of separation.", "structured": {"action": "WHIP", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Thick, holds peaks", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Spread half of the cheesecake mixture over the chilled crust. Dollop half of the cooled pineapple jam randomly over the surface. Swirl gently with a knife. Repeat with the remaining cheesecake and pineapple.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Cover tightly and refrigerate for at least 8 hours (preferably overnight) to set. Before serving, lift the bars out using the parchment overhang, garnish with toasted coconut, and slice into 16 squares.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT8H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT8H", "total_time": "PT8H45M", "overnight_required": true, "yields": "16 bars", "yield_count": 16, "serving_size_g": 115}', '{"flags": ["Vegetarian", "Egg-Free", "Peanut-Free"], "not_suitable_for": ["Vegans (contains dairy)", "Coeliacs (contains gluten)"]}', '{"per_serving": {"calories": 286.08, "protein_g": 3.4, "carbohydrates_g": 27.13, "fat_g": 18.98, "saturated_fat_g": 11.22, "trans_fat_g": 0.33, "monounsaturated_fat_g": 4.77, "polyunsaturated_fat_g": 0.84, "fiber_g": 1.48, "sugar_g": 15.54, "sodium_mg": 201.69, "cholesterol_mg": 40.5, "potassium_mg": 144.74, "calcium_mg": 57.25, "iron_mg": 1.44, "magnesium_mg": 21.14, "phosphorus_mg": 68.61, "zinc_mg": 0.42, "vitamin_a_mcg": 125.68, "vitamin_c_mg": 9.45, "vitamin_d_mcg": null, "vitamin_e_mg": 0.53, "vitamin_k_mcg": 1.51, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.07, "thiamin_mg": 0.06, "riboflavin_mg": 0.12, "niacin_mg": 0.71, "folate_mcg": 21.53, "water_g": 37.78, "alcohol_g": 0.11, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep tightly covered to prevent absorbing fridge odors.", "duration": "P4D"}, "freezer": {"notes": "Freeze individual bars wrapped in parchment and foil. Thaw in fridge for 2 hours.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "20cm (8-inch) square baking pan", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Food processor or sealed bag/rolling pin", "required": true, "alternative": "Mortar and pestle"}, {"name": "Stand mixer or electric hand mixer", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Rubber spatula", "required": true, "alternative": null}]', '[{"symptom": "Cheesecake mixture is runny or won''t set", "likely_cause": "Used liquid coconut milk instead of the solid cream, or cream cheese was too warm/soft", "prevention": "Only use the solid white cream from a chilled can of full-fat coconut milk; ensure cream cheese is room temp but not melting", "fix": "Freeze the bars for 2-3 hours and serve as a frozen treat instead of refrigerated bars"}, {"symptom": "Pineapple mixture is watery and making the filling weep", "likely_cause": "Pineapple wasn''t cooked down enough to evaporate natural juices", "prevention": "Cook pineapple until the pan is almost dry and the fruit is sticky", "fix": "Cannot be fixed once assembled"}]', '["To get the thickest coconut cream, place a can of full-fat coconut milk in the fridge the night before. Open it carefully and scoop off only the hard white layer at the top.", "For the cleanest slices, wipe your knife with a warm, damp cloth between every single cut.", "If you cannot find gingersnaps, Biscoff cookies or graham crackers mixed with 1 tsp of ground ginger make excellent substitutes.", "Ensure the pineapple jam is completely cool (room temperature or colder) before adding to the cheese mixture, or it will melt the fat and ruin the structure.", "This recipe relies on the stiffness of full-fat brick cream cheese. Do not use ''spreadable'' or ''whipped'' tub varieties."]', '"This dessert bridges the gap between the mid-century American ''icebox cake'' tradition and tropical flavor profiles often found in Tiki culture. The use of gingersnap crust nods to the European speculoos tradition while providing a spicy counterpoint to the Caribbean-inspired lime and coconut pairing."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('59e1e014-9f60-4c4b-8747-7893b34d1b8b', 'Rustic Vegetable Beef Soup', 'A deeply comforting, hearty soup featuring melt-in-your-mouth beef chunks and tender russet potatoes in a robust tomato-beef broth. Packed with sweet corn, garden peas, and green beans, this one-pot meal balances savory depth with vegetable sweetness.', 'Soup', 'American', 'Easy', '[{"group_name": "Beef & Aromatics", "items": [{"name": "beef stew meat (chuck roast)", "quantity": 700, "unit": "g", "preparation": "cut into 2cm cubes", "notes": "trim excess hard fat", "substitutions": [], "ingredient_id": "aebf4219-b6a4-45b0-bd82-11203774257f", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": "divided", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx. 200g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "celery stalks", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx. 100g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Broth Base", "items": [{"name": "beef broth", "quantity": 1500, "unit": "ml", "preparation": null, "notes": "ensure gluten-free certified if required", "substitutions": [], "ingredient_id": "4058eb05-f1ce-43a7-81d8-f73141c89b46", "nutrition_source": "USDA FoodData Central"}, {"name": "canned diced tomatoes", "quantity": 400, "unit": "g", "preparation": "undrained", "notes": null, "substitutions": [], "ingredient_id": "0ba01b79-628f-4d68-be62-dab1fbbd087c", "nutrition_source": "Aggregated Public Data"}, {"name": "gluten-free worcestershire sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e3b693e4-5eb2-4dfd-988f-cbca12ac6cb7", "nutrition_source": "USDA FoodData Central"}, {"name": "dried thyme", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "3b938244-d506-46b2-9027-21bed955bcc5", "nutrition_source": "USDA FoodData Central"}, {"name": "bay leaf", "quantity": 1, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eab2ef3a-7a0e-4188-b746-645b795ada1e", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables", "items": [{"name": "russet potatoes", "quantity": 500, "unit": "g", "preparation": "peeled and cut into 2cm cubes", "notes": null, "substitutions": [], "ingredient_id": "a7db25be-476c-48fe-8cb8-2ea66fb91587", "nutrition_source": "USDA FoodData Central"}, {"name": "carrots", "quantity": 3, "unit": null, "preparation": "sliced into rounds", "notes": "approx. 200g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "frozen green beans", "quantity": 150, "unit": "g", "preparation": "cut into 2cm lengths", "notes": null, "substitutions": [], "ingredient_id": "ea789b38-e002-476a-b47e-8cf806dd4f7c", "nutrition_source": "USDA FoodData Central"}, {"name": "frozen corn kernels", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5307852d-0f25-4efa-bd06-4cbce70383a2", "nutrition_source": "USDA FoodData Central"}, {"name": "frozen peas", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fa661e9d-c4df-42f0-99c8-ca41610251a9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Seasoning", "items": [{"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 5g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": "for garnish", "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the beef cubes dry with paper towels and season generously with salt and pepper. This ensures a proper sear rather than steaming.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat half the olive oil in the Dutch oven over medium-high heat. Sear the beef in batches until deeply browned on all sides, about 3-5 minutes per batch. Remove beef to a plate.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT10M", "doneness_cues": {"visual": "Deep brown crust developed", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Lower heat to medium. Add remaining oil, onions, carrots, and celery. Saut\u00e9 for 5-7 minutes until onions are translucent and fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT7M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add minced garlic and dried thyme. Stir constantly for 1 minute until aromatic, being careful not to burn the garlic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour in a splash of the beef broth to deglaze the pot, scraping up the browned bits (fond) from the bottom. Add the remaining broth, diced tomatoes (with juices), Worcestershire sauce, bay leaf, and the browned beef with its resting juices.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Bring to a boil, then reduce heat to low. Cover and simmer gently for 45-60 minutes, or until the beef is beginning to get tender but still offers some resistance.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Add the cubed potatoes. Continue to simmer, covered, for another 15-20 minutes until potatoes are fork-tender.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT20M", "doneness_cues": {"visual": null, "tactile": "Potatoes pierce easily with a fork"}}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Stir in the frozen green beans, corn, and peas. Simmer for 5 minutes until vegetables are heated through and bright.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove the bay leaf. Taste and adjust seasoning with additional salt and pepper if needed. Garnish with fresh parsley before serving.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT1H30M", "total_time": "PT2H", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 450}', '{"flags": ["Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 434.24, "protein_g": 30.9, "carbohydrates_g": 36.84, "fat_g": 19.74, "saturated_fat_g": 6.99, "trans_fat_g": 0.81, "monounsaturated_fat_g": 10.78, "polyunsaturated_fat_g": 1.43, "fiber_g": 6.28, "sugar_g": 8.11, "sodium_mg": 1447.96, "cholesterol_mg": 80.5, "potassium_mg": 1267.87, "calcium_mg": 114.95, "iron_mg": 5.89, "magnesium_mg": 77.86, "phosphorus_mg": 376.48, "zinc_mg": 9.67, "vitamin_a_mcg": 326.38, "vitamin_c_mg": 22.65, "vitamin_d_mcg": 0.12, "vitamin_e_mg": 1.44, "vitamin_k_mcg": 87.22, "vitamin_b6_mg": 0.96, "vitamin_b12_mcg": 3.36, "thiamin_mg": 0.3, "riboflavin_mg": 0.36, "niacin_mg": 9.23, "folate_mcg": 68.1, "water_g": 524.28, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves the next day as ingredients meld.", "duration": "P4D"}, "freezer": {"notes": "Russet potatoes may soften slightly upon thawing but remain palatable.", "duration": "P3M"}, "reheating": "Reheat gently on the stovetop over medium heat until steaming.", "does_not_keep": false}', '[{"name": "Dutch oven or large heavy-bottomed pot", "required": true, "alternative": "Large stockpot"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Wooden spoon or spatula", "required": true, "alternative": null}]', '[{"symptom": "Beef is tough or chewy", "likely_cause": "Not cooked long enough to break down connective tissue", "prevention": "Test a piece of beef before adding vegetables; extend initial simmer time if needed", "fix": "Add a splash more broth and continue simmering on low heat until tender (vegetables may soften further)"}, {"symptom": "Soup lacks depth of flavor", "likely_cause": "Insufficient browning of meat or lack of salt", "prevention": "Ensure deep browning during step 2 and fully deglaze the pot", "fix": "Add a teaspoon of vinegar or lemon juice to brighten, or a pinch more salt"}]', '["Patting the beef dry is crucial. Wet meat steams instead of searing, causing you to lose the Maillard reaction flavor base.", "Russet potatoes are starchy and will naturally thicken the soup slightly as they cook. If you prefer firm potato chunks that hold shape perfectly, swap for Yukon Golds.", "Cut all vegetables to roughly the same size as the beef cubes (or slightly smaller) to ensure every spoonful has a balanced mix of ingredients.", "For an extra layer of umami without gluten, ensure your Worcestershire sauce is specifically labeled gluten-free, or substitute with gluten-free tamari."]', '"This style of vegetable beef soup is a staple of North American home cooking, often associated with frugal utilization of pantry staples and garden vegetables. It evolved from European pot-au-feu and stew traditions but adapted to include New World ingredients like corn and tomatoes."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('5b891f49-4472-4d71-9b2c-489fda63a02c', 'Quick Thai Red Turkey Curry', 'A vibrant and creamy curry utilizing pre-cooked turkey for speed. The richness of coconut milk balances the heat of red curry paste, while fresh spinach adds color and nutrition to this 20-minute meal.', 'Dinner', 'Thai', 'Easy', '[{"group_name": "Aromatics & Base", "items": [{"name": "vegetable oil", "quantity": 15, "unit": "ml", "preparation": "neutral oil", "notes": null, "substitutions": ["coconut oil", "canola oil"], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "red curry paste", "quantity": 60, "unit": "g", "preparation": null, "notes": "Store-bought or homemade", "substitutions": ["yellow curry paste", "massaman paste"], "ingredient_id": "e714e2f1-2295-4e8c-8ccf-65c38381e71e", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 10, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Liquids", "items": [{"name": "coconut milk", "quantity": 400, "unit": "ml", "preparation": "full-fat canned", "notes": "Shake can well before opening", "substitutions": [], "ingredient_id": "c037ee7e-e3ed-4340-b8fb-d8ad284ba96e", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken stock", "quantity": 120, "unit": "ml", "preparation": "low-sodium", "notes": null, "substitutions": [], "ingredient_id": "7e254f45-046f-4812-bcdd-7e31c9bb59b8", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Protein & Vegetables", "items": [{"name": "cooked turkey", "quantity": 400, "unit": "g", "preparation": "cubed or shredded", "notes": "Perfect for leftovers", "substitutions": [], "ingredient_id": "2832be8b-a0d1-4d8b-b3f1-107f508a32ff", "nutrition_source": "Aggregated Public Data"}, {"name": "baby spinach", "quantity": 150, "unit": "g", "preparation": "fresh washed", "notes": null, "substitutions": [], "ingredient_id": "4734440a-226d-4d26-a110-3ed5c3bde93f", "nutrition_source": "USDA FoodData Central"}, {"name": "red bell pepper", "quantity": 1, "unit": null, "preparation": "sliced into thin strips", "notes": "approx 150g", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Seasoning & Garnish", "items": [{"name": "fish sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["soy sauce", "tamari"], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "brown sugar", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": ["palm sugar"], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": null, "unit": null, "preparation": "chopped", "notes": "for garnish", "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare your ingredients: dice the cooked turkey into bite-sized pieces, slice the red bell pepper into strips, mince the garlic, and grate the ginger.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the vegetable oil in a large skillet or wok over medium heat (approx 175\u00b0C/350\u00b0F). Add the red curry paste, minced garlic, and grated ginger. Saut\u00e9 for 2 minutes until the paste darkens slightly and becomes very fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT2M", "doneness_cues": {"visual": "Paste darkens", "tactile": "Aromatics are fragrant"}}, "tips": ["Frying the paste is essential to ''wake up'' the spices and remove the raw flavor."]}, {"step_number": 3, "phase": "cook", "text": "Pour in the coconut milk and chicken stock. Stir well to dissolve the curry paste into the liquid. Bring the mixture to a gentle simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the sliced red bell peppers, fish sauce, and brown sugar. Simmer for 3-4 minutes until the peppers are slightly tender but still crisp.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the cooked turkey. Simmer for another 2-3 minutes, just long enough to heat the turkey through to 74\u00b0C/165\u00b0F. Avoid boiling vigorously to keep the turkey tender.", "structured": {"action": "SIMMER", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Turn off the heat. Stir in the fresh spinach and lime juice. The residual heat will wilt the spinach in about 30 seconds. Taste and adjust salt (fish sauce) or sweetness (sugar) if needed.", "structured": {"action": "STIR", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": ["Adding lime juice after turning off the heat preserves its fresh, zesty flavor."]}, {"step_number": 7, "phase": "finish", "text": "Serve immediately over steamed rice, garnished with fresh cilantro if desired.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT5M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Dairy-Free", "Gluten-Free", "Pescatarian"], "not_suitable_for": []}', '{"per_serving": {"calories": 500.67, "protein_g": 34.45, "carbohydrates_g": 23.95, "fat_g": 33.31, "saturated_fat_g": 22.79, "trans_fat_g": null, "monounsaturated_fat_g": 2.34, "polyunsaturated_fat_g": 0.86, "fiber_g": 11.94, "sugar_g": 9.57, "sodium_mg": 411.55, "cholesterol_mg": null, "potassium_mg": 1001.17, "calcium_mg": 156.55, "iron_mg": 7.23, "magnesium_mg": 115.27, "phosphorus_mg": 187, "zinc_mg": 1.7, "vitamin_a_mcg": 273.15, "vitamin_c_mg": 63.19, "vitamin_d_mcg": null, "vitamin_e_mg": 5.3, "vitamin_k_mcg": 198.08, "vitamin_b6_mg": 0.26, "vitamin_b12_mcg": null, "thiamin_mg": 0.11, "riboflavin_mg": 0.14, "niacin_mg": 1.93, "folate_mcg": 115.13, "water_g": 144.08, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Sauce may thicken when cold.", "duration": "P3D"}, "freezer": {"notes": "Coconut milk may separate slightly upon thawing; whisk vigorously when reheating.", "duration": "P1M"}, "reheating": "Gently reheat on the stove over low heat to prevent the coconut milk from splitting.", "does_not_keep": false}', '[{"name": "Large skillet or Wok", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Measuring spoons", "required": true, "alternative": null}]', '[{"symptom": "Curry is too spicy", "likely_cause": "Curry paste brands vary significantly in heat levels", "prevention": "Start with half the amount of paste and add more to taste", "fix": "Add a splash more coconut milk or a teaspoon of extra sugar to counteract the heat"}, {"symptom": "Turkey tastes dry", "likely_cause": "Turkey was overcooked in the sauce", "prevention": "Since the turkey is pre-cooked, only add it at the very end to warm through", "fix": "Ensure plenty of sauce is served with each bite to mask the texture"}]', '["Use full-fat coconut milk for a velvety texture; ''lite'' versions will result in a watery sauce.", "This recipe is an excellent vehicle for clearing out the fridge\u2014bamboo shoots, green beans, or snap peas are great additions alongside the peppers.", "If using leftover roast turkey that was seasoned with sage or rosemary, rinse the meat briefly before adding, or ensure those herbs complement the curry profile."]', '"Based on the Thai ''Kaeng Phet'' (Red Curry), this dish adapts the traditional method of frying curry paste in coconut cream. While authentic versions often use duck or chicken, turkey provides a lean protein alternative popular in Western adaptations, particularly after holidays."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('5fd4cd51-4f89-433e-a28e-527aad2d6b2f', 'Glazed Meatloaf Burgers', 'All the comfort of a classic Sunday meatloaf condensed into a juicy, seared patty. These burgers feature a tender crumb-soaked interior and are finished with a sticky, tangy tomato-brown sugar glaze that caramelizes on the grill or skillet.', 'Dinner', 'American', 'Easy', '[{"group_name": "Meatloaf Patties", "items": [{"name": "ground beef (80/20)", "quantity": 500, "unit": "g", "preparation": "chilled", "notes": "higher fat content ensures juicy burgers", "substitutions": [], "ingredient_id": "6c7cf0a4-a53c-415a-8d1c-7c1fc55d1d95", "nutrition_source": "USDA FoodData Central"}, {"name": "panko breadcrumbs", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84fbc204-4457-40ed-83c1-3e5a7bcd8f23", "nutrition_source": "Aggregated Public Data"}, {"name": "whole milk", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "onion", "quantity": 0.5, "unit": null, "preparation": "finely grated or minced", "notes": "approx 60g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": null, "notes": "large size, approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "worcestershire sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "aa552099-60a9-4267-a732-5870a271c28f", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Tangy Glaze", "items": [{"name": "ketchup", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9b0c1201-83fa-43c7-b2a4-66c400bcb0fd", "nutrition_source": "Aggregated Public Data"}, {"name": "brown sugar", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "apple cider vinegar", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Assembly", "items": [{"name": "bacon slices", "quantity": 4, "unit": null, "preparation": "cooked crispy", "notes": "optional topping", "substitutions": [], "ingredient_id": "339a356e-8f77-48fe-9293-b8e35fed3e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "burger buns", "quantity": 4, "unit": null, "preparation": "toasted", "notes": null, "substitutions": [], "ingredient_id": "3e054cb4-7cda-44f0-8b28-6066c1dfddaa", "nutrition_source": "Aggregated Public Data"}, {"name": "neutral oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for frying", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a large mixing bowl, combine the breadcrumbs and milk. Let this mixture (a panade) sit for 5 minutes until the breadcrumbs absorb the liquid and become mushy. This ensures the burgers remain tender.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "While the panade rests, whisk together the ketchup, brown sugar, Dijon mustard, and apple cider vinegar in a small bowl to create the glaze. Set aside.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Add the ground beef, grated onion, minced garlic, egg, Worcestershire sauce, salt, and pepper to the bowl with the soaked breadcrumbs. Gently mix with your hands just until combined. Do not overwork the meat.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Divide the mixture into 4 equal portions. Shape them into patties slightly wider than your buns, making a small indentation in the center of each with your thumb to prevent them from puffing up into balls during cooking.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Heat the neutral oil in a cast iron skillet over medium-high heat. Once the oil shimmers, add the patties. Cook for 4-5 minutes on the first side until a deep brown crust forms.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Flip the patties. Immediately brush a generous amount of the prepared glaze onto the seared side. Cook for another 3-4 minutes. If using cheese (optional), add it now over the glaze.", "structured": {"action": "GLAZE", "temperature": null, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Verify doneness. The internal temperature should reach 71\u00b0C/160\u00b0F for safe consumption of ground beef. The glaze should be sticky and caramelized.", "structured": {"action": "CHECK_TEMP", "temperature": {"celsius": 71, "fahrenheit": 160}, "duration": null, "doneness_cues": {"visual": "Glaze is bubbly and sticky", "tactile": "Patty is firm to touch"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove patties from the heat and let them rest for 5 minutes. Assemble on toasted buns with crispy bacon and extra glaze if desired.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT5M", "total_time": "PT30M", "overnight_required": false, "yields": "4 burgers", "yield_count": 4, "serving_size_g": 210}', '{"flags": ["Nut-Free", "Peanut-Free"], "not_suitable_for": ["Gluten intolerant (breadcrumbs)", "Vegans"]}', '{"per_serving": {"calories": 645.78, "protein_g": 30.49, "carbohydrates_g": 30.53, "fat_g": 35.34, "saturated_fat_g": 12.1, "trans_fat_g": 1.48, "monounsaturated_fat_g": 13.37, "polyunsaturated_fat_g": 1.37, "fiber_g": 1.34, "sugar_g": 11.15, "sodium_mg": 1124.7, "cholesterol_mg": 146.38, "potassium_mg": 528.24, "calcium_mg": 94.47, "iron_mg": 3.99, "magnesium_mg": 30.52, "phosphorus_mg": 289.94, "zinc_mg": 5.8, "vitamin_a_mcg": 44.42, "vitamin_c_mg": 3.04, "vitamin_d_mcg": 0.57, "vitamin_e_mg": 0.39, "vitamin_k_mcg": 3.25, "vitamin_b6_mg": 0.49, "vitamin_b12_mcg": 2.96, "thiamin_mg": 0.11, "riboflavin_mg": 0.3, "niacin_mg": 6.3, "folate_mcg": 18.57, "water_g": 116.63, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store patties separate from buns to prevent sogginess.", "duration": "P3D"}, "freezer": {"notes": "Freeze raw patties on parchment paper before bagging.", "duration": "P3M"}, "reheating": "Reheat gently in a skillet with a splash of water, covered, to steam through without drying.", "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Cast iron skillet or griddle", "required": true, "alternative": "Heavy-bottomed non-stick pan"}, {"name": "Spatula", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": "Spoon"}]', '[{"symptom": "Burgers are tough or rubbery", "likely_cause": "The meat mixture was overmixed, developing the protein strands too much", "prevention": "Mix gently with your hands only until ingredients are just incorporated", "fix": "Cannot be fixed, serve with extra sauce to mask texture"}, {"symptom": "Patties fall apart in the pan", "likely_cause": "Panade (milk/bread mixture) was too wet or patties weren''t compacted enough", "prevention": "Ensure breadcrumbs fully absorb the milk; if mixture feels too wet, add dry breadcrumbs teaspoon by teaspoon", "fix": "Press pieces together and melt cheese over the top to bind them visually"}]', '["The ''panade'' (milk and breadcrumb paste) is the secret to keeping these burgers moist, mimicking the texture of a slow-baked meatloaf in a fraction of the time.", "Grating the onion instead of chopping it allows the onion flavor to permeate the meat more evenly and prevents raw crunchy bits in the quickly cooked burger.", "Do not skip the resting period; cutting into the burger immediately will cause all the juices to run out, resulting in a dry patty.", "For a true diner-style experience, butter and griddle your buns until golden brown before assembly."]', '"Meatloaf is an icon of mid-20th-century American comfort food, born from the Great Depression necessity of stretching protein with fillers like grains. This recipe adapts that Sunday dinner staple into the ubiquitous American burger format, bridging the gap between slow-cooked comfort and fast-food convenience."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('60bc33b9-b8fd-40d6-b692-5648f281fa0a', 'Blistered & Smashed Cherry Tomato Salad', 'Sweet cherry tomatoes are charred under high heat until bursting, then gently crushed to release their warm juices into a vibrant vinaigrette. A rustic, intensely flavorful side that balances smoky sweetness with bright acidity and fresh herbs.', 'Side Dish', 'Mediterranean', 'Easy', '[{"group_name": "Vegetables", "items": [{"name": "cherry tomatoes", "quantity": 500, "unit": "g", "preparation": "whole", "notes": "mixture of colors preferred", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil leaves", "quantity": 15, "unit": "g", "preparation": "torn", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pantry & Dressing", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "sherry vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["red wine vinegar", "balsamic vinegar"], "ingredient_id": "dcfa7371-7051-4604-a76e-4a46ae1f9e7b", "nutrition_source": "Aggregated Public Data"}, {"name": "flaky sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 3g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Move the oven rack to the highest position (about 10-15cm from the element) and preheat the broiler to high.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 260, "fahrenheit": 500}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "On a rimmed baking sheet, toss the whole cherry tomatoes with 15ml of the olive oil and a pinch of salt. Ensure they are in a single layer.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Broil the tomatoes until the skins are blistered, blackened in spots, and some have begun to burst, approximately 5 to 8 minutes. Watch closely to prevent total incineration.", "structured": {"action": "BROIL", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Skins blackened and split", "tactile": "Tomatoes are soft and collapsing"}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "While tomatoes broil, whisk the remaining 30ml olive oil, sherry vinegar, minced garlic, and black pepper in a large heat-proof bowl.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Transfer the hot tomatoes and all accumulated juices from the baking sheet directly into the bowl with the dressing. The heat of the tomatoes will mellow the raw garlic.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Using a potato masher or fork, gently squash the tomatoes until they flatten and release more juice, creating a rustic sauce. Fold in the torn basil and serve immediately.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT10M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 140}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Paleo", "Whole30", "Low-Carb", "Keto"], "not_suitable_for": []}', '{"per_serving": {"calories": 128.34, "protein_g": 1.34, "carbohydrates_g": 6.69, "fat_g": 11.54, "saturated_fat_g": 1.6, "trans_fat_g": null, "monounsaturated_fat_g": 8.22, "polyunsaturated_fat_g": 1.21, "fiber_g": 2.4, "sugar_g": 4.91, "sodium_mg": 299.54, "cholesterol_mg": null, "potassium_mg": 316.83, "calcium_mg": 23.25, "iron_mg": 0.96, "magnesium_mg": 16.96, "phosphorus_mg": 34.79, "zinc_mg": 0.26, "vitamin_a_mcg": 9.97, "vitamin_c_mg": 18.27, "vitamin_d_mcg": null, "vitamin_e_mg": 1.65, "vitamin_k_mcg": 22.77, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": null, "thiamin_mg": null, "riboflavin_mg": 0.01, "niacin_mg": 0.05, "folate_mcg": 2.64, "water_g": 4.37, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves after resting, but basil may discolor. Store in an airtight container.", "duration": "P3D"}, "freezer": {"notes": "Texture degrades significantly upon thawing; do not freeze.", "duration": null}, "reheating": "Serve at room temperature or gently warm in a pan over low heat.", "does_not_keep": false}', '[{"name": "Rimmed baking sheet", "required": true, "alternative": "Cast iron skillet"}, {"name": "Oven with broiler function", "required": true, "alternative": null}, {"name": "Potato masher", "required": true, "alternative": "Large fork"}, {"name": "Mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Tomatoes are raw inside but burnt outside", "likely_cause": "Broiler was too close or tomatoes were very large/cold", "prevention": "Use room temperature tomatoes; lower rack slightly for larger tomatoes", "fix": "Finish baking at 200\u00b0C/400\u00b0F for 3-5 minutes on a lower rack"}, {"symptom": "Sauce is too watery", "likely_cause": "Tomatoes had very high water content", "prevention": "None (seasonal variance)", "fix": "Serve with crusty bread to soak it up, or strain juice and reduce in a small pan"}]', '["Sherry vinegar is preferred over balsamic here as it provides acidity without overwhelming the sweetness of the tomatoes with too much sugar.", "Do not skip the bread; the ''pot liquor'' created by the tomato water and olive oil is the best part of the dish.", "If using a cast iron skillet, you can serve the dish directly in the skillet for a rustic presentation, adding the dressing to the pan instead of a bowl.", "This technique works best with ripe, in-season tomatoes. If using winter supermarket tomatoes, add a pinch of sugar to the dressing."]', '"This preparation draws on Mediterranean traditions where vegetables are often treated with high heat to concentrate flavor, then dressed simply with high-quality oil and vinegar. It mimics the flavor profile of ''Pan con Tomate'' but in a deconstructed, salad-like format."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('63fefef2-d266-4fe7-ae9a-385961bf0f22', 'Spicy Anchovy and Peanut Crunch (Ikan Bilis Goreng)', 'A highly addictive Southeast Asian bar snack balancing the deep umami of crispy dried anchovies with the earthiness of roasted peanuts. The heat from dried chilies and the sweetness of a caramelized glaze create a complex textural interplay of crunch and shatter.', 'Snack', 'Malaysian', 'Intermediate', '[{"group_name": "Main Components", "items": [{"name": "dried anchovies (ikan bilis)", "quantity": 150, "unit": "g", "preparation": "peeled and split", "notes": "Select high-grade, whitish-blue dried anchovies for best texture", "substitutions": [], "ingredient_id": "cfdad407-c486-4fcc-9e47-7dd4cb32277c", "nutrition_source": "Aggregated Public Data"}, {"name": "raw peanuts", "quantity": 200, "unit": "g", "preparation": "skin-on", "notes": "Spanish peanuts work best", "substitutions": [], "ingredient_id": "033645df-fab2-4821-be6d-1744f9f55816", "nutrition_source": "Aggregated Public Data"}, {"name": "neutral oil", "quantity": 500, "unit": "ml", "preparation": "for frying", "notes": "Peanut, canola, or vegetable oil", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}]}, {"group_name": "Aromatics & Seasoning", "items": [{"name": "dried red chilies", "quantity": 15, "unit": "g", "preparation": "deseeded and cut into 2cm lengths", "notes": "Adjust quantity for heat preference", "substitutions": [], "ingredient_id": "a4bf8b34-30b2-4d24-a120-b5b191811f64", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "thinly sliced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "white sugar", "quantity": 20, "unit": "g", "preparation": null, "notes": "Superfine sugar dissolves best", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "Use sparingly as anchovies are naturally salty", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Rinse the dried anchovies thoroughly in cold water to remove excess salt and dust. Drain immediately and pat extremely dry with paper towels or air dry for 10 minutes. Moisture is the enemy of crispiness.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": ["If the anchovies are wet when they hit the oil, they will steam instead of fry and become chewy."]}, {"step_number": 2, "phase": "cook", "text": "Heat the oil in a wok to 160\u00b0C/320\u00b0F. Add the raw peanuts. Fry gently, stirring constantly, until they turn light golden brown and the bubbling subsides. Remove with a spider strainer and drain on paper towels.", "structured": {"action": "FRY", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT5M", "doneness_cues": {"visual": "Light golden brown color", "tactile": "Bubbling around peanuts reduces significantly"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Increase oil heat to 180\u00b0C/350\u00b0F. Fry the dried anchovies in batches. They will bubble aggressively at first. Fry until the bubbling almost stops and they are golden and light. Remove and drain.", "structured": {"action": "FRY", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown", "tactile": "Crisp and light"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Turn off the heat but leave the oil warm. Quickly flash-fry the dried chilies and garlic slices for 10-15 seconds until fragrant but not burnt. Remove immediately.", "structured": {"action": "FRY", "temperature": null, "duration": "PT15S", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove all but 1 tablespoon (15ml) of oil from the wok. Heat over low heat. Add the fried peanuts, anchovies, chilies, and garlic back to the pan. Sprinkle with sugar and salt. Toss continuously for 1-2 minutes until the sugar melts slightly and coats the mixture.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Spread the mixture onto a flat tray lined with baking paper to cool completely. The mixture will crisp up further as it cools.", "structured": {"action": "COOL", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT15M", "total_time": "PT40M", "overnight_required": false, "yields": "4 cups", "yield_count": 8, "serving_size_g": 40}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free"], "not_suitable_for": ["Shellfish allergy sufferers (cross-contamination risk in dried fish processing)", "Individuals with nut allergies"]}', '{"per_serving": {"calories": 182.93, "protein_g": 10.31, "carbohydrates_g": 7.77, "fat_g": 13.28, "saturated_fat_g": 1.9, "trans_fat_g": null, "monounsaturated_fat_g": null, "polyunsaturated_fat_g": 0.01, "fiber_g": 2.56, "sugar_g": 3.51, "sodium_mg": 142.72, "cholesterol_mg": null, "potassium_mg": 283.31, "calcium_mg": 53.57, "iron_mg": 2.27, "magnesium_mg": 49.97, "phosphorus_mg": 146.18, "zinc_mg": 1.1, "vitamin_a_mcg": 0.01, "vitamin_c_mg": 1.71, "vitamin_d_mcg": null, "vitamin_e_mg": null, "vitamin_k_mcg": 0.03, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": null, "thiamin_mg": null, "riboflavin_mg": null, "niacin_mg": 0.01, "folate_mcg": 0.06, "water_g": 1.1, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Do not refrigerate; humidity ruins the texture.", "duration": null}, "freezer": {"duration": null}, "reheating": "Re-crisp in a dry pan or low oven if softened.", "does_not_keep": false}', '[{"name": "Wok or deep frying pan", "required": true, "alternative": null}, {"name": "Spider strainer or slotted spoon", "required": true, "alternative": null}, {"name": "Paper towel-lined baking sheet", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": true, "alternative": null}]', '[{"symptom": "Anchovies are chewy or tough", "likely_cause": "Oil temperature was too low or anchovies were not dried properly before frying", "prevention": "Ensure oil is 180\u00b0C (350\u00b0F) and anchovies are bone-dry before frying", "fix": "Refry them briefly in hot oil for 30 seconds"}, {"symptom": "Garlic or chilies taste bitter", "likely_cause": "Burnt during the flash-fry step", "prevention": "Fry them in residual heat or for only seconds; they carry over cook significantly", "fix": "Pick out the burnt aromatics; do not serve them"}]', '["Grade Matters: Look for ''Ikan Bilis Mata Biru'' (Blue Eye Anchovy) from Pangkor or Langkawi for the premium, less salty experience.", "The Cold Start: If you are unsure about frying peanuts, start them in cold oil and bring the heat up together. This ensures the center is cooked before the skin burns.", "Storage: This must be stored in an absolute airtight container with a silica gel packet if possible. Humidity makes the sugar sticky and the fish soft within hours."]', '"Known as Ikan Bilis Goreng in Malaysia and Indonesia, this is a foundational element of Nasi Lemak but stands alone as a popular beer snack or appetizer. It showcases the Southeast Asian mastery of texture, balancing the shatter-crisp of dried seafood with the dense crunch of legumes."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('64014345-ccfa-4114-a678-2fb26295e6d4', 'Roasted Tomatillo Salsa Verde', 'A vibrant, zesty salsa balancing the tart acidity of roasted tomatillos with the smoky heat of blistered jalapeños. Fresh cilantro and crisp white onion provide a bright, herbaceous finish.', 'Condiment', 'Mexican', 'Easy', '[{"group_name": "Base Vegetables", "items": [{"name": "tomatillos", "quantity": 450, "unit": "g", "preparation": "husked and rinsed", "notes": "approx 8-10 medium tomatillos", "substitutions": [], "ingredient_id": "5e6c5eb7-cabd-41cc-b0e6-c48db933110e", "nutrition_source": "USDA FoodData Central"}, {"name": "jalape\u00f1o peppers", "quantity": 2, "unit": null, "preparation": "whole", "notes": "approx 40g total; use 1 for mild heat", "substitutions": [], "ingredient_id": "4253d4ec-8462-43c6-963a-ae1f94367e2b", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "unpeeled", "notes": "approx 8g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Fresh Aromatics", "items": [{"name": "white onion", "quantity": 40, "unit": "g", "preparation": "roughly chopped", "notes": "about 1/4 small onion", "substitutions": [], "ingredient_id": "ee82a9b0-15f7-45cd-bd5f-ba0b65eb1100", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "leaves and tender stems", "notes": "approx 1/2 cup packed", "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Set your oven broiler to high. Arrange the husked tomatillos, whole jalape\u00f1os, and unpeeled garlic cloves on a baking sheet lined with foil for easy cleanup.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 260, "fahrenheit": 500}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Broil the vegetables for 5-7 minutes, flipping halfway through, until the tomatillos are blistered and charred in spots and the peppers have softened.", "structured": {"action": "BROIL", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Blackened spots on skins", "tactile": "Tomatillos are soft to the touch"}}, "tips": ["Watch the garlic closely; remove it earlier if it starts to burn."]}, {"step_number": 3, "phase": "prep", "text": "Remove from the oven and let cool for 10 minutes. Once handleable, squeeze the roasted garlic out of its skin and discard the skin. If a milder salsa is desired, remove the seeds and ribs from the jalape\u00f1os.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Place the roasted tomatillos (including any juices on the pan), roasted jalape\u00f1os, peeled roasted garlic, fresh white onion, cilantro, lime juice, and salt into a blender or food processor.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Pulse until combined but still slightly chunky. Do not puree until completely smooth unless a distinct sauce texture is desired.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT30S", "doneness_cues": {"visual": "Uniformly chopped with visible flecks of cilantro and char", "tactile": null}}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT15M", "total_time": "PT30M", "overnight_required": false, "yields": "500ml", "yield_count": 16, "serving_size_g": 30}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Paleo", "Whole30", "Keto", "Low-Carb", "Sugar-Free", "Low-Sodium"], "not_suitable_for": ["Individuals with nightshade sensitivity"]}', '{"per_serving": {"calories": 9.33, "protein_g": 0.44, "carbohydrates_g": 2.09, "fat_g": 0.08, "saturated_fat_g": 0.01, "trans_fat_g": null, "monounsaturated_fat_g": 0.01, "polyunsaturated_fat_g": 0.02, "fiber_g": 0.46, "sugar_g": 1.39, "sodium_mg": 77.18, "cholesterol_mg": null, "potassium_mg": 75.35, "calcium_mg": 5.8, "iron_mg": 0.16, "magnesium_mg": 3.39, "phosphorus_mg": 9.42, "zinc_mg": 0.03, "vitamin_a_mcg": 27.99, "vitamin_c_mg": 7.27, "vitamin_d_mcg": null, "vitamin_e_mg": 0.11, "vitamin_k_mcg": 2.86, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": null, "thiamin_mg": 0.02, "riboflavin_mg": 0.01, "niacin_mg": 0.15, "folate_mcg": 2.64, "water_g": 27.3, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors meld and improve after 24 hours.", "duration": "P1W"}, "freezer": {"notes": "Texture may become slightly more watery upon thawing; blend briefly to re-emulsify.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Food processor or Blender", "required": true, "alternative": "Molcajete (mortar and pestle)"}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Salsa is too sour or acidic", "likely_cause": "Tomatillos were underripe or naturally very tart", "prevention": "Choose tomatillos that fill their husks completely", "fix": "Stir in 1/2 teaspoon of sugar or agave syrup to neutralize the acidity"}, {"symptom": "Salsa is too thick or gelatinous", "likely_cause": "Natural pectin in tomatillos gelling after cooling", "prevention": "Normal behavior for tomatillos", "fix": "Stir in 1 tablespoon of water or extra lime juice to thin it out"}]', '["Washing tomatillos is crucial; they have a sticky residue under the husk containing saponins which can taste bitter if not rinsed off with warm water.", "For the most authentic flavor, use fresh white onion rather than yellow or red; the sharp bite cuts through the richness of the roasted tomatillos.", "This salsa serves as an excellent base (simmered) for Chilaquiles Verdes or Enchiladas Suizas.", "Roasting the garlic in its skin prevents it from turning acrid and burnt under the broiler, resulting in a sweet, mellow garlic flavor."]', '"Salsa Verde dates back to the Aztec empire, utilizing the tomatillo (Physalis philadelphica), a staple distinct from the red tomato. While often eaten raw (cruda), this roasted version deepens the flavors, a technique common in Central Mexican cuisine to reduce acidity and increase savory notes."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('661bbc84-dd97-42da-ba47-4de365a2205c', 'Ginger Coconut Whole Wheat Scones', 'Nutty, tender scones featuring the earthy depth of whole wheat pastry flour, brightened by zesty crystallized ginger and the subtle, creamy sweetness of coconut.', 'Baked Good', 'British', 'Intermediate', '[{"group_name": "Dry Ingredients", "items": [{"name": "whole wheat pastry flour", "quantity": 260, "unit": "g", "preparation": null, "notes": "spooned and leveled", "substitutions": [], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}, {"name": "cane sugar", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 12, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "ground ginger", "quantity": 2, "unit": "g", "preparation": null, "notes": "dried powder", "substitutions": [], "ingredient_id": "401ddd0b-3597-4b46-bb54-f3bc755048bb", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "unsweetened shredded coconut", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "dbd3e1d1-e181-4364-b869-f2e9c0f15317", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Cold Fats & Mix-ins", "items": [{"name": "unsalted butter", "quantity": 85, "unit": "g", "preparation": "very cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "crystallized ginger", "quantity": 40, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "94aa0dff-461d-4081-b1aa-bac372e8fc0d", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "coconut milk", "quantity": 120, "unit": "ml", "preparation": "cold, full-fat canned", "notes": "plus 15ml for brushing", "substitutions": ["heavy cream"], "ingredient_id": "c037ee7e-e3ed-4340-b8fb-d8ad284ba96e", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Topping", "items": [{"name": "turbinado sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 205\u00b0C (400\u00b0F). Line a baking sheet with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 205, "fahrenheit": 401}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, whisk together the whole wheat pastry flour, cane sugar, baking powder, ground ginger, salt, and shredded coconut until well combined.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Add the cold, cubed butter to the dry ingredients. Use a pastry blender or your fingertips to cut the butter into the flour until the mixture resembles coarse crumbs with some pea-sized pieces of butter remaining.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Coarse crumbs, pea-sized butter bits", "tactile": "Cold and sandy"}}, "tips": ["If the butter starts melting, put the bowl in the freezer for 5 minutes."]}, {"step_number": 4, "phase": "prep", "text": "Toss the chopped crystallized ginger into the flour mixture ensuring the pieces are coated and not stuck together.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Make a well in the center. Pour in the cold coconut milk and vanilla extract. Stir gently with a spatula just until a shaggy dough forms. Do not overmix.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Shaggy dough, no dry flour pockets", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Turn the dough onto a lightly floured surface. Gently pat it into a circle approximately 2.5cm (1 inch) thick. Use a bench scraper or knife to cut the circle into 8 equal wedges.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Transfer wedges to the prepared baking sheet, spacing them 5cm apart. Brush the tops with the reserved coconut milk and sprinkle with turbinado sugar.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Bake for 18-22 minutes, or until the tops are golden brown and the edges look set.", "structured": {"action": "BAKE", "temperature": {"celsius": 205, "fahrenheit": 401}, "duration": "PT20M", "doneness_cues": {"visual": "Golden brown tops", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove from the oven and transfer to a wire rack to cool slightly before serving.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT40M", "overnight_required": false, "yields": "8 scones", "yield_count": 8, "serving_size_g": 75}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegans (contains butter)", "Gluten intolerance"]}', '{"per_serving": {"calories": 296.11, "protein_g": 3.84, "carbohydrates_g": 39.06, "fat_g": 15.11, "saturated_fat_g": 8.68, "trans_fat_g": null, "monounsaturated_fat_g": 2.73, "polyunsaturated_fat_g": 0.74, "fiber_g": 5.44, "sugar_g": 10.27, "sodium_mg": 311.02, "cholesterol_mg": 22.84, "potassium_mg": 174.76, "calcium_mg": 106.39, "iron_mg": 1.7, "magnesium_mg": 44.81, "phosphorus_mg": 155.83, "zinc_mg": 1.08, "vitamin_a_mcg": 72.68, "vitamin_c_mg": 0.42, "vitamin_d_mcg": null, "vitamin_e_mg": 0.44, "vitamin_k_mcg": 1.38, "vitamin_b6_mg": 0.07, "vitamin_b12_mcg": 0.02, "thiamin_mg": 0.1, "riboflavin_mg": 0.07, "niacin_mg": 1.88, "folate_mcg": 11.85, "water_g": 16.32, "alcohol_g": 0.22, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container; texture is best fresh.", "duration": "P3D"}, "freezer": {"notes": "Freeze unbaked wedges for best results, baking from frozen with added time.", "duration": "P3M"}, "reheating": "Warm in a 150\u00b0C/300\u00b0F oven for 5-8 minutes to restore crispness.", "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Pastry blender", "required": false, "alternative": "Two knives or fingertips"}, {"name": "Bench scraper or sharp knife", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}]', '[{"symptom": "Scones are tough or dense", "likely_cause": "Overworking the dough developed too much gluten", "prevention": "Stop mixing as soon as the dough comes together; it should look shaggy/rough before patting out.", "fix": "Cannot be fixed once baked; serve warm with plenty of butter or jam."}, {"symptom": "Scones spread too much and are flat", "likely_cause": "Butter became too warm before baking", "prevention": "Keep ingredients cold; chill shaped scones in the fridge for 15 minutes before baking if your kitchen is warm.", "fix": "None"}]', '["Using whole wheat pastry flour is crucial here; regular whole wheat flour has a higher protein content that will result in a tough, heavy scone.", "Canned full-fat coconut milk provides the best tenderness due to its fat content. If using carton coconut beverage, the scones will be drier and less rich.", "Ensure your baking powder is fresh. Whole wheat flour is heavier than white flour and requires active leavening to achieve a good rise."]', '"Scones originated in Scotland in the early 1500s as quick breads cooked on griddles. This variation incorporates modern health-conscious ingredients like whole grains and tropical influences via coconut, bridging traditional British tea time with global flavor profiles."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('6cb85aa3-0523-430f-83ff-462e4c0ab96d', 'Aerial Chocolate Raspberry Sponge', 'A feather-light, fatless chocolate sponge that relies on aerated eggs rather than butter for its cloud-like lift. Filled with a sharp, ruby-red raspberry compote that cuts through the cocoa richness, serving as both the filling and a vibrant drizzle. An elegant, guilt-free finish to a meal.', 'Dessert', 'French', 'Intermediate', '[{"group_name": "Fatless Chocolate Sponge", "items": [{"name": "large eggs", "quantity": 4, "unit": null, "preparation": "room temperature", "notes": "approx 200g total without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "caster sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "cake flour", "quantity": 80, "unit": "g", "preparation": null, "notes": "low protein flour ensures tenderness", "substitutions": ["all-purpose flour"], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "dutch-process cocoa powder", "quantity": 25, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c06a8e5a-163a-4f21-ad00-a6d90e34c38c", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Raspberry Compote & Drizzle", "items": [{"name": "fresh raspberries", "quantity": 300, "unit": "g", "preparation": null, "notes": null, "substitutions": ["frozen raspberries"], "ingredient_id": "f4f5b84c-c364-40cd-b737-375755e481f9", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Garnish", "items": [{"name": "icing sugar", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh raspberries", "quantity": 8, "unit": null, "preparation": null, "notes": "whole, for topping", "substitutions": [], "ingredient_id": "f4f5b84c-c364-40cd-b737-375755e481f9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 170\u00b0C/340\u00b0F. Line the bottom of a 20cm round cake tin with parchment paper. Do not grease the sides of the tin; the batter needs to grip the sides to rise properly.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Sift the cake flour and cocoa powder together three times. This aerates the dry ingredients to prevent clumps from deflating the egg foam later.", "structured": {"action": "SIFT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Combine eggs, caster sugar, and vanilla in a large heatproof bowl set over a pan of simmering water (bain-marie). Whisk constantly until the sugar dissolves and the mixture is warm to the touch (about 40\u00b0C/105\u00b0F).", "structured": {"action": "WHISK", "temperature": {"celsius": 40, "fahrenheit": 104}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Remove from heat and whisk on high speed using an electric mixer until the mixture has tripled in volume, is pale, and reaches the ''ribbon stage'' (where a trail of batter stays on the surface for a few seconds before sinking). This takes about 5-7 minutes.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Pale, tripled volume, ribbon stage", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Gently fold the sifted flour and cocoa into the egg foam in three batches. Use a metal spoon or spatula to cut down the center and fold over the top. Be extremely gentle to retain the air bubbles.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not overmix or the cake will be rubbery and flat."]}, {"step_number": 6, "phase": "cook", "text": "Pour the batter into the prepared tin and bake immediately for 20-25 minutes. The cake is done when the top springs back when lightly pressed and the sides pull away slightly from the tin.", "structured": {"action": "BAKE", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": "PT25M", "doneness_cues": {"visual": "Sides pulling away from tin", "tactile": "Springs back when touched"}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "While the cake bakes, combine raspberries, granulated sugar, lemon juice, and water in a small saucepan. Simmer over medium heat until the fruit breaks down and the sauce thickens slightly, about 10 minutes. Strain half for a smooth drizzle, keep the other half chunky for filling. Let cool completely.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Once the cake is cool, remove from the tin. Slice horizontally into two layers. Spread the chunky raspberry compote in the middle. Top with the second sponge layer.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Dust the top with icing sugar and drizzle with the smooth raspberry coulis. Garnish with fresh raspberries before serving.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT1H", "total_time": "PT1H35M", "overnight_required": false, "yields": "8 slices", "yield_count": 8, "serving_size_g": 85}', '{"flags": ["Vegetarian", "Dairy-Free", "Nut-Free", "Soy-Free", "Low-Sodium"], "not_suitable_for": []}', '{"per_serving": {"calories": 172.57, "protein_g": 5.28, "carbohydrates_g": 32.73, "fat_g": 3.17, "saturated_fat_g": 1.06, "trans_fat_g": 0.01, "monounsaturated_fat_g": 1.09, "polyunsaturated_fat_g": 0.69, "fiber_g": 4.06, "sugar_g": 20.15, "sodium_mg": 37.07, "cholesterol_mg": 93, "potassium_mg": 156.44, "calcium_mg": 29.99, "iron_mg": 1.28, "magnesium_mg": 29.87, "phosphorus_mg": 95.12, "zinc_mg": 0.78, "vitamin_a_mcg": 40.81, "vitamin_c_mg": 11.1, "vitamin_d_mcg": 0.5, "vitamin_e_mg": 0.63, "vitamin_k_mcg": 3.34, "vitamin_b6_mg": 0.08, "vitamin_b12_mcg": 0.22, "thiamin_mg": 0.04, "riboflavin_mg": 0.15, "niacin_mg": 0.46, "folate_mcg": 24.11, "water_g": 58.45, "alcohol_g": 0.22, "caffeine_mg": 7.19}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to prevent drying out.", "duration": "P2D"}, "freezer": {"notes": "Freeze sponge layers without filling only.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Stand mixer or electric hand whisk", "required": true, "alternative": null}, {"name": "20cm (8 inch) round cake tin", "required": true, "alternative": null}, {"name": "Large metal spoon or spatula", "required": true, "alternative": "Silicone spatula"}, {"name": "Sieve", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}]', '[{"symptom": "The cake collapsed or turned out dense and rubbery", "likely_cause": "The air was knocked out of the eggs during the folding stage, or the dry ingredients were not folded in gently enough.", "prevention": "Fold using a ''cut and turn'' motion and stop exactly when no flour streaks remain.", "fix": "Cannot be fixed. Use dense cake pieces for a trifle."}]', '["Warming the eggs and sugar before whisking helps dissolve the sugar and relaxes the egg proteins, allowing them to whip to a greater volume.", "Because there is no fat (butter or oil) in the sponge, this cake is best eaten on the day it is made. It relies on the moisture from the filling to stay palatable.", "If using frozen raspberries for the compote, you may need to simmer for an extra 2-3 minutes to evaporate the excess water content.", "Dutch-process cocoa is essential here; natural cocoa is more acidic and can react with the egg foam structure unpredictably in this specific chemical-leavener-free formula."]', '"This recipe is a variation of the ''Genoise'' sponge, a fundamental building block of French p\u00e2tisserie named after the city of Genoa. While traditional Genoise often contains melted butter, this fatless version (Biscuit de Savoie style) was historically favored for its lightness and ability to soak up syrups and liqueurs without becoming heavy."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('703fe65a-f159-400d-8df3-760611d06c04', 'Blueberry Teff & Oat Power Pancakes', 'Hearty, nutrient-packed pancakes featuring the nutty, malty flavor of ancient teff grain paired with the texture of rolled oats. These are fluffier than typical whole-grain pancakes thanks to the buttermilk reaction, bursting with jammy blueberries in every bite.', 'Breakfast', 'American', 'Easy', '[{"group_name": "Dry Ingredients", "items": [{"name": "teff flour", "quantity": 100, "unit": "g", "preparation": "brown or ivory", "notes": "approx 3/4 cup", "substitutions": [], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}, {"name": "whole wheat flour", "quantity": 60, "unit": "g", "preparation": null, "notes": "approx 1/2 cup", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "old-fashioned rolled oats", "quantity": 50, "unit": "g", "preparation": null, "notes": "do not use steel cut", "substitutions": [], "ingredient_id": "4490fcb6-a551-427f-885d-b3589c1c21c2", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 8, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5c0b5fc8-b210-4e39-b3a6-479541ac45d2", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "buttermilk", "quantity": 360, "unit": "ml", "preparation": "shaken", "notes": null, "substitutions": [], "ingredient_id": "de1c3d44-e3e7-47d2-a315-83a46edfb165", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "large", "notes": "approx 100g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": "melted and cooled", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "maple syrup", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c9ca1f35-b107-46c2-92a3-4c1c620f3c11", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Mix-ins & Cooking", "items": [{"name": "fresh blueberries", "quantity": 150, "unit": "g", "preparation": "washed and dried", "notes": null, "substitutions": ["frozen blueberries (do not thaw)"], "ingredient_id": "0f9f22a4-4f00-4950-9145-943d55b6dec8", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 10, "unit": "g", "preparation": null, "notes": "for greasing pan", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a large mixing bowl, whisk together the teff flour, whole wheat flour, rolled oats, baking powder, baking soda, salt, and cinnamon until well combined.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a medium bowl, whisk the buttermilk, eggs, melted butter, maple syrup, and vanilla extract until smooth.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Pour the wet ingredients into the dry ingredients. Mix gently with a spatula just until no dry flour streaks remain. Do not overmix; the batter should be slightly lumpy. Let the batter rest for 10 minutes to allow the teff and oats to hydrate.", "structured": {"action": "MIX", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": ["Resting is crucial for teff flour to soften and absorb liquid, preventing a gritty texture."]}, {"step_number": 4, "phase": "cook", "text": "Preheat a skillet or griddle over medium heat (approx 190\u00b0C/375\u00b0F). Brush the surface lightly with butter.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Ladle 60ml (1/4 cup) portions of batter onto the hot skillet. Immediately press a small handful of blueberries onto the top of each pancake.", "structured": {"action": "POUR", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Placing berries on top rather than mixing them in prevents the batter from turning grey."]}, {"step_number": 6, "phase": "cook", "text": "Cook for 2-3 minutes until bubbles form on the surface and the edges look set and dry. Flip carefully.", "structured": {"action": "FRY", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Bubbles on surface, set edges", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Cook on the second side for another 1-2 minutes until golden brown and the center springs back when lightly pressed.", "structured": {"action": "FRY", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": null, "tactile": "Springs back when pressed"}}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT10M", "total_time": "PT30M", "overnight_required": false, "yields": "12 pancakes", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 404.96, "protein_g": 12.61, "carbohydrates_g": 54.85, "fat_g": 16.13, "saturated_fat_g": 8.62, "trans_fat_g": 0.01, "monounsaturated_fat_g": 4.74, "polyunsaturated_fat_g": 1.65, "fiber_g": 6.22, "sugar_g": 13.62, "sodium_mg": 602.53, "cholesterol_mg": 126.16, "potassium_mg": 593.69, "calcium_mg": 241.29, "iron_mg": 2.5, "magnesium_mg": 72.71, "phosphorus_mg": 437.52, "zinc_mg": 2.19, "vitamin_a_mcg": 147.85, "vitamin_c_mg": 4.56, "vitamin_d_mcg": 0.5, "vitamin_e_mg": 1, "vitamin_k_mcg": 9.04, "vitamin_b6_mg": 0.16, "vitamin_b12_mcg": 0.45, "thiamin_mg": 0.25, "riboflavin_mg": 0.44, "niacin_mg": 1.9, "folate_mcg": 36.84, "water_g": 143.11, "alcohol_g": 0.43, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container.", "duration": "P3D"}, "freezer": {"notes": "Freeze in a single layer before stacking with parchment paper in between.", "duration": "P2M"}, "reheating": "Toaster or oven at 175\u00b0C (350\u00b0F) until warmed through.", "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Medium mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Non-stick skillet or Griddle", "required": true, "alternative": "Cast iron skillet"}, {"name": "Spatula", "required": true, "alternative": null}]', '[{"symptom": "Pancakes are dark on the outside but raw/gummy inside", "likely_cause": "Heat is too high, causing the sugar and teff to burn before the interior cooks", "prevention": "Lower the heat to medium-low after the skillet is preheated", "fix": "Finish cooking the remaining pancakes in a 175\u00b0C/350\u00b0F oven for 3-5 minutes"}]', '["Teff flour is technically gluten-free, but because it is a heavy grain, we use a portion of wheat flour in this recipe to ensure the pancakes hold together well. If strict gluten-free is required, replace the wheat flour with a 1:1 GF baking blend.", "If using frozen blueberries, do not thaw them beforehand, or they will bleed excessive juice into the batter.", "The resting step (Step 3) is non-negotiable when working with whole grains like teff and oats; skipping it will result in flat, gritty pancakes.", "Leftovers can be popped directly into a toaster from the freezer for a quick weekday breakfast."]', '"Teff is an ancient grain originating from Ethiopia and Eritrea, traditionally fermented to make Injera. In this modern American breakfast application, its mild, malty flavor pairs exceptionally well with the rustic texture of oats, providing a high-iron, high-fiber alternative to standard refined flour pancakes."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('712d1e01-a761-47cb-bfb3-2911ce5c15a4', 'Classic San Marzano Pomodoro', 'A vibrant, velvety foundation sauce balancing the natural sweetness of sun-ripened tomatoes with the savory depth of garlic and fruity olive oil. The texture is rustic yet cohesive, perfect for coating pasta or using as a pizza base.', 'Sauce', 'Italian', 'Easy', '[{"group_name": "Base", "items": [{"name": "whole peeled tomatoes", "quantity": 800, "unit": "g", "preparation": "canned", "notes": "San Marzano variety preferred for sweetness", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": "Use high quality oil", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 4, "unit": null, "preparation": "thinly sliced", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Seasoning & Aromatics", "items": [{"name": "fresh basil", "quantity": 2, "unit": null, "preparation": "whole sprigs", "notes": "approx. 10g", "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 4, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "red pepper flakes", "quantity": 1, "unit": "g", "preparation": null, "notes": "for a gentle heat", "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pour the canned tomatoes and their juices into a large bowl. Using clean hands, crush the tomatoes into coarse chunks, removing any hard stem ends or tough skins if present.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Tomatoes are broken down but still chunky"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Combine the olive oil and sliced garlic in a heavy-bottomed saucepan. Turn the heat to medium-low. Cook gently, stirring occasionally, until the garlic is fragrant and pale gold, about 2-3 minutes. Do not let it brown.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT3M", "doneness_cues": {"visual": "Garlic is pale gold", "tactile": "Fragrant aroma"}}, "tips": ["Starting garlic in cold oil infuses the oil more effectively than dropping it into hot oil.", "If using red pepper flakes, add them during the last 30 seconds of this step."]}, {"step_number": 3, "phase": "cook", "text": "Carefully pour the crushed tomatoes and juices into the pan (watch for splatter). Add the basil sprigs and salt. Stir to combine.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Increase heat to medium to bring to a gentle bubble, then reduce heat to low to maintain a steady simmer. Cook uncovered for 45 minutes, stirring occasionally, until the sauce has thickened and the oil separates slightly from the tomatoes.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT45M", "doneness_cues": {"visual": "Oil pools on surface, sauce coats the back of a spoon", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove and discard the wilted basil sprigs. Taste the sauce. If it tastes too acidic, add a pinch of sugar (optional). Add more salt if needed.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT45M", "total_time": "PT55M", "overnight_required": false, "yields": "800ml", "yield_count": 6, "serving_size_g": 130}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Paleo", "Whole30"], "not_suitable_for": []}', '{"per_serving": {"calories": 116.29, "protein_g": 1.37, "carbohydrates_g": 5.99, "fat_g": 10.32, "saturated_fat_g": 1.43, "trans_fat_g": null, "monounsaturated_fat_g": 7.31, "polyunsaturated_fat_g": 1.08, "fiber_g": 2.51, "sugar_g": 5.24, "sodium_mg": 265.99, "cholesterol_mg": null, "potassium_mg": 332.44, "calcium_mg": 20.41, "iron_mg": 0.52, "magnesium_mg": 16.49, "phosphorus_mg": 36.48, "zinc_mg": 0.27, "vitamin_a_mcg": 7.87, "vitamin_c_mg": 19.32, "vitamin_d_mcg": null, "vitamin_e_mg": 1.51, "vitamin_k_mcg": 13.1, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": null, "thiamin_mg": null, "riboflavin_mg": 0.01, "niacin_mg": 0.04, "folate_mcg": 1.37, "water_g": 2.72, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container once fully cooled.", "duration": "P5D"}, "freezer": {"notes": "Leave 2cm headspace in container for expansion.", "duration": "P3M"}, "reheating": "Simmer gently over low heat, adding a splash of water if too thick.", "does_not_keep": false}', '[{"name": "Heavy-bottomed saucepan or Dutch oven", "required": true, "alternative": "Large skillet with high sides"}, {"name": "Wooden spoon", "required": true, "alternative": null}, {"name": "Large bowl", "required": true, "alternative": null}]', '[{"symptom": "Sauce tastes metallic or overly acidic", "likely_cause": "Tomatoes were under-ripe or lower quality canning", "prevention": "Use DOP certified San Marzano tomatoes", "fix": "Stir in a pinch of baking soda (neutralizes acid) or 2g of sugar (masks acid)"}, {"symptom": "Garlic tastes bitter", "likely_cause": "Garlic was burned during the saut\u00e9 step", "prevention": "Start garlic in cold oil and keep heat low", "fix": "Cannot be fixed; the burnt flavor permeates the oil. You must restart the base."}]', '["Hand-crushing the tomatoes results in a superior rustic texture compared to using a blender, which can aerate the sauce and turn it orange.", "The ''oil slick'' that appears on top at the end is a sign of a properly cooked sauce; stir it back in before serving for a glossy finish.", "For a smooth ''passata'' style sauce, you can pass the finished product through a food mill, but remove the basil first.", "If you have a parmesan rind, add it during the simmer step for extra umami, but remove before serving."]', '"Known simply as ''Sugo di Pomodoro'' in Italy, this is the mother sauce of Southern Italian cooking. While tomatoes originated in the Americas, this specific technique of slow-simmering them with a soffritto of garlic and oil became a Neapolitan staple in the late 18th century."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('732b4cdf-d611-4bf6-8cdd-1e594d93c892', 'Zuppa alla Pavese', 'A comforting, rustic Italian soup originating from Pavia, consisting of rich hot broth poured over butter-fried bread and a perfectly poached egg, finished with a generous dusting of Parmesan.', 'Soup', 'Italian', 'Easy', '[{"group_name": "Broth", "items": [{"name": "chicken broth", "quantity": 600, "unit": "ml", "preparation": "high quality", "notes": "homemade or low-sodium preferred", "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Toast & Toppings", "items": [{"name": "crusty white bread", "quantity": 2, "unit": null, "preparation": "sliced 2cm thick", "notes": "approx. 40-50g per slice", "substitutions": [], "ingredient_id": "c4052e66-d9d4-41e7-a365-cd88abcd9202", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "fresh, room temperature", "notes": "approx. 60g each", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "parmesan cheese", "quantity": 30, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh chives", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Heat the chicken broth in a medium saucepan over medium heat until it reaches a gentle simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "While broth heats, melt butter in a frying pan over medium heat. Fry the bread slices until golden brown and crispy on both sides.", "structured": {"action": "FRY", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT4M", "doneness_cues": {"visual": "Golden brown", "tactile": "Crispy"}}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "Place one slice of toasted bread into the bottom of each serving bowl. Sprinkle half of the grated Parmesan cheese directly onto the hot toast.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Crack the eggs directly into the simmering broth. Poach gently for about 3 minutes until the whites are set but the yolks remain runny.", "structured": {"action": "POACH", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT3M", "doneness_cues": {"visual": "Opaque whites", "tactile": "Soft yolk"}}, "tips": ["Crack eggs into a small ramekin first to avoid shell fragments.", "Ensure broth is not boiling vigorously or it will break the eggs."]}, {"step_number": 5, "phase": "finish", "text": "Carefully ladle a poached egg onto each slice of bread, then pour the hot broth around it. Garnish with remaining Parmesan, chives, and black pepper. Serve immediately.", "structured": {"action": "SERVE", "temperature": {"celsius": 70, "fahrenheit": 158}, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 350}', '{"flags": ["Nut-Free", "Peanut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": ["Vegans", "Vegetarians (if using chicken broth)"]}', '{"per_serving": {"calories": 900.03, "protein_g": 79.61, "carbohydrates_g": 25.72, "fat_g": 51.2, "saturated_fat_g": 20, "trans_fat_g": 0.33, "monounsaturated_fat_g": 18.66, "polyunsaturated_fat_g": 8.51, "fiber_g": 1.44, "sugar_g": 3.04, "sodium_mg": 694.63, "cholesterol_mg": 458.1, "potassium_mg": 829.88, "calcium_mg": 304.16, "iron_mg": 4.97, "magnesium_mg": 102.28, "phosphorus_mg": 796.7, "zinc_mg": 3.93, "vitamin_a_mcg": 318.07, "vitamin_c_mg": 1.46, "vitamin_d_mcg": 2.48, "vitamin_e_mg": 1.94, "vitamin_k_mcg": 3.43, "vitamin_b6_mg": 1.73, "vitamin_b12_mcg": 1.77, "thiamin_mg": 0.4, "riboflavin_mg": 0.76, "niacin_mg": 31.59, "folate_mcg": 88.55, "water_g": 274.86, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best consumed immediately; bread becomes soggy and eggs do not reheat well.", "duration": null}, "freezer": {"duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Frying pan", "required": true, "alternative": null}, {"name": "Soup bowls", "required": true, "alternative": null}, {"name": "Ladle", "required": true, "alternative": null}]', '[{"symptom": "Egg whites spread too much in the broth", "likely_cause": "Broth was boiling too hard or eggs were not fresh", "prevention": "Keep broth at a very gentle simmer and use the freshest eggs possible", "fix": "Use a slotted spoon to gather stray whites before serving"}]', '["The quality of this dish relies entirely on the quality of the broth. Use a rich homemade stock or a high-quality bone broth for the best result.", "For an authentic touch, rub a clove of raw garlic on the toasted bread before placing it in the bowl.", "This dish is sometimes served by placing the raw egg on the bread and pouring boiling broth over it to cook it (Zuppa alla Pavese style), but poaching in the pot ensures consistent food safety and texture.", "If using store-bought broth, taste for salinity before adding extra salt, as the Parmesan and butter add significant sodium."]', '"Legend has it that King Francis I of France invented this dish after losing the Battle of Pavia in 1525. Seeking refuge in a peasant farmhouse, he was served this simple soup made from the limited ingredients available: stale bread, eggs, and broth."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('77f2862d-e8e1-4207-bfbd-52c0f5b3e184', 'Creamy Risotto with Tender Baby Artichokes', 'A luxurious Italian classic balancing the nutty, earthiness of fresh baby artichokes with the rich creaminess of perfectly cooked Arborio rice. Finished with a bright hint of lemon and savory Parmigiano Reggiano.', 'Main Course', 'Italian', 'Intermediate', '[{"group_name": "Artichoke Prep", "items": [{"name": "baby artichokes", "quantity": 8, "unit": null, "preparation": "whole", "notes": "approx 400g before trimming", "substitutions": ["frozen artichoke hearts (300g)", "canned artichoke hearts in water"], "ingredient_id": "071d7551-8bef-45ef-9c43-9fca9dd2ecae", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "halved", "notes": "for acidulated water", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 1000, "unit": "ml", "preparation": "cold", "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Risotto Base", "items": [{"name": "vegetable stock", "quantity": 1200, "unit": "ml", "preparation": "hot", "notes": "low-sodium preferred", "substitutions": ["chicken stock"], "ingredient_id": "93b5bf35-1f82-4ec2-a12c-5d219f15f241", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "divided use", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "shallots", "quantity": 2, "unit": null, "preparation": "finely chopped", "notes": "approx 60g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 4g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "arborio rice", "quantity": 320, "unit": "g", "preparation": null, "notes": null, "substitutions": ["carnaroli rice", "vialone nano rice"], "ingredient_id": "d8a2c73d-e2de-4182-b43b-6bdf55f00a87", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": "Pinot Grigio or Sauvignon Blanc", "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Mantecatura (Finishing)", "items": [{"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "parmigiano reggiano", "quantity": 60, "unit": "g", "preparation": "finely grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh mint", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": "optional", "substitutions": [], "ingredient_id": "17abecc0-a2a0-4478-8486-57b46e4305c9", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare a bowl of cold water and squeeze the lemon juice into it (drop the lemon halves in as well). This acidulated water prevents the artichokes from turning brown.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Trim the baby artichokes: snap off the tough outer dark green leaves until you reach the pale yellow tender leaves. Cut off the top third of the artichoke. Trim the stem end, peel the stem, and quarter the artichoke lengthwise. Remove any fuzzy choke if present (usually minimal in baby varieties). Immediately drop into lemon water.", "structured": {"action": "TRIM", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Be aggressive when removing outer leaves; if they feel tough to your thumb, they will be tough to eat."]}, {"step_number": 3, "phase": "prep", "text": "Pour the vegetable stock into the medium saucepan and bring to a gentle simmer. Keep it hot throughout the cooking process.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In the heavy-bottomed pot, heat 30g of butter and the olive oil over medium heat. Drain the artichokes and add them to the pot along with the shallots. Saut\u00e9 for 5-7 minutes until the shallots are soft and artichokes begin to brown slightly.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT7M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the minced garlic and Arborio rice. Toast the rice, stirring constantly, for 2 minutes until the edges of the grains are translucent and the center remains opaque (the ''pearl'').", "structured": {"action": "TOAST", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Pour in the white wine to deglaze the pan. Stir vigorously to release any fond from the bottom. Cook until the smell of alcohol dissipates and the liquid is almost entirely evaporated.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Begin adding the hot stock, one ladle at a time (approx 150ml). Stir frequently. Wait until the liquid is mostly absorbed before adding the next ladle. Regulate heat to maintain a steady, gentle simmer.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT18M", "doneness_cues": {"visual": "Rice looks creamy but distinct", "tactile": "Rice is al dente with a slight bite"}}, "tips": ["Constant stirring releases the starch from the rice, creating the signature creamy texture."]}, {"step_number": 8, "phase": "finish", "text": "Once the rice is tender but still has a slight bite (al dente) and the texture is fluid (not stiff), remove the pot from the heat. If it is too dry, add a final half-ladle of stock.", "structured": {"action": "REST", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Perform the ''mantecatura'': Vigorously stir in the cold cubed butter (45g), grated Parmesan, parsley, and mint. Season with salt and pepper to taste. Let sit for 2 minutes before serving.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT5M", "total_time": "PT50M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Vegetarian", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 476.22, "protein_g": 12.26, "carbohydrates_g": 47.62, "fat_g": 23.58, "saturated_fat_g": 12.28, "trans_fat_g": null, "monounsaturated_fat_g": 8.32, "polyunsaturated_fat_g": 1.15, "fiber_g": 3.65, "sugar_g": 11.92, "sodium_mg": 1299.02, "cholesterol_mg": 50.51, "potassium_mg": 725.76, "calcium_mg": 255.59, "iron_mg": 6.04, "magnesium_mg": 41.25, "phosphorus_mg": 247.13, "zinc_mg": 0.97, "vitamin_a_mcg": 173.64, "vitamin_c_mg": 22.91, "vitamin_d_mcg": 0.08, "vitamin_e_mg": 1.26, "vitamin_k_mcg": 45.47, "vitamin_b6_mg": 0.31, "vitamin_b12_mcg": 0.21, "thiamin_mg": 0.4, "riboflavin_mg": 0.14, "niacin_mg": 3.3, "folate_mcg": 92.04, "water_g": 426.62, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture will degrade; risotto is best eaten immediately.", "duration": "P3D"}, "freezer": {"notes": "Freezing is not recommended as rice will become grainy and mushy.", "duration": null}, "reheating": "Reheat gently on the stove with a splash of water or stock to loosen the starch structure.", "does_not_keep": false}', '[{"name": "Heavy-bottomed pot or Dutch oven", "required": true, "alternative": "Large deep saut\u00e9 pan"}, {"name": "Medium saucepan", "required": true, "alternative": "Microwave-safe bowl (for stock)"}, {"name": "Wooden spoon", "required": true, "alternative": null}, {"name": "Ladle", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Bowl", "required": true, "alternative": null}]', '[{"symptom": "Rice is crunchy in the middle", "likely_cause": "Undercooked or heat was too high causing liquid to evaporate before penetrating the grain", "prevention": "Maintain a gentle simmer and taste test frequently after 15 minutes", "fix": "Add another ladle of hot stock or water and cook for 2-3 more minutes, stirring constantly"}, {"symptom": "Risotto is gummy or gluey", "likely_cause": "Rice was stirred too aggressively or overcooked", "prevention": "Stir frequently but not violently; stop cooking when rice is al dente", "fix": "Stir in a splash of hot stock to loosen the texture immediately before serving"}]', '["The ''Mantecatura'' (Step 9) is the most critical step for texture. Using cold butter helps create a glossy, stable emulsion.", "Do not wash the rice before cooking; you need the surface starch to achieve the creamy consistency.", "If baby artichokes are unavailable, frozen artichoke hearts are a reliable substitute. Defrost and pat them dry before saut\u00e9ing.", "Serve on a flat plate rather than a deep bowl; the risotto should slowly spread outwards (all''onda) rather than sit in a pile."]', '"Risotto is a staple of Northern Italian cuisine, particularly in regions like Lombardy and Piedmont where rice paddies are abundant. This specific variation celebrates spring produce, pairing the bitterness of artichokes (carciofi) with the sweetness of dairy, a combination deeply rooted in Roman and Tuscan traditions."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('7a1a2a99-c45a-496f-a1b4-ee67fab1996d', 'Pan-Seared Salmon with Lime Herb Butter', 'Succulent, crispy-skinned salmon fillets melting under a crown of zesty lime and fresh dill compound butter. The brightness of the citrus cuts through the rich, flaky fish for a perfectly balanced finish.', 'Dinner', 'Modern American', 'Easy', '[{"group_name": "Compound Butter", "items": [{"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "softened to room temperature", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "lime zest", "quantity": 1, "unit": null, "preparation": null, "notes": "zest of 1 lime, approx 2g", "substitutions": [], "ingredient_id": "295e8d21-9ba3-4ab8-a118-b09b77defacc", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh lime juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh dill", "quantity": 5, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "4be2b047-475d-4c84-82d5-4883298c6121", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 5, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "minced or grated", "notes": "approx 3-5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Salmon", "items": [{"name": "salmon fillets", "quantity": 4, "unit": null, "preparation": "skin-on, pin bones removed", "notes": "approx 150g each, 600g total", "substitutions": [], "ingredient_id": "6648fae7-4f63-45b3-b45d-19d927b57c2d", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for searing", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 4, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a small mixing bowl, combine the softened butter, lime zest, lime juice, chopped dill, parsley, minced garlic, and a pinch of salt. Mash with a fork until thoroughly combined. Set aside at room temperature.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Pat the salmon fillets completely dry with paper towels. Moisture prevents searing. Season the flesh side generously with salt and black pepper.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat the olive oil in a heavy-bottomed skillet over medium-high heat. When the oil shimmers but is not smoking, carefully place the salmon fillets into the pan, skin-side down. Press gently with a spatula for 10 seconds to prevent curling.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Cook undisturbed for about 4-5 minutes until the skin is crispy and golden brown, and the opaque color has cooked about 2/3 of the way up the side of the fillet.", "structured": {"action": "FRY", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Skin is golden brown, flesh opaque halfway up", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Flip the fillets and cook for another 1-2 minutes until the internal temperature reaches 50\u00b0C (122\u00b0F) for medium-rare or 54\u00b0C (129\u00b0F) for medium. Do not overcook.", "structured": {"action": "FRY", "temperature": {"celsius": 52, "fahrenheit": 126}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove the pan from heat. Immediately place a generous spoonful of the lime herb butter on top of each fillet, allowing it to melt over the fish. Transfer to a plate and rest for 2 minutes before serving.", "structured": {"action": "REST", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT5M", "total_time": "PT20M", "overnight_required": false, "yields": "4 fillets", "yield_count": 4, "serving_size_g": 175}', '{"flags": ["Pescatarian", "Gluten-Free", "Low-Carb", "Keto", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": ["Dairy-Free", "Vegan", "Vegetarian"]}', '{"per_serving": {"calories": 540.67, "protein_g": 37.21, "carbohydrates_g": 6.66, "fat_g": 54.36, "saturated_fat_g": 8.1, "trans_fat_g": null, "monounsaturated_fat_g": 6.26, "polyunsaturated_fat_g": 0.86, "fiber_g": 0.22, "sugar_g": 0.1, "sodium_mg": 3435.46, "cholesterol_mg": 32.25, "potassium_mg": 30.97, "calcium_mg": 424.09, "iron_mg": 18.05, "magnesium_mg": 452.51, "phosphorus_mg": 457.43, "zinc_mg": 1.41, "vitamin_a_mcg": 519.3, "vitamin_c_mg": 3.79, "vitamin_d_mcg": null, "vitamin_e_mg": 0.91, "vitamin_k_mcg": 24.25, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.06, "folate_mcg": 4.55, "water_g": 7.49, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store salmon and butter separately if possible.", "duration": "P2D"}, "freezer": {"notes": "Compound butter freezes well; cooked salmon texture degrades.", "duration": "P1M"}, "reheating": "Gently reheat salmon in a low oven; add fresh butter after heating.", "does_not_keep": false}', '[{"name": "Heavy-bottomed skillet", "required": true, "alternative": "Non-stick frying pan"}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Fish spatula", "required": true, "alternative": "Standard spatula"}, {"name": "Microplane or zester", "required": true, "alternative": null}]', '[{"symptom": "Salmon skin sticks to the pan", "likely_cause": "Pan wasn''t hot enough or oil wasn''t shimmering before adding fish", "prevention": "Wait until the oil shimmers and barely smokes before adding fish; do not move it once placed", "fix": "Let it cook a minute longer; the skin often releases naturally once crisp. If stuck, slide a thin metal spatula firmly underneath to separate"}]', '["Pat the skin extremely dry before cooking; this is the secret to glass-like crispiness.", "If the butter separates when mixing in the lime juice, just keep whipping; the milk solids will eventually emulsify the liquid.", "For thicker fillets, you can sear the skin and then finish in a 200\u00b0C (400\u00b0F) oven for 3-4 minutes to ensure even cooking without burning the skin.", "Leftover compound butter is excellent on roasted vegetables, steak, or grilled corn."]', '"Compound butters (beurre compos\u00e9) are a staple of classic French cuisine used to instantly create sauce-like richness. This recipe adapts the technique with bright New World flavors\u2014lime and cilantro/dill\u2014popular in contemporary coastal American dining."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('7a2b5ab4-02e9-45d4-a5bc-34c507f5a917', 'Classic Greek Pastitsio', 'A deeply comforting architectural masterpiece featuring layers of tubular pasta bound with cheese, a robust beef ragù aromatic with cinnamon and cloves, and a crown of velvety, golden-brown béchamel custard.', 'Dinner', 'Greek', 'Intermediate', '[{"group_name": "Aromatic Beef Rag\u00f9", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "ground beef", "quantity": 750, "unit": "g", "preparation": "lean (85/15)", "notes": null, "substitutions": [], "ingredient_id": "696b2887-6464-4698-a80a-6860f8633185", "nutrition_source": "Aggregated Public Data"}, {"name": "red onion", "quantity": 2, "unit": null, "preparation": "finely diced", "notes": "approx. 300g total", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato paste", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d0a34229-249b-49e5-a653-227bd7afb7fc", "nutrition_source": "Aggregated Public Data"}, {"name": "red wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": "dry varietal like Cabernet or Merlot", "substitutions": [], "ingredient_id": "0fc93141-8ba8-42e0-ac8b-b5af3851554c", "nutrition_source": "USDA FoodData Central"}, {"name": "canned crushed tomatoes", "quantity": 400, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "49a62ca7-db63-4d23-9f6f-2cf873fba8a3", "nutrition_source": "Aggregated Public Data"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": "approx. 3g", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "whole cloves", "quantity": 3, "unit": null, "preparation": null, "notes": "optional, remove before baking", "substitutions": [], "ingredient_id": "7b3bf68a-3ae9-4dad-91f4-6c7a14ec5e0e", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 1, "unit": null, "preparation": null, "notes": "approx. 2g", "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "B\u00e9chamel Custard", "items": [{"name": "unsalted butter", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 1000, "unit": "ml", "preparation": "warmed", "notes": null, "substitutions": [], "ingredient_id": "c75fcd6a-414e-40b9-bc04-333fb15c0c38", "nutrition_source": "USDA FoodData Central"}, {"name": "nutmeg", "quantity": 1, "unit": null, "preparation": "freshly grated", "notes": "approx. 0.5g", "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "kefalotyri cheese", "quantity": 100, "unit": "g", "preparation": "finely grated", "notes": "substitute with Parmesan or Pecorino Romano", "substitutions": ["Parmesan", "Pecorino Romano"], "ingredient_id": "75aede38-b00a-4383-9000-06b67134eb61", "nutrition_source": "USDA FoodData Central"}, {"name": "egg yolks", "quantity": 2, "unit": null, "preparation": "room temperature", "notes": "approx. 40g", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pasta Base", "items": [{"name": "bucatini or ziti pasta", "quantity": 500, "unit": "g", "preparation": null, "notes": "No. 2 macaroni is traditional", "substitutions": [], "ingredient_id": "6b7d03cf-262e-4a03-89d1-ecb4ac3556b5", "nutrition_source": "Aggregated Public Data"}, {"name": "kefalotyri cheese", "quantity": 50, "unit": "g", "preparation": "grated", "notes": "for binding pasta", "substitutions": [], "ingredient_id": "75aede38-b00a-4383-9000-06b67134eb61", "nutrition_source": "USDA FoodData Central"}, {"name": "egg whites", "quantity": 2, "unit": null, "preparation": null, "notes": "reserved from b\u00e9chamel eggs", "substitutions": [], "ingredient_id": "17645f6b-c1ea-4e82-a4b4-5ae8cb6a5a53", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 180\u00b0C/350\u00b0F. Ensure a rack is positioned in the center.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In the Dutch oven, saut\u00e9 the onions in olive oil over medium heat until soft and translucent, about 5-7 minutes. Add the minced garlic and cook for another minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Increase heat to medium-high and add the ground beef. Cook, breaking it up with a spoon, until fully browned and no pink remains.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Meat is browned, fat rendered", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stir in tomato paste and cook for 2 minutes to caramelize. Deglaze with red wine, scraping the bottom of the pot. Add crushed tomatoes, cinnamon stick, cloves, oregano, salt, and pepper. Simmer uncovered on low heat until thick and most liquid has evaporated, about 30 minutes. Remove cinnamon and cloves.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT35M", "doneness_cues": null}, "tips": ["The meat sauce must be thick, not watery, to prevent the pie from collapsing."]}, {"step_number": 5, "phase": "cook", "text": "While beef simmers, bring a large pot of salted water to a boil. Cook pasta 2-3 minutes less than package instructions (very al dente). Drain and return to the pot.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Toss the drained pasta with the reserved egg whites and 50g of grated cheese. This creates a binding layer that helps the base hold its shape when sliced.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "For the b\u00e9chamel, melt butter in the saucepan over medium heat. Whisk in flour and cook for 2-3 minutes until pale and sandy (a white roux). Do not let it brown.", "structured": {"action": "STIR", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Gradually whisk in the warmed milk, a ladle at a time, ensuring the mixture is smooth before adding more. Simmer gently for 5-7 minutes until thickened enough to coat the back of a spoon.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove b\u00e9chamel from heat. Stir in nutmeg, most of the 100g cheese (save a handful for the top), and salt to taste. Rapidly whisk in the egg yolks one by one to temper them without curdling.", "structured": {"action": "TEMPER", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "assemble", "text": "Grease the baking dish. Layer the pasta mixture evenly at the bottom. Spread the meat sauce over the pasta, pressing down gently to compact the layers.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 11, "phase": "assemble", "text": "Pour the b\u00e9chamel over the meat, spreading it to the edges. Sprinkle the remaining grated cheese on top.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 12, "phase": "cook", "text": "Bake for 45-50 minutes until the top is golden brown and bubbling. If it browns too quickly, tent loosely with foil.", "structured": {"action": "BAKE", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT45M", "doneness_cues": {"visual": "Golden brown crust, bubbling edges", "tactile": null}}, "tips": []}, {"step_number": 13, "phase": "finish", "text": "Remove from oven and let rest for at least 30 minutes before slicing. This allows the layers to set; slicing too early will cause the pie to fall apart.", "structured": {"action": "REST", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT1H", "passive_time": "PT1H15M", "total_time": "PT2H15M", "overnight_required": false, "yields": "9 generous servings", "yield_count": 9, "serving_size_g": 350}', '{"flags": [], "not_suitable_for": ["Gluten intolerance", "Lactose intolerance", "Egg allergy"]}', '{"per_serving": {"calories": 692.23, "protein_g": 37.99, "carbohydrates_g": 68.45, "fat_g": 27.43, "saturated_fat_g": 12.1, "trans_fat_g": null, "monounsaturated_fat_g": 6.74, "polyunsaturated_fat_g": 1.19, "fiber_g": 3.57, "sugar_g": 10.64, "sodium_mg": 679.76, "cholesterol_mg": 87.44, "potassium_mg": 853.2, "calcium_mg": 319.02, "iron_mg": 5.08, "magnesium_mg": 96.12, "phosphorus_mg": 508.21, "zinc_mg": 6.32, "vitamin_a_mcg": 186.4, "vitamin_c_mg": 9.21, "vitamin_d_mcg": 1.68, "vitamin_e_mg": 1.02, "vitamin_k_mcg": 5.5, "vitamin_b6_mg": 0.15, "vitamin_b12_mcg": 0.81, "thiamin_mg": 0.11, "riboflavin_mg": 0.27, "niacin_mg": 0.36, "folate_mcg": 26.78, "water_g": 153.47, "alcohol_g": 1.24, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Cover tightly with foil or transfer to airtight containers.", "duration": "P4D"}, "freezer": {"notes": "Freeze in portions. Thaw overnight in refrigerator before reheating.", "duration": "P3M"}, "reheating": "Reheat in a 160\u00b0C oven covered with foil for 20 minutes, or microwave individual portions until hot.", "does_not_keep": false}', '[{"name": "Large Dutch oven or deep skillet", "required": true, "alternative": null}, {"name": "Large saucepan", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "9x13 inch (approx 23x33cm) baking dish", "required": true, "alternative": null}, {"name": "Large pot for pasta", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Pie collapses when sliced", "likely_cause": "The pie was sliced while too hot", "prevention": "Allow the dish to rest for at least 30-45 minutes after baking to let the b\u00e9chamel and starches set", "fix": "Let it cool longer; it will firm up as it approaches room temperature"}, {"symptom": "B\u00e9chamel is lumpy", "likely_cause": "Milk was added too quickly or was too cold", "prevention": "Add warm milk slowly, whisking constantly between additions", "fix": "Pass the sauce through a fine-mesh sieve or use an immersion blender before adding cheese/eggs"}]', '["The secret to a neat slice is the ''cementing'' of the pasta layer. Tossing the cooked pasta with egg whites and cheese creates a structure that binds the tubes together during baking.", "For a truly authentic flavor profile, the cinnamon is non-negotiable. It provides the signature warmth that distinguishes Greek meat sauce from Italian rag\u00f9.", "If using bucatini, try to align the noodles in the pan running the same direction for a stunning cross-section when sliced.", "Do not rinse the pasta after boiling; the surface starch helps the egg and cheese mixture adhere to the noodles."]', '"Pastitsio is a staple of Greek cuisine, often described as ''Greek Lasagna''. While its name derives from the Italian ''pasticcio'' (a mess or pie), the modern version with b\u00e9chamel was popularized in the early 20th century by Nikolaos Tselementes, a French-trained Greek chef who integrated classic French sauces into Greek cooking."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('7aada9de-7eff-49df-9ff3-da06b2193fa4', 'Bún Thịt Nướng (Vietnamese Grilled Pork Vermicelli)', 'A vibrant, textural masterpiece featuring smoky, lemongrass-charred pork atop cool, slippery rice vermicelli. The dish creates a perfect harmony of temperatures and flavors: savory hot meat, crisp fresh herbs, tangy pickled carrots, and the quintessential salty-sweet-sour nuance of Nuoc Cham sauce.', 'Main Course', 'Vietnamese', 'Intermediate', '[{"group_name": "Lemongrass Pork", "items": [{"name": "pork shoulder or pork neck", "quantity": 600, "unit": "g", "preparation": "sliced thinly (3-4mm)", "notes": "Choose a cut with good fat content for grilling", "substitutions": [], "ingredient_id": "074f9812-c3dd-4b65-9e90-6b668e6c71fe", "nutrition_source": "USDA FoodData Central"}, {"name": "lemongrass stalks", "quantity": 2, "unit": null, "preparation": "white part only, minced", "notes": "approx 30g", "substitutions": [], "ingredient_id": "6dde667b-d122-48d9-a70f-a4f820fc5bd5", "nutrition_source": "USDA FoodData Central"}, {"name": "shallots", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 50g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fish sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": "choose a high-protein variety (35\u00b0N or higher)", "substitutions": [], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "tamari or gluten-free soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "brown sugar or palm sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "vegetable or canola", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Nuoc Cham (Dressing)", "items": [{"name": "warm water", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "white sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "fish sauce", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "lime juice", "quantity": 30, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "bird''s eye chili", "quantity": 1, "unit": null, "preparation": "thinly sliced", "notes": "adjust to heat preference", "substitutions": [], "ingredient_id": "6cdb0615-378e-4bfa-b76d-f19bbd780e6c", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Noodles & Vegetables", "items": [{"name": "dried rice vermicelli (b\u00fan)", "quantity": 300, "unit": "g", "preparation": null, "notes": "thin round noodles, not flat pho noodles", "substitutions": [], "ingredient_id": "d8a2c73d-e2de-4182-b43b-6bdf55f00a87", "nutrition_source": "USDA FoodData Central"}, {"name": "carrots", "quantity": 150, "unit": "g", "preparation": "julienned", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "cucumber", "quantity": 150, "unit": "g", "preparation": "julienned", "notes": null, "substitutions": [], "ingredient_id": "457adec2-3e06-4efe-a26e-9e6ea9f84924", "nutrition_source": "USDA FoodData Central"}, {"name": "bean sprouts", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "6d29b2fe-d48e-4143-b38e-919c67febaea", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh mint", "quantity": 20, "unit": "g", "preparation": "leaves picked", "notes": null, "substitutions": [], "ingredient_id": "17abecc0-a2a0-4478-8486-57b46e4305c9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 20, "unit": "g", "preparation": "rough chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "roasted peanuts", "quantity": 40, "unit": "g", "preparation": "crushed", "notes": null, "substitutions": ["toasted sesame seeds"], "ingredient_id": "ba36d967-879c-446b-ba1e-b1fa36e475db", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Quick Pickle Liquid", "items": [{"name": "white vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8d5bf07e-89a1-47ee-a6b7-d9cb03e96d64", "nutrition_source": "Aggregated Public Data"}, {"name": "sugar", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine minced lemongrass, shallots, garlic (3 cloves), fish sauce (30ml), tamari, brown sugar, black pepper, and neutral oil in a food processor or mortar. Process into a coarse paste.", "structured": {"action": "BLEND", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Massage the marinade paste thoroughly into the thinly sliced pork. Cover and let marinate at room temperature for 30 minutes, or refrigerate up to 24 hours for deeper flavor.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "While pork marinates, dissolve 15g sugar and 2g salt in 30ml vinegar. Toss the julienned carrots in this mixture and set aside to quick-pickle.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Prepare the Nuoc Cham sauce: In a small bowl, dissolve 30g sugar in 120ml warm water. Stir in 45ml fish sauce, lime juice, remaining minced garlic, and chili. Adjust to taste\u2014it should be a bold balance of salty, sweet, and sour.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Bring a large pot of water to a rolling boil. Cook the rice vermicelli according to package instructions (usually 3-5 minutes) until white and soft but not mushy. Drain immediately and rinse thoroughly under cold running water to stop cooking and remove excess starch.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Preheat a grill pan or heavy skillet over medium-high heat. working in batches, sear the pork slices. Cook for 2-3 minutes per side until well-charred and cooked through (internal temp 63\u00b0C/145\u00b0F minimum, though texture benefits from slight caramelization).", "structured": {"action": "GRILL", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": null, "doneness_cues": {"visual": "Deep brown char marks", "tactile": "Firm edges"}}, "tips": ["Do not overcrowd the pan, or the meat will steam instead of searing."]}, {"step_number": 7, "phase": "assemble", "text": "To serve, divide noodles among bowls. Top with a pile of grilled pork, pickled carrots (drained), fresh cucumber, bean sprouts, mint, and cilantro.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Garnish with crushed peanuts and serve with the Nuoc Cham sauce on the side to be poured over just before eating.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT40M", "passive_time": "PT30M", "total_time": "PT1H10M", "overnight_required": false, "yields": "4 bowls", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Gluten-Free", "Dairy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 496.94, "protein_g": 35.26, "carbohydrates_g": 54.24, "fat_g": 15.1, "saturated_fat_g": 4.37, "trans_fat_g": null, "monounsaturated_fat_g": 4.92, "polyunsaturated_fat_g": 1.34, "fiber_g": 3.55, "sugar_g": 23.99, "sodium_mg": 1782.71, "cholesterol_mg": 100.5, "potassium_mg": 992.38, "calcium_mg": 100.44, "iron_mg": 7.31, "magnesium_mg": 86.26, "phosphorus_mg": 408.62, "zinc_mg": 5.62, "vitamin_a_mcg": 431.75, "vitamin_c_mg": 16.99, "vitamin_d_mcg": null, "vitamin_e_mg": 0.33, "vitamin_k_mcg": 20.58, "vitamin_b6_mg": 0.95, "vitamin_b12_mcg": 1.26, "thiamin_mg": 1.56, "riboflavin_mg": 0.56, "niacin_mg": 8.89, "folate_mcg": 104.1, "water_g": 308.37, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store meat, noodles, herbs, and sauce in separate containers.", "duration": "P3D"}, "freezer": {"notes": "Marinated raw pork can be frozen. Cooked noodles do not freeze well.", "duration": "P1M"}, "reheating": "Reheat pork in a pan or microwave. Serve noodles and vegetables room temperature or cold.", "does_not_keep": false}', '[{"name": "Food processor or Mortar and Pestle", "required": true, "alternative": "Chef''s knife and patience"}, {"name": "Grill pan or Heavy Skillet", "required": true, "alternative": "Outdoor BBQ Grill"}, {"name": "Large pot", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Pork is tough or dry", "likely_cause": "Slices were too thick or cooked too long at too low heat", "prevention": "Freeze pork for 20 minutes before slicing to get paper-thin cuts; cook hot and fast", "fix": "Cut cooked meat into smaller bite-sized strips and mix well with the dressing to rehydrate"}, {"symptom": "Noodles are gummy and stuck together", "likely_cause": "Insufficient rinsing after boiling", "prevention": "Rinse vigorously under cold water until noodles feel cool to the touch", "fix": "Briefly rinse under warm water to separate, then cold water again"}]', '["The secret to authentic flavor is ''blackening'' the sugar in the marinade slightly during cooking\u2014don''t fear the dark char marks on the pork; that is where the flavor lives.", "Nuoc Cham strength varies by fish sauce brand (Red Boat is saltier/purer than Squid brand). Add fish sauce gradually and taste as you go.", "For a true restaurant finish, make a quick Scallion Oil (M\u1ee1 H\u00e0nh) by pouring hot oil over chopped green onions and spooning this over the assembled bowl.", "If using wooden skewers on an outdoor grill, soak them in water for 30 minutes beforehand to prevent burning."]', '"B\u00fan Th\u1ecbt N\u01b0\u1edbng is a staple of Southern Vietnam, particularly popular in Ho Chi Minh City. Unlike the broth-heavy Ph\u1edf, this is a ''dry'' noodle salad that relies on the contrast between hot, savory grilled meat and cold, refreshing noodles and herbs, tied together by the ubiquitous Nuoc Cham sauce."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('7efe9997-7c90-4c48-9ef4-e8b397cac4de', 'Fresh Oysters with Ginger-Soy Vinaigrette', 'Briny, pristine ocean freshness meets the sharp tang of rice vinegar and the warming bite of fresh ginger. This Asian-inspired mignonette balances the creaminess of the oysters with a bright, savory acidity.', 'Appetizer', 'Asian Fusion', 'Intermediate', '[{"group_name": "Oysters", "items": [{"name": "fresh live oysters", "quantity": 12, "unit": null, "preparation": "chilled", "notes": "approx. 1kg whole weight", "substitutions": [], "ingredient_id": "920550b5-ab98-4d81-a6e7-5806abf83033", "nutrition_source": "USDA FoodData Central"}, {"name": "crushed ice", "quantity": 500, "unit": "g", "preparation": "for serving", "notes": null, "substitutions": [], "ingredient_id": "ace33db4-8651-416e-85b7-5d2d0e12fa6b", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Ginger-Soy Vinaigrette", "items": [{"name": "rice vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fcbf5252-1be9-4dd4-8c22-4fda1dbdca28", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["tamari for gluten-free"], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh ginger", "quantity": 10, "unit": "g", "preparation": "finely minced or grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "scallion", "quantity": 1, "unit": null, "preparation": "finely chopped", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "sesame oil", "quantity": 2, "unit": "ml", "preparation": null, "notes": "just a few drops", "substitutions": [], "ingredient_id": "a9a59164-d949-4acd-99da-689f0a32e2e7", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Scrub the oyster shells under cold running water with a stiff brush to remove grit and mud. Discard any oysters that are open and do not close when tapped.", "structured": {"action": "PEEL", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Combine rice vinegar, soy sauce, minced ginger, chopped scallion, and sesame oil in a small bowl. Stir to combine and set aside to let flavors meld.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Prepare a serving platter with a bed of crushed ice to hold the shucked oysters stable and cold.", "structured": {"action": "PREPARE_GARNISH", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Hold an oyster cup-side down in a folded towel. Insert the tip of the oyster knife into the hinge. Twist firmly until the hinge pops. Slide the knife along the top shell to sever the muscle, remove the top shell, and inspect for shell fragments.", "structured": {"action": "SHUCK", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": ["Keep the oyster level to avoid spilling the brine (liquor).", "Sever the bottom muscle so the oyster slides easily for the guest."]}, {"step_number": 5, "phase": "finish", "text": "Nestle the shucked oysters immediately into the crushed ice. Spoon about 5ml (1 tsp) of the vinaigrette over each oyster or serve the sauce on the side.", "structured": {"action": "SERVE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT10M", "total_time": "PT35M", "overnight_required": false, "yields": "12 oysters", "yield_count": 4, "serving_size_g": 60}', '{"flags": ["Pescatarian", "Dairy-Free", "Egg-Free", "Nut-Free", "Low-Carb", "Keto", "Sugar-Free"], "not_suitable_for": ["Infants", "Pregnant individuals (raw shellfish)", "Immunocompromised individuals (raw shellfish)"]}', '{"per_serving": {"calories": 59.07, "protein_g": 8.27, "carbohydrates_g": 2.48, "fat_g": 1.93, "saturated_fat_g": 0.46, "trans_fat_g": null, "monounsaturated_fat_g": 0.48, "polyunsaturated_fat_g": 0.24, "fiber_g": 0.21, "sugar_g": 1.82, "sodium_mg": 615.85, "cholesterol_mg": 27.38, "potassium_mg": 132.1, "calcium_mg": 5.35, "iron_mg": 1.52, "magnesium_mg": 9.7, "phosphorus_mg": 78.74, "zinc_mg": 1.37, "vitamin_a_mcg": 1.88, "vitamin_c_mg": 0.83, "vitamin_d_mcg": null, "vitamin_e_mg": 0.1, "vitamin_k_mcg": 7.77, "vitamin_b6_mg": 0.2, "vitamin_b12_mcg": 1.84, "thiamin_mg": 0.08, "riboflavin_mg": 0.11, "niacin_mg": 1.79, "folate_mcg": 5.68, "water_g": 33.69, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Oysters must be kept alive on ice until shucking. Once shucked, consume immediately. Sauce keeps for 3 days.", "duration": "PT2H"}, "freezer": {"notes": "Do not freeze raw oysters in shell.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Oyster knife", "required": true, "alternative": "Strong, short-bladed dull knife (risky)"}, {"name": "Clean kitchen towel or cut-resistant glove", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Stiff bristle brush", "required": true, "alternative": "New sponge"}, {"name": "Serving platter with crushed ice", "required": true, "alternative": null}]', '[{"symptom": "Oyster shell shatters while shucking", "likely_cause": "Applying force to the wrong point or brittle shell", "prevention": "Ensure knife is securely in the hinge before twisting; do not pry the side of the shell", "fix": "Carefully pick out all shell fragments with a clean towel or discard if too fragmented"}, {"symptom": "Oyster smells sulfurous or ''off''", "likely_cause": "Oyster is dead and spoiling", "prevention": "Purchase from reputable fishmongers; check tag dates", "fix": "Cannot be fixed. Discard immediately to prevent food poisoning."}]', '["Safety First: Never force the oyster knife. If it slips, it can cause serious injury. Use a proper guard or thick towel.", "The ''Liquor'': Try to retain the clear, salty liquid inside the oyster shell; it contains the essence of the oyster''s flavor.", "Temperature: Oysters must be kept very cold. If not serving immediately, keep them on ice in the fridge.", "Ginger Tip: For the finest texture in the sauce, use a microplane to grate the ginger rather than chopping it.", "Variety: This sauce works best with Pacific oysters (Crassostrea gigas) which have a creamy, vegetal profile that stands up to the soy and ginger."]', '"While the classic French mignonette relies on red wine vinegar and shallots, this variation draws on East Asian flavor profiles. The combination of ginger and vinegar is traditionally used in Chinese cuisine to balance the ''cooling'' nature of seafood (yin) with ''warming'' ingredients (yang)."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('80619a41-5190-40a6-9e00-ca22d45ae52a', 'Soy-Glazed Brown Butter Brussels Sprout Spaghetti', 'An indulgent umami bomb that transforms humble ingredients into a restaurant-quality meal. Nutty browned butter and salty soy sauce create a glossy emulsion that clings to shredded, deeply caramelized Brussels sprouts and al dente spaghetti. A squeeze of lemon cuts through the richness.', 'Dinner', 'Fusion', 'Easy', '[{"group_name": "Pasta", "items": [{"name": "spaghetti", "quantity": 400, "unit": "g", "preparation": "dry", "notes": "Standard or thick spaghetti works best", "substitutions": [], "ingredient_id": "8f9d3063-4bf0-46dc-9f13-5f49cd92d47d", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 4000, "unit": "ml", "preparation": "boiling", "notes": "For cooking pasta", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 25, "unit": "g", "preparation": null, "notes": "For pasta water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables & Aromatics", "items": [{"name": "brussels sprouts", "quantity": 450, "unit": "g", "preparation": "shredded or thinly sliced", "notes": "Trim ends before slicing", "substitutions": [], "ingredient_id": "2ee7388c-3256-477d-8d05-4ce09df9d8f1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Brown Butter Soy Sauce", "items": [{"name": "unsalted butter", "quantity": 85, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "soy sauce", "quantity": 45, "unit": "ml", "preparation": null, "notes": "Low sodium preferred", "substitutions": [], "ingredient_id": "1a157828-0624-4e67-815d-8e6bdf8b23c2", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "red pepper flakes", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "Freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Garnish", "items": [{"name": "parmesan cheese", "quantity": 40, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Bring a large pot of water to a boil and season heavily with salt (it should taste like the ocean). While water heats, trim the hard stems off the Brussels sprouts and slice them very thinly (shaved style) using a knife or mandoline.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add spaghetti to boiling water. Cook until just shy of al dente (about 1-2 minutes less than package directions), as it will finish cooking in the sauce. Reserve 250ml (1 cup) of starchy pasta water before draining.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "While pasta cooks, heat olive oil in a large skillet over medium-high heat. Add shredded Brussels sprouts in an even layer. Let them sit undisturbed for 2 minutes to char, then saut\u00e9 for another 3-4 minutes until tender and deeply caramelized. Remove sprouts from the pan and set aside.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT6M", "doneness_cues": {"visual": "Deep brown char on edges", "tactile": "Tender but not mushy"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to medium. Add the cubed butter to the now-empty skillet. Cook, swirling the pan occasionally, until the butter foams, then subsides, and the milk solids turn a golden hazelnut brown. Immediately add minced garlic and red pepper flakes (if using) and cook for 30 seconds until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Golden brown milk solids", "tactile": "Foaming subsides"}}, "tips": ["Watch the butter closely; it goes from browned to burnt in seconds."]}, {"step_number": 5, "phase": "assemble", "text": "Add the soy sauce to the browned butter (it will bubble vigorously). Add the drained pasta and the reserved cooked Brussels sprouts to the pan. Toss vigorously with tongs.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Pour in about 60-80ml of the reserved pasta water. Continue tossing over low heat until the butter and water emulsify into a glossy sauce that clings to the noodles. Add more pasta water if the mixture looks dry. Stir in lemon juice.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Serve immediately, garnished with generous amounts of freshly cracked black pepper and grated parmesan cheese if desired.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT10M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 375}', '{"flags": ["Vegetarian", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 659.47, "protein_g": 21.59, "carbohydrates_g": 88.23, "fat_g": 25.6, "saturated_fat_g": 13.08, "trans_fat_g": null, "monounsaturated_fat_g": 8.51, "polyunsaturated_fat_g": 1.34, "fiber_g": 7.32, "sugar_g": 5.03, "sodium_mg": 3372.91, "cholesterol_mg": 52.49, "potassium_mg": 752.98, "calcium_mg": 222.66, "iron_mg": 2.97, "magnesium_mg": 99.38, "phosphorus_mg": 351.1, "zinc_mg": 1.86, "vitamin_a_mcg": 219.27, "vitamin_c_mg": 98.63, "vitamin_d_mcg": 0.05, "vitamin_e_mg": 2.21, "vitamin_k_mcg": 203.92, "vitamin_b6_mg": 0.34, "vitamin_b12_mcg": 0.16, "thiamin_mg": 0.18, "riboflavin_mg": 0.17, "niacin_mg": 1.26, "folate_mcg": 72.86, "water_g": 1116.59, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Reheat gently with a splash of water to loosen the butter sauce.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; emulsion may break and sprouts will lose texture.", "duration": null}, "reheating": "Pan-fry over medium heat for best texture, or microwave.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": "Wok"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Sauce is greasy or oily and not clinging to pasta", "likely_cause": "Broken emulsion due to insufficient water or lack of agitation", "prevention": "Ensure pasta water is starchy and toss vigorously", "fix": "Add another splash of hot pasta water and toss rapidly over high heat to re-emulsify"}, {"symptom": "Butter tastes acrid and bitter", "likely_cause": "Butter was burned rather than browned", "prevention": "Remove from heat immediately when it smells nutty and solids turn golden", "fix": "Cannot be fixed; discard butter and start that step over"}]', '["Shredding the Brussels sprouts allows them to cook very quickly and integrate with the pasta strands, ensuring you get a bit of vegetable in every bite.", "Do not skip the lemon juice; the acidity is necessary to cut through the richness of the butter and the salinity of the soy sauce.", "If you want extra protein, a fried egg with a runny yolk placed on top makes this even more indulgent."]', '"This dish exemplifies modern fusion comfort food, marrying the Italian technique of ''pasta al burro'' (butter pasta) with the East Asian flavor profile of soy sauce (shoyu). While ''Wafu'' pasta (Japanese-style pasta) has existed since the 1950s in Tokyo, this specific combination leans on the universal appeal of umami-rich browned butter paired with cruciferous vegetables."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('81f0a3f5-9127-41e9-879b-2a161bd70a8e', 'Alsatian Slow-Roasted Duck with Riesling Sauerkraut', 'A rustic yet elegant centerpiece featuring a whole duck with shatteringly crisp skin and tender meat, roasted directly over a bed of aromatic sauerkraut. The duck fat renders down into the fermented cabbage, apples, and Riesling, creating a luxurious, tangy, and deeply savory accompaniment.', 'Dinner', 'French', 'Intermediate', '[{"group_name": "Duck", "items": [{"name": "whole duck", "quantity": 1, "unit": null, "preparation": "thawed, giblets removed", "notes": "approx. 2.2kg - 2.5kg", "substitutions": [], "ingredient_id": "13478315-8da6-4268-be1a-d8928a6500e3", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 15, "unit": "g", "preparation": "coarse", "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 5, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sauerkraut Base", "items": [{"name": "raw sauerkraut", "quantity": 1000, "unit": "g", "preparation": "drained", "notes": null, "substitutions": [], "ingredient_id": "d1d39781-bb71-40b2-b9fe-e8b934a4fdcc", "nutrition_source": "USDA FoodData Central"}, {"name": "duck fat", "quantity": 30, "unit": "g", "preparation": null, "notes": "or olive oil", "substitutions": [], "ingredient_id": "f11d095a-3279-472e-b30f-865d6418e103", "nutrition_source": "Aggregated Public Data"}, {"name": "yellow onion", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "approx. 300g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "granny smith apples", "quantity": 2, "unit": null, "preparation": "peeled, cored, and sliced", "notes": "approx. 300g", "substitutions": [], "ingredient_id": "9985672b-aa9f-4125-8a32-62d520c99d6f", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "smashed", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Braising Liquid & Aromatics", "items": [{"name": "dry riesling", "quantity": 350, "unit": "ml", "preparation": null, "notes": "Alsatian preferred", "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "chicken stock", "quantity": 150, "unit": "ml", "preparation": null, "notes": "unsalted, gluten-free", "substitutions": [], "ingredient_id": "7e254f45-046f-4812-bcdd-7e31c9bb59b8", "nutrition_source": "Aggregated Public Data"}, {"name": "juniper berries", "quantity": 10, "unit": null, "preparation": null, "notes": "slightly crushed", "substitutions": [], "ingredient_id": "bbd559c9-41f8-4b18-8c45-8836fdfbd280", "nutrition_source": "Aggregated Public Data"}, {"name": "caraway seeds", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5fb07424-aa49-4da5-afeb-0636713c313f", "nutrition_source": "USDA FoodData Central"}, {"name": "bay leaves", "quantity": 2, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": null, "notes": "sprigs", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "The day before (recommended): Remove the duck from packaging and pat thoroughly dry with paper towels. Prick the skin all over with a sharp needle or knife tip, focusing on fatty areas (breast and thighs), being careful not to pierce the meat. Season generously with salt inside and out. Place uncovered in the refrigerator overnight to dry the skin.", "structured": {"action": "CURE", "temperature": null, "duration": "P1D", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Preheat your oven to 160\u00b0C (320\u00b0F). If you did not dry-brine overnight, prick and season the duck now, letting it stand at room temperature for 30 minutes. Rinse the sauerkraut in cold water and drain well in a colander to remove excess brine.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a large roasting pan placed on the stovetop over medium heat, melt the duck fat. Add sliced onions and saut\u00e9 for 5-8 minutes until softened and translucent.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the apple slices, garlic, juniper berries, caraway seeds, bay leaves, and thyme. Cook for another 2 minutes until fragrant. Stir in the drained sauerkraut, then pour in the Riesling and chicken stock. Spread this mixture evenly across the bottom of the pan.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Place a roasting rack directly over the sauerkraut mixture. Place the duck, breast side up, on the rack. (The duck should not be submerged; it should sit above the kraut so the fat renders down into it).", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Roast in the center of the oven for approximately 2 hours. Halfway through, gently stir the sauerkraut underneath to prevent burning at the edges. Pierce the leg joint to check doneness; juices should run clear, or internal temperature of the thickest part of the thigh should reach 74\u00b0C (165\u00b0F).", "structured": {"action": "ROAST", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT2H", "doneness_cues": {"visual": "Skin golden, juices run clear", "tactile": "Leg joint moves freely"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Increase oven temperature to 220\u00b0C (425\u00b0F). Roast for an additional 15-20 minutes to deeply brown and crisp the skin. Watch closely to prevent burning.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT20M", "doneness_cues": {"visual": "Skin is deep amber and crispy", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove the duck from the oven and transfer to a cutting board. Rest for at least 20 minutes before carving. Meanwhile, taste the sauerkraut. If it is too dry, add a splash of water or stock. If it is too liquid, simmer on the stovetop to reduce.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT2H30M", "total_time": "PT3H15M", "overnight_required": true, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Dairy-Free", "Gluten-Free", "Nut-Free", "Paleo", "Low-Carb"], "not_suitable_for": []}', '{"per_serving": {"calories": 1147.84, "protein_g": 114.92, "carbohydrates_g": 55.78, "fat_g": 36.07, "saturated_fat_g": 11.16, "trans_fat_g": null, "monounsaturated_fat_g": 4.31, "polyunsaturated_fat_g": 4, "fiber_g": 11.75, "sugar_g": 17.3, "sodium_mg": 4060.32, "cholesterol_mg": 3025.63, "potassium_mg": 2033.81, "calcium_mg": 197.98, "iron_mg": 183.99, "magnesium_mg": 194.49, "phosphorus_mg": 1677.15, "zinc_mg": 18.85, "vitamin_a_mcg": 70512.6, "vitamin_c_mg": 76.02, "vitamin_d_mcg": null, "vitamin_e_mg": 0.55, "vitamin_k_mcg": 36.55, "vitamin_b6_mg": 4.96, "vitamin_b12_mcg": 317.25, "thiamin_mg": 3.41, "riboflavin_mg": 5.34, "niacin_mg": 38.8, "folate_mcg": 4413.35, "water_g": 787.12, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store duck meat removed from the bone. Flavor of sauerkraut improves after 24 hours.", "duration": "P3D"}, "freezer": {"notes": "Sauerkraut freezes well; duck meat texture may degrade slightly upon thawing.", "duration": "P2M"}, "reheating": "Reheat sauerkraut in a pot. Crisp duck skin under a broiler or in a hot pan before serving.", "does_not_keep": false}', '[{"name": "Large roasting pan with rack", "required": true, "alternative": "Large Dutch oven with vegetables acting as a rack"}, {"name": "Sharp knife or needle", "required": true, "alternative": "Skewer"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Sieve or colander", "required": true, "alternative": null}]', '[{"symptom": "Duck skin is flabby or chewy", "likely_cause": "Insufficient fat rendering or humidity in the oven was too high", "prevention": "Ensure skin is thoroughly pricked and dry-brined overnight", "fix": "Remove duck from the roasting rack, place on a clean baking sheet, and broil (grill) for 2-4 minutes under high heat, watching constantly."}]', '["Pricking the skin is the most critical step. You must pierce the skin and fat layer without penetrating the meat, or juices will escape and dry out the bird.", "If the sauerkraut becomes too greasy from the rendered duck fat, use a ladle to skim the excess fat from the surface of the pan before serving. Save this ''liquid gold'' for roasting potatoes later.", "For the wine, select a dry Alsatian Riesling or a Gew\u00fcrztraminer. Avoid sweet wines, as the apples already provide natural sweetness.", "Always check the ingredients on your sauerkraut. For this recipe, raw fermented sauerkraut from the refrigerated section is superior to canned versions."]', '"This dish is inspired by Choucroute Garnie, the emblematic dish of Alsace, a region straddling France and Germany. While the traditional version features various cuts of pork and sausages, using duck (specifically locally raised waterfowl) is a luxurious variation found in Strasbourg''s finer winstubs, highlighting the region''s love for fruit, fermentation, and game birds."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('87ddfb28-cf76-4a57-8298-666cc1fa77f2', 'Alsatian-Style Slow Cooker Lentil & Apple Soup', 'A comforting, rustic stew where earthiness meets subtle sweetness. Smoky sausage and nutty brown lentils form a savory base, while tart Granny Smith apples melt into the broth, creating a velvety texture balanced by the sharp tang of Dijon mustard and cool sour cream.', 'Soup', 'German', 'Easy', '[{"group_name": "Base & Aromatics", "items": [{"name": "dried brown lentils", "quantity": 400, "unit": "g", "preparation": "rinsed and picked over", "notes": null, "substitutions": [], "ingredient_id": "fc77776c-fd4a-436e-a164-8fdf1198fea3", "nutrition_source": "Aggregated Public Data"}, {"name": "smoked sausage (kielbasa or similar)", "quantity": 450, "unit": "g", "preparation": "sliced into half-moons", "notes": "Ensure gluten-free if required", "substitutions": [], "ingredient_id": "5604355c-b51e-4f0d-ad3b-212f2e217a12", "nutrition_source": "Aggregated Public Data"}, {"name": "tart apples (granny smith)", "quantity": 2, "unit": null, "preparation": "peeled, cored, and diced", "notes": "approx 300g total", "substitutions": [], "ingredient_id": "e4936f5c-8828-4564-8b6f-27ccd85bfe85", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrots", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "celery stalks", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx 100g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Liquid & Seasoning", "items": [{"name": "chicken stock", "quantity": 1500, "unit": "ml", "preparation": "low sodium", "notes": null, "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "dried thyme", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "3b938244-d506-46b2-9027-21bed955bcc5", "nutrition_source": "USDA FoodData Central"}, {"name": "dried bay leaves", "quantity": 2, "unit": null, "preparation": null, "notes": "remove before serving", "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}, {"name": "ground allspice", "quantity": 1, "unit": "g", "preparation": null, "notes": "approx 1/4 tsp", "substitutions": [], "ingredient_id": "d0b9d4b4-744d-472b-bb19-a779a23d70c6", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "dijon mustard", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "3e25e626-c9b4-4b62-9d08-7c650bcb3d2b", "nutrition_source": "Aggregated Public Data"}, {"name": "apple cider vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "sour cream", "quantity": 120, "unit": "g", "preparation": "for garnish", "notes": null, "substitutions": [], "ingredient_id": "773a6e88-6185-4784-92a7-104b7c1b7688", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the diced onion, carrots, celery, sliced sausage, and diced apples into the basin of the slow cooker.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["For deeper flavor, briefly sear the sausage and onions in a hot skillet before adding to the slow cooker to develop fond."]}, {"step_number": 2, "phase": "assemble", "text": "Add the rinsed lentils, dried thyme, bay leaves, allspice, and black pepper. Pour the chicken stock over the mixture and stir gently to combine.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Cover and cook on LOW for 7-8 hours or HIGH for 3-4 hours, until the lentils are tender and the vegetables are soft.", "structured": {"action": "BOIL", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT7H", "doneness_cues": {"visual": null, "tactile": "Lentils should be creamy but not disintegrated"}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Discard the bay leaves. Stir in the Dijon mustard and apple cider vinegar. Taste and season with salt if necessary (the sausage and stock usually provide sufficient salinity).", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not skip the vinegar; the acid is crucial to brighten the rich, earthy flavors."]}, {"step_number": 5, "phase": "finish", "text": "Ladle into bowls and top with a dollop of sour cream and fresh chopped parsley.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT7H", "total_time": "PT7H20M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 400}', '{"flags": ["Gluten-Free", "Nut-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 399.13, "protein_g": 24.31, "carbohydrates_g": 36.76, "fat_g": 19.3, "saturated_fat_g": 5.55, "trans_fat_g": null, "monounsaturated_fat_g": 0.84, "polyunsaturated_fat_g": 0.16, "fiber_g": 8.74, "sugar_g": 10.17, "sodium_mg": 10943.8, "cholesterol_mg": 7, "potassium_mg": 716.54, "calcium_mg": 152.67, "iron_mg": 7.37, "magnesium_mg": 15.62, "phosphorus_mg": 265.56, "zinc_mg": 3.17, "vitamin_a_mcg": 247.45, "vitamin_c_mg": 6.72, "vitamin_d_mcg": 0.06, "vitamin_e_mg": 0.46, "vitamin_k_mcg": 52.15, "vitamin_b6_mg": 0.11, "vitamin_b12_mcg": 0.06, "thiamin_mg": 0.06, "riboflavin_mg": 0.1, "niacin_mg": 0.48, "folate_mcg": 24.13, "water_g": 121.13, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors improve significantly the next day.", "duration": "P4D"}, "freezer": {"notes": "Texture may soften slightly upon thawing; reheat gently.", "duration": "P3M"}, "reheating": "Simmer gently on the stovetop; add a splash of water if the stew has thickened.", "does_not_keep": false}', '[{"name": "Slow cooker (6 quart / 6 liter)", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Skillet", "required": false, "alternative": "Microwave (to sweat onions)"}]', '[{"symptom": "Lentils are still hard after cooking time", "likely_cause": "The lentils were old or acid was added too early", "prevention": "Check expiration dates on dry goods; ensure vinegar/mustard are added only at the end", "fix": "Add 100ml hot water and continue cooking on HIGH for 45-60 minutes"}]', '["The apples will largely disintegrate during the long cook, thickening the broth naturally and providing a subtle, sweet counterpoint to the smoky sausage.", "Brown lentils work best here; red lentils will turn to mush, and French green lentils (Puy) may remain too firm for a rustic stew texture.", "If using a particularly fatty sausage, you may want to skim the surface of the soup before stirring in the mustard."]', '"This dish draws inspiration from the Alsace region on the border of France and Germany, where the combination of fruit (apples), cured meats, and brassicas or pulses is a staple of hearty winter cooking."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('8a5d4d85-2d03-44a8-850d-db3b764768af', 'Classic American Strawberry Shortcake', 'Tender, flaky, slightly sweet biscuits split open and piled high with juicy macerated strawberries and clouds of freshly whipped vanilla cream. A quintessential summer dessert that balances rich buttery pastry with bright fruit acidity.', 'Dessert', 'American', 'Easy', '[{"group_name": "Macerated Strawberries", "items": [{"name": "fresh strawberries", "quantity": 500, "unit": "g", "preparation": "hulled and sliced", "notes": "ripe summer berries are best", "substitutions": [], "ingredient_id": "b2199214-7c2d-4083-92ae-b0a8a044e25b", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 50, "unit": "g", "preparation": null, "notes": "adjust based on berry sweetness", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Shortcake Biscuits", "items": [{"name": "all-purpose flour", "quantity": 250, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 12, "unit": "g", "preparation": null, "notes": "ensure it is fresh for rise", "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 85, "unit": "g", "preparation": "very cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 160, "unit": "ml", "preparation": "cold", "notes": null, "substitutions": ["heavy cream", "half-and-half"], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "coarse sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": "for sprinkling", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Whipped Cream", "items": [{"name": "heavy whipping cream", "quantity": 240, "unit": "ml", "preparation": "very cold", "notes": "35% fat or higher", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a medium bowl, combine sliced strawberries, 50g sugar, and lemon juice. Toss to coat and let sit at room temperature to release their juices.", "structured": {"action": "MACERATE", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": ["This process creates a delicious natural syrup.", "Letting them sit for at least 20 minutes yields the best flavor."]}, {"step_number": 2, "phase": "prep", "text": "Preheat your oven to 220\u00b0C/425\u00b0F. Line a baking sheet with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a large mixing bowl, whisk together the flour, 30g sugar, baking powder, and salt.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Add the cold cubed butter to the flour mixture. Use a pastry blender or your fingertips to rub the butter into the flour until the mixture resembles coarse crumbs with some pea-sized pieces of butter remaining.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Coarse crumbs with pea-sized butter bits", "tactile": "Sandy texture but not greasy"}}, "tips": ["Do not overmix; visible butter pieces create flaky layers."]}, {"step_number": 5, "phase": "prep", "text": "Pour in the cold milk. Stir gently with a fork or spatula just until a shaggy dough forms and the dry ingredients are moistened.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Turn dough onto a lightly floured surface. Gently pat (do not roll) into a rectangle about 2cm thick. Use a biscuit cutter to punch out rounds. Place on the prepared baking sheet, touching slightly. Sprinkle tops with coarse sugar if desired.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": {"visual": "2cm thick rounds", "tactile": null}}, "tips": ["Press the cutter straight down without twisting to ensure high rising biscuits.", "Gather scraps gently to cut remaining biscuits."]}, {"step_number": 7, "phase": "cook", "text": "Bake for 12-15 minutes until the tops are golden brown and the biscuits have risen significantly.", "structured": {"action": "BAKE", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT15M", "doneness_cues": {"visual": "Golden brown tops", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "While biscuits bake, combine heavy cream, powdered sugar, and vanilla in a clean bowl. Whip until soft-to-medium peaks form.", "structured": {"action": "WHIP", "temperature": null, "duration": null, "doneness_cues": {"visual": "Soft peaks that hold shape", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove biscuits from oven and transfer to a wire rack to cool slightly. They should be warm but not hot when serving.", "structured": {"action": "COOL", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "assemble", "text": "Slice the warm biscuits in half horizontally. Spoon the macerated strawberries and their syrup over the bottom halves. Top generously with whipped cream and the biscuit caps. Serve immediately.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT20M", "total_time": "PT45M", "overnight_required": false, "yields": "6 shortcakes", "yield_count": 6, "serving_size_g": 185}', '{"flags": ["Vegetarian", "Egg-Free", "Soy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Vegan", "Gluten-Free", "Dairy-Free"]}', '{"per_serving": {"calories": 503.59, "protein_g": 6.95, "carbohydrates_g": 58.83, "fat_g": 27.46, "saturated_fat_g": 16.92, "trans_fat_g": 0.5, "monounsaturated_fat_g": 7.24, "polyunsaturated_fat_g": 1.4, "fiber_g": 2.8, "sugar_g": 24.25, "sodium_mg": 431.78, "cholesterol_mg": 78.33, "potassium_mg": 251.57, "calcium_mg": 197.55, "iron_mg": 1.12, "magnesium_mg": 26.44, "phosphorus_mg": 157.92, "zinc_mg": 0.62, "vitamin_a_mcg": 274.4, "vitamin_c_mg": 49.56, "vitamin_d_mcg": 0.99, "vitamin_e_mg": 0.98, "vitamin_k_mcg": 4.31, "vitamin_b6_mg": 0.09, "vitamin_b12_mcg": 0.21, "thiamin_mg": 0.09, "riboflavin_mg": 0.17, "niacin_mg": 0.9, "folate_mcg": 34.36, "water_g": 130.98, "alcohol_g": 0.29, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store components separately. Assembled shortcakes will become soggy within hours.", "duration": "P1D"}, "freezer": {"notes": "Baked biscuits can be frozen. Reheat in oven before serving.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Medium mixing bowl", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Pastry blender", "required": false, "alternative": "Two forks or fingertips"}, {"name": "Biscuit cutter (7cm)", "required": false, "alternative": "Rim of a glass or knife"}, {"name": "Electric mixer or whisk", "required": true, "alternative": null}]', '[{"symptom": "Biscuits are tough and flat", "likely_cause": "The dough was overworked or the butter melted before baking", "prevention": "Handle the dough as little as possible and keep ingredients very cold", "fix": "Cannot be fixed, but can be crumbled for a trifle"}, {"symptom": "Biscuits rose unevenly", "likely_cause": "Twisting the cutter sealed the edges", "prevention": "Press the cutter straight down and lift straight up", "fix": "None, cosmetic issue only"}]', '["Temperature is key for the biscuits: ensure your butter and milk are fridge-cold to create steam pockets for a flaky rise.", "If your strawberries are not very sweet or juicy, you can mash a few of them with a fork to help create more syrup.", "For an extra rich version, brush the tops of the unbaked biscuits with a little heavy cream before sprinkling with sugar.", "This recipe uses the American ''biscuit'' style base, which is more savory and substantial than sponge cake, providing a perfect texture contrast to the soft fruit and cream."]', '"Shortcake dates back to 16th century England, but the modern strawberry version is a distinctly American classic, popularized in the mid-19th century during ''Strawberry Fever''. Unlike sponge cake versions, the authentic American shortcake uses a biscuit or scone-like base to soak up the fruit juices."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('8db48d5f-83d8-4d11-b3ad-677de54e463e', 'Roasted Cod with Black Pepper Potatoes', 'Mild, flaky cod fillets served atop a bed of thinly sliced, golden-edged potatoes. The potatoes absorb the savory juices from the fish while broiling to a crisp finish, creating a comforting, textural contrast with just five key ingredients.', 'Dinner', 'American', 'Easy', '[{"group_name": "Potatoes", "items": [{"name": "yukon gold potatoes", "quantity": 800, "unit": "g", "preparation": "scrubbed and thinly sliced (3mm)", "notes": "approx. 4-5 medium potatoes", "substitutions": [], "ingredient_id": "a9d640ff-a969-4f0a-9a92-974f376ac272", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly cracked", "notes": "coarse grind preferred", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Fish", "items": [{"name": "cod fillets", "quantity": 680, "unit": "g", "preparation": "skinless, patted dry", "notes": "4 fillets, approx 170g each", "substitutions": [], "ingredient_id": "229ccaef-c763-440b-b44f-6e22222d3fd1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "wedged", "notes": "approx 60g", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 220\u00b0C (425\u00b0F) and set a rack in the upper third position.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Toss the sliced potatoes with 30ml (2 tbsp) of olive oil, half the salt, and half the black pepper directly on the baking sheet until evenly coated. Spread them out in a single, slightly overlapping layer.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Use a mandoline for uniform slices to ensure even cooking.", "Do not pile the potatoes too high or they will steam instead of roast."]}, {"step_number": 3, "phase": "cook", "text": "Roast the potatoes for 20 minutes, or until they are tender and the edges are beginning to brown.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT20M", "doneness_cues": {"visual": "Edges browning", "tactile": "Fork-tender"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "While potatoes roast, pat the cod fillets very dry with paper towels. Rub with the remaining 15ml (1 tbsp) olive oil and season strictly with the remaining salt and cracked black pepper.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Remove the baking sheet from the oven. Carefully arrange the cod fillets on top of the potato layer.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Return to the oven and roast for 8-10 minutes, until the fish is opaque and begins to flake easily.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Switch the oven to high broiler setting. Broil for 2-3 minutes, watching closely, until the fish develops a golden color and the exposed potato edges crisp up. Ensure internal temperature of fish reaches 63\u00b0C (145\u00b0F).", "structured": {"action": "BROIL", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown spots", "tactile": "Fish flakes easily"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from oven and serve immediately with fresh lemon wedges squeezed over the top.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT30M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Whole30", "Paleo"], "not_suitable_for": []}', '{"per_serving": {"calories": 425.46, "protein_g": 35.28, "carbohydrates_g": 44.12, "fat_g": 12.71, "saturated_fat_g": 1.79, "trans_fat_g": null, "monounsaturated_fat_g": 8.37, "polyunsaturated_fat_g": 1.59, "fiber_g": 7.55, "sugar_g": 3.18, "sodium_mg": 613.63, "cholesterol_mg": 73.1, "potassium_mg": 2016.66, "calcium_mg": 60.63, "iron_mg": 2.32, "magnesium_mg": 144.47, "phosphorus_mg": 535.29, "zinc_mg": 0.78, "vitamin_a_mcg": 20.69, "vitamin_c_mg": 51.95, "vitamin_d_mcg": 1.53, "vitamin_e_mg": 2.74, "vitamin_k_mcg": 7.76, "vitamin_b6_mg": 0.42, "vitamin_b12_mcg": 1.55, "thiamin_mg": 0.14, "riboflavin_mg": 0.12, "niacin_mg": 3.52, "folate_mcg": 13.64, "water_g": 151.46, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best reheated in an oven or toaster oven to maintain potato crispness.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; potatoes become mealy and fish texture degrades.", "duration": null}, "reheating": "Reheat in a 175\u00b0C (350\u00b0F) oven for 10-15 minutes.", "does_not_keep": false}', '[{"name": "Large rimmed baking sheet", "required": true, "alternative": "Roasting pan"}, {"name": "Chef''s knife or Mandoline", "required": true, "alternative": "Food processor with slicing disk"}, {"name": "Fish spatula", "required": false, "alternative": null}]', '[{"symptom": "Potatoes are still hard when fish is added", "likely_cause": "Potatoes were sliced too thickly or oven temperature runs low", "prevention": "Slice potatoes no thicker than 3-4mm; test doneness with a fork before adding fish", "fix": "Remove fish temporarily to a plate, continue roasting potatoes until tender, then return fish to pan to finish cooking"}]', '["Patting the fish dry is crucial. Excess moisture will steam the fish rather than roasting it, preventing that appetizing golden crust.", "Yukon Gold potatoes are preferred for this recipe as they have a creamy interior and hold their shape better than Russets when sliced thin.", "If your fillets are very thick (over 1 inch), increase the roasting time in step 6 by 3-4 minutes before switching to the broiler.", "Coarsely cracked black pepper adds a necessary textural crunch and heat that contrasts beautifully with the mild sweetness of the cod."]', '"This one-pan preparation is a modern staple in American coastal home cooking, particularly in New England where Atlantic cod is abundant. It emphasizes the ''meat and potatoes'' philosophy but lightens it for weeknight dining, relying on the high heat of roasting rather than the traditional batter-frying found in fish and chips."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('8f2ab9c2-c162-4640-989d-99de30b326cb', 'Poached White Peaches in Spiced Cabernet & Raspberry Syrup', 'Tender white peaches bathe in a vibrant, ruby-red syrup infused with Cabernet Sauvignon, fresh raspberries, and warming spices. The result is a sophisticated yet simple dessert where the wine''s tannins balance the fruit''s natural sweetness.', 'Dessert', 'French', 'Easy', '[{"group_name": "Fruit", "items": [{"name": "white peaches", "quantity": 4, "unit": null, "preparation": "ripe but firm", "notes": "approx. 150g each", "substitutions": [], "ingredient_id": "8d70adb0-d52e-4842-9c0b-ad4eacdf35ae", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh raspberries", "quantity": 125, "unit": "g", "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "f4f5b84c-c364-40cd-b737-375755e481f9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Poaching Liquid", "items": [{"name": "cabernet sauvignon", "quantity": 500, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["Merlot", "Pinot Noir"], "ingredient_id": "8dcd3a06-85eb-4512-a98d-0400f163837f", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 125, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": ["raw sugar"], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "peel removed in strips and juiced", "notes": "approx 45ml juice", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics", "items": [{"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 5g", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "star anise", "quantity": 2, "unit": null, "preparation": null, "notes": "whole pods", "substitutions": [], "ingredient_id": "9010f167-112f-4c3b-80c3-b49783e568a1", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla bean", "quantity": 0.5, "unit": null, "preparation": "split lengthwise", "notes": "or 5ml vanilla bean paste", "substitutions": [], "ingredient_id": "90237166-b129-4858-8c9c-2f8a7ab9a301", "nutrition_source": "Aggregated Public Data"}, {"name": "whole cloves", "quantity": 3, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "7b3bf68a-3ae9-4dad-91f4-6c7a14ec5e0e", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Using a vegetable peeler, carefully remove the skin from the peaches, leaving the stem intact if possible. If the peaches are very firm, you can score the bottom with an X and blanch them in boiling water for 30 seconds to loosen the skin.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a medium saucepan, combine the Cabernet Sauvignon, water, sugar, lemon peel, lemon juice, raspberries, cinnamon stick, star anise, cloves, and split vanilla bean. Bring to a boil over medium-high heat, stirring to dissolve the sugar.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to a gentle simmer (around 85\u00b0C/185\u00b0F). Carefully lower the peeled peaches into the liquid. They should be mostly submerged. If using parchment paper, cut a circle (cartouche) with a small hole in the center and place it directly on the surface of the liquid to keep the peaches submerged.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Poach the peaches gently for 15 to 25 minutes. The time depends heavily on the ripeness of the fruit. Test by inserting a sharp knife tip into the flesh; it should meet no resistance.", "structured": {"action": "POACH", "temperature": null, "duration": "PT20M", "doneness_cues": {"visual": null, "tactile": "Knife slides in with zero resistance"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove the saucepan from the heat. Allow the peaches to cool completely within the syrup. This rest period allows the peaches to absorb the red wine color and flavor deeper into their flesh.", "structured": {"action": "COOL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Serve the peaches in shallow bowls with a generous ladle of the poaching syrup and the cooked raspberries. Garnish with a fresh mint leaf if desired.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT40M", "total_time": "PT1H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 250}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Soy-Free", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 352.53, "protein_g": 1.2, "carbohydrates_g": 65.84, "fat_g": 1.19, "saturated_fat_g": 0.36, "trans_fat_g": null, "monounsaturated_fat_g": 0.19, "polyunsaturated_fat_g": 0.47, "fiber_g": 3.6, "sugar_g": 56.18, "sodium_mg": 14.49, "cholesterol_mg": null, "potassium_mg": 169.88, "calcium_mg": 41.47, "iron_mg": 0.87, "magnesium_mg": 18.74, "phosphorus_mg": 24.19, "zinc_mg": 0.25, "vitamin_a_mcg": 43.16, "vitamin_c_mg": 64.96, "vitamin_d_mcg": null, "vitamin_e_mg": 1.26, "vitamin_k_mcg": 3.01, "vitamin_b6_mg": 0.11, "vitamin_b12_mcg": null, "thiamin_mg": 0.11, "riboflavin_mg": 0.06, "niacin_mg": 0.55, "folate_mcg": 10.58, "water_g": 316.4, "alcohol_g": 13.13, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store peaches submerged in the syrup to prevent browning and intensify the flavor.", "duration": "P5D"}, "freezer": {"notes": "Texture of the peaches will be softer upon thawing; best used for smoothies or sauces if frozen.", "duration": "P3M"}, "reheating": "Gently warm in a saucepan over low heat if serving warm, though delicious chilled.", "does_not_keep": false}', '[{"name": "Medium Saucepan", "required": true, "alternative": "Deep saut\u00e9 pan"}, {"name": "Vegetable Peeler", "required": true, "alternative": null}, {"name": "Parchment Paper", "required": false, "alternative": "Small lid or plate"}, {"name": "Slotted Spoon", "required": true, "alternative": null}]', '[{"symptom": "Peaches are mushy or falling apart", "likely_cause": "Peaches were too ripe before starting or overcooked", "prevention": "Select peaches that are fragrant but firm to the touch; reduce cooking time for softer fruit", "fix": "Pur\u00e9e the mixture into a sauce or coulis for ice cream"}, {"symptom": "Syrup is too thin or watery", "likely_cause": "Fruit released excess water or wine didn''t reduce enough", "prevention": "Not preventable during poaching as fruit varies", "fix": "Remove peaches, boil the syrup vigorously for 5-10 minutes to reduce and thicken"}]', '["For a deeper red color and stronger flavor, prepare this dish a day in advance and let the peaches sit in the syrup overnight in the refrigerator.", "If you do not have parchment paper for a cartouche, you can use a heat-safe ceramic plate that fits inside the pot to gently weigh the peaches down.", "The leftover syrup is liquid gold. Strain it and use it as a base for sangria, mix it into sparkling water, or drizzle it over dairy-free vanilla ice cream.", "While Cabernet is specified for its robust body, any drinkable dry red wine like Merlot or Shiraz works well. Avoid ''cooking wines'' with added salt."]', '"Poaching fruit in wine (P\u00eaches au vin rouge) is a classic French bistro dessert technique designed to utilize seasonal fruit that might be slightly under-ripe while preserving it for a few extra days. The addition of raspberries adds a tart brightness that cuts through the deep tannins of the red wine."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('935b9a3a-fb2e-4a62-b9ce-5a36985a7775', 'Restorative Golden Garlic Broth', 'A translucent, golden elixir where pungent garlic transforms into sweet, buttery pearls through gentle simmering. This deeply comforting broth balances the natural sugars of slow-cooked alliums with fresh herbal notes, offering a gentle immune-boosting warmth without the aggressive heat of raw garlic.', 'Soup', 'European Rustic', 'Easy', '[{"group_name": "Base Aromatics", "items": [{"name": "extra virgin olive oil", "quantity": 30, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "celery stalk", "quantity": 1, "unit": null, "preparation": "sliced thin", "notes": "approx 50g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "The Garlic", "items": [{"name": "garlic heads", "quantity": 3, "unit": null, "preparation": "cloves separated and peeled", "notes": "approx 40-50 cloves / 120g total", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Liquid & Herbs", "items": [{"name": "water", "quantity": 1500, "unit": "ml", "preparation": null, "notes": "or low-sodium vegetable stock for richer flavor", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh thyme", "quantity": 5, "unit": null, "preparation": "whole sprigs", "notes": "approx 5g", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "bay leaves", "quantity": 2, "unit": null, "preparation": "dried", "notes": null, "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}, {"name": "black peppercorns", "quantity": 10, "unit": null, "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 10, "unit": "g", "preparation": null, "notes": "adjust to taste at the end", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the garlic by separating the heads into cloves. Peel them carefully to keep the cloves whole. A quick way is to crush the head slightly to separate, then blanch in boiling water for 30 seconds to loosen skins.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not smash the cloves; we want them whole to simmer gently."]}, {"step_number": 2, "phase": "cook", "text": "In a heavy pot over medium-low heat, warm the olive oil. Add the diced onion, sliced celery, and a pinch of salt. Sweat the vegetables for 8-10 minutes until they are translucent and soft, but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT10M", "doneness_cues": {"visual": "Translucent onions", "tactile": "Soft texture"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the peeled whole garlic cloves to the pot. Stir gently to coat them in the oil and aromatics. Cook for 2-3 minutes just to wake up the garlic oils, ensuring they do not take on any color.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the water (or vegetable stock). Add the thyme sprigs, bay leaves, and whole black peppercorns. Increase heat to bring the liquid to a gentle boil, then immediately reduce to a very low simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Cover the pot partially with a lid and simmer gently for 40-45 minutes. The garlic cloves should become completely tender and creamy, resembling soft butter when pressed.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT45M", "doneness_cues": {"visual": null, "tactile": "Garlic mashes easily against pot side"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove the thyme stems and bay leaves. Stir in the lemon juice to brighten the flavor. Taste and adjust salt. Serve hot, ensuring each bowl gets plenty of the soft, sweet garlic cloves.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT45M", "total_time": "PT1H10M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Paleo", "Whole30", "Low-Carb"], "not_suitable_for": []}', '{"per_serving": {"calories": 132.93, "protein_g": 2.63, "carbohydrates_g": 15.08, "fat_g": 7.81, "saturated_fat_g": 1.1, "trans_fat_g": null, "monounsaturated_fat_g": 5.5, "polyunsaturated_fat_g": 0.89, "fiber_g": 1.88, "sugar_g": 2.18, "sodium_mg": 997.73, "cholesterol_mg": null, "potassium_mg": 241, "calcium_mg": 90.12, "iron_mg": 1.28, "magnesium_mg": 20.9, "phosphorus_mg": 63.81, "zinc_mg": 0.51, "vitamin_a_mcg": 17.86, "vitamin_c_mg": 19.54, "vitamin_d_mcg": null, "vitamin_e_mg": 1.18, "vitamin_k_mcg": 50.25, "vitamin_b6_mg": 0.44, "vitamin_b12_mcg": null, "thiamin_mg": 0.09, "riboflavin_mg": 0.06, "niacin_mg": 0.36, "folate_mcg": 17.68, "water_g": 444.43, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors deepen over time. Store in an airtight container.", "duration": "P5D"}, "freezer": {"notes": "Freeze without garnish. Garlic texture may become slightly softer upon thawing.", "duration": "P3M"}, "reheating": "Gently warm on the stovetop over medium heat.", "does_not_keep": false}', '[{"name": "Heavy-bottomed pot or Dutch oven", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": false, "alternative": "Slotted spoon"}]', '[{"symptom": "Broth tastes bitter or acrid", "likely_cause": "The garlic was burned or browned too darkly during the initial saut\u00e9 step", "prevention": "Keep heat low (medium-low) and stir constantly when adding garlic; do not let it turn brown", "fix": "Cannot be fixed. Burnt garlic permeates the liquid. You must restart."}, {"symptom": "Broth is too thin or watery", "likely_cause": "Natural result of a broth-based soup without starch thickeners", "prevention": "Accept the style, or use vegetable stock instead of water for body", "fix": "Mash 5-6 of the soft garlic cloves and stir them back into the broth to emulsify slightly"}]', '["The cooked garlic cloves lose their pungency and become surprisingly sweet. Encourage diners to smash them onto crusty bread or eat them whole.", "For a clearer consomm\u00e9 style, strain the solids out completely, but I recommend keeping the garlic for the full experience.", "If you are not strictly vegan, a parmesan rind simmered in the broth adds incredible umami depth.", "This is an excellent base for a poaching liquid; try poaching tofu or delicate vegetables in it for the last 5 minutes."]', '"While garlic is often used as a background note in Western cooking, this dish celebrates it as a vegetable in its own right. It draws inspiration from Spanish ''Sopa de Ajo'' (Garlic Soup) and French garlic confit traditions, focusing on the restorative properties of alliums which have been used in folk medicine for centuries to combat colds."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('949de7a3-95ff-4340-b1b0-612d96c2951b', 'Brown Butter Cauliflower Amandine', 'A refined yet effortless side dish where tender-crisp steamed cauliflower is dressed in a nutty, golden-brown butter sauce speckled with crunchy toasted almonds and brightened with a squeeze of fresh lemon.', 'Side Dish', 'French', 'Easy', '[{"group_name": "Vegetable", "items": [{"name": "cauliflower", "quantity": 1, "unit": null, "preparation": "cut into bite-sized florets", "notes": "1 medium head, approx. 600-700g trimmed", "substitutions": [], "ingredient_id": "2d9d5068-77e7-4dfc-b24b-8e6a6275cb33", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sauce", "items": [{"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "cubed", "notes": "cold or room temperature", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "sliced almonds", "quantity": 40, "unit": "g", "preparation": "flaked or slivered", "notes": null, "substitutions": [], "ingredient_id": "5bcbb4d4-6845-4825-bd21-1c13e52b989c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": "about half a lemon", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Seasoning", "items": [{"name": "sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly ground", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh parsley", "quantity": 5, "unit": "g", "preparation": "finely chopped", "notes": "for garnish", "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Fill a large pot with about 3cm (1 inch) of water and bring to a boil. Place the cauliflower florets in a steamer basket over the water, ensuring the water does not touch the vegetable.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Cover the pot and steam the cauliflower until tender-crisp. A knife should slide in with slight resistance. Avoid overcooking to mush.", "structured": {"action": "STEAM", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Bright white and slightly translucent at edges", "tactile": "Knife meets slight resistance"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "While cauliflower steams, place the butter in a light-colored skillet over medium heat. Once melted and foaming, add the sliced almonds.", "structured": {"action": "MELT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": ["Using a light-colored pan helps you monitor the color change of the milk solids to prevent burning."]}, {"step_number": 4, "phase": "cook", "text": "Swirl the pan constantly. Cook until the milk solids turn a golden hazelnut brown and the almonds are toasted. Remove from heat immediately once the aroma becomes nutty.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown flecks (milk solids) and toasted almonds", "tactile": "Foam subsides slightly"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Immediately stir in the lemon juice and salt to stop the cooking process (be careful, it may sputter). Add the steamed cauliflower to the pan and toss gently to coat in the brown butter and almonds.", "structured": {"action": "TOSS", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Transfer to a serving platter. Garnish with black pepper and fresh parsley if using. Serve immediately while warm.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Gluten-Free", "Keto", "Low-Carb", "Soy-Free", "Peanut-Free"], "not_suitable_for": ["Nut allergies (almonds)", "Dairy allergies (butter)"]}', '{"per_serving": {"calories": 207.98, "protein_g": 5.44, "carbohydrates_g": 10.75, "fat_g": 17.64, "saturated_fat_g": 8.18, "trans_fat_g": null, "monounsaturated_fat_g": 6.73, "polyunsaturated_fat_g": 1.74, "fiber_g": 4.62, "sugar_g": 3.66, "sodium_mg": 342.29, "cholesterol_mg": 32.25, "potassium_mg": 576.95, "calcium_mg": 69.49, "iron_mg": 1.16, "magnesium_mg": 52.96, "phosphorus_mg": 124.62, "zinc_mg": 0.78, "vitamin_a_mcg": 107.93, "vitamin_c_mg": 81.44, "vitamin_d_mcg": null, "vitamin_e_mg": 3.06, "vitamin_k_mcg": 47.15, "vitamin_b6_mg": 0.31, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.11, "riboflavin_mg": 0.22, "niacin_mg": 1.22, "folate_mcg": 100.17, "water_g": 157.13, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Butter may solidify; reheat gently.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; cauliflower will become mushy upon thawing.", "duration": null}, "reheating": "Warm gently in a skillet over low heat until butter melts and cauliflower is heated through.", "does_not_keep": false}', '[{"name": "Large pot with steamer basket", "required": true, "alternative": "Large pot with colander and lid"}, {"name": "Light-colored skillet", "required": true, "alternative": "Stainless steel frying pan (avoid non-stick dark pans to see butter color)"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Butter tastes acrid or burnt with black specks", "likely_cause": "The milk solids burned because the heat was too high or it was left on the stove too long", "prevention": "Remove pan from heat the moment you smell a nutty aroma and see golden brown color; residual heat continues cooking", "fix": "Cannot be fixed. Discard and start the butter sauce again (it is the primary flavor)"}]', '["Cut the cauliflower into uniform sizes to ensure even steaming.", "Beurre noisette (brown butter) moves from perfect to burnt in seconds. Have your lemon juice measured and ready near the stove to arrest the cooking immediately.", "If you want extra crunch, you can toast the almonds in a dry pan first, set them aside, and add them back to the finished brown butter, but cooking them in the butter infuses the fat with almond flavor.", "Ensure the cauliflower is well-drained after steaming so it doesn''t water down the rich butter sauce."]', '"This dish draws from the French technique ''\u00e0 l''Amandine'' (garnished with almonds), typically associated with trout or green beans. Applying this classic sauce to cauliflower elevates a humble brassica into an elegant side dish suitable for festive autumn tables."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('9e66c79b-9ede-42cd-b4bf-e03974876f67', 'Sugo all''Arrabbiata', 'A classic Roman tomato sauce defined by its fiery kick and aromatic garlic profile. ''Arrabbiata'' translates to ''angry,'' referencing the heat from the dried chilies, balanced by the sweetness of high-quality San Marzano tomatoes.', 'Sauce', 'Italian', 'Easy', '[{"group_name": "Aromatics", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "thinly sliced", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dried red chili flakes", "quantity": 5, "unit": "g", "preparation": null, "notes": "Adjust to heat preference, also known as peperoncino", "substitutions": ["fresh red chili (sliced)"], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Base", "items": [{"name": "whole peeled tomatoes", "quantity": 800, "unit": "g", "preparation": null, "notes": "San Marzano variety preferred; crushed by hand", "substitutions": ["crushed tomatoes", "tomato passata"], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finish", "items": [{"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pour the tomatoes and their juices into a bowl and crush them by hand until they are broken down but still slightly chunky. Slice the garlic cloves thinly.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Roughly crushed texture"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Combine olive oil, sliced garlic, and chili flakes in a large cool skillet. Turn heat to medium-low. This cold start allows the garlic to infuse the oil without burning immediately.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": null, "doneness_cues": {"visual": "Garlic turns pale gold", "tactile": "Aromatic sizzle"}}, "tips": ["Do not brown the garlic deeply; it will turn bitter."]}, {"step_number": 3, "phase": "cook", "text": "Once the garlic is pale gold and fragrant, immediately add the crushed tomatoes carefully (the oil may splatter). Season with salt.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Simmer gently, stirring occasionally, until the sauce thickens and the oil separates slightly, pooling on the surface. This indicates the raw tomato flavor has cooked out.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT20M", "doneness_cues": {"visual": "Oil separates and floats on top", "tactile": "Thickened consistency"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove from heat. Taste and adjust salt if necessary. Stir in fresh parsley just before tossing with pasta.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT20M", "total_time": "PT30M", "overnight_required": false, "yields": "600g (Coats 500g pasta)", "yield_count": 4, "serving_size_g": 150}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 145.46, "protein_g": 2.24, "carbohydrates_g": 9.8, "fat_g": 11.87, "saturated_fat_g": 1.65, "trans_fat_g": null, "monounsaturated_fat_g": 8.26, "polyunsaturated_fat_g": 1.3, "fiber_g": 4.2, "sugar_g": 7.95, "sodium_mg": 339.14, "cholesterol_mg": null, "potassium_mg": 527.43, "calcium_mg": 34.66, "iron_mg": 1.04, "magnesium_mg": 26.06, "phosphorus_mg": 58.94, "zinc_mg": 0.47, "vitamin_a_mcg": 29.03, "vitamin_c_mg": 31.9, "vitamin_d_mcg": null, "vitamin_e_mg": 2.12, "vitamin_k_mcg": 49.16, "vitamin_b6_mg": 0.08, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.02, "niacin_mg": 0.21, "folate_mcg": 4.26, "water_g": 4.53, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight glass container.", "duration": "P5D"}, "freezer": {"notes": "Freeze in portions. Thaw overnight in the refrigerator.", "duration": "P3M"}, "reheating": "Simmer gently in a pan, adding a splash of water if the sauce has thickened too much.", "does_not_keep": false}', '[{"name": "Large saut\u00e9 pan or skillet", "required": true, "alternative": "Wide saucepan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}]', '[{"symptom": "Sauce tastes bitter", "likely_cause": "The garlic was burned during the initial saut\u00e9", "prevention": "Start with a cold pan and use medium-low heat; watch the garlic constantly", "fix": "Cannot be fixed completely; adding a pinch of sugar may mask slight bitterness, but starting over is best"}]', '["The secret to this sauce is the ''soffritto'' of garlic and chili; slicing the garlic instead of mincing it prevents it from burning too quickly.", "Always reserve a cup of starchy pasta water when boiling your noodles. Splash some into the sauce when tossing the pasta to create a silky emulsion.", "San Marzano tomatoes are recommended because they have fewer seeds and a sweeter flesh, which balances the heat of the chilies without added sugar."]', '"Arrabbiata originated in the Lazio region, particularly Rome. The name means ''angry'' in Italian, a reference to the heat of the chili peppers that causes the eater''s face to turn red, much like an angry person."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('9e703122-122c-418f-999b-ba844937a79f', 'Rhubarb Streusel Coffee Cake', 'A tender, fine-crumbed cake balancing the sharp acidity of fresh rhubarb with a sweet, floral vanilla base. Topped with a generous layer of spiced butter streusel that provides a textural counterpoint to the soft fruit and moist cake.', 'Baked Good', 'American', 'Intermediate', '[{"group_name": "Spiced Streusel Topping", "items": [{"name": "all-purpose flour", "quantity": 120, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "light brown sugar", "quantity": 100, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 85, "unit": "g", "preparation": "melted and cooled", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "large pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Rhubarb Layer", "items": [{"name": "fresh rhubarb", "quantity": 300, "unit": "g", "preparation": "trimmed and diced into 1cm pieces", "notes": "discard leaves entirely", "substitutions": [], "ingredient_id": "293d2132-013e-4594-801e-4d86e1d04df0", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 25, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 5, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Cake Base", "items": [{"name": "cake flour", "quantity": 200, "unit": "g", "preparation": null, "notes": "sifted", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 113, "unit": "g", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "large, room temperature", "notes": "approx 100g total without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "sour cream", "quantity": 120, "unit": "g", "preparation": "full fat, room temperature", "notes": null, "substitutions": ["Greek yogurt (full fat)"], "ingredient_id": "d171100e-1088-4266-8d50-06cdedda7193", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 175\u00b0C (350\u00b0F). Grease a 23cm (9-inch) square baking pan and line the bottom with parchment paper, leaving an overhang for easy removal.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Prepare the streusel: In a medium bowl, whisk together the all-purpose flour, brown sugar, cinnamon, and salt. Pour in the melted butter and mix with a fork until moist clumps form. Refrigerate this mixture while preparing the batter.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Moist, sandy clumps", "tactile": "Holds shape when pressed"}}, "tips": ["Chilling the streusel ensures the butter resolidifies, creating a crunchier texture rather than melting into the cake."]}, {"step_number": 3, "phase": "prep", "text": "Toss the diced rhubarb with 25g granulated sugar and cornstarch in a small bowl. Set aside.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In a separate medium bowl, sift together the cake flour, baking powder, baking soda, and salt.", "structured": {"action": "SIFT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "In the bowl of a stand mixer fitted with the paddle attachment, cream the room temperature butter and 150g granulated sugar on medium-high speed until pale and fluffy, about 3-4 minutes.", "structured": {"action": "CREAM", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Pale yellow, almost white", "tactile": "Aerated and soft"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Reduce speed to medium. Add eggs one at a time, mixing fully after each addition. Scrape down the sides of the bowl. Add the vanilla extract and sour cream, mixing until just combined.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Reduce mixer speed to low. Add the dry flour mixture in two batches. Mix only until the flour streaks disappear. Do not overmix.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": {"visual": "Uniform batter with no dry pockets", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Spread the batter evenly into the prepared pan. Scatter the rhubarb mixture over the top of the batter, pressing the fruit pieces slightly into the surface. Finally, sprinkle the chilled streusel evenly over the rhubarb.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Bake in the center of the oven for 45 to 55 minutes, or until a tester inserted into the center comes out clean or with just a few moist crumbs (avoiding a piece of rhubarb). Ideally, the internal temperature of the cake crumb should reach 93\u00b0C (200\u00b0F).", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT50M", "doneness_cues": {"visual": "Golden brown topping", "tactile": "Internal temp 93\u00b0C"}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Remove from oven and let cool in the pan on a wire rack for at least 30 minutes before lifting out via the parchment paper and slicing.", "structured": {"action": "COOL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT1H15M", "total_time": "PT1H45M", "overnight_required": false, "yields": "9 squares", "yield_count": 9, "serving_size_g": 115}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegans (contains dairy, eggs)", "Coeliacs (contains gluten)"]}', '{"per_serving": {"calories": 450.14, "protein_g": 5.96, "carbohydrates_g": 60.59, "fat_g": 20.92, "saturated_fat_g": 12.53, "trans_fat_g": null, "monounsaturated_fat_g": 6.06, "polyunsaturated_fat_g": 1.11, "fiber_g": 1.68, "sugar_g": 30.8, "sodium_mg": 339.54, "cholesterol_mg": 93.83, "potassium_mg": 188.99, "calcium_mg": 110.39, "iron_mg": 0.88, "magnesium_mg": 16.33, "phosphorus_mg": 98.31, "zinc_mg": 0.52, "vitamin_a_mcg": 183.56, "vitamin_c_mg": 2.8, "vitamin_d_mcg": 0.25, "vitamin_e_mg": 0.79, "vitamin_k_mcg": 11.6, "vitamin_b6_mg": 0.05, "vitamin_b12_mcg": 0.18, "thiamin_mg": 0.06, "riboflavin_mg": 0.11, "niacin_mg": 0.59, "folate_mcg": 19.05, "water_g": 58.69, "alcohol_g": 0.19, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to prevent drying out.", "duration": "P5D"}, "freezer": {"notes": "Wrap individual slices tightly in plastic wrap then foil.", "duration": "P3M"}, "reheating": "Warm gently in a microwave for 10-15 seconds or in a low oven to refresh the crumb.", "does_not_keep": false}', '[{"name": "Square baking pan (23cm / 9in)", "required": true, "alternative": null}, {"name": "Stand mixer or hand mixer", "required": true, "alternative": "Whisk and strong arm"}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Rubber spatula", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}]', '[{"symptom": "Cake is dense or gummy", "likely_cause": "Overmixing the batter after adding flour", "prevention": "Stop mixing the moment the dry ingredients are incorporated", "fix": "Cannot be fixed after baking"}, {"symptom": "Soggy area around fruit", "likely_cause": "Rhubarb released too much liquid that wasn''t bound", "prevention": "Ensure rhubarb is tossed with cornstarch before adding to the cake", "fix": "Bake 5-10 minutes longer; ensure cake cools completely to set juices"}, {"symptom": "Streusel sinks into the cake", "likely_cause": "Streusel butter was too warm or batter was too thin", "prevention": "Chill the streusel thoroughly; ensure cake flour is used for batter structure", "fix": "Cannot be fixed"}]', '["Room temperature ingredients (butter, eggs, sour cream) are non-negotiable here; they emulsify better, trapping more air for a lighter crumb.", "If using frozen rhubarb, do not thaw it completely before baking, as it will release too much water. Toss it in the cornstarch while still frozen and bake immediately, adding 5 minutes to bake time.", "Cake flour is preferred over all-purpose for the base because its lower protein content yields a velvety, tender crumb that contrasts beautifully with the crunchy topping."]', '"While ''coffee cake'' in the US implies a cake meant to be eaten with coffee (often containing cinnamon and streusel), its roots lie in the German ''Kaffeekuchen'' tradition. This recipe bridges the gap between a classic American sour cream coffee cake and the fruit-forward tray bakes found in Northern Europe."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('a08b4aec-5b3b-484e-810d-944318e66d50', 'Crispy Smoked Shiitake ''Bacon''', 'Umami-rich shiitake mushrooms transformed into crispy, savory ribbons with a deep smoky aroma and a hint of maple sweetness. A plant-based essential that rivals cured pork in texture and depth.', 'Side Dish', 'American', 'Easy', '[{"group_name": "Mushroom Bacon", "items": [{"name": "shiitake mushrooms", "quantity": 250, "unit": "g", "preparation": "fresh, stems removed", "notes": "Choose thick caps for best texture", "substitutions": [], "ingredient_id": "127ce8a8-238d-40e6-a4b0-c58c42a7c745", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "Grapeseed or avocado oil", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "tamari", "quantity": 15, "unit": "ml", "preparation": null, "notes": "Or soy sauce if not strictly gluten-free", "substitutions": ["Soy sauce", "Coconut aminos"], "ingredient_id": "1a157828-0624-4e67-815d-8e6bdf8b23c2", "nutrition_source": "USDA FoodData Central"}, {"name": "liquid smoke", "quantity": 5, "unit": "ml", "preparation": null, "notes": "Hickory or applewood", "substitutions": [], "ingredient_id": "5a57a4ee-7c53-4a3d-be12-a8f061f7a931", "nutrition_source": "Aggregated Public Data"}, {"name": "maple syrup", "quantity": 5, "unit": "ml", "preparation": null, "notes": "Optional, for balance", "substitutions": [], "ingredient_id": "c9ca1f35-b107-46c2-92a3-4c1c620f3c11", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Clean the shiitake mushrooms by brushing off any dirt with a pastry brush or paper towel. Do not wash with water. Remove the tough stems and slice the caps into strips approximately 3-5mm thick.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Uniform strips", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the neutral oil in a large skillet over medium-high heat (approx. 190\u00b0C/375\u00b0F). Add the mushroom slices in a single layer. If your pan is small, do this in two batches to avoid steaming.", "structured": {"action": "HEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": ["Crowding the pan causes mushrooms to steam rather than crisp."]}, {"step_number": 3, "phase": "cook", "text": "Fry the mushrooms undisturbed for 3-4 minutes until the bottoms are golden brown. Flip and cook for another 2-3 minutes until golden all over and significantly reduced in size.", "structured": {"action": "FRY", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Golden brown", "tactile": "Crispy edges"}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Reduce heat to low. In a small cup, whisk the tamari, liquid smoke, and maple syrup together. Pour over the mushrooms and toss rapidly for 30-60 seconds until the liquid evaporates and glazes the mushrooms without burning.", "structured": {"action": "GLAZE", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Dark, glossy coating", "tactile": "Sticky but not wet"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove from the pan immediately and transfer to a paper towel-lined plate. Allow to cool for at least 5 minutes; they will crisp up further as they cool.", "structured": {"action": "COOL", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": null, "tactile": "Crunchy snap"}}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT5M", "total_time": "PT20M", "overnight_required": false, "yields": "4 garnish servings", "yield_count": 4, "serving_size_g": 30}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Paleo"], "not_suitable_for": []}', '{"per_serving": {"calories": 93.7, "protein_g": 1.66, "carbohydrates_g": 5.47, "fat_g": 7.83, "saturated_fat_g": 1.08, "trans_fat_g": null, "monounsaturated_fat_g": null, "polyunsaturated_fat_g": 0.01, "fiber_g": 1.58, "sugar_g": 2.37, "sodium_mg": 263.58, "cholesterol_mg": null, "potassium_mg": 209.58, "calcium_mg": 3.58, "iron_mg": 0.28, "magnesium_mg": 13.85, "phosphorus_mg": 73.53, "zinc_mg": 0.66, "vitamin_a_mcg": null, "vitamin_c_mg": null, "vitamin_d_mcg": 0.25, "vitamin_e_mg": null, "vitamin_k_mcg": null, "vitamin_b6_mg": 0.19, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.16, "niacin_mg": 2.53, "folate_mcg": 8.61, "water_g": 59.02, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container lined with a paper towel to absorb moisture.", "duration": "P5D"}, "freezer": {"notes": "Not recommended as texture will degrade.", "duration": null}, "reheating": "Re-crisp in a dry pan over medium heat for 1-2 minutes.", "does_not_keep": false}', '[{"name": "Large skillet or frying pan", "required": true, "alternative": "Wok"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Pastry brush", "required": false, "alternative": "Paper towel"}]', '[{"symptom": "Mushrooms are soggy or chewy instead of crisp", "likely_cause": "Pan was overcrowded or heat was too low, causing steaming", "prevention": "Cook in batches ensuring space between slices; use medium-high heat", "fix": "Spread on a baking sheet and bake at 175\u00b0C (350\u00b0F) for 5-10 minutes to dry out"}]', '["Consistency in slicing is key; uneven slices will result in some burning while others remain chewy.", "Do not salt the mushrooms at the beginning of cooking; salt draws out moisture and delays the browning process.", "For a ''Professional'' variation without liquid smoke: Fry the mushrooms, then use a smoking gun with applewood chips under a cloche for 5 minutes before serving.", "These are excellent crumbled over Caesar salads, loaded baked potatoes, or creamy pasta dishes."]', '"While ''facon'' has existed in various forms, using whole vegetables like shiitake mushrooms honors the Japanese ingredient''s natural high levels of guanylate (umami) while applying American curing and smoking flavor profiles to create a bridge between plant-based ethics and carnivorous nostalgia."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('b51ae434-f72a-4702-8925-e0518ba19ad9', 'Piquillo Peppers Stuffed With Salt Cod Brandade', 'Sweet, fire-roasted piquillo peppers filled with a silky, garlicky emulsion of salt cod and olive oil, resting on a velvety red pepper and white wine sauce. A classic Basque tapa that balances salinity with sweetness.', 'Appetizer', 'Spanish', 'Intermediate', '[{"group_name": "Salt Cod (Bacalao)", "items": [{"name": "dried salt cod", "quantity": 300, "unit": "g", "preparation": "whole fillet", "notes": "Requires 24-48h soaking", "substitutions": [], "ingredient_id": "8845e7e7-3d4d-49ae-9d5c-0a0e57c1171c", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": null, "unit": "ml", "preparation": null, "notes": "For soaking and poaching", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Brandade Filling", "items": [{"name": "potatoes", "quantity": 250, "unit": "g", "preparation": "peeled and cubed", "notes": "Starchy variety like Russet or Yukon Gold", "substitutions": [], "ingredient_id": "a87814d3-a635-474b-a78d-4d20b45066e5", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": null, "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 100, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 60, "unit": "ml", "preparation": "warmed", "notes": null, "substitutions": ["whole milk"], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "jarred piquillo peppers", "quantity": 16, "unit": null, "preparation": "whole", "notes": "Use 12 for stuffing, 4 for sauce", "substitutions": [], "ingredient_id": "32a393f4-6b49-419d-8c84-8f1ab5b733db", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Sauce", "items": [{"name": "onion", "quantity": 100, "unit": "g", "preparation": "diced", "notes": null, "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 50, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "fish stock", "quantity": 100, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["water", "vegetable stock"], "ingredient_id": "3912e04d-71a3-4a31-b033-cc5c5aa4452d", "nutrition_source": "Aggregated Public Data"}, {"name": "reserved piquillo peppers", "quantity": 4, "unit": null, "preparation": null, "notes": "From the jar used above", "substitutions": [], "ingredient_id": "7291d1f7-5821-4180-90b9-79eec428e938", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "At least 24 hours in advance, rinse the salt cod thoroughly. Place in a large bowl, cover with cold water, and refrigerate. Change the water every 8 hours to remove excess salt.", "structured": {"action": "SOAK", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "P1D", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Drain the cod. Place it in a saucepan and cover with fresh cold water. Bring to a gentle simmer, then remove from heat immediately. Let it steep for 10 minutes. Drain, remove skin and bones, and flake the meat.", "structured": {"action": "POACH", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT15M", "doneness_cues": {"visual": "Fish flakes easily", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "While cod steeps, boil the peeled potato chunks in salted water until very tender. Drain and let steam dry for a minute.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": null, "tactile": "Fork tender"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In a small skillet, gently heat the 100ml olive oil with 3 cloves of sliced garlic over low heat until the garlic is golden. Discard the garlic (or save for garnish) and keep the oil warm.", "structured": {"action": "INFUSE", "temperature": {"celsius": 70, "fahrenheit": 158}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Mash the potatoes and flaked cod together in a bowl while still warm. Vigorously beat in the warm garlic-infused oil and the warm cream, alternating small amounts, until the mixture (brandade) is creamy and emulsified. Season with pepper (salt is likely unnecessary).", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": {"visual": "Smooth, pale, and fluffy texture", "tactile": "Holds shape on a spoon"}}, "tips": ["If the mixture is too stiff, add a splash of the cod poaching liquid."]}, {"step_number": 6, "phase": "cook", "text": "For the sauce: Saut\u00e9 the diced onion and garlic in 30ml olive oil until soft. Add the 4 reserved piquillo peppers and white wine. Reduce wine by half, then add stock. Simmer for 10 minutes. Blend until smooth and strain if desired.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Preheat oven to 180\u00b0C (350\u00b0F). Fill a piping bag with the brandade mixture. Carefully stuff each of the remaining 12 piquillo peppers. Be gentle to avoid tearing the delicate skin.", "structured": {"action": "FILL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Spread the sauce on the bottom of a baking dish. Arrange the stuffed peppers on top. Bake for 10-15 minutes until heated through. Serve immediately.", "structured": {"action": "BAKE", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT15M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "P1D", "total_time": "P1DT50M", "overnight_required": true, "yields": "12 stuffed peppers", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Pescatarian", "Gluten-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 694.63, "protein_g": 52.3, "carbohydrates_g": 24.48, "fat_g": 40.33, "saturated_fat_g": 8.38, "trans_fat_g": 0.19, "monounsaturated_fat_g": 7.1, "polyunsaturated_fat_g": 1.64, "fiber_g": 7.44, "sugar_g": 7.99, "sodium_mg": 6425.7, "cholesterol_mg": 130.95, "potassium_mg": 1853.38, "calcium_mg": 197.59, "iron_mg": 2.75, "magnesium_mg": 119.24, "phosphorus_mg": 772.66, "zinc_mg": 1.54, "vitamin_a_mcg": 93.15, "vitamin_c_mg": 18, "vitamin_d_mcg": 3.24, "vitamin_e_mg": 3.36, "vitamin_k_mcg": 5.48, "vitamin_b6_mg": 0.74, "vitamin_b12_mcg": 7.53, "thiamin_mg": 0.23, "riboflavin_mg": 0.22, "niacin_mg": 5.7, "folate_mcg": 24.25, "water_g": 45.94, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container; reheat gently to avoid splitting the emulsion.", "duration": "P3D"}, "freezer": {"notes": "Texture of the peppers may degrade slightly upon thawing.", "duration": "P1M"}, "reheating": "Cover with foil and bake at 160\u00b0C until warmed through, or microwave on low power.", "does_not_keep": false}', '[{"name": "Large bowl", "required": true, "alternative": "Basin"}, {"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Skillet", "required": true, "alternative": null}, {"name": "Immersion blender", "required": true, "alternative": "Standard blender"}, {"name": "Piping bag", "required": false, "alternative": "Small spoon"}, {"name": "Baking dish", "required": true, "alternative": null}]', '[{"symptom": "Brandade is oily or separated", "likely_cause": "Oil was added too quickly or the mixture became too cold", "prevention": "Add oil in a slow, steady stream while whipping warm potato/cod mixture", "fix": "Add a tablespoon of hot water or hot milk and whisk vigorously to re-emulsify"}]', '["The quality of the piquillo peppers is paramount; look for ''Piquillo de Lodosa'' designation for the best sweetness and texture.", "Do not let the cod boil vigorously during poaching, or the flesh will become tough and stringy.", "If you want a lighter texture, you can fold whipped egg whites into the brandade before stuffing, though this makes it more like a souffl\u00e9.", "Reserve the oil from the piquillo pepper jar; you can whisk a few drops into the final sauce for extra color and flavor."]', '"Originating from the Navarre and Basque regions of Spain, this dish showcases the preservation history of the area. Salt cod (bacalao) allowed fish to be consumed inland, while the roasting and jarring of piquillo peppers preserved the harvest. The combination creates a perfect balance of the sea''s salinity and the land''s sweetness."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('bb142a0d-364d-4693-a9d5-129dd6d939cb', 'Smoked Duck & Citrus Wild Rice Salad', 'A sophisticated grain bowl balancing the rich, savory depth of smoked duck with the vibrant acidity of blood orange and pink grapefruit. Nutty wild rice provides a hearty base, while toasted pecans and pomegranate seeds offer a textural crunch, tied together with a zesty honey-citrus vinaigrette.', 'Salad', 'Fusion', 'Intermediate', '[{"group_name": "Base", "items": [{"name": "wild rice blend", "quantity": 200, "unit": "g", "preparation": "dry", "notes": "Or brown rice mix", "substitutions": [], "ingredient_id": "e99f7d25-554d-4078-b6af-e2b53484a492", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 600, "unit": "ml", "preparation": null, "notes": "Or vegetable stock for more flavor", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Protein", "items": [{"name": "hot-smoked duck breast", "quantity": 2, "unit": null, "preparation": "skin-on", "notes": "approx 400g total weight", "substitutions": [], "ingredient_id": "10ea2903-e622-46ac-90ab-261904af3399", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Fresh Elements", "items": [{"name": "blood oranges", "quantity": 2, "unit": null, "preparation": "segmented", "notes": "approx 250g", "substitutions": [], "ingredient_id": "68255621-f24a-4ddd-a795-10f36645222e", "nutrition_source": "USDA FoodData Central"}, {"name": "pink grapefruit", "quantity": 1, "unit": null, "preparation": "segmented", "notes": "approx 200g", "substitutions": [], "ingredient_id": "1317cddf-704a-4c24-8451-29af2f3ef227", "nutrition_source": "USDA FoodData Central"}, {"name": "radishes", "quantity": 4, "unit": null, "preparation": "thinly sliced", "notes": "approx 60g", "substitutions": [], "ingredient_id": "2d6f93d3-117b-49ab-9e11-1058462db7ce", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh mint leaves", "quantity": 15, "unit": "g", "preparation": "torn", "notes": null, "substitutions": [], "ingredient_id": "17abecc0-a2a0-4478-8486-57b46e4305c9", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 3, "unit": null, "preparation": "sliced", "notes": "approx 45g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish & Crunch", "items": [{"name": "pecans", "quantity": 60, "unit": "g", "preparation": "toasted", "notes": null, "substitutions": [], "ingredient_id": "a5c5ee79-2bcd-4ab2-aed5-b09d0a3df4b5", "nutrition_source": "USDA FoodData Central"}, {"name": "pomegranate seeds", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "793af9f7-6371-4f4b-822d-b2bac2f93aa5", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Citrus Vinaigrette", "items": [{"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh orange juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a15da11d-f8dd-46e3-9ac5-725a7912f1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "white wine vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b2f8f0c0-6da9-47aa-932a-c2747b64b807", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "honey", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste (min 1g)", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Rinse the wild rice blend thoroughly under cold water. Combine rice, water (or stock), and salt in a medium saucepan. Bring to a boil, then reduce heat to low, cover, and simmer until tender but chewy, usually 45-50 minutes.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT45M", "doneness_cues": {"visual": "Water absorbed", "tactile": "Grains tender with slight bite"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "While rice cooks, prepare the citrus. Cut the top and bottom off the oranges and grapefruit. Slice off the peel and pith, then carefully cut between the membranes to release the segments (supremes). Squeeze the remaining membrane juice into a small bowl for the dressing.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Clean segments with no pith", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Whisk together the olive oil, reserved citrus juice (supplement with fresh orange juice to reach 30ml), vinegar, Dijon mustard, honey, and black pepper until emulsified.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": {"visual": "Creamy and unified liquid", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Score the skin of the smoked duck breast in a crosshatch pattern. Place skin-side down in a cold skillet. Turn heat to medium and render the fat until the skin is golden and crispy, about 6-8 minutes. Flip and warm the flesh side for 1-2 minutes.", "structured": {"action": "SEAR", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT8M", "doneness_cues": {"visual": "Skin golden brown and crispy", "tactile": "Fat rendered"}}, "tips": ["Starting in a cold pan helps render fat more effectively than a hot pan."]}, {"step_number": 5, "phase": "finish", "text": "Remove duck from the pan and let it rest for 5 minutes. Once rested, slice thinly against the grain.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "In a large bowl, toss the slightly cooled wild rice with half the vinaigrette. Gently fold in the citrus segments, sliced radishes, scallions, torn mint, and pomegranate seeds.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Divide the rice mixture among serving bowls. Fan the sliced duck breast over the top. Garnish with toasted pecans and drizzle with the remaining vinaigrette.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT45M", "total_time": "PT1H10M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 380}', '{"flags": ["Gluten-Free", "Dairy-Free", "Egg-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 615.88, "protein_g": 30.79, "carbohydrates_g": 59.02, "fat_g": 30.86, "saturated_fat_g": 4.12, "trans_fat_g": null, "monounsaturated_fat_g": 17.18, "polyunsaturated_fat_g": 5.21, "fiber_g": 8.91, "sugar_g": 20.09, "sodium_mg": 379.31, "cholesterol_mg": null, "potassium_mg": 935.3, "calcium_mg": 57.35, "iron_mg": 6.78, "magnesium_mg": 143.07, "phosphorus_mg": 463.73, "zinc_mg": 4.58, "vitamin_a_mcg": 38.01, "vitamin_c_mg": 33.44, "vitamin_d_mcg": null, "vitamin_e_mg": 2.99, "vitamin_k_mcg": 36.46, "vitamin_b6_mg": 0.28, "vitamin_b12_mcg": null, "thiamin_mg": 0.21, "riboflavin_mg": 0.19, "niacin_mg": 3.87, "folate_mcg": 77.78, "water_g": 244.29, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store dressing separately to keep greens fresh. Duck is best consumed immediately but keeps well.", "duration": "P2D"}, "freezer": {"notes": "Rice can be frozen, but fresh ingredients will not survive freezing.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Medium saucepan with lid", "required": true, "alternative": null}, {"name": "Skillet", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Rice is still hard after 45 minutes", "likely_cause": "Heat was too low or lid wasn''t tight enough, allowing steam to escape", "prevention": "Ensure a tight-fitting lid and maintain a gentle simmer", "fix": "Add 30-50ml boiling water and continue cooking for 10 minutes"}, {"symptom": "Duck skin is chewy", "likely_cause": "Fat didn''t render completely or pan was too hot too fast", "prevention": "Start duck in a cold pan to slowly melt the fat layer", "fix": "Return to pan skin-side down over medium-low heat until crisp"}]', '["Save the rendered duck fat from the skillet; it is liquid gold for roasting potatoes or saut\u00e9ing vegetables later.", "Supreming citrus (removing pith and membrane) is crucial for texture; pith can add unwanted bitterness.", "The wild rice can be cooked a day in advance; just bring it to room temperature before assembling for the best flavor release."]', '"This dish exemplifies modern fusion cuisine, marrying the French technique of duck preparation and citrus supreming with the hearty, nutty grains native to North American cuisine. It reflects a shift toward texturally complex, nutrient-dense main course salads."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('c0a81042-1477-434e-8e11-8dcd446cb6f4', 'Eggplant and Ricotta Gratin with Velvet Béchamel', 'A sophisticated white lasagna alternative where tender, roasted eggplant steaks replace pasta. Layers of herb-infused ricotta and a silky, nutmeg-scented béchamel sauce melt together under a golden crust of Parmesan cheese.', 'Main Course', 'Italian', 'Intermediate', '[{"group_name": "Roasted Eggplant", "items": [{"name": "globe eggplant", "quantity": 3, "unit": null, "preparation": "sliced into 1cm rounds", "notes": "approx. 1.2kg total weight", "substitutions": [], "ingredient_id": "77c14307-dacf-4ab2-85d1-3594bff0ec99", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 10, "unit": "g", "preparation": null, "notes": "for sweating eggplant", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "B\u00e9chamel Sauce", "items": [{"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 750, "unit": "ml", "preparation": "warm", "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "nutmeg", "quantity": null, "unit": null, "preparation": "freshly grated", "notes": "generous pinch", "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "white pepper", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Ricotta Filling & Topping", "items": [{"name": "whole milk ricotta", "quantity": 500, "unit": "g", "preparation": "drained", "notes": null, "substitutions": [], "ingredient_id": "7a68dbea-ec03-42ae-b0eb-983bf3d4c7b6", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil", "quantity": 15, "unit": "g", "preparation": "chiffonade", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "zest of 1 lemon", "substitutions": [], "ingredient_id": "9e54e651-2396-4bef-9625-00ed1c90838f", "nutrition_source": "Aggregated Public Data"}, {"name": "parmigiano reggiano", "quantity": 100, "unit": "g", "preparation": "freshly grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Arrange eggplant slices on baking sheets or wire racks. Sprinkle with salt and let sit for 20 minutes to draw out bitter moisture. Preheat oven to 220\u00b0C/425\u00b0F.", "structured": {"action": "CURE", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Pat the eggplant slices thoroughly dry with paper towels. Brush both sides lightly with olive oil and arrange in a single layer on baking sheets. Roast for 25 minutes until tender and golden brown. Remove and lower oven temperature to 190\u00b0C/375\u00b0F.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT25M", "doneness_cues": {"visual": "Golden brown spots", "tactile": "Soft center"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "To make the b\u00e9chamel, melt butter in a saucepan over medium heat. Whisk in flour and cook for 2 minutes without browning to cook out the raw flour taste.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Gradually stream in the warm milk while whisking constantly to prevent lumps. Simmer gently for 5-7 minutes until the sauce thickens enough to coat the back of a spoon. Remove from heat and season with nutmeg, salt, and white pepper.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Coats back of spoon (nappe consistency)", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "In a bowl, mix the drained ricotta with the lemon zest, chopped basil, and a pinch of salt. Mix until smooth.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Spread a thin layer of b\u00e9chamel on the bottom of the baking dish. Layer one-third of the roasted eggplant, dollop with half the ricotta mixture, and top with one-third of the remaining b\u00e9chamel. Repeat layers, finishing with the final layer of eggplant, the remaining b\u00e9chamel, and the grated Parmesan cheese.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bake at 190\u00b0C/375\u00b0F for 30-35 minutes until the dish is bubbling and the top is deeply golden brown. If browning too quickly, tent loosely with foil.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT35M", "doneness_cues": {"visual": "Bubbling edges and browned top", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Let the gratin rest for at least 15-20 minutes before slicing. This allows the layers to set and prevents the sauce from running out when cut.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT55M", "total_time": "PT1H40M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Egg-Free", "Soy-Free", "Nut-Free"], "not_suitable_for": ["Vegans (Dairy)", "Celiac Disease (Gluten)"]}', '{"per_serving": {"calories": 515.89, "protein_g": 19.38, "carbohydrates_g": 32.44, "fat_g": 35.38, "saturated_fat_g": 16.69, "trans_fat_g": 0.27, "monounsaturated_fat_g": 14.18, "polyunsaturated_fat_g": 2.29, "fiber_g": 6.51, "sugar_g": 13.72, "sodium_mg": 994.42, "cholesterol_mg": 86.17, "potassium_mg": 844.11, "calcium_mg": 537.17, "iron_mg": 1.03, "magnesium_mg": 69.15, "phosphorus_mg": 412.25, "zinc_mg": 1.79, "vitamin_a_mcg": 269.01, "vitamin_c_mg": 5.6, "vitamin_d_mcg": 1.88, "vitamin_e_mg": 2.52, "vitamin_k_mcg": 25.7, "vitamin_b6_mg": 0.32, "vitamin_b12_mcg": 1.49, "thiamin_mg": 0.17, "riboflavin_mg": 0.61, "niacin_mg": 1.73, "folate_mcg": 59.49, "water_g": 366.29, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves the next day. Reheat gently to prevent oil separation.", "duration": "P4D"}, "freezer": {"notes": "Bake from frozen at 180\u00b0C/350\u00b0F for 45-50 minutes covered, then uncover to brown.", "duration": "P2M"}, "reheating": "Oven at 170\u00b0C/340\u00b0F covered with foil for 20 minutes.", "does_not_keep": false}', '[{"name": "Rimmed baking sheets", "required": true, "alternative": "Large frying pan (batch cooking)"}, {"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Ceramic baking dish (approx. 23x33cm)", "required": true, "alternative": null}, {"name": "Pastry brush", "required": false, "alternative": null}]', '[{"symptom": "The finished dish is watery and soupy", "likely_cause": "Insufficient moisture removal from the eggplant before assembly", "prevention": "Ensure eggplant is sweated with salt and roasted until truly dry before layering", "fix": "Let the dish rest for an additional 20 minutes; the liquids will reabsorb as it cools"}]', '["Do not skip the resting period after baking. Like lasagna, this dish needs time for the hydrocolloids in the sauce and cheese to stabilize, ensuring clean cuts rather than a mess.", "Warm your milk before adding it to the roux (butter/flour mixture). Cold milk shocks the starch and makes creating a smooth, lump-free sauce much more difficult.", "The lemon zest in the ricotta is essential. It provides a bright acidic counterpoint to the heavy dairy fats, cutting through the richness for a more balanced palate.", "For an extra crisp top, turn on the broiler/grill for the last 2 minutes of baking, but watch closely to prevent burning."]', '"This dish draws inspiration from the Italian ''Melanzane alla Parmigiana'' but substitutes the traditional tomato sauce with a French-influenced B\u00e9chamel, creating a ''Melanzane Bianche'' (White Eggplant). It highlights the versatility of eggplant as a meaty, substantial vegetable capable of carrying rich dairy flavors."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('c9ab0e8b-b20c-496c-afeb-1d1beac4b8af', 'Steak Frites with Triple-Cooked Chips', 'The quintessential bistro classic featuring a thick-cut, crusty sirloin steak served alongside scientifically perfected chips—glass-like crunch on the outside, fluffy cloud-like interior.', 'Dinner', 'French Bistro', 'Advanced', '[{"group_name": "Steak", "items": [{"name": "sirloin steaks", "quantity": 2, "unit": null, "preparation": "room temperature", "notes": "approx. 250g-300g each, 4cm thick", "substitutions": [], "ingredient_id": "6ab398fc-b106-4c49-a2c7-0c643f644581", "nutrition_source": "USDA FoodData Central"}, {"name": "grapeseed oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "or other high smoke point oil", "substitutions": [], "ingredient_id": "00f43166-1b77-4e77-9e30-e912a59d118a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 40, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "crushed", "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 3, "unit": null, "preparation": "sprigs", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "flaky sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "generous amount to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Triple-Cooked Chips", "items": [{"name": "starchy potatoes", "quantity": 800, "unit": "g", "preparation": "peeled and cut into 2cm batons", "notes": "Maris Piper, Russet, or Sebago", "substitutions": [], "ingredient_id": "4920385c-ae78-4023-8318-c5dfe051fecc", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral frying oil", "quantity": 2000, "unit": "ml", "preparation": null, "notes": "peanut or vegetable oil for deep frying", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}, {"name": "white vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": "prevents disintegration during boiling", "substitutions": [], "ingredient_id": "8d5bf07e-89a1-47ee-a6b7-d9cb03e96d64", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place cut potatoes in a pot, cover with cold water, add vinegar and a pinch of salt. Bring to a boil and simmer until the edges are breaking apart but the center remains intact (approx. 20-25 mins).", "structured": {"action": "BOIL", "temperature": null, "duration": "PT25M", "doneness_cues": {"visual": "Edges looking friable/rough", "tactile": "Soft but not mush"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Gently drain potatoes and arrange on a wire rack. Allow to steam dry and cool completely, preferably in the refrigerator for at least 1 hour to remove surface moisture.", "structured": {"action": "COOL", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat oil in a deep pot to 130\u00b0C/266\u00b0F. Fry potatoes in batches until a pale crust forms (about 5-7 minutes). They should not brown yet. Remove and drain on rack. Cool for 30 minutes.", "structured": {"action": "FRY", "temperature": {"celsius": 130, "fahrenheit": 266}, "duration": "PT7M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While chips cool, pat steaks bone-dry with paper towels. Season heavily with salt on all sides. Heat cast iron skillet until smoking hot.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add oil to the smoking pan. Sear steaks, flipping every minute to build an even crust. Continue until internal temperature reaches 50\u00b0C/122\u00b0F for medium-rare.", "structured": {"action": "SEAR", "temperature": {"celsius": 50, "fahrenheit": 122}, "duration": null, "doneness_cues": {"visual": "Deep dark brown crust", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "In the last minute of cooking, add butter, garlic, and thyme. Baste the steak foaming butter over the meat continuously.", "structured": {"action": "BASTE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove steaks to a warm plate and rest for 10 minutes. While resting, increase oil heat to 190\u00b0C/375\u00b0F.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Fry the cooled chips a second time at 190\u00b0C/375\u00b0F until deep golden brown and extremely crisp (approx 3-4 minutes). Drain, season immediately with salt, and serve with the steak.", "structured": {"action": "FRY", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT4M", "doneness_cues": {"visual": "Deep golden brown", "tactile": "Hard shell sound when tapped"}}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "PT2H", "total_time": "PT2H50M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 450}', '{"flags": ["Gluten-Free", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 941.34, "protein_g": 78.79, "carbohydrates_g": 64.75, "fat_g": 42.13, "saturated_fat_g": 15.25, "trans_fat_g": null, "monounsaturated_fat_g": 7.1, "polyunsaturated_fat_g": 11.27, "fiber_g": 10.04, "sugar_g": 4.65, "sodium_mg": 1773.26, "cholesterol_mg": 43, "potassium_mg": 2624.29, "calcium_mg": 128.32, "iron_mg": 7.01, "magnesium_mg": 152.76, "phosphorus_mg": 831.12, "zinc_mg": 12.28, "vitamin_a_mcg": 142.75, "vitamin_c_mg": 41.65, "vitamin_d_mcg": null, "vitamin_e_mg": 4.83, "vitamin_k_mcg": 7.87, "vitamin_b6_mg": 0.86, "vitamin_b12_mcg": 0.04, "thiamin_mg": 0.29, "riboflavin_mg": 0.14, "niacin_mg": 4.37, "folate_mcg": 73.85, "water_g": 333.63, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Steak stores well; chips lose texture immediately.", "duration": "P2D"}, "freezer": {"notes": "Do not freeze cooked chips.", "duration": null}, "reheating": "Reheat steak gently in pan; chips must be refried or air-fried to restore crunch.", "does_not_keep": false}', '[{"name": "Heavy-bottomed cast iron skillet or grill pan", "required": true, "alternative": null}, {"name": "Deep heavy pot or Dutch oven", "required": true, "alternative": "Deep fryer"}, {"name": "Digital instant-read thermometer", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}, {"name": "Spider strainer or slotted spoon", "required": true, "alternative": null}]', '[{"symptom": "Chips are soggy or greasy", "likely_cause": "Oil temperature dropped too low when adding potatoes", "prevention": "Fry in smaller batches and ensure thermometer reads 190\u00b0C/375\u00b0F before adding chips", "fix": "Refry at correct high temperature briefly to drive out oil"}, {"symptom": "Steak has a grey band inside the crust", "likely_cause": "Steak was too cold when cooking or not flipped often enough", "prevention": "Temper steak and flip every 60 seconds", "fix": "Cannot be fixed"}]', '["The ''micro-cracks'' created during the vigorous boil are essential; they trap oil during the final fry to create that glass-like crunch.", "Flipping the steak every minute (the ''constant flip'' method) cooks the meat more evenly and develops a better crust than flipping once.", "Adding vinegar to the potato water prevents the potato from disintegrating completely before the starch is gelatinized.", "Always salt chips immediately after the final fry; the hot surface oil helps the salt adhere."]', '"While ''Steak Frites'' is the national dish of bistro dining in France, the triple-cooked chip method is a modern British gastronomic innovation attributed to Heston Blumenthal, elevating the humble potato to a technical masterpiece."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('d08a05be-aa5e-471a-b7af-fb914d52dda4', 'Massaman-Style Chicken Curry', 'A luxurious, velvety Thai curry that bridges the gap between bright red curry and rich Indian aromatics. Tender chicken thighs and creamy Yukon Gold potatoes braise in a coconut sauce deepened with toasted cumin, coriander, and warm spices, finished with the classic crunch of roasted peanuts.', 'Dinner', 'Thai', 'Intermediate', '[{"group_name": "Spice Blend", "items": [{"name": "coriander seeds", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "cumin seeds", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "green cardamom pods", "quantity": 5, "unit": null, "preparation": "whole", "notes": "approx 1g", "substitutions": [], "ingredient_id": "c56f6cd8-882c-487c-956f-3a91ee1fec07", "nutrition_source": "USDA FoodData Central"}, {"name": "cloves", "quantity": 3, "unit": null, "preparation": "whole", "notes": "approx 0.5g", "substitutions": [], "ingredient_id": "7b3bf68a-3ae9-4dad-91f4-6c7a14ec5e0e", "nutrition_source": "USDA FoodData Central"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": "whole", "notes": "approx 5g", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Curry Base", "items": [{"name": "coconut milk", "quantity": 400, "unit": "ml", "preparation": "full fat, divided", "notes": "do not shake can before opening if possible", "substitutions": [], "ingredient_id": "c037ee7e-e3ed-4340-b8fb-d8ad284ba96e", "nutrition_source": "USDA FoodData Central"}, {"name": "red curry paste", "quantity": 60, "unit": "g", "preparation": null, "notes": "adjust based on spice preference", "substitutions": [], "ingredient_id": "e714e2f1-2295-4e8c-8ccf-65c38381e71e", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken stock", "quantity": 120, "unit": "ml", "preparation": null, "notes": "or water", "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Solids", "items": [{"name": "chicken thighs", "quantity": 600, "unit": "g", "preparation": "boneless, skinless, cut into 4cm chunks", "notes": null, "substitutions": [], "ingredient_id": "d7fc1bf9-fc05-429b-bfa6-2ad857cb0bb6", "nutrition_source": "USDA FoodData Central"}, {"name": "yukon gold potatoes", "quantity": 400, "unit": "g", "preparation": "peeled and cut into 4cm chunks", "notes": null, "substitutions": [], "ingredient_id": "90fa399c-54a2-461c-b410-868fba3bac36", "nutrition_source": "Aggregated Public Data"}, {"name": "yellow onion", "quantity": 150, "unit": "g", "preparation": "peeled and cut into thick wedges", "notes": null, "substitutions": [], "ingredient_id": "cc868876-7ceb-46a8-b72a-c3e8a743ee97", "nutrition_source": "Aggregated Public Data"}, {"name": "roasted peanuts", "quantity": 50, "unit": "g", "preparation": "unsalted", "notes": null, "substitutions": [], "ingredient_id": "e69dc0eb-7563-4023-9bc5-a07cc9cdc3d0", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Seasoning", "items": [{"name": "fish sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "tamarind concentrate", "quantity": 30, "unit": "ml", "preparation": null, "notes": "sourness varies by brand, add to taste", "substitutions": [], "ingredient_id": "254bdaf4-58fe-4717-9ff5-4ae88119aac3", "nutrition_source": "Aggregated Public Data"}, {"name": "palm sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": "or brown sugar", "substitutions": ["brown sugar"], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Toast the coriander and cumin seeds in a dry small pan over medium heat until fragrant (about 1-2 minutes). Let cool slightly, then grind into a fine powder using a mortar and pestle or spice grinder. Set aside.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Seeds darken slightly", "tactile": "Aromatic"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a heavy-bottomed pot over medium heat, add about 100ml of the thick coconut cream from the top of the can. Cook, stirring occasionally, until the water evaporates and the coconut oil separates (it will look curdled and shiny).", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Oil separates from solids", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the red curry paste and the ground coriander/cumin spice blend to the cracked coconut cream. Fry, stirring constantly, until the paste darkens and becomes very aromatic.", "structured": {"action": "FRY", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Paste darkens, oil turns red", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the chicken thigh chunks to the pot. Stir well to coat the meat in the curry paste mixture and cook for 2 minutes to sear the outside slightly.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour in the remaining coconut milk and the chicken stock. Add the whole cinnamon stick, cloves, cardamom pods, potatoes, onion wedges, and roasted peanuts. Ensure solids are mostly submerged.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Reduce heat to low, cover, and simmer gently until the potatoes are tender and the chicken is cooked through (internal temperature of chicken should reach 74\u00b0C/165\u00b0F).", "structured": {"action": "SIMMER", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT40M", "doneness_cues": {"visual": null, "tactile": "Potatoes pierce easily with a fork"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Stir in the fish sauce, tamarind concentrate, and palm sugar. Simmer for 5 more minutes uncovered to meld flavors. Taste and adjust: it should be a balance of salty, sour, and sweet.", "structured": {"action": "SEASON", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT45M", "total_time": "PT1H15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 400}', '{"flags": ["Gluten-Free", "Dairy-Free"], "not_suitable_for": ["Peanut allergy", "Shellfish allergy (fish sauce/shrimp paste)"]}', '{"per_serving": {"calories": 696.91, "protein_g": 40.04, "carbohydrates_g": 53.23, "fat_g": 39.75, "saturated_fat_g": 23.9, "trans_fat_g": 0.04, "monounsaturated_fat_g": 8.17, "polyunsaturated_fat_g": 4.6, "fiber_g": 14.66, "sugar_g": 17.5, "sodium_mg": 7727.11, "cholesterol_mg": 141, "potassium_mg": 1347.99, "calcium_mg": 163.22, "iron_mg": 8.43, "magnesium_mg": 147.74, "phosphorus_mg": 532.77, "zinc_mg": 4.31, "vitamin_a_mcg": 11.62, "vitamin_c_mg": 21.36, "vitamin_d_mcg": null, "vitamin_e_mg": 4.26, "vitamin_k_mcg": 20.55, "vitamin_b6_mg": 0.73, "vitamin_b12_mcg": 0.92, "thiamin_mg": 0.22, "riboflavin_mg": 0.34, "niacin_mg": 10.11, "folate_mcg": 38.06, "water_g": 183.66, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors deepen significantly the next day.", "duration": "P3D"}, "freezer": {"notes": "Potatoes may become slightly grainy upon thawing.", "duration": "P1M"}, "reheating": "Reheat gently on the stovetop over medium-low heat until piping hot. Add a splash of water if the sauce has thickened too much.", "does_not_keep": false}', '[{"name": "Heavy-bottomed pot or Dutch oven", "required": true, "alternative": null}, {"name": "Small frying pan", "required": true, "alternative": "Wok"}, {"name": "Mortar and pestle", "required": true, "alternative": "Spice grinder"}]', '[{"symptom": "Curry tastes too sour or too salty", "likely_cause": "Imbalance of the three key seasoning agents (fish sauce, tamarind, sugar)", "prevention": "Add seasoning gradually in the final step, tasting as you go", "fix": "If too sour, add more sugar. If too salty, add a splash of water and sugar. If too sweet, add more tamarind or lime juice."}]', '["Using Red Curry Paste plus dry spices (cumin, coriander, cardamom, cloves) effectively creates a Massaman profile if you cannot find specific Massaman curry paste.", "Cracking the coconut cream (frying it until the oil separates) is a traditional technique that enhances the flavor and color of the curry. If using low-fat milk or homogenized milk that won''t separate, simply fry the paste in 1 tablespoon of coconut oil instead.", "The potatoes and chicken should be cut to roughly the same size to ensure they finish cooking at the same time.", "This curry tastes significantly better the next day as the spices have time to permeate the potatoes and meat."]', '"Massaman curry (Gaeng Massaman) has Persian and Indian roots, evidenced by the use of dried spices like cardamom, cinnamon, and cloves which are rare in other Thai curries. It originated in Southern Thailand near the border with Malaysia and was historically associated with the Muslim community."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('d2c6c5b8-ea47-48c2-af3e-19886d8a4e37', 'Roasted Butternut Squash & Shallots with Date-Cranberry Agrodolce', 'Golden, caramelized cubes of roasted squash and jammy shallots provide a savory base for a festive, jewel-toned relish. The sweetness of Medjool dates and the tart pop of cranberries are balanced by salty, creamy feta in this vibrant side dish.', 'Side Dish', 'Modern Mediterranean', 'Easy', '[{"group_name": "Roasted Vegetables", "items": [{"name": "butternut squash", "quantity": 1000, "unit": "g", "preparation": "peeled and cubed into 2.5cm pieces", "notes": "approx. 1 large squash", "substitutions": [], "ingredient_id": "7f8919a5-2de5-47ce-91b2-d2a999ea11f7", "nutrition_source": "USDA FoodData Central"}, {"name": "shallots", "quantity": 300, "unit": "g", "preparation": "peeled and halved lengthwise", "notes": "keep root intact to hold layers together", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme leaves", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste (min 1g)", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Date & Cranberry Relish", "items": [{"name": "medjool dates", "quantity": 80, "unit": "g", "preparation": "pitted and roughly chopped", "notes": "approx. 4-5 dates", "substitutions": [], "ingredient_id": "657c170c-11cc-41f7-a980-050a218a088e", "nutrition_source": "USDA FoodData Central"}, {"name": "dried cranberries", "quantity": 40, "unit": "g", "preparation": null, "notes": "unsweetened preferred", "substitutions": [], "ingredient_id": "788f186b-788f-4fcd-aff0-ab8983926e97", "nutrition_source": "USDA FoodData Central"}, {"name": "apple cider vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "orange zest", "quantity": null, "unit": null, "preparation": null, "notes": "zest of half an orange", "substitutions": [], "ingredient_id": "c1a067e6-674f-4f68-9fe9-3eda4b074356", "nutrition_source": "Aggregated Public Data"}, {"name": "extra virgin olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "chili flakes", "quantity": null, "unit": null, "preparation": null, "notes": "pinch, optional for heat", "substitutions": [], "ingredient_id": "a4bf8b34-30b2-4d24-a120-b5b191811f64", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Topping", "items": [{"name": "feta cheese", "quantity": 100, "unit": "g", "preparation": "crumbled", "notes": "Greek feta preferred", "substitutions": [], "ingredient_id": "a9a8605c-3bf2-4ca3-8c58-80e87aff7cd8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 220\u00b0C (425\u00b0F). Prepare the vegetables: peel and cube the squash into uniform 2.5cm (1 inch) pieces. Peel the shallots and cut them in half lengthwise.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, toss the squash and shallots with olive oil, thyme, salt, and black pepper until thoroughly coated.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Spread the vegetables in a single, even layer on a rimmed baking sheet. Do not overcrowd. Roast for 30-35 minutes, flipping halfway through, until the squash is tender and caramelized at the edges.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT35M", "doneness_cues": {"visual": "Squash edges browned, shallots softened", "tactile": "Fork-tender"}}, "tips": ["Use two baking sheets if necessary to ensure vegetables roast rather than steam."]}, {"step_number": 4, "phase": "prep", "text": "While vegetables roast, prepare the relish. In a small bowl, combine chopped dates, dried cranberries, apple cider vinegar, orange zest, extra virgin olive oil, and parsley. Stir well and let sit for at least 10 minutes to allow flavors to meld and fruits to plump slightly.", "structured": {"action": "MACERATE", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Transfer the hot roasted vegetables to a serving platter. Spoon the date and cranberry relish evenly over the top.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Garnish immediately with crumbled feta cheese. The residual heat from the vegetables will slightly warm the cheese without melting it completely.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT35M", "total_time": "PT1H", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 220}', '{"flags": ["Vegetarian", "Gluten-Free", "Egg-Free", "Soy-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 310.83, "protein_g": 4.97, "carbohydrates_g": 40.95, "fat_g": 16.44, "saturated_fat_g": 4.01, "trans_fat_g": null, "monounsaturated_fat_g": 9.94, "polyunsaturated_fat_g": 1.51, "fiber_g": 5.72, "sugar_g": 19.53, "sodium_mg": 589.61, "cholesterol_mg": 14.83, "potassium_mg": 789.17, "calcium_mg": 190.98, "iron_mg": 1.89, "magnesium_mg": 75.12, "phosphorus_mg": 137.34, "zinc_mg": 0.92, "vitamin_a_mcg": 917.72, "vitamin_c_mg": 42.99, "vitamin_d_mcg": 0.07, "vitamin_e_mg": 4.4, "vitamin_k_mcg": 38.33, "vitamin_b6_mg": 0.42, "vitamin_b12_mcg": 0.28, "thiamin_mg": 0.23, "riboflavin_mg": 0.2, "niacin_mg": 2.52, "folate_mcg": 64.92, "water_g": 208.72, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store relish and roasted vegetables separately if possible to maintain texture.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; squash becomes mushy and feta texture degrades.", "duration": null}, "reheating": "Reheat vegetables in a 180\u00b0C oven for 10 minutes; add relish and cheese after heating.", "does_not_keep": false}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Large rimmed baking sheet", "required": true, "alternative": "Two smaller roasting pans"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Vegetable peeler", "required": true, "alternative": null}]', '[{"symptom": "Squash is soggy rather than browned", "likely_cause": "The baking sheet was overcrowded, causing the vegetables to steam instead of roast", "prevention": "Use two baking sheets or roast in batches to ensure air circulation around each piece", "fix": "Increase oven temp to 230\u00b0C/450\u00b0F and roast for 5 more minutes on the convection setting if available"}]', '["Cut the butternut squash into uniform sizes to ensure even cooking; mixing small and large chunks will result in some being mushy while others are hard.", "For the best flavor, buy block feta in brine and crumble it yourself. Pre-crumbled feta often contains anti-caking agents that affect the texture.", "The relish relies on the balance of acid and sugar. If your dates are very sweet, add a squeeze of fresh lemon juice to the relish to sharpen the flavor profile.", "If preparing ahead for a dinner party, roast the vegetables 90% of the way, then blast them in the oven for 5-8 minutes right before serving to reheat and crisp up."]', '"This dish exemplifies modern Mediterranean cooking, where the sweetness of dried fruits (common in North African tagines) meets the European tradition of roasted root vegetables. The contrast of warm, earthy squash with bright, acidic fruit and briny cheese makes it a staple profile in contemporary harvest cuisine."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('d332123d-a429-4f1a-b457-bcb09594075f', 'Kentucky Bourbon Pecan Pie', 'A sophisticated elevation of the Southern classic. Toasted pecans are suspended in a rich, dark custard infused with Kentucky bourbon and vanilla bean, set atop a buttery, blind-baked pastry crust to ensure crispness.', 'Dessert', 'American', 'Intermediate', '[{"group_name": "P\u00e2te Bris\u00e9e (Crust)", "items": [{"name": "all-purpose flour", "quantity": 170, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ice water", "quantity": 60, "unit": "ml", "preparation": null, "notes": "approximate, use just enough to bind", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Bourbon Filling", "items": [{"name": "pecan halves", "quantity": 200, "unit": "g", "preparation": "raw", "notes": null, "substitutions": [], "ingredient_id": "a5c5ee79-2bcd-4ab2-aed5-b09d0a3df4b5", "nutrition_source": "USDA FoodData Central"}, {"name": "large eggs", "quantity": 3, "unit": null, "preparation": null, "notes": "approx 150g total without shell, room temperature", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "dark corn syrup", "quantity": 300, "unit": "g", "preparation": null, "notes": "provides viscosity and prevents crystallization", "substitutions": [], "ingredient_id": "afcbec4e-1b32-41b6-825d-453531fdd55e", "nutrition_source": "USDA FoodData Central"}, {"name": "light brown sugar", "quantity": 100, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "melted and cooled", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "bourbon whiskey", "quantity": 30, "unit": "ml", "preparation": null, "notes": "use a quality brand like Maker''s Mark or Woodford Reserve", "substitutions": [], "ingredient_id": "6b50db10-fa85-4831-90f9-6cf2c78546c2", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "flaked sea salt preferred", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pulse flour, sugar, and salt in a food processor. Add cold cubed butter and pulse briefly until mixture resembles coarse meal with pea-sized butter bits remaining.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Drizzle in ice water one tablespoon at a time, pulsing until the dough just begins to hold together when pinched. Form into a disk, wrap in plastic, and refrigerate for at least 30 minutes.", "structured": {"action": "REST", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Preheat oven to 190\u00b0C (375\u00b0F). Roll dough out on a floured surface to a 30cm (12-inch) circle. Transfer to pie dish, trim overhang, and crimp edges. Freeze for 10 minutes to set the shape.", "structured": {"action": "ROLL", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Line the crust with parchment paper and fill with pie weights. Par-bake (blind bake) for 15 minutes. Remove weights and paper, then bake for another 5 minutes until the bottom looks dry. Lower oven temperature to 175\u00b0C (350\u00b0F).", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "While the crust cools slightly, spread pecans on a baking sheet and toast in the oven for 5-7 minutes until fragrant. Set aside to cool.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "In a large bowl, whisk together eggs, dark corn syrup, brown sugar, melted butter, bourbon, vanilla, and salt until completely smooth and emulsified.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Arrange the toasted pecans in the bottom of the par-baked crust. Pour the filling mixture evenly over the pecans. The nuts will rise to the surface.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Bake at 175\u00b0C (350\u00b0F) for 40-50 minutes. The pie is done when the edges are set and puffed, but the center still has a slight wobble (like gelatin) when gently shaken. It should not be liquid.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT45M", "doneness_cues": {"visual": "Edges puffed, center wobbles like gelatin", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove from oven and place on a wire rack. Cool completely for at least 2 hours before slicing. This rest period is mandatory for the filling to set.", "structured": {"action": "COOL", "temperature": null, "duration": "PT2H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT2H", "total_time": "PT2H45M", "overnight_required": false, "yields": "1 9-inch pie", "yield_count": 8, "serving_size_g": 135}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Nut allergies", "Gluten intolerance", "Alcohol restrictions"]}', '{"per_serving": {"calories": 606.32, "protein_g": 7.05, "carbohydrates_g": 62.65, "fat_g": 37.73, "saturated_fat_g": 13.21, "trans_fat_g": 0.01, "monounsaturated_fat_g": 16.02, "polyunsaturated_fat_g": 6.51, "fiber_g": 2.97, "sugar_g": 43.76, "sodium_mg": 382.39, "cholesterol_mg": 116.78, "potassium_mg": 191.46, "calcium_mg": 54.04, "iron_mg": 1.45, "magnesium_mg": 41.97, "phosphorus_mg": 139.61, "zinc_mg": 1.56, "vitamin_a_mcg": 180.38, "vitamin_c_mg": 0.28, "vitamin_d_mcg": 0.38, "vitamin_e_mg": 1.07, "vitamin_k_mcg": 2.53, "vitamin_b6_mg": 0.1, "vitamin_b12_mcg": 0.21, "thiamin_mg": 0.2, "riboflavin_mg": 0.14, "niacin_mg": 0.61, "folate_mcg": 20.62, "water_g": 37.82, "alcohol_g": 0.43, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Cover loosely with foil or plastic wrap once fully cooled.", "duration": "P4D"}, "freezer": {"notes": "Wrap tightly in plastic wrap and then foil. Thaw in refrigerator overnight.", "duration": "P2M"}, "reheating": "Serve at room temperature or warm gently in a 150\u00b0C oven for 10 minutes.", "does_not_keep": false}', '[{"name": "9-inch pie dish", "required": true, "alternative": "9-inch tart pan"}, {"name": "Food processor", "required": false, "alternative": "Pastry blender and mixing bowl"}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Pie weights", "required": true, "alternative": "Dried beans or uncooked rice"}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Wire rack", "required": true, "alternative": null}]', '[{"symptom": "Filling is runny after cooling", "likely_cause": "Underbaked pie", "prevention": "Ensure the internal temperature reaches 93\u00b0C (200\u00b0F) or the center jiggle is firm, not wave-like.", "fix": "Refrigerate; cold pecan pie sets firmer than room temperature pie."}, {"symptom": "Crust is soggy", "likely_cause": "Skipped blind baking or filling sat in raw crust too long", "prevention": "Always par-bake the crust for custard pies.", "fix": "Cannot be fixed."}, {"symptom": "Crust edges are burning before filling sets", "likely_cause": "High sugar content in dough or oven hot spots", "prevention": "Use a pie shield or foil ring around the edges after 20 minutes of baking.", "fix": "Cover edges with foil immediately."}]', '["Toasting the pecans before adding them to the filling releases their natural oils and ensures they stay crisp in the liquid custard.", "Dark corn syrup is preferred over light for its molasses content, which complements the bourbon notes.", "Do not skip the cooling step. Pecan pie filling is essentially a sugar-egg custard; cutting it hot will result in a landslide on the plate.", "For clean slices, run your knife under hot water and wipe dry between cuts.", "If using salted butter, reduce the added salt in the filling to 1g."]', '"Pecan pie is a quintessential dish of the American South, popularized in the mid-20th century by Karo syrup recipes, though its roots lie in the abundance of native pecan groves in states like Texas and Georgia. The addition of bourbon is a modern nod to Kentucky''s distilling heritage, adding a mature complexity to the sugar-forward dessert."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('dab1d87b-8306-4369-9552-a0b9d37a1ecb', 'Spiced Pear and Pistachio Phyllo Strudel', 'A sophisticated twist on the Austrian classic, featuring tender, cardamom-spiced pears and emerald green pistachios encased in shattering layers of golden, buttered phyllo pastry. A perfect festive centerpiece.', 'Dessert', 'European', 'Intermediate', '[{"group_name": "Filling", "items": [{"name": "firm pears (bosc or anjou)", "quantity": 600, "unit": "g", "preparation": "peeled, cored, and diced into 1cm cubes", "notes": "approx. 4 medium pears", "substitutions": [], "ingredient_id": "ed5dd928-efa8-4c10-aeb3-3c08c94c62f8", "nutrition_source": "USDA FoodData Central"}, {"name": "shelled pistachios", "quantity": 100, "unit": "g", "preparation": "roughly chopped", "notes": "unsalted, roasted", "substitutions": [], "ingredient_id": "59207580-65c8-4564-9467-eb7286b8e5a7", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 80, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cardamom", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "c56f6cd8-882c-487c-956f-3a91ee1fec07", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 1, "unit": "g", "preparation": null, "notes": "approx 0.5 tsp", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pastry & Assembly", "items": [{"name": "phyllo dough sheets", "quantity": 10, "unit": null, "preparation": "thawed", "notes": "approx 250g total weight", "substitutions": [], "ingredient_id": "c070937d-c91b-4f22-90f4-6ec707a13cd2", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 120, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "panko breadcrumbs", "quantity": 40, "unit": "g", "preparation": "fine", "notes": null, "substitutions": ["ground almonds", "cookie crumbs"], "ingredient_id": "84fbc204-4457-40ed-83c1-3e5a7bcd8f23", "nutrition_source": "Aggregated Public Data"}, {"name": "powdered sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": "for dusting", "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 190\u00b0C (375\u00b0F). Line a baking sheet with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, combine the diced pears, chopped pistachios, brown sugar, cornstarch, lemon juice, cardamom, cinnamon, vanilla, and salt. Toss well to coat the fruit evenly. Set aside to macerate slightly while preparing the dough.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": ["The cornstarch is crucial to absorb pear juices and prevent a soggy bottom."]}, {"step_number": 3, "phase": "assemble", "text": "Lay one sheet of phyllo dough on a clean, dry surface or a large sheet of parchment. Keep the remaining phyllo covered with a slightly damp towel to prevent drying out. Brush the sheet lightly with melted butter and sprinkle with a small amount of breadcrumbs.", "structured": {"action": "LAMINATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Repeat this process, stacking the phyllo sheets one on top of the other, brushing each with butter and sprinkling with breadcrumbs, until you have used all 10 sheets. Do not butter the very top layer yet.", "structured": {"action": "LAMINATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Spoon the pear mixture along the longer edge of the phyllo stack, leaving a 5cm (2-inch) border on the sides and bottom.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Fold the side borders in over the filling. Roll the strudel up tightly from the filled long edge, encasing the fruit completely. Place the strudel seam-side down on the prepared baking sheet.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Brush the entire exterior of the strudel generously with the remaining melted butter. Using a sharp knife, score the top of the pastry diagonally every 4cm (1.5 inches) to allow steam to escape (do not cut all the way through).", "structured": {"action": "SCORE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Bake in the preheated oven for 35-40 minutes, or until the phyllo is deep golden brown and crisp to the touch.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT35M", "doneness_cues": {"visual": "Deep golden brown pastry", "tactile": "Hollow sound when tapped lightly"}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove from the oven and let cool on the pan for at least 20 minutes to allow the filling to set. Dust with powdered sugar before slicing and serving.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT40M", "total_time": "PT1H25M", "overnight_required": false, "yields": "8 slices", "yield_count": 8, "serving_size_g": 165}', '{"flags": ["Vegetarian", "Egg-Free", "Soy-Free"], "not_suitable_for": ["Vegans (contains butter)"]}', '{"per_serving": {"calories": 384.77, "protein_g": 5.82, "carbohydrates_g": 48.27, "fat_g": 19.9, "saturated_fat_g": 8.79, "trans_fat_g": null, "monounsaturated_fat_g": 7.47, "polyunsaturated_fat_g": 2.61, "fiber_g": 4.58, "sugar_g": 19.74, "sodium_mg": 218.46, "cholesterol_mg": 32.25, "potassium_mg": 260.81, "calcium_mg": 37.68, "iron_mg": 1.83, "magnesium_mg": 27.16, "phosphorus_mg": 98.64, "zinc_mg": 0.55, "vitamin_a_mcg": 106.62, "vitamin_c_mg": 4.71, "vitamin_d_mcg": null, "vitamin_e_mg": 0.83, "vitamin_k_mcg": 5.17, "vitamin_b6_mg": 0.25, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.29, "riboflavin_mg": 0.16, "niacin_mg": 1.58, "folate_mcg": 40.06, "water_g": 78.55, "alcohol_g": 0.22, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Phyllo loses crispness rapidly in the fridge. Re-crisp in oven before serving.", "duration": "P2D"}, "freezer": {"notes": "Freeze unbaked for best results. Bake from frozen, adding 10-15 minutes to time.", "duration": "P1M"}, "reheating": "Oven at 180\u00b0C/350\u00b0F for 10-15 minutes to recrisp.", "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": null}, {"name": "Sharp knife", "required": true, "alternative": null}, {"name": "Clean kitchen towel", "required": true, "alternative": "Damp paper towels"}]', '[{"symptom": "Strudel is soggy on the bottom", "likely_cause": "Excess moisture from pears or insufficient breadcrumbs between layers", "prevention": "Ensure pears are tossed with cornstarch; do not skip the breadcrumb layer between phyllo sheets", "fix": "Bake on the lowest oven rack for an extra 5-10 minutes; serve slices with a custard sauce to mask the texture"}]', '["Thaw phyllo dough in the refrigerator overnight, never on the counter, to prevent the sheets from sticking together.", "Bosc pears are preferred over Bartlett because they hold their shape better during baking and release less liquid.", "The breadcrumbs between the layers act as a barrier, absorbing butter and creating separation for maximum flake.", "Serve warm with a dollop of mascarpone or vanilla bean cr\u00e8me anglaise for a luxurious finish.", "If the phyllo tears while rolling, simply patch it with a little melted butter and an extra scrap of dough; it will not be visible after baking."]', '"While Strudel is synonymous with Austrian cuisine (Apfelstrudel gained popularity in the 18th century Habsburg Empire), its roots trace back to the Middle East. The thin, stretched dough is a direct descendant of Turkish baklava pastry. This recipe bridges that history by utilizing pistachios and cardamom, flavors prominent in the dough''s geographical origins."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('dfab05f6-9dc4-4602-84fb-d4240ebd6095', 'Brown Butter Sea Salt Rice Crispy Treats', 'An elevated interpretation of the childhood classic, featuring deep, nutty notes from caramelized brown butter, balanced by flaky sea salt and rich vanilla bean paste. The texture is perfectly chewy and gooey, never hard.', 'Dessert', 'American', 'Easy', '[{"group_name": "Base", "items": [{"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "cubed", "notes": "Cold or room temp", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "mini marshmallows", "quantity": 300, "unit": "g", "preparation": "fresh", "notes": "Ensure fresh for best texture", "substitutions": [], "ingredient_id": "430032c6-b60b-4130-855e-b8a3d879c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla bean paste", "quantity": 5, "unit": "ml", "preparation": null, "notes": "Or high-quality extract", "substitutions": ["vanilla extract"], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 3, "unit": "g", "preparation": "flaky", "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "gluten-free crisp rice cereal", "quantity": 160, "unit": "g", "preparation": null, "notes": "Check label to ensure no barley malt", "substitutions": [], "ingredient_id": "950e6c79-15ed-4147-9b9e-63f366c7aff8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Line a 20cm x 20cm (8x8 inch) baking pan with parchment paper, leaving an overhang on two sides for easy removal.", "structured": {"action": "PREPARE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In the large pot over medium heat, melt the butter. Continue cooking, swirling the pan frequently, until the butter foams, the milk solids turn a golden-brown color, and it smells nutty (about 5-7 minutes). Watch closely to prevent burning.", "structured": {"action": "CARAMELIZE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT7M", "doneness_cues": {"visual": "Golden brown specs (noisette) at bottom", "tactile": "Foaming subsides slightly"}}, "tips": ["Use a light-colored pan if possible to see the color change easier."]}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to low. Reserve 50g of marshmallows for later. Add the remaining 250g marshmallows to the brown butter. Stir constantly with a silicone spatula until completely melted and smooth.", "structured": {"action": "MELT", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Remove from heat immediately. Stir in the vanilla bean paste and sea salt.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Add the crisp rice cereal and the reserved 50g of mini marshmallows. Fold gently but quickly until the cereal is evenly coated.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Adding fresh marshmallows at the end creates pockets of gooey texture."]}, {"step_number": 6, "phase": "shape", "text": "Transfer the mixture to the prepared pan. Using a piece of greased parchment paper or lightly oiled hands, gently press the mixture into the corners to level it. Do not pack it down tightly.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Allow to cool at room temperature for at least 1 hour before slicing into squares.", "structured": {"action": "COOL", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT1H", "total_time": "PT1H20M", "overnight_required": false, "yields": "16 squares", "yield_count": 16, "serving_size_g": 45}', '{"flags": ["Gluten-Free", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": ["Vegans (contains gelatin and dairy)"]}', '{"per_serving": {"calories": 178.53, "protein_g": 1.35, "carbohydrates_g": 20.08, "fat_g": 11.58, "saturated_fat_g": 8.03, "trans_fat_g": 0.04, "monounsaturated_fat_g": 2.55, "polyunsaturated_fat_g": 0.29, "fiber_g": 1.02, "sugar_g": 17.34, "sodium_mg": 232.17, "cholesterol_mg": 17.75, "potassium_mg": 39.2, "calcium_mg": 35.5, "iron_mg": 0.61, "magnesium_mg": 6.38, "phosphorus_mg": 22.44, "zinc_mg": 0.24, "vitamin_a_mcg": 55.66, "vitamin_c_mg": 0.06, "vitamin_d_mcg": null, "vitamin_e_mg": 0.22, "vitamin_k_mcg": 1.07, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": 0.09, "thiamin_mg": 0.01, "riboflavin_mg": 0.03, "niacin_mg": 0.07, "folate_mcg": 2.02, "water_g": 2.27, "alcohol_g": 0.11, "caffeine_mg": 2}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Not recommended; refrigeration makes them hard.", "duration": null}, "freezer": {"notes": "Layer with parchment paper in an airtight container.", "duration": "P6W"}, "reheating": null, "does_not_keep": false}', '[{"name": "Large heavy-bottomed pot", "required": true, "alternative": "Dutch oven"}, {"name": "20cm x 20cm (8x8 inch) baking pan", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Silicone spatula", "required": true, "alternative": null}]', '[{"symptom": "Treats are rock hard", "likely_cause": "Marshmallows were cooked too long or at too high heat, or mixture was compressed too tightly in pan", "prevention": "Melt marshmallows on low heat just until smooth and press very gently into the pan", "fix": "Microwave individual squares for 5-10 seconds to soften before eating"}]', '["The secret to soft treats is low heat. High heat caramelizes the sugar in the marshmallows, turning it into hard candy once cooled.", "Browning the butter is the ''elevation'' step. It adds a toffee-like complexity that cuts through the simple sugar sweetness.", "To ensure this is truly Gluten-Free, you must buy specific GF rice cereal. Standard Rice Krispies contain barley malt, which has gluten.", "For ultra-clean cuts, lightly oil your knife before slicing the cooled block.", "Don''t skip the salt; it is essential to balance the sweetness of the marshmallows."]', '"Originating in the late 1930s in the United States, this ''no-bake'' confection became a staple of American home economics due to its simplicity and speed. This version applies French culinary technique (beurre noisette) to mature the flavor profile of the nostalgic childhood snack."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('e4b2a2eb-a566-4bed-9dbd-588a282c2363', 'Quick Broccoli and Spinach Saag with Spiced Butter', 'A vibrant, emerald-green curry that hacks the traditional slow-cooked method by using broccoli to provide the creamy body typically associated with mustard greens. Enriched with generous knobs of butter and tempered with warming aromatic spices.', 'Main Course', 'Indian', 'Easy', '[{"group_name": "Greens Base", "items": [{"name": "fresh spinach", "quantity": 300, "unit": "g", "preparation": "washed", "notes": "baby spinach or roughly chopped mature spinach", "substitutions": [], "ingredient_id": "4734440a-226d-4d26-a110-3ed5c3bde93f", "nutrition_source": "USDA FoodData Central"}, {"name": "broccoli", "quantity": 350, "unit": "g", "preparation": "cut into florets", "notes": "approx 1 medium head", "substitutions": [], "ingredient_id": "b0a26615-a0a7-4b5c-9143-e9becf53b41a", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 100, "unit": "ml", "preparation": null, "notes": "for blending", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Aromatics & Spices", "items": [{"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "cubed", "notes": "divided into 40g for cooking, 20g for finishing", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "cumin seeds", "quantity": 4, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "onion", "quantity": 150, "unit": "g", "preparation": "finely diced", "notes": "1 medium onion", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "ginger", "quantity": 15, "unit": "g", "preparation": "grated or paste", "notes": "approx 1 tbsp", "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 15, "unit": "g", "preparation": "minced or paste", "notes": "approx 3-4 cloves", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "green chili", "quantity": 1, "unit": null, "preparation": "finely chopped", "notes": "adjust to heat preference, approx 5g", "substitutions": [], "ingredient_id": "6cdb0615-378e-4bfa-b76d-f19bbd780e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "ground coriander", "quantity": 4, "unit": "g", "preparation": null, "notes": "approx 2 tsp", "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "turmeric powder", "quantity": 1, "unit": "g", "preparation": null, "notes": "approx 1/4 tsp", "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 6, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "garam masala", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "8ffcea01-5f22-462b-94de-ad2a97049325", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Bring a large pot of salted water to a rolling boil. Prepare a bowl of ice water nearby.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add broccoli florets to the boiling water. Cook for 3 minutes until bright green and slightly tender. Add the spinach and cook for just 30 seconds until wilted.", "structured": {"action": "BLANCH", "temperature": null, "duration": "PT3M30S", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Drain the vegetables immediately and plunge them into the ice water to stop the cooking process and lock in the vibrant green color. Drain well after cooling.", "structured": {"action": "SHOCK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Transfer the drained vegetables to a blender. Add 100ml water (or just enough to facilitate blending) and pulse into a coarse puree. Do not over-blend into a smoothie texture; some texture is desirable.", "structured": {"action": "BLEND", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["If the mixture is too thick, add water 1 tablespoon at a time."]}, {"step_number": 5, "phase": "cook", "text": "Heat 40g of butter in a skillet over medium heat. Add cumin seeds and let them crackle for 30 seconds.", "structured": {"action": "TEMPER", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add diced onions. Saut\u00e9 for 5-7 minutes until they turn translucent and start to brown at the edges. Add ginger, garlic, and green chili, cooking for another minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Onions are golden brown", "tactile": "Soft texture"}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Stir in the coriander powder and turmeric. Cook for 30 seconds to toast the spices, ensuring they do not burn.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Pour the green broccoli-spinach puree into the skillet. Stir to combine with the aromatics. Simmer on low heat for 5 minutes to meld the flavors. Season with salt.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Turn off the heat. Stir in the garam masala, the remaining 20g of butter, and heavy cream (if using). Serve immediately.", "structured": {"action": "FINISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT5M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 300}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Egg-Free", "Low-Carb"], "not_suitable_for": ["Vegans (contains dairy butter)"]}', '{"per_serving": {"calories": 213.31, "protein_g": 6.08, "carbohydrates_g": 15.67, "fat_g": 16.06, "saturated_fat_g": 9.5, "trans_fat_g": 0.09, "monounsaturated_fat_g": 4.51, "polyunsaturated_fat_g": 0.87, "fiber_g": 5.47, "sugar_g": 3.82, "sodium_mg": 680.13, "cholesterol_mg": 40.73, "potassium_mg": 843.05, "calcium_mg": 158.09, "iron_mg": 3.84, "magnesium_mg": 92.81, "phosphorus_mg": 130.74, "zinc_mg": 1.06, "vitamin_a_mcg": 513.68, "vitamin_c_mg": 106.63, "vitamin_d_mcg": 0.12, "vitamin_e_mg": 2.69, "vitamin_k_mcg": 453.28, "vitamin_b6_mg": 0.41, "vitamin_b12_mcg": 0.04, "thiamin_mg": 0.17, "riboflavin_mg": 0.29, "niacin_mg": 1.29, "folate_mcg": 209.46, "water_g": 218.32, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Color may darken upon reheating due to oxidation.", "duration": "P3D"}, "freezer": {"notes": "Texture may become slightly watery; reheat gently to emulsify.", "duration": "P1M"}, "reheating": "Simmer gently on stovetop; add a splash of water if too thick.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Blender or Food Processor", "required": true, "alternative": "Immersion blender"}, {"name": "Heavy-bottomed skillet or kadhai", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Curry tastes bitter", "likely_cause": "Spinach was overcooked or broccoli stems were too mature", "prevention": "Blanch quickly and shock in ice water immediately", "fix": "Add a teaspoon of sugar, honey, or extra cream to mask the bitterness"}, {"symptom": "Texture is too watery", "likely_cause": "Vegetables were not drained well after shocking", "prevention": "Squeeze excess water from spinach before blending", "fix": "Simmer for an additional 5-10 minutes to evaporate excess moisture"}]', '["Using broccoli is a modern restaurant trick to give saag the thick, creamy body of slow-cooked mustard greens (sarson) without the bitterness or 2-hour cooking time.", "For an authentic finish, serve with makki ki roti (cornmeal flatbread) or a crisp naan.", "Do not cover the pot once the green puree is added; covering traps acids which will turn the vibrant green color into a dull olive drab.", "If you want to add protein, pan-fried paneer cubes or tofu can be folded in at the very end."]', '"Saag is a staple of Punjabi cuisine in North India, traditionally made from mustard greens and cooked slowly in earthen pots. This version adapts the dish for modern, fast-paced kitchens using broccoli to replicate the traditional texture while maintaining the signature spiced butter flavor profile known as ''tadka''."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('e5d93476-53f3-467a-9c4e-f5f525b6592e', 'Brown Butter Chocolate Chip Cookie Cake', 'A dense, chewy oversized cookie with deep caramel notes from browned butter. The extra egg yolk ensures a fudgy, tender crumb, while the crisp golden edges provide the perfect textural contrast to the soft center.', 'Dessert', 'American', 'Intermediate', '[{"group_name": "Wet Ingredients", "items": [{"name": "unsalted butter", "quantity": 170, "unit": "g", "preparation": "cold or room temp", "notes": "Will be browned", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "dark brown sugar", "quantity": 200, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated white sugar", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "large egg", "quantity": 1, "unit": null, "preparation": "room temperature", "notes": "approx. 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "egg yolk", "quantity": 1, "unit": null, "preparation": "room temperature", "notes": "approx. 18g", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dry Ingredients & Mix-ins", "items": [{"name": "all-purpose flour", "quantity": 215, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 8, "unit": "g", "preparation": null, "notes": "Adds tenderness", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "semisweet chocolate chips", "quantity": 170, "unit": "g", "preparation": null, "notes": "Reserve a handful for topping", "substitutions": ["bittersweet chocolate chunks", "milk chocolate chips"], "ingredient_id": "d5e5830a-bf2e-4bb2-b6b2-81be34a8fba1", "nutrition_source": "Aggregated Public Data"}, {"name": "flaky sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "Optional, for finishing", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 175\u00b0C (350\u00b0F). Grease a 9-inch round cake pan lightly with butter or non-stick spray.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Place the butter in a light-colored saucepan over medium heat. Cook, swirling the pan occasionally, until the butter foams, then quiets down, and brown specks form at the bottom with a nutty aroma (about 5-8 minutes).", "structured": {"action": "HEAT", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Golden brown specks on bottom", "tactile": "Nutty aroma"}}, "tips": ["Use a light-colored pan to easily see the color change so you don''t burn the butter."]}, {"step_number": 3, "phase": "prep", "text": "Pour the browned butter (including all the toasted brown bits) into a large heatproof mixing bowl. Let it cool for 10 minutes until warm but not hot.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Whisk the brown sugar and granulated sugar into the cooled butter until combined. The mixture may look slightly gritty, which is normal.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Add the whole egg, egg yolk, and vanilla extract. Whisk vigorously for about 1 minute until the mixture becomes smooth, glossy, and slightly thickened.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Glossy and pale", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Add the flour, cornstarch, baking soda, and fine sea salt. Switch to a spatula and mix just until no flour streaks remain.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not overmix at this stage, or the cake will be tough."]}, {"step_number": 7, "phase": "prep", "text": "Fold in the chocolate chips, reserving a small handful to press into the top later.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Transfer the dough to the prepared pan. Press it down into an even layer using your spatula or fingertips. Press the reserved chocolate chips into the top surface.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Bake for 20-25 minutes. The edges should be golden brown and set, while the center should still look slightly soft and underbaked. Do not overbake.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT25M", "doneness_cues": {"visual": "Golden edges, soft center", "tactile": null}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Remove from the oven and sprinkle with flaky sea salt if desired. Place the pan on a wire rack and let cool completely in the pan before slicing. The center will firm up as it cools.", "structured": {"action": "COOL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT50M", "total_time": "PT1H15M", "overnight_required": false, "yields": "1 9-inch cake", "yield_count": 10, "serving_size_g": 90}', '{"flags": ["Vegetarian", "Nut-Free"], "not_suitable_for": ["Vegans", "Gluten Intolerant"]}', '{"per_serving": {"calories": 402.18, "protein_g": 4.15, "carbohydrates_g": 53.13, "fat_g": 20.15, "saturated_fat_g": 12.5, "trans_fat_g": null, "monounsaturated_fat_g": 4.39, "polyunsaturated_fat_g": 0.77, "fiber_g": 1.67, "sugar_g": 33.24, "sodium_mg": 281.02, "cholesterol_mg": 74.59, "potassium_mg": 137.28, "calcium_mg": 29.3, "iron_mg": 0.84, "magnesium_mg": 12.43, "phosphorus_mg": 123.6, "zinc_mg": 0.28, "vitamin_a_mcg": 131.14, "vitamin_c_mg": null, "vitamin_d_mcg": 0.2, "vitamin_e_mg": 0.51, "vitamin_k_mcg": 1.28, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": 0.11, "thiamin_mg": 0.03, "riboflavin_mg": 0.05, "niacin_mg": 0.31, "folate_mcg": 11.28, "water_g": 10.93, "alcohol_g": 0.34, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to prevent drying out.", "duration": "P5D"}, "freezer": {"notes": "Wrap individual slices tightly in plastic wrap and foil.", "duration": "P2M"}, "reheating": "Microwave for 10-15 seconds to restore warmth and chewiness.", "does_not_keep": false}', '[{"name": "Light-colored saucepan", "required": true, "alternative": "Stainless steel skillet"}, {"name": "9-inch round cake pan", "required": true, "alternative": "9-inch cast iron skillet or pie dish"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Silicone spatula", "required": true, "alternative": null}]', '[{"symptom": "Cookie cake is dry or hard", "likely_cause": "Overbaking", "prevention": "Pull the cake from the oven when the center still looks slightly raw; carryover heat finishes the cooking.", "fix": "Serve warmed with ice cream to mask the dryness."}, {"symptom": "Butter burned instead of browned", "likely_cause": "Heat was too high or pan wasn''t watched", "prevention": "Use medium heat and swirl constantly once foaming starts.", "fix": "Cannot be fixed. Discard and start over to avoid acrid taste."}]', '["Browning the butter evaporates water, meaning you lose volume. The recipe accounts for this, but don''t skip scraping the pan\u2014the brown bits are pure flavor.", "The extra egg yolk adds fat and emulsifiers, creating a richer, fudgier texture closer to a brownie than a standard crisp cookie.", "Cornstarch is the secret weapon here; it softens the harsh proteins in the flour to keep the cookie cake tender even if slightly overbaked.", "For a birthday treat, pipe buttercream frosting around the rim after the cake has completely cooled."]', '"The chocolate chip cookie, invented by Ruth Wakefield in the 1930s, is a quintessential American dessert. The ''cookie cake'' variation emerged in American shopping malls in the 1970s and 80s as a popular alternative to traditional birthday cakes, celebrating the country''s love for soft, gooey textures over airy sponges."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('e65e6b3e-04d3-40f6-b967-3ad1a2a077ce', 'Rustic Ribollita (Tuscan Bread Soup)', 'A robust and comforting Tuscan classic where day-old bread melts into a savory broth loaded with creamy cannellini beans, cavolo nero, and aromatic vegetables. The bread acts as a thickener, creating a silky, spoon-standing texture that transforms humble leftovers into a gastronomic centerpiece.', 'Soup', 'Italian', 'Intermediate', '[{"group_name": "Soffritto & Aromatics", "items": [{"name": "extra virgin olive oil", "quantity": 80, "unit": "ml", "preparation": "plus extra for serving", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx 300g total", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrots", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx 150g total", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "celery stalks", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx 120g total", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "minced", "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": null, "notes": "sprigs", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Soup Base", "items": [{"name": "cannellini beans", "quantity": 480, "unit": "g", "preparation": "cooked/canned", "notes": "drained and rinsed weight (approx 2 cans)", "substitutions": [], "ingredient_id": "338d5b1f-5e90-4e7f-b286-e827b78558e9", "nutrition_source": "Aggregated Public Data"}, {"name": "whole peeled tomatoes", "quantity": 400, "unit": "g", "preparation": "canned", "notes": "crushed by hand", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "cavolo nero (lacinato kale)", "quantity": 300, "unit": "g", "preparation": "tough stems removed, leaves roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "bb6a90eb-f157-455a-b438-d2333c784c60", "nutrition_source": "USDA FoodData Central"}, {"name": "savoy cabbage", "quantity": 250, "unit": "g", "preparation": "shredded", "notes": null, "substitutions": [], "ingredient_id": "dff437b6-b727-4312-86be-82ff42b14644", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable stock", "quantity": 1500, "unit": "ml", "preparation": "hot", "notes": null, "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Bread & Finish", "items": [{"name": "stale country bread", "quantity": 350, "unit": "g", "preparation": "torn into large chunks", "notes": "sourdough or rustic Italian loaf preferred", "substitutions": [], "ingredient_id": "dc2725fb-42eb-4769-a033-2297b90bcbf7", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Heat the olive oil in a Dutch oven over medium heat. Add the diced onion, carrot, and celery with a pinch of salt.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": "PT10M", "doneness_cues": {"visual": "Vegetables are softened and translucent but not browned", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the minced garlic and thyme sprigs. Stir constantly for about 1-2 minutes until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Garlic is aromatic and pale gold", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the hand-crushed tomatoes and their juices along with the cannellini beans. Simmer for 5 minutes.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Remove the pot briefly from heat or lower heat significantly. Use a potato masher to crush about half of the beans directly in the pot. This releases starch to thicken the soup.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Mixture becomes thicker and pasty"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour in the hot vegetable stock. Stir in the chopped cavolo nero and savoy cabbage. Bring to a boil, then reduce heat to low.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Cover and simmer gently for 30 minutes until the greens are very tender.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Add the stale bread chunks. Submerge them into the liquid. Cook for another 5-10 minutes, stirring occasionally to help the bread break down slightly.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Bread is swollen and soft, soup is thick", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from heat. Discard the thyme sprigs. Let the soup rest for at least 15 minutes before serving to allow flavors to meld.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Serve warm, drizzled generously with high-quality olive oil and plenty of black pepper.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT50M", "total_time": "PT1H35M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 400}', '{"flags": ["Vegetarian", "Vegan", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 523.52, "protein_g": 23.63, "carbohydrates_g": 78.2, "fat_g": 16.18, "saturated_fat_g": 2.21, "trans_fat_g": null, "monounsaturated_fat_g": 9.77, "polyunsaturated_fat_g": 1.6, "fiber_g": 16.49, "sugar_g": 12.64, "sodium_mg": 1866.68, "cholesterol_mg": null, "potassium_mg": 1459.91, "calcium_mg": 301.31, "iron_mg": 6.84, "magnesium_mg": 145.56, "phosphorus_mg": 274.25, "zinc_mg": 2.74, "vitamin_a_mcg": 405.71, "vitamin_c_mg": 51.55, "vitamin_d_mcg": null, "vitamin_e_mg": 2.51, "vitamin_k_mcg": 213.37, "vitamin_b6_mg": 0.27, "vitamin_b12_mcg": null, "thiamin_mg": 0.11, "riboflavin_mg": 0.12, "niacin_mg": 0.88, "folate_mcg": 63.84, "water_g": 171.41, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves significantly after 24 hours. The soup will thicken; thin with water or stock when reheating.", "duration": "P4D"}, "freezer": {"notes": "Bread texture may become slightly mushier upon thawing, but flavor remains excellent.", "duration": "P3M"}, "reheating": "Gently reheat on the stove over low heat. If too thick, add a splash of water.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed pot", "required": true, "alternative": "Large stockpot"}, {"name": "Potato masher", "required": false, "alternative": "Back of a wooden spoon or fork"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Soup has turned into a solid porridge", "likely_cause": "The bread was very dry and absorbed more liquid than expected", "prevention": "Add bread gradually or increase initial stock quantity", "fix": "Stir in extra hot vegetable stock or water 50ml at a time until desired consistency is reached"}]', '["The name ''Ribollita'' means ''reboiled.'' This soup is traditionally made one day, chilled, and reheated the next. The flavor complexity doubles after an overnight rest.", "Do not use sliced sandwich bread. You need a dense, rustic loaf (ideally sourdough or ciabatta) with a thick crust to maintain some texture without dissolving into glue.", "If you have a parmesan rind (and are not strictly vegan), add it during step 5 for a massive umami boost. Remove before serving.", "The quality of the finishing olive oil makes or breaks this dish. Use your best peppery, grassy extra virgin olive oil for the final drizzle."]', '"Originating from the peasant kitchens of Tuscany, Ribollita was created to prevent food waste by utilizing leftover minestrone and stale bread. In the Middle Ages, servants would gather bread-trenchers (bread used as plates) from noble banquets and boil them with vegetables for their own dinner."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('e9036a7f-3b0a-4589-933f-727f04375fd3', 'Lamb Pot-au-Feu with Cockles and Roasted Rump', 'A refined surf-and-turf interpretation of the French farmhouse classic. Meltingly tender braised lamb shoulder and root vegetables simmer in an aromatic broth, finished with the briny sweetness of fresh cockles and topped with slices of perfectly roasted, pink lamb rump.', 'Dinner', 'French', 'Advanced', '[{"group_name": "Stew Base (Shoulder)", "items": [{"name": "lamb shoulder", "quantity": 600, "unit": "g", "preparation": "cut into 3cm cubes", "notes": "boneless weight", "substitutions": [], "ingredient_id": "88f516f5-f8d5-4245-8d3a-50376dacfdc2", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "onions", "quantity": 2, "unit": null, "preparation": "quartered", "notes": "approx. 300g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "smashed", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 150, "unit": "ml", "preparation": null, "notes": "Sauvignon Blanc or Chardonnay", "substitutions": [], "ingredient_id": "5e1efe68-ff2d-432c-9239-ff83f37c5e07", "nutrition_source": "Aggregated Public Data"}, {"name": "lamb stock", "quantity": 800, "unit": "ml", "preparation": null, "notes": "or high-quality chicken stock", "substitutions": ["chicken stock", "beef stock"], "ingredient_id": "f6084980-7930-4c18-ba4b-87ea32c37572", "nutrition_source": "Aggregated Public Data"}, {"name": "bouquet garni", "quantity": 1, "unit": null, "preparation": null, "notes": "bundle of thyme, parsley stalks, bay leaf", "substitutions": [], "ingredient_id": "35bd6873-5403-4b94-81a3-3995092bd1cc", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Vegetables & Cockles", "items": [{"name": "baby carrots", "quantity": 300, "unit": "g", "preparation": "peeled and trimmed", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "baby turnips", "quantity": 200, "unit": "g", "preparation": "peeled and halved", "notes": null, "substitutions": [], "ingredient_id": "b7a26052-3b0b-4df2-b816-9a3dd3c2fb32", "nutrition_source": "USDA FoodData Central"}, {"name": "leeks", "quantity": 2, "unit": null, "preparation": "white parts only, washed and cut into 3cm lengths", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "c689e786-49ea-4b98-9526-3b7bb15a8edc", "nutrition_source": "USDA FoodData Central"}, {"name": "waxy potatoes", "quantity": 300, "unit": "g", "preparation": "peeled and quartered", "notes": "Charlotte or Yukon Gold", "substitutions": [], "ingredient_id": "4920385c-ae78-4023-8318-c5dfe051fecc", "nutrition_source": "USDA FoodData Central"}, {"name": "live cockles", "quantity": 500, "unit": "g", "preparation": "purged and scrubbed", "notes": null, "substitutions": ["vongole", "littleneck clams"], "ingredient_id": "561ebef2-6735-4dfe-a5e4-de3ffaaebcfd", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Roasted Lamb Rump", "items": [{"name": "lamb rump", "quantity": 400, "unit": "g", "preparation": "room temperature", "notes": "usually 2 whole rumps", "substitutions": [], "ingredient_id": "e09d98c6-36ff-4b5f-81f5-a07f54dfaa70", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "thyme sprigs", "quantity": 4, "unit": null, "preparation": null, "notes": "approx. 2g", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt flakes", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 5g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place cockles in a bowl of cold salted water for 30 minutes to purge sand. Discard any with broken shells or those that do not close when tapped.", "structured": {"action": "BRINE", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Season the diced lamb shoulder with salt and pepper. In a large Dutch oven, heat olive oil over medium-high heat and sear the lamb in batches until browned on all sides. Remove lamb and set aside.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": {"visual": "Golden brown crust", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In the same pot, reduce heat to medium. Add quartered onions and smashed garlic. Saut\u00e9 for 3-4 minutes until softened but not browned. Deglaze with white wine, scraping up any fond from the bottom.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Return the seared shoulder to the pot. Add the bouquet garni and cover with lamb stock. Bring to a boil, skim off any foam, then reduce heat to low. Cover and simmer gently for 1 hour.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the potatoes, carrots, and turnips to the pot. Continue to simmer for another 20 minutes. Then add the leeks and simmer for a final 10-15 minutes until all vegetables are tender.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT35M", "doneness_cues": {"visual": null, "tactile": "Vegetables piercable with knife"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "While vegetables finish, preheat oven to 200\u00b0C (400\u00b0F). Score the fat cap of the lamb rumps. Season generously. In a hot skillet, sear the rumps fat-side down to render, then sear all sides. Add butter and thyme, baste briefly.", "structured": {"action": "SEAR", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Transfer the skillet to the oven (or move rumps to a roasting tray). Roast for 8-12 minutes until internal temperature reaches 52\u00b0C (125\u00b0F) for medium-rare. Remove and rest in a warm place for 10 minutes.", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT10M", "doneness_cues": {"visual": null, "tactile": "Internal temp 52\u00b0C"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Just before serving, increase the heat under the stew. Add the drained cockles to the pot. Cover tightly and steam for 3-4 minutes until shells open. Discard any unopened cockles.", "structured": {"action": "STEAM", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Shells wide open", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Slice the rested lamb rump against the grain. Ladle the stew (shoulder, vegetables, cockles, and broth) into shallow bowls. Fan slices of roasted rump on top. Garnish with fresh herbs if desired.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "PT1H40M", "total_time": "PT2H30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 550}', '{"flags": ["Gluten-Free", "Pescatarian", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": ["Shellfish allergy sufferers"]}', '{"per_serving": {"calories": 1710.05, "protein_g": 174.51, "carbohydrates_g": 44.94, "fat_g": 102.88, "saturated_fat_g": 30.53, "trans_fat_g": null, "monounsaturated_fat_g": 7.25, "polyunsaturated_fat_g": 1.24, "fiber_g": 7.55, "sugar_g": 12.82, "sodium_mg": 3124.21, "cholesterol_mg": 16.13, "potassium_mg": 1248.75, "calcium_mg": 188.49, "iron_mg": 29.87, "magnesium_mg": 87.29, "phosphorus_mg": 387.19, "zinc_mg": 8.1, "vitamin_a_mcg": 709.93, "vitamin_c_mg": 33.53, "vitamin_d_mcg": null, "vitamin_e_mg": 2.14, "vitamin_k_mcg": 34.58, "vitamin_b6_mg": 0.52, "vitamin_b12_mcg": 0.01, "thiamin_mg": 0.2, "riboflavin_mg": 0.38, "niacin_mg": 6.01, "folate_mcg": 74.08, "water_g": 373.16, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store the roasted lamb rump and stew separately if possible. Reheat gently to avoid overcooking the cockles.", "duration": "P2D"}, "freezer": {"notes": "Stew base freezes well; do not freeze the cockles or roasted rump.", "duration": "P1M"}, "reheating": "Gently warm the stew on the stove; serve leftover rump cold or flash-sear to warm.", "does_not_keep": false}', '[{"name": "Large Dutch oven or heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Heavy skillet (cast iron or stainless steel)", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Meat thermometer", "required": true, "alternative": null}, {"name": "Slotted spoon", "required": true, "alternative": null}]', '[{"symptom": "Cockles are gritty", "likely_cause": "Insufficient purging time", "prevention": "Purge in salted water (30g salt per liter) for at least 30 mins, changing water once.", "fix": "Remove meat from shells, rinse meat in clean broth, strain the main stew broth through muslin cloth."}, {"symptom": "Lamb shoulder is tough", "likely_cause": "Under-cooked or simmered too violently", "prevention": "Maintain a very gentle simmer and ensure enough cooking time before adding vegetables.", "fix": "Remove vegetables and keep warm; continue simmering meat until tender."}]', '["The brine from the cockles will season the broth significantly. Under-season the stew base slightly in the beginning to account for this salty finish.", "For the lamb rump, rendering the fat cap properly is crucial. Start in a cold pan if necessary to render fat without burning the meat, then crank the heat to sear.", "This dish relies on timing. If the stew is ready before the rump rests, simply turn off the heat on the stew (before adding cockles). Reheat to a boil, then add cockles right before plating.", "Serve with crusty sourdough bread and rouille or aioli for a true nod to French coastal stews."]', '"This recipe bridges two French traditions: the rustic ''Pot-au-Feu'' (usually beef and root vegetables) and the coastal affinity for mixing meat and shellfish. The addition of cockles introduces an iodine mineral note that cuts through the richness of the lamb fat, a technique often seen in modern bistro cooking in Brittany and Normandy."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('eb0146d1-436a-4551-94d9-9e8146b3c026', 'Spicy Harissa Spatchcock Chicken with Caramelized Squash', 'A vibrant, texturally contrasting centerpiece featuring a flattened, juicy whole chicken with shattering-crisp skin, roasted alongside sweet, tender butternut squash. Infused with North African spices for a slow-building heat.', 'Dinner', 'Mediterranean', 'Intermediate', '[{"group_name": "Chicken", "items": [{"name": "whole chicken", "quantity": 1800, "unit": "g", "preparation": "room temperature", "notes": "Backbone removed (reserved)", "substitutions": [], "ingredient_id": "69a078cb-b5ac-4d3d-85f0-39e2a05f3b9e", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Spice Rub", "items": [{"name": "smoked paprika", "quantity": 8, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "ground coriander", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "cayenne pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": "Adjust for heat level", "substitutions": [], "ingredient_id": "58780fb1-30a8-45d7-9983-b7a6bc626333", "nutrition_source": "Aggregated Public Data"}, {"name": "kosher salt", "quantity": 12, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 4, "unit": "g", "preparation": null, "notes": "Aluminum-free; promotes browning", "substitutions": [], "ingredient_id": "5c0b5fc8-b210-4e39-b3a6-479541ac45d2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables", "items": [{"name": "butternut squash", "quantity": 800, "unit": "g", "preparation": "peeled and cubed (2cm)", "notes": null, "substitutions": [], "ingredient_id": "7f8919a5-2de5-47ce-91b2-d2a999ea11f7", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Optional Crackling & Finish", "items": [{"name": "chicken skin", "quantity": null, "unit": null, "preparation": "cut into strips", "notes": "Harvested from reserved backbone/neck", "substitutions": [], "ingredient_id": "ea657c3c-6604-4cbf-b1a1-898b0aee7b9a", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "wedged", "notes": null, "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the chicken breast-side down. Using kitchen shears, cut along both sides of the backbone to remove it entirely. Flip the chicken over and press firmly on the breastbone until it cracks and lies flat (spatchcocking).", "structured": {"action": "CUT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Save the backbone for stock.", "If making the optional crackling, peel the skin off the backbone and neck area now and set aside."]}, {"step_number": 2, "phase": "prep", "text": "In a small bowl, whisk together smoked paprika, cumin, coriander, cayenne, kosher salt, and baking powder. Pat the chicken extremely dry with paper towels, rub with olive oil, then coat evenly with the spice mixture.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["The baking powder changes the pH of the skin, allowing it to dehydrate and crisp faster."]}, {"step_number": 3, "phase": "cook", "text": "Preheat oven to 220\u00b0C (425\u00b0F). Toss the cubed butternut squash with olive oil and salt. spread evenly on a rimmed baking sheet. Place a wire rack directly over the squash, then place the chicken on the rack, skin-side up.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Roast for 40-50 minutes. The high heat will crisp the skin and roast the squash simultaneously. The chicken juices will drip down, seasoning the squash.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT45M", "doneness_cues": {"visual": "Skin is deep golden brown and crispy", "tactile": "Internal temperature of thickest part of thigh reaches 74\u00b0C"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "OPTIONAL: While chicken roasts, place the reserved skin scraps in a cold, small frying pan. Turn heat to medium-low. Render the fat slowly until the skin scraps are golden brown and crunchy (gribenes). Drain on paper towels and season with salt.", "structured": {"action": "FRY", "temperature": null, "duration": null, "doneness_cues": {"visual": "Golden brown and shrunken", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove chicken from the oven when the breast reads 70\u00b0C (158\u00b0F) and thigh reads 74\u00b0C (165\u00b0F). Let rest for 10 minutes before carving. Garnish squash and chicken with fresh cilantro, lemon wedges, and the optional crispy skin crumble.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT45M", "total_time": "PT1H10M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Gluten-Free", "Dairy-Free", "Paleo", "Whole30", "Nut-Free"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 832.57, "protein_g": 94.36, "carbohydrates_g": 28.3, "fat_g": 37.82, "saturated_fat_g": 7.14, "trans_fat_g": null, "monounsaturated_fat_g": 17.31, "polyunsaturated_fat_g": 6.7, "fiber_g": 6.05, "sugar_g": 5.24, "sodium_mg": 1953.54, "cholesterol_mg": 360, "potassium_mg": 1940.82, "calcium_mg": 221.74, "iron_mg": 7.72, "magnesium_mg": 185.79, "phosphorus_mg": 891.43, "zinc_mg": 9.59, "vitamin_a_mcg": 1314.52, "vitamin_c_mg": 68.66, "vitamin_d_mcg": null, "vitamin_e_mg": 6.63, "vitamin_k_mcg": 23.69, "vitamin_b6_mg": 1.85, "vitamin_b12_mcg": 1.62, "thiamin_mg": 0.59, "riboflavin_mg": 0.89, "niacin_mg": 30.82, "folate_mcg": 102.42, "water_g": 534.17, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Skin will lose crispness; reheat in oven or air fryer.", "duration": "P3D"}, "freezer": {"notes": "Remove meat from bone before freezing. Squash texture may degrade.", "duration": "P3M"}, "reheating": "Reheat in a 180\u00b0C/350\u00b0F oven for 10-15 minutes to recrisp skin.", "does_not_keep": false}', '[{"name": "Kitchen shears", "required": true, "alternative": "Heavy chef''s knife"}, {"name": "Rimmed baking sheet", "required": true, "alternative": null}, {"name": "Wire rack", "required": true, "alternative": "Bed of sliced onions"}, {"name": "Small frying pan", "required": false, "alternative": "None (for optional crackling)"}, {"name": "Meat thermometer", "required": true, "alternative": null}]', '[{"symptom": "Chicken skin is soggy", "likely_cause": "Surface moisture on the bird before roasting", "prevention": "Pat dry thoroughly; air-dry in fridge uncovered for 12 hours if possible", "fix": "Broil for 1-2 minutes, watching constantly to prevent burning"}, {"symptom": "Squash is burning before chicken is done", "likely_cause": "Squash cubes cut too small or oven has hot spots", "prevention": "Cut squash into larger 2.5cm chunks", "fix": "Remove the baking sheet, transfer chicken directly to oven rack (place foil below to catch drips), and remove squash"}]', '["Spatchcocking reduces cooking time by nearly 40% compared to a trussed bird and ensures the breast and thighs cook evenly.", "For the ultimate skin, salt the bird and leave it uncovered in the refrigerator for 24 hours (dry brining). Skip the salt in the rub if you do this.", "The rendered fat from the chicken (schmaltz) dripping onto the squash creates a flavor depth that oil alone cannot achieve.", "If you want extra heat, mix a tablespoon of harissa paste with the olive oil before rubbing the chicken."]', '"While spatchcocking (or butterflying) dates back to 18th-century Ireland, this recipe borrows flavors from the Maghreb region of North Africa. The combination of earthy cumin, bright coriander, and heat creates a warming profile typical of Moroccan or Tunisian roasts."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('edacf129-6dec-4db1-bea5-c83adc2b648a', 'Cerveza-Braised Pork Carnitas', 'Succulent, fall-apart pork shoulder slow-braised in Mexican lager and bright citrus until tender. The meat is shredded and finished under the broiler to create caramelized, crispy edges while maintaining a juicy interior—the ultimate texture for street-style tacos.', 'Dinner', 'Mexican', 'Intermediate', '[{"group_name": "Pork", "items": [{"name": "boneless pork shoulder", "quantity": 2000, "unit": "g", "preparation": "cut into 5cm chunks", "notes": "Boston butt cut preferred for fat content", "substitutions": [], "ingredient_id": "2435c811-13bb-4d94-b94c-ac0381ef4b0f", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": "liquid", "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Spice Blend", "items": [{"name": "kosher salt", "quantity": 20, "unit": "g", "preparation": null, "notes": "adjust to taste if using table salt", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 5, "unit": "g", "preparation": null, "notes": "Mexican oregano preferred", "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "chili powder", "quantity": 10, "unit": "g", "preparation": null, "notes": "mild blend, usually ancho based", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 5, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Braising Liquid & Aromatics", "items": [{"name": "mexican lager beer", "quantity": 355, "unit": "ml", "preparation": null, "notes": "Modelo Especial or similar; room temperature", "substitutions": [], "ingredient_id": "3c4b4d80-5ee5-4488-b81b-fdc88c3e8227", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh orange juice", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a15da11d-f8dd-46e3-9ac5-725a7912f1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "white onion", "quantity": 1, "unit": null, "preparation": "roughly chopped", "notes": "approx 200g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 6, "unit": null, "preparation": "crushed", "notes": "approx 30g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "bay leaves", "quantity": 2, "unit": null, "preparation": null, "notes": "dried", "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 150\u00b0C (300\u00b0F). Combine the salt, cumin, oregano, chili powder, and black pepper in a small bowl. Pat the pork chunks dry and massage the spice blend thoroughly into the meat.", "structured": {"action": "SEASON", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the vegetable oil in a large Dutch oven over medium-high heat. Sear the pork chunks in batches to avoid overcrowding, turning them until browned on all sides. Remove browned pork and set aside.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": {"visual": "Deep golden brown crust", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the chopped onion and crushed garlic to the pot. Saut\u00e9 for 2-3 minutes until fragrant and slightly softened, scraping up the browned bits (fond) from the bottom of the pot.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the beer and orange juice. Return the pork and any accumulated juices to the pot. Add the bay leaves. Bring the liquid to a gentle simmer.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Cover the Dutch oven with a heavy lid and transfer to the preheated oven. Braise for 3 to 3.5 hours, or until the pork is extremely tender and shreds easily with a fork. Internal temperature should exceed 90\u00b0C (195\u00b0F).", "structured": {"action": "BRAISE", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT3H30M", "doneness_cues": {"visual": null, "tactile": "Meat offers zero resistance to a fork"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove the pot from the oven. Discard the bay leaves. Transfer the pork to a large baking sheet using a slotted spoon. Shred the meat into bite-sized pieces using two forks. Ladle about 100ml of the braising liquid over the shredded meat.", "structured": {"action": "SHRED", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Place the baking sheet under a broiler (grill) set to high for 5-8 minutes. Watch closely to prevent burning; you want the edges to become crisp and caramelized while the interior stays moist.", "structured": {"action": "BROIL", "temperature": null, "duration": null, "doneness_cues": {"visual": "Charred tips and crispy edges", "tactile": null}}, "tips": ["This step is crucial for authentic carnitas texture."]}]', '{"active_time": "PT45M", "passive_time": "PT3H30M", "total_time": "PT4H15M", "overnight_required": false, "yields": "8 servings", "yield_count": 8, "serving_size_g": 220}', '{"flags": ["Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Gluten-Free diets (unless GF beer is used)"]}', '{"per_serving": {"calories": 819.79, "protein_g": 68.6, "carbohydrates_g": 16.63, "fat_g": 73.07, "saturated_fat_g": 4.37, "trans_fat_g": null, "monounsaturated_fat_g": 4.72, "polyunsaturated_fat_g": 1.1, "fiber_g": 1.95, "sugar_g": 2.51, "sodium_mg": 1653.62, "cholesterol_mg": 27.51, "potassium_mg": 1763.61, "calcium_mg": 56.38, "iron_mg": 5.69, "magnesium_mg": 22.89, "phosphorus_mg": 1034.98, "zinc_mg": 14.72, "vitamin_a_mcg": 23.22, "vitamin_c_mg": 10.97, "vitamin_d_mcg": null, "vitamin_e_mg": 0.65, "vitamin_k_mcg": 7.19, "vitamin_b6_mg": 0.22, "vitamin_b12_mcg": 0.52, "thiamin_mg": 0.16, "riboflavin_mg": 0.11, "niacin_mg": 1.68, "folate_mcg": 13.64, "water_g": 63.26, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container with some of the braising liquid to keep moist.", "duration": "P4D"}, "freezer": {"notes": "Freeze flat in vacuum-sealed bags for best results.", "duration": "P3M"}, "reheating": "Pan-fry with a splash of water or reserved fat until crispy and hot.", "does_not_keep": false}', '[{"name": "Dutch Oven (5-6L)", "required": true, "alternative": "Heavy-bottomed pot and transfer to roasting pan"}, {"name": "Chef''s Knife", "required": true, "alternative": null}, {"name": "Cutting Board", "required": true, "alternative": null}, {"name": "Baking Sheet", "required": true, "alternative": "Cast iron skillet"}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Meat is tough and not shredding", "likely_cause": "The connective tissue hasn''t had enough time to break down", "prevention": "Ensure the oven temperature is low and consistent; do not rush the cooking time", "fix": "Return to the oven covered, add a splash more liquid if dry, and cook for another 30-45 minutes"}]', '["Do not trim all the fat off the pork shoulder before cooking; the fat renders out and keeps the meat moist during the long braise.", "For the beer, choose a Mexican lager or pilsner for a lighter taste, or a Negra Modelo for a deeper, maltier flavor. Avoid IPAs as they become bitter when reduced.", "The remaining braising liquid is liquid gold. Strain it and keep it to pour over leftovers or use as a base for a soup.", "Authentic Carnitas are often cooked in lard (confit style), but this braise-then-broil method replicates that texture with less mess for home cooks."]', '"Carnitas, meaning ''little meats'', originate from the state of Michoac\u00e1n, Mexico. Traditionally cooked in copper cauldrons with lard, this dish is a staple of Mexican street food, celebrated for the interplay between the juicy interior and the crispy, caramelized exterior."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('ee3c41b1-dd73-4cb1-b9c5-70e17e774b46', 'Rainbow Garden Cheese Frittata', 'A fluffy, golden egg pie speckled with colorful, mild vegetables and melted cheddar. The texture is soft and creamy, not rubbery, making it an excellent vehicle for vegetables that kids will enjoy eating.', 'Breakfast', 'Italian', 'Easy', '[{"group_name": "Base", "items": [{"name": "large eggs", "quantity": 8, "unit": null, "preparation": null, "notes": "approx. 400-450g total weight", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "whole milk", "quantity": 60, "unit": "ml", "preparation": null, "notes": "adds creaminess", "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx. 1/2 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, optional for picky eaters", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables & Cheese", "items": [{"name": "mild cheddar cheese", "quantity": 100, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "6cc08e49-8e1b-4065-be23-f57782560a8b", "nutrition_source": "Aggregated Public Data"}, {"name": "red bell pepper", "quantity": 80, "unit": "g", "preparation": "diced small", "notes": null, "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "USDA FoodData Central"}, {"name": "zucchini", "quantity": 80, "unit": "g", "preparation": "diced small", "notes": null, "substitutions": [], "ingredient_id": "c34b610f-8869-4d77-a9b3-e01849d703b5", "nutrition_source": "USDA FoodData Central"}, {"name": "frozen peas", "quantity": 50, "unit": "g", "preparation": "thawed", "notes": null, "substitutions": [], "ingredient_id": "fa661e9d-c4df-42f0-99c8-ca41610251a9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven broiler (grill setting) to high. If you do not have a broiler, preheat the oven to 200\u00b0C (400\u00b0F).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, crack the eggs and add the milk, salt, and pepper. Whisk vigorously until the yolks and whites are fully combined and the mixture is slightly frothy. (Kid Step: Great for kids to practice whisking).", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat the olive oil in the oven-safe skillet over medium heat. Add the diced red pepper and zucchini. Saut\u00e9 for 4-5 minutes until the vegetables are soft and any excess moisture has evaporated.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT5M", "doneness_cues": null}, "tips": ["Cooking the vegetables first prevents a watery frittata."]}, {"step_number": 4, "phase": "cook", "text": "Add the thawed peas to the skillet and stir briefly. Pour the egg mixture over the vegetables. Using a spatula, gently lift the edges of the setting egg to allow uncooked egg to flow underneath.", "structured": {"action": "POUR", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Cook undisturbed on the stove-top over medium-low heat for about 4-5 minutes, or until the edges are set but the center is still slightly runny.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Edges are firm/opaque, center is liquid", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Sprinkle the grated cheddar cheese evenly over the top. (Kid Step: Kids can sprinkle the cheese carefully).", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Transfer the skillet to the oven. Broil (or bake) for 3-5 minutes until the eggs are fully puffed, set in the center, and the cheese is melted and bubbling.", "structured": {"action": "BROIL", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Puffed, golden cheese, no liquid egg when shaken", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from the oven using oven mitts (handle will be extremely hot). Let the frittata rest for 5 minutes before slicing into wedges.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT15M", "total_time": "PT30M", "overnight_required": false, "yields": "4-6 servings", "yield_count": 6, "serving_size_g": 140}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Low-Carb", "Keto"], "not_suitable_for": ["Vegans"]}', '{"per_serving": {"calories": 204.27, "protein_g": 13.56, "carbohydrates_g": 3.78, "fat_g": 14.79, "saturated_fat_g": 5.98, "trans_fat_g": 0.03, "monounsaturated_fat_g": 4.35, "polyunsaturated_fat_g": 1.61, "fiber_g": 0.87, "sugar_g": 2.11, "sodium_mg": 409.1, "cholesterol_mg": 249, "potassium_mg": 199.88, "calcium_mg": 174.49, "iron_mg": 1.53, "magnesium_mg": 20.33, "phosphorus_mg": 237.29, "zinc_mg": 1.66, "vitamin_a_mcg": 186.37, "vitamin_c_mg": 20.95, "vitamin_d_mcg": 1.46, "vitamin_e_mg": 1.3, "vitamin_k_mcg": 5.83, "vitamin_b6_mg": 0.19, "vitamin_b12_mcg": 0.64, "thiamin_mg": 0.07, "riboflavin_mg": 0.36, "niacin_mg": 0.39, "folate_mcg": 45.64, "water_g": 91.25, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container once fully cooled.", "duration": "P3D"}, "freezer": {"notes": "Texture may become slightly spongy upon thawing; reheat gently.", "duration": "P2M"}, "reheating": "Microwave slices for 30-45 seconds or warm in a toaster oven at 150\u00b0C (300\u00b0F) until heated through.", "does_not_keep": false}', '[{"name": "Oven-safe non-stick skillet (25cm/10in)", "required": true, "alternative": "Cast iron skillet"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": "Fork"}, {"name": "Silicon spatula", "required": true, "alternative": null}]', '[{"symptom": "Frittata is watery or weeps liquid", "likely_cause": "Vegetables were not cooked long enough to release their water before adding eggs", "prevention": "Ensure peppers and zucchini are saut\u00e9ed until they look dry before adding the egg mixture", "fix": "Drain excess liquid from the plate; texture will be fine"}, {"symptom": "Bottom is burnt but top is raw", "likely_cause": "Stove heat was too high during the initial stovetop cooking phase", "prevention": "Keep heat at medium-low; the goal is just to set the bottom, not brown it deeply", "fix": "Slice off the burnt bottom layer before serving"}]', '["To involve kids: Let them choose the vegetable colors (bell peppers come in red, yellow, orange) to increase buy-in.", "For extra fluffiness, do not overbeat the eggs, but ensure the white and yolk are completely homogenous before cooking.", "Safety alert: The handle of the skillet will remain hot for a long time after coming out of the oven. Always leave a potholder or towel draped over the handle as a visual warning.", "Leftovers make excellent cold lunchbox items for the next day."]', '"The frittata is an Italian egg-based dish similar to an omelet or crustless quiche, enriched with additional ingredients like meats, cheeses, or vegetables. Unlike a French omelet, which is folded, a frittata is cooked slowly and finished in the oven, making it a rustic, communal dish often served at room temperature in Italy."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('ee553308-12cb-481d-a6ca-5e1cfd69cb84', 'Macanese Grilled Prawns with Turmeric Sambal & Soy Beurre Blanc', 'Succulent tiger prawns butterflied and filled with a fragrant, golden paste of fresh turmeric, lemongrass, and shallots. Grilled over charcoal to impart smokiness and served with a velvety, umami-laden butter emulsion that pays homage to Macau''s Portuguese-Cantonese heritage.', 'Dinner', 'Macanese', 'Intermediate', '[{"group_name": "Prawns", "items": [{"name": "large tiger prawns", "quantity": 12, "unit": null, "preparation": "whole, shell-on", "notes": "approx 800g total weight", "substitutions": [], "ingredient_id": "2d8221bd-a2d1-4233-894f-cb6b0cf40234", "nutrition_source": "Aggregated Public Data"}, {"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "for brushing", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "fine sea salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Macanese Stuffing Paste", "items": [{"name": "shallots", "quantity": 3, "unit": null, "preparation": "peeled", "notes": "approx 60g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "peeled", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh turmeric", "quantity": 10, "unit": "g", "preparation": "peeled", "notes": "or 1 tsp ground turmeric", "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "lemongrass", "quantity": 1, "unit": null, "preparation": "white part only, chopped", "notes": "approx 15g", "substitutions": [], "ingredient_id": "6dde667b-d122-48d9-a70f-a4f820fc5bd5", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh red chili", "quantity": 2, "unit": null, "preparation": "deseeded", "notes": "approx 20g", "substitutions": [], "ingredient_id": "5080eb9a-d555-4558-94e5-d5700e96ff9b", "nutrition_source": "USDA FoodData Central"}, {"name": "shrimp paste", "quantity": 5, "unit": "g", "preparation": null, "notes": "belacan or balich\u00e3o", "substitutions": [], "ingredient_id": "02034d13-a948-4cfd-ba06-d78d03006e5e", "nutrition_source": "Aggregated Public Data"}, {"name": "coconut milk", "quantity": 30, "unit": "ml", "preparation": null, "notes": "thick cream from top of can", "substitutions": [], "ingredient_id": "c037ee7e-e3ed-4340-b8fb-d8ad284ba96e", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Soy Butter Sauce", "items": [{"name": "unsalted butter", "quantity": 100, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "tamari soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": "use gluten-free if required", "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "white pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "spring onions", "quantity": 2, "unit": null, "preparation": "finely sliced", "notes": "approx 20g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "lime wedges", "quantity": 4, "unit": null, "preparation": null, "notes": "for serving", "substitutions": [], "ingredient_id": "d3d2677e-fe02-4404-add0-29d73df7e921", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the aromatics. Combine shallots, garlic, turmeric, lemongrass, red chili, and shrimp paste in a food processor. Pulse until a fine, vibrant paste forms. Stir in the coconut milk to bind the mixture.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Prepare the prawns. Using kitchen shears, cut through the back shell from head to tail, leaving the head attached. Use a knife to slice deep into the back meat to butterfly it open (do not cut all the way through). Remove the dark vein. Rinse and pat dry thoroughly.", "structured": {"action": "BUTTERFLY", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "Spoon the spice paste generously into the cavity of each butterflied prawn. Press the filling down gently so it adheres to the meat. Brush the outer shells with neutral oil and season lightly with salt. Let rest at room temperature while preparing the grill.", "structured": {"action": "STUFF", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Preheat your grill to medium-high heat (approx 200\u00b0C/400\u00b0F). If using charcoal, ensure coals are glowing red with a light ash coating.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "While the grill heats, make the sauce. In a small saucepan over low heat, warm the soy sauce and lemon juice. Whisk in the cold cubed butter, one piece at a time, ensuring the mixture stays emulsified and creamy (do not let it boil). Season with white pepper. Remove from heat and keep in a warm spot.", "structured": {"action": "EMULSIFY", "temperature": {"celsius": 60, "fahrenheit": 140}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Grill the prawns. Place them shell-side down first to protect the meat. Grill for 3-4 minutes until the shell turns bright orange and the meat begins to turn opaque. Carefully flip onto the flesh side for just 1-2 minutes to char the stuffing and finish cooking. Internal temperature should reach 63\u00b0C/145\u00b0F.", "structured": {"action": "GRILL", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Shells bright orange, meat opaque white", "tactile": "Firm to the touch"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Transfer prawns to a serving platter. Drizzle generously with the warm soy butter sauce. Garnish with spring onions and serve immediately with lime wedges.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT20M", "total_time": "PT55M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 280}', '{"flags": ["Pescatarian", "Gluten-Free"], "not_suitable_for": ["Shellfish allergy"]}', '{"per_serving": {"calories": 513.57, "protein_g": 49.84, "carbohydrates_g": 11.39, "fat_g": 33.82, "saturated_fat_g": 15.35, "trans_fat_g": null, "monounsaturated_fat_g": 5.95, "polyunsaturated_fat_g": 0.82, "fiber_g": 1.78, "sugar_g": 2.64, "sodium_mg": 2231.66, "cholesterol_mg": 53.75, "potassium_mg": 204.11, "calcium_mg": 57.54, "iron_mg": 2.52, "magnesium_mg": 16.54, "phosphorus_mg": 43.28, "zinc_mg": 0.4, "vitamin_a_mcg": 183.5, "vitamin_c_mg": 19.68, "vitamin_d_mcg": null, "vitamin_e_mg": 0.76, "vitamin_k_mcg": 12.66, "vitamin_b6_mg": 0.1, "vitamin_b12_mcg": 0.04, "thiamin_mg": 0.03, "riboflavin_mg": 0.03, "niacin_mg": 0.2, "folate_mcg": 12.22, "water_g": 37.77, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store prawns and sauce separately. Reheat gently to avoid splitting the sauce.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; texture of prawns and stability of butter sauce will degrade.", "duration": null}, "reheating": "Gently warm prawns in a pan over low heat; whisk sauce over a warm water bath.", "does_not_keep": false}', '[{"name": "Food processor or mortar and pestle", "required": true, "alternative": null}, {"name": "Outdoor grill or grill pan", "required": true, "alternative": "Oven broiler"}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Sharp knife (Chef or Paring)", "required": true, "alternative": null}, {"name": "Kitchen shears", "required": true, "alternative": null}]', '[{"symptom": "Stuffing falls out during grilling", "likely_cause": "Paste was too wet or prawns were flipped too aggressively", "prevention": "Ensure coconut milk is thick; press stuffing firmly; flip gently", "fix": "Spoon any fallen stuffing back onto the prawns after flipping them onto the serving plate"}, {"symptom": "Butter sauce separates (looks oily)", "likely_cause": "Heat was too high or butter was added too quickly", "prevention": "Keep heat very low; whisk in cold butter slowly", "fix": "Remove from heat, add a teaspoon of cold water or cream, and whisk vigorously to re-emulsify"}]', '["To achieve a true Macanese flavor profile, try to source ''Balich\u00e3o'' (Macanese shrimp paste), but standard Belacan or fine shrimp sauce is a worthy substitute.", "Do not discard the prawn heads; the ''tomalley'' inside mixes with the butter sauce and grilled stuffing to create the most flavorful part of the dish.", "If using wooden skewers to keep the prawns straight, soak them in water for 30 minutes beforehand to prevent burning.", "For the sauce, the butter must be cold when adding it to the warm liquid; this technique (mounting with butter) creates a thick, creamy emulsion without cream."]', '"Macanese cuisine is often cited as one of the world''s first fusion cuisines, evolving over 400 years in Macau. This dish reflects that history by combining Portuguese grilling techniques and love for seafood with local Chinese ingredients and spices (turmeric, coconut, chili) acquired along the maritime spice routes."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('eeb6f0a4-5ef3-4ffb-b9da-f8672e9de48e', 'Sizzling Ginger & Tomato Chicken Rice Soup', 'A soul-warming fusion soup that bridges the gap between comforting rice porridge and zesty Tom Yum. Golden-fried ginger strips provide a smoky, spicy crunch, while bursting cherry tomatoes and lime juice cut through the savory depth of chicken and fish sauce.', 'Soup', 'Asian Fusion', 'Easy', '[{"group_name": "Aromatics & Base", "items": [{"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": "room temperature", "notes": "grapeseed or canola", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh ginger", "quantity": 50, "unit": "g", "preparation": "julienned into thin matchsticks", "notes": "peeled", "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "boneless skinless chicken thighs", "quantity": 500, "unit": "g", "preparation": "cut into 2cm pieces", "notes": null, "substitutions": [], "ingredient_id": "d7fc1bf9-fc05-429b-bfa6-2ad857cb0bb6", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato paste", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "41400e7f-7a06-42d2-a625-072c380d60b2", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Soup & Grains", "items": [{"name": "chicken stock", "quantity": 1500, "unit": "ml", "preparation": null, "notes": "low sodium preferred", "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "jasmine rice", "quantity": 150, "unit": "g", "preparation": "uncooked, rinsed", "notes": null, "substitutions": [], "ingredient_id": "b671f3cd-cdec-4182-8911-82a06a22815a", "nutrition_source": "USDA FoodData Central"}, {"name": "fish sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["tamari for gluten-free"], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "cherry tomatoes", "quantity": 250, "unit": "g", "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Finishing", "items": [{"name": "lime", "quantity": 1, "unit": null, "preparation": "juiced", "notes": "approx 30ml juice", "substitutions": [], "ingredient_id": "d3d2677e-fe02-4404-add0-29d73df7e921", "nutrition_source": "USDA FoodData Central"}, {"name": "toasted sesame oil", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8fa9dd65-c49e-449c-b660-a9d9deb638b2", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "red chili flakes", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare your ingredients: cut chicken into bite-sized pieces, julienne the ginger into fine matchsticks, and mince the garlic. Rinse the jasmine rice until the water runs clear.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat neutral oil in the heavy-bottomed pot over medium-high heat. Add the julienned ginger and fry, stirring constantly, until golden brown and crisp. Use a slotted spoon to remove half of the ginger and set aside on a paper towel for garnishing. Leave the remaining ginger and oil in the pot.", "structured": {"action": "FRY", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT4M", "doneness_cues": {"visual": "Golden brown", "tactile": "Crispy"}}, "tips": ["Watch the ginger closely; it transitions from golden to burnt very quickly."]}, {"step_number": 3, "phase": "cook", "text": "Add the chicken pieces to the pot with the remaining ginger oil. Sear for 3-4 minutes until the chicken is opaque. Add garlic and tomato paste, stirring vigorously to coat the chicken and caramelize the paste until it deepens in color (about 2 minutes).", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Tomato paste turns brick red", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the chicken stock, fish sauce, and soy sauce. Scrape the bottom of the pot to release any fond (browned bits). Bring to a boil, then stir in the rinsed rice. Reduce heat to low to maintain a gentle simmer.", "structured": {"action": "DEGLAZE", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Cover and simmer for 15 minutes. Uncover, add the whole cherry tomatoes, and simmer for another 5-7 minutes. The rice should be tender, the chicken cooked through (internal temp 74\u00b0C/165\u00b0F), and the tomatoes just starting to burst skins.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT20M", "doneness_cues": {"visual": null, "tactile": "Rice is tender"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from heat. Stir in the lime juice and toasted sesame oil. Taste and adjust salt if needed. Ladle into bowls and top generously with the reserved crispy ginger, fresh cilantro, and chili flakes if using.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT25M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Dairy-Free", "Pescatarian", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 515.9, "protein_g": 36.94, "carbohydrates_g": 45.06, "fat_g": 23.33, "saturated_fat_g": 2.97, "trans_fat_g": 0.03, "monounsaturated_fat_g": 2, "polyunsaturated_fat_g": 1.33, "fiber_g": 3.15, "sugar_g": 4.74, "sodium_mg": 16069.7, "cholesterol_mg": 117.5, "potassium_mg": 700.2, "calcium_mg": 47.34, "iron_mg": 2.91, "magnesium_mg": 64.1, "phosphorus_mg": 310.91, "zinc_mg": 2.68, "vitamin_a_mcg": 98.63, "vitamin_c_mg": 18.25, "vitamin_d_mcg": null, "vitamin_e_mg": 0.54, "vitamin_k_mcg": 4.4, "vitamin_b6_mg": 0.71, "vitamin_b12_mcg": 0.76, "thiamin_mg": 0.16, "riboflavin_mg": 0.29, "niacin_mg": 7.77, "folate_mcg": 11.33, "water_g": 135.99, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Rice will continue to absorb liquid; add a splash of water or stock when reheating.", "duration": "P3D"}, "freezer": {"notes": "Texture of rice may degrade slightly upon freezing.", "duration": "P1M"}, "reheating": "Simmer gently on stovetop, adding water to loosen consistency.", "does_not_keep": false}', '[{"name": "Heavy-bottomed pot or Dutch oven", "required": true, "alternative": "Large deep saut\u00e9 pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Slotted spoon", "required": true, "alternative": null}]', '[{"symptom": "Soup has turned into a thick porridge", "likely_cause": "The rice absorbed too much liquid or the heat was too high during simmering", "prevention": "Rinse rice thoroughly before cooking to remove excess surface starch", "fix": "Stir in an additional 100-200ml of hot water or stock to reach desired consistency"}]', '["Frying the ginger first is the critical step. It flavors the oil that cooks the chicken and provides a textural contrast at the end that makes the dish pop.", "Do not skip rinsing the rice. Excess starch will make the soup slimy rather than silky.", "For a deeper umami punch, use bone-in chicken thighs and simmer for 10 minutes longer before adding the rice.", "The tomatoes should be ''jammy'' but not disintegrated\u2014add them only in the last stage of cooking.", "If you love heat, saut\u00e9 a sliced fresh chili along with the garlic in step 3."]', '"This dish draws inspiration from two culinary traditions: the comforting texture of Chinese ''Pao Fan'' (submerged rice) or Congee, and the hot-sour aromatic profile of Thai Tom Yum. It represents modern home-cooking fusion, utilizing pantry staples to create complex flavors rapidly."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('f31bf994-c967-40af-a8f6-b1822ba4e9eb', 'Dark Cherry & Hazelnut Biscotti', 'Traditional twice-baked Italian cookies featuring a shattering, crisp texture perfect for dipping in coffee or Vin Santo. The earthy crunch of toasted hazelnuts pairs elegantly with the chewy, tart sweetness of dark dried cherries and a hint of orange zest.', 'Baked Good', 'Italian', 'Intermediate', '[{"group_name": "Inclusions", "items": [{"name": "raw hazelnuts", "quantity": 130, "unit": "g", "preparation": "whole, skin-on or blanched", "notes": null, "substitutions": [], "ingredient_id": "4a2947d7-4339-48a9-89b7-039c446295e4", "nutrition_source": "Aggregated Public Data"}, {"name": "dried tart cherries", "quantity": 110, "unit": "g", "preparation": "roughly chopped if large", "notes": null, "substitutions": [], "ingredient_id": "005de8eb-74c0-482b-866a-d194645f353e", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dough", "items": [{"name": "all-purpose flour", "quantity": 315, "unit": "g", "preparation": null, "notes": "plus extra for dusting", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 200, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "melted and cooled slightly", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 3, "unit": null, "preparation": "large, room temperature", "notes": "approx. 150g total (without shell)", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "baking powder", "quantity": 8, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "orange zest", "quantity": 1, "unit": null, "preparation": null, "notes": "from 1 medium orange", "substitutions": [], "ingredient_id": "a644a589-02d1-4b90-98c5-ec79373a767b", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 175\u00b0C (350\u00b0F). Spread the hazelnuts on a baking sheet and toast for 8-10 minutes until fragrant and skins begin to crack.", "structured": {"action": "TOAST", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT10M", "doneness_cues": {"visual": "Skins cracking and nuts golden", "tactile": "Hot and fragrant"}}, "tips": ["If using skin-on hazelnuts, wrap warm nuts in a kitchen towel and rub vigorously to remove loose skins."]}, {"step_number": 2, "phase": "prep", "text": "Reduce oven temperature to 160\u00b0C (320\u00b0F). Line a large baking sheet with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a large bowl, whisk together the melted butter, sugar, eggs, vanilla extract, and orange zest until well combined and slightly lightened in color.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Sift in the flour, baking powder, and salt. Mix gently with a spatula until just combined and few flour streaks remain. Do not overmix.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": {"visual": "Shaggy, sticky dough formed", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Fold in the toasted hazelnuts (chopped roughly if preferred, or left whole) and dried cherries until evenly distributed.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "shape", "text": "Divide the dough in half. With flour-dusted hands, shape each half into a log approximately 25cm (10 inches) long and 5cm (2 inches) wide directly on the prepared baking sheet. Space them at least 8cm apart as they will spread.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Two smooth, flattened logs", "tactile": null}}, "tips": ["The dough will be sticky; keep hands well-floured or slightly damp to prevent sticking."]}, {"step_number": 7, "phase": "cook", "text": "Bake for 25-30 minutes at 160\u00b0C (320\u00b0F) until the logs are golden brown and firm to the touch in the center.", "structured": {"action": "BAKE", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT25M", "doneness_cues": {"visual": null, "tactile": "Firm center, springs back slightly"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from oven and let the logs cool on the sheet for exactly 15-20 minutes. Maintain oven temperature at 160\u00b0C (320\u00b0F).", "structured": {"action": "COOL", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": ["Cooling is critical. If sliced too hot, they crumble; too cold, they crack."]}, {"step_number": 9, "phase": "finish", "text": "Transfer logs to a cutting board. Using a serrated knife and a sawing motion, cut logs diagonally into 1.5cm (0.5 inch) thick slices. Arrange slices cut-side down back on the baking sheet.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Clean slices without heavy crumbling", "tactile": null}}, "tips": []}, {"step_number": 10, "phase": "cook", "text": "Bake for a second time for 15-20 minutes, flipping the biscotti halfway through, until they are dry and crisp. They will harden further as they cool.", "structured": {"action": "BAKE", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT15M", "doneness_cues": {"visual": null, "tactile": "Hard and dry to the touch"}}, "tips": []}, {"step_number": 11, "phase": "finish", "text": "Transfer to a wire rack to cool completely before storing.", "structured": {"action": "COOL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT1H10M", "total_time": "PT1H45M", "overnight_required": false, "yields": "24 biscotti", "yield_count": 24, "serving_size_g": 35}', '{"flags": ["Vegetarian", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Nut allergies"]}', '{"per_serving": {"calories": 157.23, "protein_g": 3.04, "carbohydrates_g": 23.19, "fat_g": 6.09, "saturated_fat_g": 1.73, "trans_fat_g": null, "monounsaturated_fat_g": 0.83, "polyunsaturated_fat_g": 0.26, "fiber_g": 1.03, "sugar_g": 11.72, "sodium_mg": 94.12, "cholesterol_mg": 28.63, "potassium_mg": 78.51, "calcium_mg": 34.19, "iron_mg": 0.59, "magnesium_mg": 13.71, "phosphorus_mg": 51.88, "zinc_mg": 0.32, "vitamin_a_mcg": 33.93, "vitamin_c_mg": 1.44, "vitamin_d_mcg": 0.13, "vitamin_e_mg": 0.14, "vitamin_k_mcg": 0.47, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": 0.06, "thiamin_mg": 0.02, "riboflavin_mg": 0.04, "niacin_mg": 0.21, "folate_mcg": 6.93, "water_g": 7.62, "alcohol_g": 0.07, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Do not refrigerate; humidity softens the texture.", "duration": null}, "freezer": {"notes": "Freeze baked biscotti in airtight containers. Thaw at room temperature.", "duration": "P3M"}, "reheating": "If they soften, recrisp in a 150\u00b0C oven for 5 minutes.", "does_not_keep": false}', '[{"name": "Large baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": "Silicone baking mat"}, {"name": "Serrated bread knife", "required": true, "alternative": "Very sharp chef''s knife (less ideal)"}, {"name": "Stand mixer or hand mixer", "required": false, "alternative": "Whisk and sturdy spatula"}, {"name": "Wire cooling rack", "required": true, "alternative": null}]', '[{"symptom": "Dough crumbles excessively when slicing", "likely_cause": "The logs were sliced while still too hot or using a dull/straight-edge knife", "prevention": "Allow logs to cool for 20 minutes; use a sharp serrated bread knife", "fix": "Wait 10 more minutes for the remaining log to cool; use a gentle sawing motion"}, {"symptom": "Biscotti are not crunchy enough", "likely_cause": "Second bake was too short or oven humidity was high", "prevention": "Ensure they are golden on the cut sides before removing", "fix": "Return to oven at 140\u00b0C (285\u00b0F) for 10-15 minutes to dry out further"}]', '["Use a serrated bread knife for slicing. A straight-edged chef''s knife will compress the dough and cause the hazelnuts to shatter the cookie structure.", "For a glossy finish, you can brush the logs with an egg wash (1 egg beaten with 1 tbsp water) before the first bake, though this softens the crust slightly.", "Orange zest acts as a bridge flavor, connecting the earthy hazelnut with the tart cherry. Do not skip it.", "If your dried cherries are very hard or old, soak them in warm water for 10 minutes and pat strictly dry before using to prevent tough rocks in your cookies."]', '"Biscotti, specifically ''Biscotti di Prato'' or Cantucci, originated in Tuscany, Italy. The name derives from the Latin ''bis coctus'', meaning twice-cooked. Historically, this double-baking method was used to create durable, travel-ready food for Roman legions, as the lack of moisture prevented mold and spoilage."');
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context) VALUES ('f6488b11-5b29-4e63-a8c9-e3cdd8e31bc5', 'Classic Lachha Paratha', 'A visually striking, multi-layered North Indian flatbread. Known for its visible concentric rings, this bread features a crispy, flaky exterior that shatters upon touch, revealing a tender, soft interior. The lamination technique relies on fat and flour separation similar to puff pastry.', 'Bread', 'Indian', 'Intermediate', '[{"group_name": "Dough", "items": [{"name": "whole wheat flour (atta)", "quantity": 250, "unit": "g", "preparation": "fine grind", "notes": "Indian Atta flour yields best results; standard whole wheat is a coarser substitute", "substitutions": ["50% all-purpose flour + 50% whole wheat flour"], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "fine sea salt", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 160, "unit": "ml", "preparation": "warm (40\u00b0C)", "notes": "quantity may vary slightly based on humidity", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "ghee", "quantity": 15, "unit": "g", "preparation": "melted", "notes": "added to dough for tenderness", "substitutions": ["vegetable oil", "avocado oil"], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Lamination & Cooking", "items": [{"name": "ghee", "quantity": 45, "unit": "g", "preparation": "melted", "notes": "for brushing layers and frying", "substitutions": ["neutral oil", "clarified butter"], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "whole wheat flour", "quantity": 20, "unit": "g", "preparation": "dry", "notes": "for dusting layers", "substitutions": [], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a mixing bowl, combine the flour and salt. Add 15g of melted ghee and mix with your fingers until the flour resembles coarse crumbs. Gradually add warm water while mixing until a dough begins to form.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Knead the dough on a clean surface for 6-8 minutes until it is smooth, soft, and pliable. It should not be sticky. If too dry, add water 1 teaspoon at a time.", "structured": {"action": "KNEAD", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": null, "tactile": "Soft, pliable, springs back slowly when indented"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Cover the dough with a damp kitchen towel or plastic wrap and let it rest at room temperature. This relaxes the gluten, making it easier to roll.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Divide the dough into 4 equal portions. Roll one portion into a thin circle, approximately 20cm (8 inches) in diameter. The thinner you roll it, the more layers you will achieve.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Brush the surface liberally with melted ghee and dust lightly with dry flour. This creates the barrier necessary for layer separation.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Create the layers using the fan-fold method: Make small pleats (accordion folds) about 1cm wide starting from one edge to the other. You should end up with a long, pleated strip.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Hold one end of the pleated strip and roll it tightly inward like a cinnamon roll or coil. Tuck the outer end underneath the center of the coil to seal. Repeat for all portions. Let coils rest covered for 10 minutes.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Heat a heavy skillet or tawa over medium heat. Gently flatten a coil with your hand, then roll it out carefully to a 15cm (6 inch) circle. Do not press too hard, or the layers will merge.", "structured": {"action": "ROLL", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Place the paratha on the hot skillet. Cook for about 1 minute until small bubbles appear. Flip and cook for another minute. Brush the top side with ghee, flip again, and press gently with a spatula to crisp up the layers. Repeat flipping and brushing until golden brown spots appear on both sides.", "structured": {"action": "FRY", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Golden brown leopard spots", "tactile": "Crispy exterior"}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Remove from heat. To release the layers, place the hot paratha between your hands (use a towel if sensitive to heat) and clap your hands together gently to crush the bread slightly from the sides. Serve immediately.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT30M", "total_time": "PT1H5M", "overnight_required": false, "yields": "4 flatbreads", "yield_count": 4, "serving_size_g": 95}', '{"flags": ["Vegetarian", "Egg-Free", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 331.65, "protein_g": 6.62, "carbohydrates_g": 50.3, "fat_g": 13.48, "saturated_fat_g": 7.87, "trans_fat_g": null, "monounsaturated_fat_g": 3.7, "polyunsaturated_fat_g": 1.24, "fiber_g": 8.84, "sugar_g": 0.7, "sodium_mg": 489.68, "cholesterol_mg": 32.25, "potassium_mg": 269.85, "calcium_mg": 26.98, "iron_mg": 2.51, "magnesium_mg": 79.69, "phosphorus_mg": 221.63, "zinc_mg": 2.01, "vitamin_a_mcg": 102.6, "vitamin_c_mg": null, "vitamin_d_mcg": null, "vitamin_e_mg": 0.71, "vitamin_k_mcg": 2.33, "vitamin_b6_mg": 0.13, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.2, "riboflavin_mg": 0.13, "niacin_mg": 3.62, "folate_mcg": 19.35, "water_g": 50.8, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container or wrapped in foil.", "duration": "P3D"}, "freezer": {"notes": "Freeze par-cooked parathas separated by parchment paper.", "duration": "P2M"}, "reheating": "Reheat on a hot skillet for 1-2 minutes per side until crisp.", "does_not_keep": false}', '[{"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Rolling pin", "required": true, "alternative": "Clean wine bottle"}, {"name": "Tawa or Cast Iron Skillet", "required": true, "alternative": "Heavy-bottomed non-stick pan"}, {"name": "Pastry brush", "required": false, "alternative": "Back of a spoon"}, {"name": "Clean kitchen towel", "required": true, "alternative": null}]', '[{"symptom": "Paratha is chewy or hard rather than flaky", "likely_cause": "Dough was not rested enough or cooked on too low heat", "prevention": "Ensure the 20-minute rest period and cook on medium-high heat to flash-cook the layers", "fix": "Keep cooked parathas wrapped in a cloth to steam-soften slightly"}, {"symptom": "Layers are not visible", "likely_cause": "Rolling too firmly during the final shape or insufficient flour/fat between pleats", "prevention": "Use a gentle hand when rolling the final circle and ensure adequate dusting during lamination", "fix": "Cannot be fixed for this batch"}]', '["The ''crush'' or ''clap'' at the very end is the secret to restaurant-style parathas; it physically separates the layers that may have stuck together during cooking.", "Using warm water (40\u00b0C/105\u00b0F) helps hydrate the bran in whole wheat flour faster, resulting in a softer dough without extended kneading.", "If you want a Vegan version, substitute the ghee for a high-heat neutral oil like avocado or grapeseed, though the flavor profile will lack the traditional nutty aroma.", "Do not stack hot parathas directly on top of each other without a cloth, or the steam will destroy the crispiness of the bottom ones."]', '"Lachha Paratha originates from Punjab in North India. The word ''Lachha'' literally translates to ''ring'' or ''coil,'' referring to the circular layers visible in the final bread. It is a staple accompaniment to rich curries like Butter Chicken or Paneer Butter Masala, designed to scoop up thick gravies."');
